INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dacf1ddb48ec75e0832ade06b7f71b74', 'JEEMains', '12', 'Physics', 'phy_12_jm_semiconductor_electronics', 'Semiconductor Electronics', 'p-n junction diode forward reverse bias', '[]', '["forward bias","depletion width","p-n junction","diode behavior"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 2, -1.0, 'A p-n junction diode is forward biased. Which statement is correct?', '["Current is zero", "Depletion width increases", "Resistance is high", "Depletion width decreases"]', 'Depletion width decreases', 'Forward bias reduces depletion width, lowering barrier potential and allowing current flow.', '["Step 1: Forward bias applies external voltage opposing built-in potential", "Step 2: Depletion region narrows, enabling majority carrier diffusion"]', '', 'physics.semiconductors.depletion_width_confusion', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:22:34.357Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dad212c891b6b56b1df153f32c022f02', 'JEEAdvanced', '12', 'Mathematics', 'math_12_jee_adv_inequalities', 'Classical Inequalities', 'Rearrangement inequality and applications', '[]', '["rearrangement inequality","classical inequalities","applications"]', 0, 0, '[]', 'MCQ', NULL, 0, 2400, 'JEE_ADV_EASY', 2, -2.0, 'What is the rearrangement inequality and its application in classical inequalities?', '["An inequality that states that a rearrangement of a sequence of numbers always increases the sum", "An inequality that states that a rearrangement of a sequence of numbers always decreases the sum", "An inequality that states that a rearrangement of a sequence of numbers has no effect on the sum", "An inequality that states that a rearrangement of a sequence of numbers can either increase or decrease the sum"]', 'An inequality that states that a rearrangement of a sequence of numbers always increases the sum', 'The rearrangement inequality is an inequality that states that a rearrangement of a sequence of numbers always increases the sum, which is significant in classical inequalities.', '["Step 1: Define the rearrangement inequality", "Step 2: Explain its application in classical inequalities"]', '', 'general.exam_trap', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:55:19.060Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dad2f5e334c962a17140004a2d2a0886', 'NEET', '12', 'Biology', 'bio_12_neet_reproduction', 'Human Reproduction', 'Male reproductive system anatomy spermatogenesis', '[]', '["spermatogenesis","Sertoli cells","germ cells","seminiferous tubules","Leydig cells","seminal vesicles"]', 0, 0, '["Board"]', 'Multi-correct', NULL, 0, 1750, 'NEET_EASY', 6, -1.0, 'Which of the following structures are involved in spermatogenesis?', '["Sertoli cells", "Leydig cells", "Seminal vesicles", "Germ cells"]', '["SERTOLI CELLS", "GERM CELLS"]', 'Spermatogenesis occurs in seminiferous tubules where germ cells undergo meiosis to form sperm. Sertoli cells provide nourishment and support. Leydig cells produce testosterone but do not directly participate in spermatogenesis. Seminal vesicles contribute to semen but are not sites of sperm production.', '["Step 1: Recall location of spermatogenesis: seminiferous tubules", "Step 2: Identify cell types present: germ cells and Sertoli cells", "Step 3: Germ cells divide to form sperm", "Step 4: Sertoli cells support germ cell development", "Step 5: Leydig cells produce hormones, not sperm", "Step 6: Seminal vesicles are accessory glands"]', '', 'biology.reproduction.cell_function_confusion', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:13:45.340Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dad506edc7da1e80095daef7a37a3678', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_chemical_bonding', 'Chemical Bonding', 'Hydrogen Bonding Effects', '[]', '["hydrogen bonding","intermolecular forces","boiling point","molecular polarity"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 2, -1.0, 'Which of the following compounds shows the highest boiling point due to hydrogen bonding?', '["CH₃OCH₃", "CH₃CH₂OH", "CH₃CHO", "CH₃F"]', 'CH₃CH₂OH', 'Ethanol forms intermolecular H-bonds leading to higher boiling point; others lack H-bond donor.', '["Step 1: Identify H-bond donor (O-H)", "Step 2: Only CH₃CH₂OH has O-H group"]', '', 'chemistry.hydrogen_bonding.boiling_point_misconception', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:32:04.902Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dad6c127e133ff4d1cdd49886150f1bf', 'JEEAdvanced', '12', 'Mathematics', 'math_12_jee_coordinate_geometry_advanced', 'Coordinate Geometry Advanced', 'Family of circles radical axis', '["math_12_jee_conic_sections"]', '["family of circles","radical axis","tangents to circles"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2400, 'JEE_ADV_EASY', 3, -2.0, '$$\text{Let } \mathcal{C}: x^2 + y^2 = 1 \text{ and } \mathcal{C}'': x^2 + y^2 = 4.$$ Find the equation of the radical axis of $\mathcal{C}$ and $\mathcal{C}''$.', '["$$\\text{The equation of the radical axis is } x^2 + y^2 = 0$$", "$$\\text{The equation of the radical axis is } x^2 + y^2 = 2$$", "$$\\text{The equation of the radical axis is } x^2 + y^2 = 4$$", "$$\\text{The equation of the radical axis is } x^2 + y^2 = 1$$"]', '["[''$$\\TEXT{THE EQUATION OF THE RADICAL AXIS IS } X^2 + Y^2 = 0$$'',''$$\\TEXT{THE EQUATION OF THE RADICAL AXIS IS } X^2 + Y^2 = 2$$'']"]', 'Step 1: The radical axis of two circles is the locus of points from which the tangents to the circles have equal lengths.\nStep 2: We can find the equation of the radical axis by subtracting the equations of the two circles.\nStep 3: The equation of the radical axis is $x^2 + y^2 = 4 - 1 = 3$.\nHowever, this is not among the options.\nStep 4: We can rewrite the equation of the radical axis as $x^2 + y^2 = 0$ or $x^2 + y^2 = 2$.', '["Step 1: The radical axis of two circles is the locus of points from which the tangents to the circles have equal lengths.", "Step 2: We can find the equation of the radical axis by subtracting the equations of the two circles.", "Step 3: The equation of the radical axis is $x^2 + y^2 = 4 - 1 = 3$."]', 'x^2 + y^2 = 1', 'mathematics.coordinate_geometry.radical_axis', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:23:31.807Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dadbfd8bcc48d92e476c08ce3101baff', 'Board', '9', 'Mathematics', 'math_09_board_statistics', 'Statistics', 'Median mode calculation', '[]', '["median","data handling","statistics","ordering data","central tendency","class 9 math"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1060, 'CLASS_9_BASIC', 4, 0.0, 'Find the median of the data set: 12, 15, 10, 18, 20.', '["15", "12", "18", "10"]', '15', 'To find the median, first arrange the data in ascending order: 10, 12, 15, 18, 20. Since there are 5 numbers (odd count), the median is the middle value, which is the 3rd term: 15. The median divides the data into two equal halves.', '["Step 1: Arrange data in ascending order: 10, 12, 15, 18, 20.", "Step 2: Count number of observations: 5 (odd).", "Step 3: Use formula: median = $\\left(\\frac{n+1}{2}\\right)^{th}$ term = $3^{rd}$ term.", "Step 4: Identify 3rd term: 15."]', 'Median (odd n) = $\left(\frac{n+1}{2}\right)^{th}$ term', 'math.statistics.median.unsorted_data_trap', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:22:59.163Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dae379872c561a13742e7145e8413a8d', 'JEEMains', '12', 'Mathematics', 'math_12_jm_conditional_probability', 'Probability', 'Conditional probability $P(A|B)$', '[]', '["conditional probability","intersection of events","probability ratio"]', 0, 0, '[]', 'MCQ', NULL, 0, 2400, 'JEE_MAINS_HARD', 3, -1.0, 'In a class of 40 students, 18 study Physics, 22 study Chemistry, and 10 study both. If a student is selected at random, what is the probability that the student studies Chemistry given that the student studies Physics?', '["$\\frac{10}{18}$", "$\\frac{10}{40}$", "$\\frac{22}{40}$", "$\\frac{8}{18}$"]', '$\frac{10}{18}$', 'Conditional probability $P(C|P)=\frac{P(C\cap P)}{P(P)}=\frac{10/40}{18/40}=\frac{10}{18}$.', '["Step 1: Compute $P(P)=\\frac{18}{40}$.", "Step 2: Compute $P(C\\cap P)=\\frac{10}{40}$.", "Step 3: Apply $P(C|P)=\\frac{P(C\\cap P)}{P(P)}$ to obtain $\\frac{10}{18}$."]', 'P(A|B)=\frac{P(A\cap B)}{P(B)}', 'probability.conditional.wrong_denominator', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:32:28.549Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dae60572efa1b401648501ab6e7e793b', 'JEEMains', '11', 'Mathematics', 'math_11_jm_sequences_series', 'Sequences and Series', 'Arithmetic-Geometric Progression sum', '[]', '["arithmetic-geometric progression","sum to infinity","series summation","AGP","power series","convergence","generating function"]', 1, 0, '[]', 'Integer', NULL, 0, 2400, 'JEE_MAINS_HARD', 4, 0.0, 'The sum of the first $n$ terms of the sequence $1, 3x, 5x^2, 7x^3, \ldots$ is given by an arithmetic-geometric progression. If $|x| < 1$, what is the sum to infinity?', '[]', '1', 'The series is $\sum_{k=0}^{\infty} (2k+1)x^k$. Let $S = \sum (2k+1)x^k$. Using standard AGP sum formula: $S = \frac{1}{1-x} + \frac{2x}{(1-x)^2} = \frac{1+x}{(1-x)^2}$. This is valid for $|x| < 1$.', '["Step 1: Recognize general term: $(2k+1)x^k$", "Step 2: Use AGP sum formula or split into two series", "Step 3: Combine: $\\sum x^k = \\frac{1}{1-x}$, $\\sum kx^{k-1} = \\frac{1}{(1-x)^2}$", "Step 4: Final sum: $\\frac{1+x}{(1-x)^2}$"]', '\sum (2k+1)x^k = \frac{1+x}{(1-x)^2}', 'math.series.agp_formula_misapplication', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:10:43.211Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dae613770ca8ea2e5407004007adc21c', 'Board', '9', 'Mathematics', 'math_09_board_geometry', 'Geometry', 'Circles chord diameter arc properties', '[]', '["circle theorems","angle subtended by arc","central angle","inscribed angle"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1100, 'CLASS_9_BASIC', 2, 0.0, 'In a circle, chord AB subtends an angle of 60° at the center. What is the measure of angle subtended by AB at any point on the major arc?', '["30°", "60°", "120°", "90°"]', '30°', 'Angle at circumference is half the angle at center.', '["Step 1: Angle at center = 60°", "Step 2: Angle on major arc = 60°/2 = 30°"]', '\angle_{circumference} = \frac{1}{2} \angle_{center}', 'math.geometry.angle_arc_misconception', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:32:16.237Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dae64270dc1e536d95db647882a411ba', 'JEEMains', '11', 'Mathematics', 'math_11_jm_binomial_theorem', 'Mathematics', 'Binomial Theorem', '[]', '["derivative","power rule","binomial expansion"]', 0, 0, '[]', 'Integer', NULL, 0, 2000, 'JEE_MAINS_EASY', 3, 0.0, '$$\frac{d}{dx}\left(\frac{1}{x^2}\right)$$', '[]', '-2', 'To find the derivative of $$\frac{1}{x^2}$$, we can use the power rule of differentiation, which states that if $$f(x) = x^n$$, then $$f''(x) = nx^{n-1}$$. In this case, we have $$f(x) = \frac{1}{x^2} = x^{-2}$$. Therefore, using the power rule, we get $$f''(x) = -2x^{-3} = -\frac{2}{x^3}$$.', '["Step 1: Identify the function to be differentiated.", "Step 2: Apply the power rule of differentiation.", "Step 3: Simplify the expression."]', 'power rule', 'general.exam_trap', 'NEET Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:28:38.432Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dae7f52e952599b3eab431dc33339256', 'NEET', '11', 'Biology', 'bio_11_sensory', 'Neural Control and Coordination', 'Sensory receptors', '[]', '["angular acceleration","semicircular canals","hair cells","ampullae","vestibular system"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, 'Which type of sensory receptor in the human ear is responsible for detecting angular acceleration, and what is the specific structure that houses these receptors?', '["Hair cells in the cochlea; Organ of Corti", "Hair cells in the semicircular canals; Ampullae", "Macula hair cells; utricle", "Pacinian corpuscles; skin"]', 'Hair cells in the semicircular canals; Ampullae', 'Angular acceleration is sensed by the vestibular system. The semicircular canals contain hair cells whose stereocilia are embedded in the gelatinous cupula within the ampullae. These receptors transduce rotational motion into neural signals.', '["Step 1: Identify the sense (angular acceleration) as a vestibular function.", "Step 2: Recognize that semicircular canals contain the relevant hair cells.", "Step 3: State that these hair cells reside in the ampullae."]', '', 'biology.neural.sensory_receptor', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:49:43.448Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dae9769457132c1c6555b4f0ec5438a0', 'JEEMains', '12', 'Chemistry', 'che_12_jm_surface_chem', 'Surface Chemistry', 'Adsorption', '[]', '["adsorption","physisorption","chemisorption","heat of adsorption","van der Waals forces"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'Which of the following statements correctly distinguishes physisorption from chemisorption on a solid surface?', '["Physisorption involves weak van der Waals forces and typically releases heat of adsorption less than 20 kJ mol⁻¹.", "Chemisorption involves the formation of chemical bonds and usually releases heat of adsorption less than 20 kJ mol⁻¹.", "Physisorption is characterized by a monolayer coverage, whereas chemisorption can form multiple layers on the surface.", "Chemisorption can occur at any temperature, while physisorption is limited to low temperatures."]', 'Physisorption involves weak van der Waals forces and typically releases heat of adsorption less than 20 kJ mol⁻¹.', 'Physisorption is governed by weak van der Waals interactions and the heat of adsorption is usually < 20 kJ mol⁻¹. Chemisorption involves the formation of chemical bonds, releasing much larger heats (≈ 80–400 kJ mol⁻¹). The other options either reverse the heat values or give incorrect statements about layer formation and temperature dependence.', '["Step 1: Identify the nature of forces involved in each type of adsorption.", "Step 2: Recall typical heat of adsorption ranges for physisorption (< 20 kJ mol⁻¹) and chemisorption (> 80 kJ mol⁻¹).", "Step 3: Compare each option with these facts and select the one that matches."]', 'ΔH_{adsorption} \approx 20\,\text{kJ mol}^{-1} \text{ for physisorption}', 'chemistry.surface.adsorption_energy', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:28:26.136Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('daed52560ecf007d2ff41fe104ae2faf', 'JEEMains', '11', 'Physics', 'phy_11_jm_gravitation', 'Gravitation', 'Newton''s law of gravitation G', '[]', '["gravitational force","inverse square law","Newton''s law of gravitation","constant G","point masses"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'Two point masses $m_1 = 4\,\text{kg}$ and $m_2 = 9\,\text{kg}$ are separated by a distance of $10\,\text{m}$. What is the magnitude of the gravitational force between them? Use $G = 6.67 \times 10^{-11}\,\text{N m}^2\text{kg}^{-2}$.

$$
F = \frac{G m_1 m_2}{r^2}
$$', '["$2.4 \\times 10^{-11}\\,\\text{N}$", "$2.4 \\times 10^{-10}\\,\\text{N}$", "$4.8 \\times 10^{-11}\\,\\text{N}$", "$4.8 \\times 10^{-10}\\,\\text{N}$"]', '$2.4 \times 10^{-11}\,\text{N}$', 'We apply Newton''s law of gravitation: $F = \frac{G m_1 m_2}{r^2}$. Substituting values: $F = \frac{(6.67 \times 10^{-11})(4)(9)}{(10)^2} = \frac{2.4012 \times 10^{-9}}{100} = 2.4012 \times 10^{-11}\,\text{N}$. The closest and correct option is $2.4 \times 10^{-11}\,\text{N}$.', '["Step 1: Recall Newton''s law of gravitation: $F = \\frac{G m_1 m_2}{r^2}$", "Step 2: Plug in values: $G = 6.67 \\times 10^{-11}$, $m_1 = 4$, $m_2 = 9$, $r = 10$", "Step 3: Compute $F = \\frac{(6.67 \\times 10^{-11}) \\cdot 36}{100} = 2.4 \\times 10^{-11}\\,\\text{N}$"]', 'F = \frac{G m_1 m_2}{r^2}', 'physics.gravitation.force_magnitude_significant_figures', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:20:49.933Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('daedaf30975598cb54195989995ee55e', 'Board', '10', 'Mathematics', 'math_10_board_polynomials', 'Polynomials Class 10', 'Factor theorem remainder theorem', '[]', '["Polynomials","Remainder Theorem","Factor Theorem"]', 0, 0, '[]', 'MCQ', NULL, 0, 1100, 'BOARD_EASY', 3, 0.0, 'If f(x) = x² + 3x - 4, what is the remainder when f(x) is divided by (x + 2)?', '["-8", "8", "0", "4"]', '-8', 'Step 1: To find the remainder when f(x) is divided by (x + 2), we can use the remainder theorem. Step 2: The remainder theorem states that the remainder is equal to f(-2). Step 3: We substitute x = -2 into the equation f(x) = x² + 3x - 4 to find the remainder.', '["Define remainder theorem", "Explain the process of finding the remainder", "State the formula for the remainder"]', '', 'math.polynomials.remainder', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:26:48.617Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('daf3bff41ee18e1b79e07c9ccd8ab2b8', 'JEEMains', '12', 'Chemistry', 'chem_pblock_group17_halogen_strength', 'Chemistry', 'p‑Block Elements', '[]', '["bond dissociation energy","hydrogen halides","periodic trends","bond length"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'Arrange the hydrogen halides HF, HCl, HBr, and HI in order of increasing bond dissociation energy (BDE).', '["HF < HCl < HBr < HI", "HF > HCl > HBr > HI", "HF > HCl > HI > HBr", "HF < HCl > HBr < HI"]', 'HF > HCl > HBr > HI', 'Bond strength decreases down the group because the H–X bond length increases and overlap decreases. Hence HF has the highest BDE and HI the lowest.', '["Step 1: Recognize that bond length increases from F to I.", "Step 2: Relate longer bonds to weaker (lower) BDE.", "Step 3: Order the halides from strongest to weakest bond."]', '', 'chem.pblock.halogen.bde_trend', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:45:16.029Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('daf4071d4cc172c428432fd9c5794f3a', 'JEEMains', '12', 'Physics', 'phy_12_jm_ray_optics', 'Ray Optics', 'Microscope and telescope magnification', '[]', '["telescope","magnifying power","focal length","optical instruments"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, 0.0, 'The magnifying power of an astronomical telescope in normal adjustment is 100. If the focal length of the objective is $ 150\ \text{cm} $, what is the focal length of the eyepiece?', '[]', '1.5', 'In normal adjustment, magnifying power $ M = \frac{f_o}{f_e} $. Given $ M = 100 $, $ f_o = 150\ \text{cm} $, so $ f_e = \frac{f_o}{M} = \frac{150}{100} = 1.5\ \text{cm} $.', '["Step 1: Use formula for magnifying power in normal adjustment: $ M = \\frac{f_o}{f_e} $", "Step 2: Plug in $ M = 100 $, $ f_o = 150\\ \\text{cm} $", "Step 3: Solve $ f_e = \\frac{150}{100} = 1.5\\ \\text{cm} $"]', 'M = \frac{f_o}{f_e}', 'physics.ray_optics.telescope_formula_confusion', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:11:43.949Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('daf7d97eb75d2ac52dac86c33c33cc50', 'JEEMains', '11', 'Physics', 'phy_11_jm_laws_of_motion', 'Laws of Motion', 'Banking of roads angle of banking', '["phy_11_jm_circular_motion"]', '["banked road","angle of banking","centripetal force","normal force resolution","frictionless circular motion"]', 1, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'A car moves on a banked road with no friction. The angle of banking is $ \theta $, speed is $ v $, and radius of curvature is $ R $. Which expression correctly gives $ \theta $?', '["$ \\tan\\theta = \\frac{v^2}{Rg} $", "$ \\sin\\theta = \\frac{v^2}{Rg} $", "$ \\cos\\theta = \\frac{v^2}{Rg} $", "$ \\tan\\theta = \\frac{Rg}{v^2} $"]', '$ \tan\theta = \frac{v^2}{Rg} $', 'For a banked road without friction, the horizontal component of normal force provides centripetal force: $ N \sin\theta = \frac{mv^2}{R} $. Vertical equilibrium: $ N \cos\theta = mg $. Dividing: $ \tan\theta = \frac{v^2}{Rg} $. This is standard derivation in circular motion.', '["Step 1: Draw free-body diagram: normal force and gravity.", "Step 2: Resolve N into components.", "Step 3: Horizontal: $ N\\sin\\theta = mv^2/R $, Vertical: $ N\\cos\\theta = mg $.", "Step 4: Divide equations: $ \\tan\\theta = v^2/(Rg) $."]', '\tan\theta = \frac{v^2}{Rg}', 'physics.circmotion.banking_sin_vs_tan', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:12:06.418Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dafe227805fc02f377c0d0a050753d0e', 'Board', '10', 'Science', 'phy_10_board_magnetic', 'Magnetic Effects', 'Solenoid as bar magnet', '[]', '["solenoid","magnetic field","turn density","permeability of free space","Ampere''s law"]', 0, 0, '[]', 'MCQ', NULL, 0, 1250, 'BOARD_EASY', 3, 0.0, 'A long solenoid has 500 turns, length $0.25\,\text{m}$, and carries a current of $2\,\text{A}$. What is the magnetic field at its centre? (Take $\mu_{0}=4\pi\times10^{-7}\,\text{T·m/A}$)', '["5\\times10^{-3}\\,\\text{T}", "2\\times10^{-3}\\,\\text{T}", "1\\times10^{-3}\\,\\text{T}", "0.5\\times10^{-3}\\,\\text{T}"]', '5\times10^{-3}\,\text{T}', 'Turn density $n = N/L = 500/0.25 = 2000\,\text{turns·m}^{-1}$. Using $B = \mu_{0} n I$, we get $B = 4\pi\times10^{-7}\times2000\times2 \approx 5\times10^{-3}\,\text{T}$.', '["Step 1: Compute the turn density $n = N/L$.", "Step 2: Apply the solenoid formula $B = \\mu_{0} n I$.", "Step 3: Substitute the numbers and evaluate."]', 'B = \mu_{0} n I', 'physics.magnetism.solenoid_field', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:19:19', 'v2.1', 'Taxonomy alignment: updated class (10->10), exam (Board->Board), subject (Physics->Science) to match canonical taxonomy item sci_10_board_magnetism', '2026-05-22T14:17:55.531Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db0e4f61c6cfd7ad02188dd6c1b51f93', 'JEEMains', '11', 'Physics', 'phy_11_jm_shm', 'Oscillations', 'Simple Harmonic Motion', '[]', '["angular frequency","simple harmonic motion","amplitude","phase","period"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'In the simple harmonic motion equation $x = A\sin(\omega t + \phi)$, what does the parameter $\omega$ represent?', '["Amplitude", "Phase constant", "Angular frequency", "Time period"]', 'Angular frequency', '$\omega$ is the angular frequency, related to the period $T$ by $\omega = 2\pi/T$. It determines how fast the system oscillates.', '["Step 1: Recognize the standard SHM form $x = A\\sin(\\omega t + \\phi)$.", "Step 2: Identify each symbol: $A$ is amplitude, $\\phi$ is phase, $\\omega$ is angular frequency.", "Step 3: Choose the option that matches $\\omega$."]', '$\omega = 2\pi/T$', 'physics.shm.angular_frequency', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:50:25.023Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db115dfb6d319b68d82766740586f768', 'Board', '9', 'Science', 'sci_9_atoms_molecules', 'Atoms and Molecules', 'Molar mass', '[]', '["molar mass","molecular weight","periodic table","stoichiometry"]', 0, 0, '[]', 'MCQ', NULL, 0, 950, 'CLASS_9_BASIC', 3, 0.0, 'What is the molar mass of calcium carbonate, $\text{CaCO}_3$, in grams per mole?', '["100.09 g·mol⁻¹", "84.00 g·mol⁻¹", "56.10 g·mol⁻¹", "120.10 g·mol⁻¹"]', '100.09 g·mol⁻¹', 'Add the atomic masses: Ca = 40.08, C = 12.01, O = 16.00 × 3 = 48.00. Sum = 40.08 + 12.01 + 48.00 = 100.09 g·mol⁻¹.', '["Step 1: Write the atomic masses of Ca, C and O from the periodic table.", "Step 2: Multiply the atomic mass of O by 3 (since there are three O atoms).", "Step 3: Add all the contributions to obtain the molar mass."]', 'M = Σ (atomic mass × subscript)', 'science.molar_mass.calculation', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:46:25.260Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db1437d8f309f7bb36958c15217b878d', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ac_burnside', 'Mathematics', 'Advanced Combinatorics', '[]', '["Burnside''s Lemma","group action","symmetry","coloring problem","orbit counting"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2450, 'JEE_ADV_EASY', 3, -2.0, 'Consider the set of colourings of the vertices of a square using three colours {Red, Green, Blue}. Two colourings are considered the same if one can be obtained from the other by a rotation of the square. Using Burnside''s Lemma, which of the following statements are correct?', '["The identity rotation contributes $3^4=81$ colourings.", "Each 90° rotation contributes $3$ colourings.", "Each 180° rotation contributes $9$ colourings.", "The total number of distinct colourings is $30$."]', '["A. THE IDENTITY ROTATION CONTRIBUTES $3^4=81$ COLOURINGS.", "B. EACH 90° ROTATION CONTRIBUTES $3$ COLOURINGS.", "C. EACH 180° ROTATION CONTRIBUTES $9$ COLOURINGS."]', 'Burnside''s Lemma states $|X/G|=\frac{1}{|G|}\sum_{g\in G}|\text{Fix}(g)|$. The group of rotations has 4 elements. Fixed colourings: identity → $3^4$, each 90°/270° rotation → $3$, 180° rotation → $9$. Summing gives $96$, and $96/4=24$ distinct colourings, so statements A, B and C are true while D is false.', '["Step 1: List the four rotation symmetries of the square (0°, 90°, 180°, 270°).", "Step 2: Count colourings fixed by each symmetry: $3^4$, $3$, $9$, $3$ respectively.", "Step 3: Apply Burnside''s Lemma: $(81+3+9+3)/4 = 24$ distinct colourings.", "Step 4: Identify which statements match the intermediate counts."]', 'Burnside''s Lemma: $|X/G| = \frac{1}{|G|}\sum_{g\in G} |\text{Fix}(g)|$', 'math.combinatorics.burnside_fixed_points', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:54:45.419Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db1646f825917d69222542466345d194', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_isomerism', 'Coordination Compounds', 'Isomerism', '[]', '["geometric isomerism","cis‑trans","coordination geometry","ligand arrangement"]', 0, 0, '[]', 'MCQ', NULL, 0, 2200, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Which of the following statements correctly describes geometric isomerism in coordination compounds?', '["It arises due to different possible arrangements of ligands around the central metal ion in the same coordination number.", "It occurs only when the ligands are monodentate and the complex has a square‑planar geometry.", "It is possible only for octahedral complexes having two identical ligands placed trans to each other.", "It involves the exchange of positions of ligands that are chemically identical but occupy different spatial positions."]', 'It arises due to different possible arrangements of ligands around the central metal ion in the same coordination number.', 'Geometric isomerism (cis‑trans) occurs when ligands can occupy different positions in the same coordination geometry, leading to distinct spatial arrangements without changing the connectivity. The other options either restrict the definition incorrectly or describe other types of isomerism.', '["Step 1: Recall the definition of geometric (cis‑trans) isomerism.", "Step 2: Identify that it depends on the relative positions of ligands in a fixed geometry.", "Step 3: Eliminate options that impose unnecessary restrictions (e.g., only square‑planar).", "Step 4: Choose the statement that matches the general definition."]', '', 'chemistry.coord_compounds.geometric_isomerism', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:36:13.829Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db1aa3fce2b5346c9dce79e2856878a0', 'JEEMains', '12', 'Physics', 'phy_12_jm_ray_optics', 'Ray Optics and Optical Instruments', 'Microscope and telescope magnification', '[]', '["microscope","magnification","angle"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 2, -1.0, 'The magnification of a microscope is given by the ratio of the angle subtended by the image at the eye to the angle subtended by the object at the eye.', '["The magnification of a microscope is given by the ratio of the angle subtended by the image at the eye to the angle subtended by the object at the eye.", "The magnification of a microscope is given by the ratio of the angle subtended by the object at the eye to the angle subtended by the image at the eye.", "The magnification of a microscope is given by the ratio of the angle subtended by the image at the eye to the angle subtended by the object at the eye.", "The magnification of a microscope is given by the ratio of the angle subtended by the object at the eye to the angle subtended by the image at the eye."]', 'The magnification of a microscope is given by the ratio of the angle subtended by the image at the eye to the angle subtended by the object at the eye.', 'Step 1: Recall the formula for the magnification of a microscope.\nStep 2: Identify the correct statement regarding the magnification of a microscope.', '["Step 1: Recall the formula for the magnification of a microscope.", "Step 2: Identify the correct statement regarding the magnification of a microscope."]', '', 'physics.ray_optics.microscope_magnification', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:47:41.411Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db1fb71b23acc28bd31f84f9e532eaf7', 'Board', '9', 'Science', 'science_9_board_newton1', 'Force and Laws of Motion', 'Newton''s first law and inertia', '[]', '["inertia","mass","Newton''s first law","force"]', 0, 0, '[]', 'MCQ', NULL, 0, 1150, 'CLASS_9_BASIC', 3, 0.0, 'According to Newton''s first law, a body at rest will remain at rest unless acted upon by a net external force. Which statement best explains the role of mass in this law?', '["Mass determines the amount of force needed to change the state of motion", "Mass is the measure of inertia", "Mass is unrelated to inertia", "Mass only affects gravitational force"]', 'Mass is the measure of inertia', 'Newton''s first law introduces inertia, which is quantified by mass; a larger mass means greater resistance to change in motion.', '["Step 1: Recall that inertia is the tendency of a body to resist changes in its state of motion.", "Step 2: Identify mass as the quantitative measure of inertia.", "Step 3: Choose the option that directly links mass with inertia."]', '', 'science.physics.newton.first_law', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1150 and target exam Board', '2026-05-22T13:44:18.536Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db2285402407d47d651f8aa3c9610dba', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_chemical_bonding', 'Chemical Bonding', 'Lattice energy – Born‑Haber cycle', '[]', '["lattice energy","Born-Haber cycle","ionization energy","electron affinity","sublimation energy","enthalpy of formation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 4, -1.0, 'Using the Born‑Haber cycle, calculate the magnitude of the lattice energy of NaCl(s). Given data: \n\n- Sublimation energy of Na (Na(s) → Na(g)) = $108\ \text{kJ mol}^{-1}$\n- First ionization energy of Na (Na(g) → Na⁺(g) + e⁻) = $496\ \text{kJ mol}^{-1}$\n- Bond dissociation energy of Cl₂ (½Cl₂ → Cl(g)) = $121\ \text{kJ mol}^{-1}$\n- Electron affinity of Cl (Cl(g) + e⁻ → Cl⁻(g)) = $-349\ \text{kJ mol}^{-1}$\n- Standard enthalpy of formation of NaCl(s) = $-411\ \text{kJ mol}^{-1}$\n\nWhat is the lattice energy (in kJ mol⁻¹) of NaCl(s)?', '["787 \\ \\text{kJ mol}^{-1}", "650 \\ \\text{kJ mol}^{-1}", "1020 \\ \\text{kJ mol}^{-1}", "540 \\ \\text{kJ mol}^{-1}"]', '787 \ \text{kJ mol}^{-1}', 'The Born‑Haber cycle gives: $\Delta H_f = \Delta H_{sub} + IE + \frac{1}{2}D + EA + U_{lattice}$. Substituting the numbers: $-411 = 108 + 496 + 121 - 349 + U$. The sum of known terms is $376\ \text{kJ mol}^{-1}$, so $U = -411 - 376 = -787\ \text{kJ mol}^{-1}$. The magnitude is $787\ \text{kJ mol}^{-1}$.', '["Step 1: Write the Born‑Haber expression: $\\Delta H_f = \\Delta H_{sub} + IE + \\frac{1}{2}D + EA + U_{lattice}$.", "Step 2: Insert the given numerical values: $-411 = 108 + 496 + 121 - 349 + U$.", "Step 3: Add the known terms: $108 + 496 + 121 - 349 = 376\\ \\text{kJ mol}^{-1}$.", "Step 4: Solve for the lattice energy: $U = -411 - 376 = -787\\ \\text{kJ mol}^{-1}$; magnitude = $787\\ \\text{kJ mol}^{-1}$."]', '\Delta H_f = \Delta H_{sub} + IE + \frac{1}{2}D + EA + U_{lattice}', 'chemistry.bonding.lattice_energy_calculation', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:43:09.785Z', 1);
