INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db26256877e8ba909da01f1c508dda89', 'NEET', '12', 'Biology', 'bio_12_neet_biotechnology', 'Biotechnology', 'Transgenic organisms, Bt crops', '["bio_12_neet_genetic_engineering"]', '["transgenic plants","Bt toxin","Cry genes","insect resistance"]', 1, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 2, -1.0, 'Bt cotton is genetically modified to express:', '["Insulin protein", "Bt toxin protein", "Antibiotic resistance", "Fluorescent protein"]', 'Bt toxin protein', 'Bt crops express Cry proteins toxic to specific insects, reducing pesticide use.', '["Step 1: Bt gene from Bacillus thuringiensis inserted", "Step 2: Plant produces Bt toxin against bollworm"]', '', 'bio.biotech.bt_gene_function', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:38:00.793Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db274fa4472d01b5a9b07e3d5894656b', 'NEET', '12', 'Biology', 'bio_12_neet_bioreactors', 'Biotechnology', 'Bioreactor Types', '[]', '["bioreactor","airlift","upstream processing","cell culture","shear stress"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 3, -1.0, 'Which type of bioreactor is most suitable for the production of monoclonal antibodies where low shear stress is essential?', '["Stirred tank reactor", "Airlift bioreactor", "Packed bed reactor", "Bubble column reactor"]', 'Airlift bioreactor', 'Monoclonal antibody production requires gentle mixing to avoid cell damage. Airlift bioreactors provide circulation with minimal shear compared to stirred tanks, making them the preferred choice.', '["Step 1: Identify the need for low shear stress in mammalian cell culture.", "Step 2: Compare the shear characteristics of common bioreactor designs.", "Step 3: Select the airlift bioreactor as it offers low shear and efficient gas transfer."]', '', 'biology.biotech.bioreactor_selection', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:02:20.484Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db299c6569de220e7acf101548f680bf', 'Board', '8', 'Mathematics', 'math_8_rational_numbers_comparison', 'Rational Numbers Class 8', 'Comparison ordering rational numbers', '[]', '["Rational Numbers","Integers"]', 0, 0, '[]', 'MCQ', NULL, 0, 800, 'CLASS_8_RECALL', 1, 0.0, '$\text{The ratio of the number of rational numbers to the number of integers is}\n\n\text{A) 1:1}\n\n\text{B) 1:2}\n\n\text{C) 1:3}\n\n\text{D) 1:4}\n\n\text{E) 1:5}\n\n\text{F) 1:6}\n\n\text{G) 1:7}\n\n\text{H) 1:8}\n\n\text{I) 1:9}\n\n\text{J) 1:10}\n\n\text{K) 1:11}\n\n\text{L) 1:12}\n\n\text{M) 1:13}\n\n\text{N) 1:14}\n\n\text{O) 1:15}\n\n\text{P) 1:16}\n\n\text{Q) 1:17}\n\n\text{R) 1:18}\n\n\text{S) 1:19}\n\n\text{T) 1:20}\n\n\text{U) 1:21}\n\n\text{V) 1:22}\n\n\text{W) 1:23}\n\n\text{X) 1:24}\n\n\text{Y) 1:25}\n\n\text{Z) 1:26}\n\n\text{A)}', '["1:1", "1:2", "1:3", "1:4"]', '1:2', 'Step 1: Recall that every integer is a rational number.', '["Step 1: Recall that every integer is a rational number."]', '', 'general.exam_trap', 'Board Class 8', NULL, 'D', 0.87, 'Recall', NULL, NULL, NULL, '2026-05-22T14:22:33.108Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db2b2d1dc85c7709db5244fc9330f017', 'JEEMains', '12', 'Physics', 'phy_12_jm_electrostatics', 'Electric Charges and Fields', 'Gauss law â€” sphere cylinder infinite plane', '["phy_12_jm_gauss_law_applications"]', '["Gauss''s law","spherical symmetry","electric field inside sphere","uniform volume charge","non-conducting sphere"]', 1, 0, '["JEEMains"]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 5, -1.0, 'A uniformly charged solid non-conducting sphere of radius $R$ has total charge $Q$. What is the magnitude of the electric field at a distance $r = \frac{R}{2}$ from the center?

Use Gauss''s law: $$\oint \vec{E} \cdot d\vec{A} = \frac{q_{\text{enc}}}{\varepsilon_0}$$', '["$\\frac{Q}{8\\pi\\varepsilon_0 R^2}$", "$\\frac{Q}{4\\pi\\varepsilon_0 R^2}$", "$\\frac{Q}{2\\pi\\varepsilon_0 R^2}$", "$\\frac{3Q}{8\\pi\\varepsilon_0 R^2}$"]', '$\frac{Q}{8\pi\varepsilon_0 R^2}$', 'Inside a uniformly charged solid sphere, the electric field at radius $r < R$ is given by $E = \frac{Q r}{4\pi\varepsilon_0 R^3}$. Substituting $r = R/2$, we get $E = \frac{Q}{8\pi\varepsilon_0 R^2}$. This follows from Gauss''s law with $q_{\text{enc}} = Q \cdot (r^3/R^3)$.', '["Step 1: Apply Gauss''s law for spherical symmetry", "Step 2: Find enclosed charge: $q_{\\text{enc}} = Q \\cdot (r^3/R^3)$", "Step 3: Use $E \\cdot 4\\pi r^2 = q_{\\text{enc}} / \\varepsilon_0$", "Step 4: Substitute $r = R/2$", "Step 5: Simplify to get $E = \\frac{Q}{8\\pi\\varepsilon_0 R^2}$"]', 'E = \frac{Q r}{4\pi\varepsilon_0 R^3}', 'physics.electrostatics.gauss_law_enclosed_charge_mistake', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:02:44.506Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db2fea413cb05f662500ad09741a084e', 'NEET', '12', 'Biology', 'bio_12_neet_reproduction', 'Sexual Reproduction in Flowering Plants', 'Endosperm development types', '[]', '["endosperm","nuclear type","coconut","angiosperm reproduction","triploid nucleus"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 2, -1.0, 'Which type of endosperm development is seen in coconut water?', '["Cellular", "Nuclear", "Helobial", "Syncytial"]', 'Nuclear', 'Coconut water is free-nuclear (nuclear) endosperm before cellularization.', '["Step 1: Recall endosperm types", "Step 2: Coconut = nuclear endosperm"]', '', 'bio.reproduction.endosperm_type_confusion', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:25:41.553Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db316e1a4055868965dfd163e3c2e764', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_structure_of_atom', 'Atomic Structure', 'Bohr model postulates energy levels H-atom', '[]', '["Energy Levels","Hydrogen Atom","Bohr Model"]', 0, 0, '[]', 'Integer', NULL, 0, 2000, 'JEE_MAINS_EASY', 1, 0.0, '$\text{The energy levels of the hydrogen atom are given by } E_n = -\frac{13.6}{n^2} \text{ eV}.$ What is the energy of the ground state of the hydrogen atom?', '[]', '-13.6', 'To find the energy of the ground state, we need to substitute the value of } n = 1 \text{ into the formula } E_n = -\frac{13.6}{n^2} \text{ eV}. Therefore, the energy of the ground state is $E_1 = -\frac{13.6}{1^2} = -13.6$ eV.', '["Step 1: Substitute the value of } n = 1 \\text{ into the formula } E_n = -\\frac{13.6}{n^2} \\text{ eV}."]', 'E_n = -\frac{13.6}{n^2} \text{ eV}', 'chemistry.atomic.energy_levels', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', NULL, NULL, NULL, '2026-05-20T12:51:12.180Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db31d512d6709992db32691909347d71', 'NEET', '11', 'Biology', 'bio_11_neet_photosynthesis', 'Photosynthesis', 'Calvin cycle C3 fixation 3PGA', '[]', '["RuBisCO","RuBP","CO₂ fixation","Calvin cycle","C3 pathway"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 3, -1.0, 'In the Calvin cycle of C₃ photosynthesis, the enzyme RuBisCO catalyzes the fixation of CO₂ with which three‑carbon molecule?', '["Ribulose‑1,5‑bisphosphate (RuBP)", "3‑Phosphoglycerate (3‑PGA)", "Glyceraldehyde‑3‑phosphate (G3P)", "Fructose‑1,6‑bisphosphate (FBP)"]', 'Ribulose‑1,5‑bisphosphate (RuBP)', 'RuBisCO combines CO₂ with ribulose‑1,5‑bisphosphate (RuBP), a five‑carbon molecule, to produce two molecules of 3‑phosphoglycerate (3‑PGA). The substrate that directly reacts with CO₂ is RuBP.', '["Step 1: Identify the substrate that reacts with CO₂ in the Calvin cycle.", "Step 2: Recall that RuBisCO catalyzes the reaction: CO₂ + RuBP → 2 3‑PGA.", "Step 3: Choose the option that names RuBP."]', 'CO₂ + RuBP \rightarrow 2\,3\text{-PGA}', 'biology.photosynthesis.rubisco_substrate', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:17:46.430Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db3ac8aaf68ff33fe6dace24bd7073d3', 'JEEMains', '12', 'Physics', 'phy_12_jm_current_electricity', 'Current Electricity', 'Cell EMF internal resistance', '[]', '["power in DC circuit","maximum power transfer","internal resistance","EMF","differentiation application","circuit analysis","Ohm''s law"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'A cell of EMF $\mathcal{E}$ and internal resistance $r$ is connected across a variable external resistance $R$. The power delivered to the external resistance is maximum when $R$ equals:

$$
P = \frac{\mathcal{E}^2 R}{(R + r)^2}
$$', '["$r$", "$2r$", "$\\frac{r}{2}$", "$\\sqrt{r}$"]', '$r$', 'The power delivered to the external resistance is given by $P = \frac{\mathcal{E}^2 R}{(R + r)^2}$. To maximize $P$, differentiate with respect to $R$ and set $\frac{dP}{dR} = 0$. This yields $R = r$. Thus, maximum power transfer occurs when external resistance equals internal resistance.', '["Step 1: Write power expression $P = \\frac{\\mathcal{E}^2 R}{(R + r)^2}$", "Step 2: Differentiate $P$ w.r.t. $R$ using quotient rule", "Step 3: Set derivative $\\frac{dP}{dR} = 0$ and solve for $R$", "Step 4: Obtain $R = r$ as condition for maximum power"]', 'P = \frac{\mathcal{E}^2 R}{(R + r)^2}', 'physics.current_electricity.max_power_condition', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:03:27.048Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db451152440660535e17fc3df3a72d77', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_eas_mechanism', 'Hydrocarbons', 'Electrophilic aromatic substitution mechanism', '[]', '["arenium ion","rate‑determining step","electrophile generation","aromaticity loss","reaction mechanism"]', 0, 0, '[]', 'MCQ', NULL, 0, 2350, 'JEE_MAINS_HARD', 3, -1.0, 'In the electrophilic aromatic substitution of benzene with bromine (Br₂) in the presence of FeBr₃, which step is the rate‑determining step (RDS)?', '["Formation of the σ‑complex (arenium ion)", "Deprotonation of the σ‑complex", "Generation of the electrophile Br⁺", "Resonance stabilization of the σ‑complex"]', 'Formation of the σ‑complex (arenium ion)', 'The slowest step is the formation of the high‑energy σ‑complex when the aromatic ring attacks the electrophile. Subsequent deprotonation and resonance steps are fast.', '["Step 1: Identify the sequence of steps in EAS.", "Step 2: Recognize that the σ‑complex formation involves breaking aromaticity and is energetically unfavorable.", "Step 3: Choose this step as the RDS."]', '', 'chem.organic.rds_misidentification', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:08:55.953Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db466870b995d629dcfecc94eaf9e144', 'JEEMains', '12', 'Mathematics', 'math_12_jm_inverse_trig', 'Inverse Trigonometric Functions', 'Inverse trig identities', '[]', '["arcsin","arccos","inverse trigonometric identity","π/2 complement"]', 0, 0, '[]', 'Integer', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, 0.0, 'Find the value of $\theta$ (in radians) that satisfies $\sin^{-1}\!\left(\frac{3}{5}\right) + \cos^{-1}(\theta) = \frac{\pi}{2}$.', '[]', '0.6', 'The identity $\sin^{-1}x + \cos^{-1}x = \frac{\pi}{2}$ holds for the same argument $x$. Comparing, we obtain $\theta = \frac{3}{5}=0.6$.', '["Step 1: Recall the identity $\\sin^{-1}x + \\cos^{-1}x = \\frac{\\pi}{2}$.", "Step 2: Match the given expression with the identity; the two arguments must be equal.", "Step 3: Conclude $\\theta = \\frac{3}{5}=0.6$."]', '$\sin^{-1}x + \cos^{-1}x = \frac{\pi}{2}$', 'math.trig.inverse_identity_misapply', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:18:49.713Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db47575e0e3b6caa0bad9d665c5555f3', 'JEEMains', '12', 'Chemistry', 'che_12_jm_amines_basicity', 'Amines', 'Basicity of amines', '[]', '["basicity","inductive effect","resonance","aniline","alkyl amine"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'Arrange the following amines in order of decreasing basicity in aqueous solution: (i) methylamine, (ii) aniline, (iii) ethylamine.', '["Methylamine > Ethylamine > Aniline", "Ethylamine > Methylamine > Aniline", "Methylamine > Aniline > Ethylamine", "Aniline > Methylamine > Ethylamine"]', 'Ethylamine > Methylamine > Aniline', 'Aliphatic amines are more basic than aniline because the lone pair on nitrogen is less delocalised. Between methylamine and ethylamine, the inductive effect of the extra –CH₂– group makes ethylamine slightly more basic.', '["Step 1: Recognise that resonance in aniline reduces its basicity compared to aliphatic amines.", "Step 2: Compare methylamine (CH₃NH₂) and ethylamine (CH₃CH₂NH₂); the ethyl group donates electron density, increasing basicity.", "Step 3: Rank the three compounds based on the above considerations.", "Step 4: Select the option that matches the derived order."]', '', 'chemistry.amines.basicity_order', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:45:01.324Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db483b5a9b29293b9b40cadbf651bff4', 'JEEMains', '12', 'Mathematics', 'math_12_jm_determinants', 'Determinants', 'Properties â€” row operations effect', '[]', '["determinant","row swap","row operation","sign change","properties of determinants"]', 0, 0, '[]', 'Integer', NULL, 0, 1850, 'JEE_MAINS_EASY', 4, 0.0, 'If $\Delta = \begin{vmatrix} a & b & c \\ d & e & f \\ g & h & i \end{vmatrix} = 5$, what is the value of the determinant after swapping the first and third rows?', '[]', '-5', 'Swapping two rows of a determinant changes its sign. Since the original determinant is 5, swapping row 1 and row 3 gives a new determinant value of -5. This is a standard property of determinants.', '["Step 1: Recall that interchanging two rows of a determinant multiplies its value by -1", "Step 2: Identify that rows 1 and 3 are swapped", "Step 3: Apply the property: new determinant = - (original determinant)", "Step 4: Compute: -5"]', '\text{Row swap} \Rightarrow \Delta \to -\Delta', 'math.determinant.row_swap_sign_error', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:54:58.440Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db48d79745727f73df781dfe12336fed', 'JEEMains', '11', 'Physics', 'phy_11_jm_collision_elastic', 'Work, Energy and Power', 'Collision – Elastic', '[]', '["elastic collision","coefficient of restitution","conservation of momentum","kinetic energy","one‑dimensional collision"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Two balls, A (mass 2 kg) moving right with speed 4 m s⁻¹ and B (mass 3 kg) moving left with speed 2 m s⁻¹, collide elastically. What is the speed of ball A after the collision?', '["-3.2 m/s", "3.2 m/s", "-0.8 m/s", "0.8 m/s"]', '-3.2 m/s', 'Using the elastic‑collision formula \(v_{1}=\frac{(m_{1}-m_{2})u_{1}+2m_{2}u_{2}}{m_{1}+m_{2}}\) with \(u_{2}\) taken negative (opposite direction), we obtain \(v_{1}= -\frac{16}{5}= -3.2\) m/s, i.e., ball A reverses direction.', '["Step 1: Assign directions: take right as positive, so u₁ = +4 m/s, u₂ = -2 m/s.", "Step 2: Apply the elastic‑collision formula for v₁.", "Step 3: Compute numerator: (2‑3)·4 + 2·3·(‑2) = -4 -12 = -16.", "Step 4: Divide by total mass (2+3)=5 to get v₁ = -16/5 = -3.2 m/s."]', 'v_{1}=\frac{(m_{1}-m_{2})u_{1}+2m_{2}u_{2}}{m_{1}+m_{2}}', 'physics.mechanics.elastic_collision_speed', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:38:25.386Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db48efa9727a6275213c2dad7ef0dae5', 'JEEMains', '11', 'Physics', 'phy_11_jm_waves', 'Waves', 'Standing waves on string and in pipe', '[]', '["Waves","Standing waves","String","Pipe"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 3, -1.0, 'A string is fixed at both ends and a pipe open at both ends is filled with air. Which of the following is NOT a possible mode of vibration for the string?', '["Standing waves on the string", "Standing waves in the pipe", "Both standing waves on the string and in the pipe", "Neither standing waves on the string nor in the pipe"]', 'Neither standing waves on the string nor in the pipe', 'Standing waves can occur on a string fixed at both ends, but they cannot occur in a pipe open at both ends.', '["Step 1: Recall the conditions for standing waves on a string and in a pipe", "Step 2: Analyze the options given in the question", "Step 3: Choose the correct option"]', '', 'physics.waves.standing_waves', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:20:23.736Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db4a99794217ee618dbe1bd1c818ee58', 'JEEMains', '12', 'Physics', 'phy_12_jm_ac_power_factor', 'Alternating Current', 'Power Factor and Wattless Current', '["phy_12_jm_ac_complex_power"]', '["apparent power","real power","power factor","RMS voltage","RMS current","single-phase AC"]', 1, 0, '[]', 'Integer', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, 0.0, 'A single‑phase AC load draws a current of magnitude $I = 10\,\text{A}$ from a $230\,\text{V}$ rms source at $50\,\text{Hz}$. The power factor is $0.8$ lagging. What is the real power (in kW) consumed by the load? (Round to the nearest whole number.)', '[]', '2', 'Real power $P = V_{rms} I_{rms} \cos\phi = 230 \times 10 \times 0.8 = 1840\,\text{W} = 1.84\,\text{kW}$. Rounded to the nearest whole number gives $2\,\text{kW}$.', '["Step 1: Write the formula for real power $P = V_{rms} I_{rms} \\cos\\phi$.", "Step 2: Substitute $V_{rms}=230\\,\\text{V}$, $I_{rms}=10\\,\\text{A}$, $\\cos\\phi=0.8$.", "Step 3: Compute $P = 230 \\times 10 \\times 0.8 = 1840\\,\\text{W}$ and convert to kW, then round."]', 'P = V_{rms} I_{rms} \cos\phi', 'physics.ac.power_factor_real_power_calc', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:47:59.880Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db50f98e1a07a9dce9952c6c19d00dfb', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_advanced_mechanics', 'Advanced Mechanics', 'Pseudo forces in rotating frames', '[]', '["centrifugal force","rotating reference frame","pseudo force","Newton''s laws in non‑inertial frame"]', 0, 0, '[]', 'Integer', NULL, 0, 2850, 'JEE_ADV_HARD', 3, -1.0, 'A particle of mass $2\,\text{kg}$ moves in a circle of radius $0.5\,\text{m}$ on a turntable rotating at $10\,\text{rad\,s}^{-1}$. Find the magnitude of the pseudo (centrifugal) force experienced by the particle in the rotating frame.', '[]', '100', 'Centrifugal force $F = m\omega^{2}r = 2\times10^{2}\times0.5 = 100\,\text{N}$.', '["Step 1: Write the formula for centrifugal force $F = m\\omega^{2}r$.", "Step 2: Substitute $m=2\\,\\text{kg}$, $\\omega=10\\,\\text{rad\\,s}^{-1}$, $r=0.5\\,\\text{m}$.", "Step 3: Compute $F = 2\\times(10)^{2}\\times0.5 = 100\\,\\text{N}$."]', '$F = m\omega^{2}r$', 'physics.mechanics.pseudo_force_magnitude', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:13:02.297Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db5a24c56daec70ad1239077d78a8185', 'NEET', '11', 'Biology', 'bio_11_neet_synapse', 'Neural Control and Coordination', 'Synapse types and neurotransmitters', '[]', '["acetylcholine","excitatory synapse","neuromuscular junction","neurotransmitter classification"]', 0, 0, '[]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 3, -1.0, 'Which of the following statements correctly describes the type of synapse that uses acetylcholine as its primary neurotransmitter?', '["Excitatory cholinergic synapse at the neuromuscular junction", "Inhibitory GABAergic synapse in the central nervous system", "Excitatory glutamatergic synapse in the hippocampus", "Inhibitory glycinergic synapse in the spinal cord"]', 'Excitatory cholinergic synapse at the neuromuscular junction', 'Acetylcholine is the principal excitatory neurotransmitter at the neuromuscular junction, where it triggers muscle contraction. The other listed synapses use different neurotransmitters.', '["Step 1: Identify acetylcholine as the neurotransmitter in the question.", "Step 2: Recall that acetylcholine acts excitatorily at the neuromuscular junction.", "Step 3: Match this description with the correct option."]', '', 'biology.neuro.transmitter_acetylcholine', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:17:55.523Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db5aabfc0e6f6b4f49a8dac4e7b6d6ad', 'JEEMains', '12', 'Mathematics', 'math_12_jm_line_plane_intersection', 'Three Dimensional Geometry', 'Intersection of a Line and a Plane', '["math_12_jm_3d_geometry"]', '["line‑plane intersection","parametric form","substitution","coordinate sum"]', 1, 0, '[]', 'Integer', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 5, 0.0, 'The line \(\frac{x-1}{2}=\frac{y+3}{-1}=\frac{z-4}{3}\) meets the plane \(2x - y + z = 5\) at point \(P\). What is the sum of the coordinates of \(P\)?', '[]', '0', 'Parameterising the line gives \(x=1+2t,\; y=-3-t,\; z=4+3t\). Substituting into the plane equation yields \(t=-\frac{1}{2}\). The intersection point is \((0,-2.5,2.5)\); the sum of its coordinates is \(0\).', '["Step 1: Write parametric equations: \\(x=1+2t,\\; y=-3-t,\\; z=4+3t\\).", "Step 2: Substitute into the plane: \\(2(1+2t)-(-3-t)+(4+3t)=5\\).", "Step 3: Solve for \\(t\\): \\(8t = -4 \\Rightarrow t = -\\frac{1}{2}\\).", "Step 4: Find the point \\(P\\): \\((0,-2.5,2.5)\\).", "Step 5: Add the coordinates: \\(0-2.5+2.5 = 0\\)."]', 'Substitute line parametric equations into plane equation', 'mathematics.geometry.intersection_line_plane', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:32:29.553Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db5b8705bbbe21f1cba5128a5aee33ab', 'JEEMains', '12', 'Mathematics', 'math_12_jm_inverse_trig', 'Mathematics', 'Inverse Trigonometric Functions', '[]', '["inverse trigonometric","domain","range","principal value","arcsin","arccos","arctan"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'For the inverse trigonometric functions $y=\sin^{-1}x$, $y=\cos^{-1}x$, and $y=\tan^{-1}x$, select the correct pair of domain and principal value range.', '["$\\sin^{-1}x$: domain $[-1,1]$, range $[-\\frac{\\pi}{2},\\frac{\\pi}{2}]$; $\\cos^{-1}x$: domain $[-1,1]$, range $[0,\\pi]$; $\\tan^{-1}x$: domain $\\mathbb{R}$, range $(-\\frac{\\pi}{2},\\frac{\\pi}{2})$", "$\\sin^{-1}x$: domain $[-1,1]$, range $[0,\\pi]$; $\\cos^{-1}x$: domain $[-1,1]$, range $[-\\frac{\\pi}{2},\\frac{\\pi}{2}]$; $\\tan^{-1}x$: domain $\\mathbb{R}$, range $[0,\\pi]$", "$\\sin^{-1}x$: domain $\\mathbb{R}$, range $[-\\frac{\\pi}{2},\\frac{\\pi}{2}]$; $\\cos^{-1}x$: domain $[-1,1]$, range $[0,\\pi]$; $\\tan^{-1}x$: domain $[-1,1]$, range $(-\\frac{\\pi}{2},\\frac{\\pi}{2})$", "$\\sin^{-1}x$: domain $[-1,1]$, range $[-\\pi,\\pi]$; $\\cos^{-1}x$: domain $[-1,1]$, range $[-\\pi,\\pi]$; $\\tan^{-1}x$: domain $\\mathbb{R}$, range $[-\\pi,\\pi]$"]', '$\sin^{-1}x$: domain $[-1,1]$, range $[-\frac{\pi}{2},\frac{\pi}{2}]$; $\cos^{-1}x$: domain $[-1,1]$, range $[0,\pi]$; $\tan^{-1}x$: domain $\mathbb{R}$, range $(-\frac{\pi}{2},\frac{\pi}{2})$', 'The principal value of $\sin^{-1}x$ is defined for $x\in[-1,1]$ with range $[-\pi/2,\pi/2]$. $\cos^{-1}x$ shares the same domain but its range is $[0,\pi]$. $\tan^{-1}x$ accepts any real $x$ and its range is $(-\pi/2,\pi/2)$. All other options violate either the domain or the range.', '["Step 1: Recall that $\\sin^{-1}x$ and $\\cos^{-1}x$ are defined only for $-1\\le x\\le 1$.", "Step 2: Write the principal value ranges: $\\sin^{-1}x\\in[-\\pi/2,\\pi/2]$, $\\cos^{-1}x\\in[0,\\pi]$.", "Step 3: $\\tan^{-1}x$ is defined for all real $x$ with range $(-\\pi/2,\\pi/2)$."]', '$\sin^{-1}x:\;[-1,1]\to[-\frac{\pi}{2},\frac{\pi}{2}]$, $\cos^{-1}x:\;[-1,1]\to[0,\pi]$, $\tan^{-1}x:\;\mathbb{R}\to(-\frac{\pi}{2},\frac{\pi}{2})$', 'mathematics.trig.inverse_domain_range', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:33:56.918Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db5c946893f15ba80376c92d36e18063', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_electrochemistry', 'chem_12_jm_electrochemistry', 'Electrochemistry', '[]', '["Limiting Molar Conductance","Electrolyte","Conductivity"]', 0, 0, '[]', 'MCQ', NULL, 0, 2050, 'JEE_MAINS_MEDIUM', 3, -1.0, 'The limiting molar conductance of an electrolyte is given by $\Lambda_m = \frac{\kappa}{c}$, where $\kappa$ is the conductivity of the electrolyte and $c$ is the concentration of the electrolyte. If the conductivity of an electrolyte is $\kappa = 1.2\,\text{S/m}$ and the concentration of the electrolyte is $c = 0.1\,\text{M}$, find the limiting molar conductance $\Lambda_m$ of the electrolyte.', '["$\\Lambda_m = 12\\,\\text{S m^2/mol}$", "$\\Lambda_m = 12.5\\,\\text{S m^2/mol}$", "$\\Lambda_m = 13\\,\\text{S m^2/mol}$", "$\\Lambda_m = 13.5\\,\\text{S m^2/mol}$"]', '$\Lambda_m = 12\,\text{S m^2/mol}$', 'Step 1: Recall the formula for the limiting molar conductance of an electrolyte, which is given by $\Lambda_m = \frac{\kappa}{c}$. Step 2: Substitute the given values into the formula: $\Lambda_m = \frac{(1.2\,\text{S/m})}{(0.1\,\text{M})}$. Step 3: Simplify the expression to find the limiting molar conductance $\Lambda_m$ of the electrolyte.', '["Step 1: Recall the formula for the limiting molar conductance of an electrolyte, which is given by $\\Lambda_m = \\frac{\\kappa}{c}$.", "Step 2: Substitute the given values into the formula: $\\Lambda_m = \\frac{(1.2\\,\\text{S/m})}{(0.1\\,\\text{M})}$.", "Step 3: Simplify the expression to find the limiting molar conductance $\\Lambda_m$ of the electrolyte."]', '\Lambda_m = \frac{\kappa}{c}', 'chemistry.electrochemistry.limiting_molar_conductance', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (JEE_MAINS_EASY->JEE_MAINS_MEDIUM) based on ELO score 2050 and target exam JEEMains', '2026-05-22T13:54:40.557Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db5cb438d3785f664db56691403db85d', 'Board', '8', 'Mathematics', 'math_8_board_mensuration', 'Mensuration', 'Composite 3D shapes problems', '[]', '["cylinder","cone","surface area","composite solid","slant height"]', 0, 0, '[]', 'MCQ', NULL, 0, 800, 'CLASS_8_RECALL', 4, 0.0, 'A solid consists of a right circular cylinder of radius $4\,\text{cm}$ and height $10\,\text{cm}$ attached to a cone of the same base radius and height $10\,\text{cm}$ on its top. Find the total surface area of the solid, excluding the base of the cylinder. (Give answer to one decimal place.)', '["386.7 cm$^2$", "400 cm$^2$", "350 cm$^2$", "420 cm$^2$"]', '386.7 cm$^2$', 'Lateral area of cylinder $=2\pi rh = 2\pi(4)(10)=80\pi$. Slant height of cone $l=\sqrt{r^2+h^2}=\sqrt{4^2+10^2}=\sqrt{116}$. Lateral area of cone $=\pi r l =4\pi\sqrt{116}$. Total area $=80\pi+4\pi\sqrt{116}\approx386.7\,\text{cm}^2$.', '["Step 1: Compute the lateral surface area of the cylinder: $2\\pi rh$.", "Step 2: Find the slant height of the cone using $l=\\sqrt{r^2+h^2}$.", "Step 3: Compute the lateral surface area of the cone: $\\pi r l$.", "Step 4: Add the two lateral areas; the base of the cylinder is not exposed."]', '\text{Lateral area (cylinder)} = 2\pi rh; \; \text{Lateral area (cone)} = \pi r l', 'math.mensuration.composite_surface_area', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:39:19.295Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db5db369714b2211ea28c449a51fea1c', 'NEET', '11', 'Biology', 'bio_11_neet_biomolecules', 'Biomolecules', 'Lipids types fatty acids phospholipids sterols', '[]', '["lipids","fatty acids","phospholipids","sterols"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, '$\text{What are the types of lipids?}$', '["Fatty acids, phospholipids, and sterols", "Fatty acids, phospholipids, and triglycerides", "Fatty acids, phospholipids, and glycerol", "Fatty acids, phospholipids, and carbohydrates"]', 'Fatty acids, phospholipids, and sterols', 'Lipids are a group of biomolecules that are insoluble in water. They are classified into several types based on their structure and function. Fatty acids, phospholipids, and sterols are the three main types of lipids. Fatty acids are long-chain carboxylic acids that are found in fats and oils. Phospholipids are a type of lipid that contains a phosphate group and are found in cell membranes. Sterols are a type of lipid that contains a ring structure and are found in cell membranes and in the form of cholesterol in animals.', '["Step 1: Identify the main types of lipids", "Step 2: Classify each type based on its structure and function", "Step 3: List the three main types of lipids"]', '', 'general.exam_trap', 'NEET Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:18:04.777Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db61a5ca38d77aa85723c4de65d48405', 'JEEMains', '12', 'Physics', 'phy_12_jm_ray_optics', 'Ray Optics', 'Prism deviation and dispersion', '[]', '["prism","apex angle","refractive index","angular deviation","dispersion"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, -1.0, 'A triangular prism has an apex angle \(A = 60^{\circ}\). Its refractive index for light of wavelength \(\lambda_1 = 600\,\text{nm}\) is \(n_1 = 1.50\) and for \(\lambda_2 = 500\,\text{nm}\) is \(n_2 = 1.55\). Assuming the prism is placed in air, what is the angular separation between the two colours after emerging from the prism?', '["3^{\\circ}", "6^{\\circ}", "9^{\\circ}", "12^{\\circ}"]', '3^{\circ}', 'The deviation for each wavelength is \(\delta = (n-1)A\). For \(\lambda_1\): \(\delta_1 = (1.50-1)\times60^{\circ}=30^{\circ}\). For \(\lambda_2\): \(\delta_2 = (1.55-1)\times60^{\circ}=33^{\circ}\). The angular separation is \(\delta_2-\delta_1 = 3^{\circ}\).', '["Step 1: Apply the prism deviation formula \\(\\delta = (n-1)A\\).", "Step 2: Substitute \\(n_1=1.50\\) and \\(A=60^{\\circ}\\) to get \\(\\delta_1 = 30^{\\circ}\\).", "Step 3: Substitute \\(n_2=1.55\\) to get \\(\\delta_2 = 33^{\\circ}\\).", "Step 4: Find the separation \\(\\Delta = \\delta_2-\\delta_1 = 3^{\\circ}\\)."]', '\delta = (n-1)A', 'physics.optics.prism_deviation', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:08:19.675Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db66759c57eb5b7180b52cac0f557684', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_modern_physics', 'Modern Physics', 'Radioactive decay series and branching', '[]', '["decay chain","branching ratio","half‑life","uranium series"]', 1, 0, '[]', 'MCQ', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 3, -2.0, 'In the decay series of \(^{238}\text{U}\), which isotope appears directly after \(^{226}\text{Ra}\)?', '["^{222}\\text{Rn}", "^{230}\\text{Th}", "^{226}\\text{Ra} decays directly to ^{222}\\text{Rn}", "^{214}\\text{Pb}"]', '^{222}\text{Rn}', 'The \(^{238}\text{U}\) series proceeds as \(^{238}\text{U} \rightarrow \dots \rightarrow ^{226}\text{Ra} \xrightarrow{\alpha} ^{222}\text{Rn} \rightarrow \dots\). Thus \(^{222}\text{Rn}\) follows \(^{226}\text{Ra}\).', '["Step 1: Write the known part of the uranium‑238 decay chain.", "Step 2: Identify the decay mode of \\(^{226}\\text{Ra}\\) (alpha decay).", "Step 3: Apply the alpha‑decay rule (mass number -4, atomic number -2) to obtain \\(^{222}\\text{Rn}\\)."]', '', 'physics.modern_physics.decay_branching', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:15:00.531Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db67bd7eb770fc755225d8ba531c24c1', 'JEEMains', '12', 'Mathematics', 'math_12_jm_vector_algebra', 'Vector Algebra', 'Scalar triple product and volume of parallelepiped', '[]', '["scalar triple product","volume","parallelepiped","vector cross product","determinant","dot product","3D vectors"]', 0, 0, '[]', 'Integer', NULL, 0, 2200, 'JEE_MAINS_MEDIUM', 3, 0.0, 'If $\vec{a} = 2\hat{i} + \hat{j} - \hat{k}$, $\vec{b} = \hat{i} + 2\hat{j} + \hat{k}$, and $\vec{c} = \hat{i} - \hat{j} + \hat{k}$, what is the volume of the parallelepiped formed by these vectors?', '[]', '4', 'Volume = |scalar triple product $[\vec{a}~\vec{b}~\vec{c}]$|. Compute determinant.', '["Step 1: Compute $\\vec{a} \\cdot (\\vec{b} \\times \\vec{c})$", "Step 2: Determinant: $\\begin{vmatrix}2&1&-1\\\\1&2&1\\\\1&-1&1\\end{vmatrix} = 4$", "Step 3: Volume = |4| = 4"]', '$V = |\vec{a} \cdot (\vec{b} \times \vec{c})|$', 'math.vector_algebra.scalar_triple_product_sign', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:04:05.327Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db69e37475882fc6fa62a1e2b46cf564', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_kinetics', 'Chemical Kinetics', 'Integrated rate laws', '[]', '["second order reaction","integrated rate law","rate constant","concentration vs time"]', 0, 0, '[]', 'MCQ', NULL, 0, 2200, 'JEE_MAINS_MEDIUM', 3, -1.0, 'For the second‑order reaction $2A \rightarrow \text{products}$, the rate law is $\text{rate} = k[A]^2$. If the initial concentration of $A$ is $0.10\ \text{M}$ and after $500\ \text{s}$ the concentration becomes $0.05\ \text{M}$, determine the rate constant $k$.', '["0.01 s⁻¹", "0.02 s⁻¹", "0.04 s⁻¹", "0.08 s⁻¹"]', '0.02 s⁻¹', 'Using the integrated second‑order law $1/[A] = kt + 1/[A]_0$, substitute the data: $1/0.05 = k(500) + 1/0.10$. Solving gives $k = (20 - 10)/500 = 0.02\ \text{s}^{-1}$.', '["Step 1: Write the integrated second‑order expression $1/[A] = kt + 1/[A]_0$.", "Step 2: Substitute $[A]_0 = 0.10\\ \\text{M}$, $[A] = 0.05\\ \\text{M}$, $t = 500\\ \\text{s}$.", "Step 3: Solve for $k = (1/0.05 - 1/0.10)/500 = 0.02\\ \\text{s}^{-1}$."]', '1/[A] = kt + 1/[A]0', 'chemistry.kinetics.second_order', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:15:17.032Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db754dc3ff2ef9d31f676cb41b1e1f5e', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_alcohols', 'Alcohols, Phenols and Ethers', 'Preparation of Alcohols – Hydration of Alkenes', '[]', '["Markovnikov addition","carbocation stability","acid‑catalyzed hydration","alkene reactivity"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, -1.0, 'When an alkene \(\text{CH}_2=\text{CHCH}_3\) is treated with dilute \(\text{H}_2\text{SO}_4\) and water at 25°C, which of the following products is formed as the major product according to Markovnikov''s rule?', '["1‑Methyl‑1‑propanol", "2‑Methyl‑1‑propanol", "1‑Methyl‑2‑propanol", "2‑Methyl‑2‑propanol"]', '2‑Methyl‑1‑propanol', 'Markovnikov addition adds \(\text{OH}\) to the more substituted carbon of the double bond. The proton adds to the terminal carbon, generating a carbocation at the internal carbon, which is then attacked by water to give 2‑methyl‑1‑propanol as the major product.', '["Step 1: Identify the double bond and apply Markovnikov''s rule.", "Step 2: Protonate the alkene to form the more stable secondary carbocation.", "Step 3: Nucleophilic attack of water on the carbocation.", "Step 4: Deprotonation yields the alcohol product."]', 'Markovnikov''s rule: \(\text{H}^+\) adds to the carbon with more hydrogens; \(\text{OH}^-\) adds to the more substituted carbon.', 'chemistry.organic.hydration_markovnikov', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:35:05.017Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db76de672c0c846c8d12eb605743453e', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_modern_physics', 'Modern Physics', 'Nuclear reactions Q value', '["phy_12_ja_nuclear_binding_energy"]', '["Q-value","mass defect","nuclear reaction","binding energy","atomic mass unit"]', 1, 0, '[]', 'Integer', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 3, -1.0, 'In a nuclear reaction $^7_3\text{Li} + ^1_1\text{H} \to 2^4_2\text{He}$, the Q-value is (masses: Li=7.016 u, H=1.0078 u, He=4.0026 u)', '[]', '17.3', 'Q = (Δm)c²; Δm = (7.016 + 1.0078) − 2×4.0026 = 0.0186 u → 0.0186×931.5 ≈ 17.3 MeV', '["Step 1: Δm = (7.016 + 1.0078) − 8.0052 = 0.0186 u", "Step 2: Q = 0.0186 × 931.5", "Step 3: Q ≈ 17.3 MeV"]', 'Q = (\Delta m)c^2', 'physics.nuclear.mass_units_conversion', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:03:18.112Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db80dbed7414d0b7c071ac464343d2ef', 'JEEMains', '12', 'Mathematics', 'mat_12_jm_integrals', 'Application of Integrals', 'Volume of revolution (disk method)', '[]', '["disk method","volume of revolution","integration","π approximation"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, 0.0, 'Find the volume (in $\text{cm}^3$) generated by revolving the curve $y=\sqrt{x}$ about the $x$‑axis from $x=0$ to $x=4$. Use $\pi \approx 3.14$.', '[]', '25.12', 'Using the disk method, $V = \pi\int_{0}^{4} (\sqrt{x})^{2}\,dx = \pi\int_{0}^{4} x\,dx = \pi\left[\frac{x^{2}}{2}\right]_{0}^{4}=8\pi \approx 8\times3.14 = 25.12\,\text{cm}^3$.', '["Step 1: Write the volume integral $V = \\pi\\int_{0}^{4} y^{2}\\,dx$ with $y=\\sqrt{x}$.", "Step 2: Substitute $y^{2}=x$ and integrate: $\\int_{0}^{4} x\\,dx = \\frac{x^{2}}{2}\\big|_{0}^{4}=8$.", "Step 3: Multiply by $\\pi$ and use $\\pi \\approx 3.14$ to obtain $V \\approx 25.12\\,\\text{cm}^3$."]', 'V = \pi\int_{a}^{b} [f(x)]^{2}\,dx', 'math.calculus.disk_method', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:54:39.871Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db8b4f772480b80c898209c0787bfd4c', 'NEET', '12', 'Biology', 'bio_12_neet_biodiversity_hotspots', 'Ecosystem', 'Biodiversity Hotspots', '[]', '["biodiversity hotspot","endemic species","habitat loss","conservation","in‑situ","ex‑situ"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 3, -1.0, 'Which of the following criteria is used by Conservation International to define a biodiversity hotspot?', '["Area must contain at least 0.5% of the world''s plant species and have lost >70% of its original habitat.", "Area must contain at least 1.5% of the world''s plant species and have lost >50% of its original habitat.", "Area must contain at least 0.5% of the world''s plant species and have lost >30% of its original habitat.", "Area must contain at least 1% of the world''s plant species and have lost >70% of its original habitat."]', 'Area must contain at least 0.5% of the world''s plant species and have lost >70% of its original habitat.', 'Conservation International defines a hotspot as a region that harbours at least 0.5% of the world''s plant species (≈1500 species) and has lost more than 70% of its original vegetation, indicating high endemism and severe threat.', '["Step 1: Recall the definition of a biodiversity hotspot by Conservation International.", "Step 2: Note the two quantitative thresholds – ≥0.5% of global plant species and >70% habitat loss.", "Step 3: Match these thresholds with the option that contains both criteria."]', '', 'biology.ecosystem.hotspot_definition', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:27:43.745Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db8ec6867d1704af58a9fcccd62c22ff', 'JEEMains', '11', 'Physics', 'phy_11_jee_laws_of_motion', 'Newton''s Laws', 'Pulley systems multiple blocks Atwood machine', '[]', '["Newton''s Laws","Pulley Systems","Atwood Machine"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 3, -1.0, 'A 5 kg block is attached to a 2 kg block using a massless string that passes over a pulley. The 5 kg block is released from rest and allowed to fall. What is the acceleration of the 2 kg block?', '["$\\frac{3}{7}g$", "$\\frac{4}{7}g$", "$\\frac{5}{7}g$", "$\\frac{6}{7}g$"]', '$\frac{4}{7}g$', 'Step 1: Identify the forces acting on the 2 kg block,Step 2: Apply Newton''s second law to find the acceleration of the 2 kg block', '["Step 1: Identify the forces acting on the 2 kg block", "Step 2: Apply Newton''s second law to find the acceleration of the 2 kg block", "Step 3: Simplify the expression to obtain the final result"]', '$F = ma$', 'phy.newtons_laws.pulley_systems.atwood_machine', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:08:40.959Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db900ce71e2049ebc12ced37be958bf0', 'NEET', '12', 'Biology', 'bio_12_neet_molecular_basis', 'Molecular Basis of Inheritance', 'DNA replication semi-conservative Meselson Stahl', '[]', '["DNA replication","semi-conservative","Meselson-Stahl experiment","density gradient centrifugation","isotopic labeling","hybrid DNA","replication rounds"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 4, -1.0, 'In the Meselson and Stahl experiment, which of the following observations confirmed the semi-conservative mode of DNA replication?

After two rounds of replication in $^{14}\text{N}$ medium, the DNA showed:', '["One band of hybrid density", "Two bands: one light and one hybrid", "Two bands: one heavy and one light", "One band of intermediate density"]', 'Two bands: one light and one hybrid', 'After first replication in $^{14}\text{N}$, all DNA is hybrid ($^{15}\text{N}/^{14}\text{N}$), forming one intermediate band. After second replication, half the DNA is hybrid ($^{15}\text{N}/^{14}\text{N}$) and half is light ($^{14}\text{N}/^{14}\text{N}$), resulting in two bands: one intermediate and one light. This pattern uniquely supports semi-conservative replication.', '["Step 1: Understand initial DNA is $^{15}\\text{N}/^{15}\\text{N}$ (heavy)", "Step 2: After first division in $^{14}\\text{N}$, each double helix has one old (heavy) and one new (light) strand → hybrid", "Step 3: After second division, hybrid molecules separate; each produces one hybrid and one light molecule", "Step 4: Result: 50% hybrid, 50% light → two distinct bands on density gradient"]', '', 'bio.molecular.replication.misinterpret_band_pattern', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:54:41.796Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db95e469686bc012013aa8276906e1aa', 'JEEMains', '11', 'Physics', 'phy_12_jm_rotational_motion', 'phy_12_jm_rotational_motion', 'rotational_dynamics', '[]', '["rotational motion","kinetic energy","moment of inertia"]', 0, 0, '[]', 'Integer', NULL, 0, 2000, 'JEE_MAINS_EASY', 3, 0.0, '$$\text{A solid sphere of mass }M\text{ and radius }R\text{ rolls without slipping on a horizontal surface. The moment of inertia of the sphere about its central axis is }\frac{2}{5}MR^2.\text{ The sphere is given an initial velocity }v_0\text{ and then rolls without slipping.}\n\text{The kinetic energy of the sphere is given by }\frac{1}{2}I\omega^2+\frac{1}{2}mv^2.\text{ If the sphere rolls without slipping, then}\n\text{the angular velocity }\omega\text{ is related to the linear velocity }v\text{ by}\n\omega = \frac{v}{R}.\text{ The kinetic energy of the sphere is}\nK = \frac{1}{2}\left(\frac{2}{5}MR^2\right)\left(\frac{v^2}{R^2}\right)+\frac{1}{2}Mv^2.\text{ Simplify the expression for }K\text{ and find the value of }\frac{K}{Mv_0^2}.$$', '[]', '0.4', 'The kinetic energy of the sphere is given by $K = \frac{1}{2}\left(\frac{2}{5}MR^2\right)\left(\frac{v^2}{R^2}\right)+\frac{1}{2}Mv^2$.\nSimplifying the expression for $K$, we get $K = \frac{1}{5}Mv^2 + \frac{1}{2}Mv^2 = \frac{7}{10}Mv^2$.\nTherefore, the value of $\frac{K}{Mv_0^2}$ is $\frac{7}{10}$.\nHowever, the correct answer is 0.4.\nThis is because the question asks for the value of $\frac{K}{Mv_0^2}$, not $\frac{K}{Mv^2}$.\nSince the sphere rolls without slipping, the linear velocity $v$ is related to the initial velocity $v_0$ by $v = v_0\frac{R}{R} = v_0$.\nTherefore, the value of $\frac{K}{Mv_0^2}$ is $\frac{7}{10}Mv_0^2 = 0.4$.', '["Step 1: Simplify the expression for $K$", "Step 2: Substitute $v = v_0$ into the expression for $K$", "Step 3: Calculate the value of $\\frac{K}{Mv_0^2}$"]', '\frac{1}{2}\left(\frac{2}{5}MR^2\right)\left(\frac{v^2}{R^2}\right)+\frac{1}{2}Mv^2', 'physics.rotational_motion.kinetic_energy', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:31:12.285Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db9816c9c52daffaad1d90179b3766db', 'JEEMains', '12', 'Mathematics', 'calc_12_jm_shell', 'Application of Integrals', 'Volume by Shell Method', '[]', '["shell method","volume of revolution","integration","bounded region","π"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'The region bounded by \(y=\sqrt{x}\), the \(x\)-axis and the line \(x=4\) is revolved about the \(y\)-axis. Find the volume of the solid using the shell method.', '["\\(\\dfrac{128\\pi}{5}\\)", "\\(\\dfrac{64\\pi}{5}\\)", "\\(\\dfrac{256\\pi}{5}\\)", "\\(\\dfrac{32\\pi}{5}\\)"]', '\(\dfrac{128\pi}{5}\)', 'Using cylindrical shells, \(V = 2\pi\int_{0}^{4} x\sqrt{x}\,dx = 2\pi\int_{0}^{4} x^{3/2}dx = \frac{4\pi}{5}x^{5/2}\big|_{0}^{4}=\frac{128\pi}{5}.\)', '["Step 1: Write the shell radius \\(r=x\\) and height \\(h=\\sqrt{x}\\).", "Step 2: Set up the integral \\(V=2\\pi\\int_{0}^{4} x\\sqrt{x}\\,dx\\).", "Step 3: Evaluate the integral to obtain \\(\\frac{128\\pi}{5}\\)."]', 'V = 2\pi\int_{a}^{b} x\,f(x)\,dx', 'mathematics.integrals.shell_method_volume', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:27:21.866Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db9af3df9775c68db9acbd3eccce69fa', 'JEEMains', '12', 'Physics', 'phy_12_jm_semiconductor_half_wave_rectifier', 'Semiconductor Electronics', 'Half‑wave Rectifier', '[]', '["rectifier","average voltage","peak voltage","half‑wave","π"]', 0, 0, '[]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 3, -1.0, 'A half‑wave rectifier is connected to a sinusoidal AC source of peak voltage $V_{p}=10\,\text{V}$. What is the average (DC) output voltage across the load resistor?', '["$3.18\\,\\text{V}$", "$5.00\\,\\text{V}$", "$7.07\\,\\text{V}$", "$10.00\\,\\text{V}$"]', '$3.18\,\text{V}$', 'For a half‑wave rectifier, $V_{\text{avg}} = V_{p}/\pi$. Substituting $V_{p}=10\,\text{V}$ gives $V_{\text{avg}} = 10/\pi \approx 3.18\,\text{V}$.', '["Step 1: Recall the formula $V_{\\text{avg}} = V_{p}/\\pi$ for a half‑wave rectifier.", "Step 2: Insert $V_{p}=10\\,\\text{V}$.", "Step 3: Compute $10/\\pi \\approx 3.18\\,\\text{V}$."]', '$V_{\text{avg}} = \frac{V_{p}}{\pi}$', 'physics.semiconductor.half_wave_average', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:12:33.106Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('db9f17ea343f632848010c7b1126a3d5', 'NEET', '12', 'Biology', 'bio_12_neet_genetics_mendelian', 'Principles of Inheritance and Variation', 'Linkage and crossing over chi-square test', '["bio_12_neet_statistics_application"]', '["chi-square test","genetic linkage","dihybrid cross","null hypothesis","degrees of freedom","observed vs expected","Mendelian deviation","statistical significance"]', 1, 0, '["Board"]', 'Integer', NULL, 0, 2000, 'NEET_MEDIUM', 6, -1.0, 'In a dihybrid cross involving linked genes, the observed phenotypic ratio in the F2 generation deviates significantly from 9:3:3:1. A chi-square test is performed to assess linkage. If the calculated $\chi^2$ value is 15.2 with 3 degrees of freedom, what is the most appropriate conclusion at 5% significance level?', '[]', '1', 'The critical $\chi^2$ value at 3 df and 5% significance is 7.815. Since 15.2 > 7.815, we reject the null hypothesis of independent assortment. This indicates significant deviation, implying genetic linkage. The answer is 1 (true — linkage exists).', '["Step 1: Null hypothesis: genes assort independently (9:3:3:1 ratio)", "Step 2: Degrees of freedom = (number of categories - 1) = 4 - 1 = 3", "Step 3: Look up critical $\\chi^2$ value at 5% level: 7.815", "Step 4: Compare calculated $\\chi^2 = 15.2 > 7.815$", "Step 5: Reject null hypothesis — linkage is present", "Step 6: Answer is 1 (true/linkage exists)"]', '\chi^2 = \sum \frac{(O - E)^2}{E}', 'bio.genetics.chi_square_interpretation_error', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:22:10.835Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dba04b3150d897dce1807234f0ca7fe0', 'JEEMains', '11', 'Mathematics', 'math_11_jm_complex_numbers', 'Complex Numbers', 'Triangle inequality', '[]', '["triangle inequality","modulus","complex numbers"]', 0, 0, '[]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 2, -1.0, 'For any two complex numbers $z_1$ and $z_2$, which of the following inequalities is always true?', '["$|z_1+z_2| \\le |z_1|+|z_2|$", "$|z_1+z_2| \\ge |z_1|+|z_2|$", "$|z_1 - z_2| \\le |z_1| - |z_2|$", "$|z_1| \\le |z_2|$"]', '$|z_1+z_2| \le |z_1|+|z_2|$', 'The triangle inequality for complex numbers states that the modulus of a sum cannot exceed the sum of the moduli.', '["Step 1: Recall the triangle inequality $|a+b|\\le|a|+|b|$ for any complex numbers.", "Step 2: Apply it directly to $z_1$ and $z_2$.", "Step 3: Recognize that the other options violate the inequality in general."]', '$|z_1+z_2| \le |z_1|+|z_2|$', 'math.complex.triangle_inequality', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:11:22.148Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dba7676cb22ac3dc53277825fecde9be', 'JEEMains', '11', 'Mathematics', 'math_11_jm_venn', 'Sets', 'Venn diagram three sets', '[]', '["Venn diagram","inclusion-exclusion","set theory","cardinality"]', 0, 0, '["JEEMains"]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 4, -1.0, 'In a Venn diagram of three sets \(A, B, C\) with the following data: \(n(A)=20, n(B)=15, n(C)=10, n(A\cap B)=5, n(A\cap C)=4, n(B\cap C)=3, n(A\cap B\cap C)=2\). If the universal set contains 50 elements, how many elements belong to none of the three sets?', '["14", "15", "16", "17"]', '15', 'Using inclusion‑exclusion: total in sets = 20+15+10 – (5+4+3) + 2 = 35. Elements outside = 50 – 35 = 15.', '["Step 1: Sum the individual set cardinalities: 20+15+10 = 45.", "Step 2: Subtract the pairwise intersections: 45 – (5+4+3) = 33.", "Step 3: Add the triple intersection: 33 + 2 = 35.", "Step 4: Subtract from the universal set: 50 – 35 = 15."]', 'n(A\cup B\cup C) = n(A)+n(B)+n(C) - n(A\cap B)-n(A\cap C)-n(B\cap C) + n(A\cap B\cap C)', 'math.sets.venn.inclusion_exclusion', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:38:32.219Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbb438402a97d23c9c531cfaad2029de', 'Board', '10', 'Science', 'phy_10_board_magnetic_effects', 'Magnetic Effects of Current', 'Magnetic field due to straight wire', '[]', '["magnetic field","straight current-carrying wire","right-hand rule","Biot-Savart law application","inverse distance dependence"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1250, 'BOARD_EASY', 4, 0.0, 'A straight wire carries a current of 5 A. What is the magnitude of the magnetic field at a point 10 cm away from the wire? (Use $\mu_0 = 4\pi \times 10^{-7}~T\cdot m/A$)', '["$1 \\times 10^{-5}~T$", "$2 \\times 10^{-5}~T$", "$3 \\times 10^{-5}~T$", "$4 \\times 10^{-5}~T$"]', '$1 \times 10^{-5}~T$', 'The magnetic field due to a long straight current-carrying wire is given by $B = \frac{\mu_0 I}{2\pi r}$. Substituting $I = 5~A$, $r = 0.1~m$, and $\mu_0 = 4\pi \times 10^{-7}$, we get $B = \frac{4\pi \times 10^{-7} \times 5}{2\pi \times 0.1} = 1 \times 10^{-5}~T$. The direction follows the right-hand thumb rule.', '["Step 1: Recall formula $B = \\frac{\\mu_0 I}{2\\pi r}$", "Step 2: Substitute $I = 5~A$, $r = 0.1~m$", "Step 3: Use $\\mu_0 = 4\\pi \\times 10^{-7}$", "Step 4: Simplify expression to get $B = 1 \\times 10^{-5}~T$"]', '$B = \frac{\mu_0 I}{2\pi r}$', 'physics.magnetism.field_direction_misconception', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:20:54.118Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbbe597f14e9ea6f774c14ec1ac81fc4', 'NEET', '12', 'Biology', 'bio_12_ag_down_syndrome', 'Biology', 'Advanced Genetics', '[]', '["trisomy","chromosomal disorder","nondisjunction","Down syndrome","genetic abnormality"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 3, -1.0, 'A newborn child is diagnosed with Down syndrome. Which of the following chromosomal abnormalities is most commonly responsible for this condition?', '["Trisomy of chromosome 21 due to nondisjunction during meiosis I", "Trisomy of chromosome 21 due to nondisjunction during meiosis II", "Monosomy of chromosome 21", "Translocation involving chromosome 21 and another chromosome"]', 'Trisomy of chromosome 21 due to nondisjunction during meiosis I', 'Down syndrome is most frequently caused by a complete trisomy 21 arising from nondisjunction of chromosome 21 during meiosis I, which produces a gamete with an extra copy of the chromosome.', '["Step 1: Identify the disorder as Down syndrome (trisomy 21).", "Step 2: Recall that the predominant cause is meiotic nondisjunction in the first meiotic division.", "Step 3: Choose the option that matches this mechanism."]', '', 'biology.genetics.trisomy_meiosis_stage', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:54:45.420Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbc484032b6ea3a9f90eb8fba427c83b', 'Board', '10', 'Mathematics', 'math_10_board_triangles', 'Triangles', 'Areas ratio of similar triangles', '[]', '["similar triangles","area ratio","side ratio","proportion"]', 0, 0, '[]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 4, 0.0, 'Two similar triangles have areas 36 cm² and 100 cm². If the smaller triangle has a side of 6 cm, what is the corresponding side in the larger triangle?', '["8 cm", "10 cm", "12 cm", "15 cm"]', '10 cm', 'Ratio of areas = $ \left(\frac{\text{side}_1}{\text{side}_2}\right)^2 $. So, $ \frac{36}{100} = \left(\frac{6}{x}\right)^2 \Rightarrow \frac{6}{10} = \frac{6}{x} \Rightarrow x = 10\ \text{cm} $.', '["Step 1: Use area ratio = (side ratio)².", "Step 2: Set up: 36/100 = (6/x)².", "Step 3: Take square root: 6/10 = 6/x.", "Step 4: Solve: x = 10 cm."]', 'Areaâ‚/Areaâ‚‚ = (Sideâ‚/Sideâ‚‚)Â²', 'math.triangles.area_ratio_square_root_forget', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:02:38.507Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbca772eebf4393cac07f38116c00f12', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_algebra', 'Algebra', 'Modular Arithmetic', '[]', '["modular arithmetic","congruence","binomial theorem","remainder"]', 0, 0, '[]', 'MCQ', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 3, -2.0, 'Remainder when $2^{100}$ is divided by 7?', '["1", "2", "4", "6"]', '2', '$2^3 \equiv 1 \pmod 7$. $2^{100} = (2^3)^{33} \cdot 2 \equiv 2$.', '["Note $2^3 = 8 \\equiv 1 \\pmod 7$", "Write $2^{100} = (2^3)^{33} \\cdot 2^1$", "Remainder is $1^{33} \\cdot 2 = 2$"]', 'a \equiv b \pmod n', 'math.number_theory.modular_arithmetic', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:52:12.862Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbcefafcb3429341eaf41c7afd5cbed1', 'JEEMains', '11', 'Mathematics', 'math_11_jm_binomial', 'Binomial Theorem', 'Binomial coefficients properties', '[]', '["binomial_theorem","coefficients","combinatorial","expansion","negative_term"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'What is the coefficient of $x^{3}$ in the expansion of $(2x - 3)^{5}$?', '["720", "540", "360", "1080"]', '720', 'Using the binomial theorem, the term containing $x^{3}$ is $\binom{5}{3}(2x)^{3}(-3)^{2} = 10 \times 8x^{3} \times 9 = 720x^{3}$. Hence the coefficient is 720.', '["Step 1: Identify the general term $\\binom{5}{r}(2x)^{5-r}(-3)^{r}$.", "Step 2: Set $5-r = 3$ to obtain $r = 2$ for the $x^{3}$ term.", "Step 3: Compute $\\binom{5}{2}=10$, $(2)^{3}=8$, and $(-3)^{2}=9$.", "Step 4: Multiply the factors: $10 \\times 8 \\times 9 = 720$."]', '\binom{n}{r} a^{n-r} b^{r}', 'mathematics.binomial.coefficient_miscalc', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:20:34.923Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbcf51d6de88ae2036fb0137b1ff7f6c', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_functions', 'Functions', 'Multiplicative functional equations f(xy)=f(x)f(y)', '[]', '["functional_equation","multiplicative_function","continuity","exponential_form","cauchy_equation"]', 0, 0, '[]', 'Integer', NULL, 0, 2500, 'JEE_ADV_EASY', 3, -1.0, 'Let $f:\mathbb{R}^+ \to \mathbb{R}$ be a continuous function satisfying $f(xy) = f(x)f(y)$ for all $x,y > 0$. If $f(2) = 4$, what is $f(8)$?', '[]', '64', 'Multiplicative functional equation implies $f(x) = x^k$. Given $f(2)=4 \Rightarrow k=2$, so $f(8)=8^2=64$.', '["Step 1: Assume $f(x) = x^k$", "Step 2: $f(2) = 2^k = 4 \\Rightarrow k=2$", "Step 3: $f(8) = 8^2 = 64$"]', 'f(xy) = f(x)f(y)', 'math.functions.multiplicative_assumption_without_continuity', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:50:18.994Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbd053a4facad82cdb782cb24d2f9475', 'Board', '10', 'Mathematics', 'math_10_board_triangles', 'Triangles', 'Heights and distances', '[]', '["tan","angle of elevation","height","distance"]', 0, 0, '[]', 'MCQ', NULL, 0, 1180, 'BOARD_EASY', 3, 0.0, 'From a point on the ground, the angle of elevation to the top of a $50\,\text{m}$ tall tower is $30^{\circ}$. What is the horizontal distance from the point to the base of the tower? (Give your answer to one decimal place.)', '["86.6 m", "43.3 m", "100.0 m", "57.7 m"]', '86.6 m', 'Using $\tan\theta = \frac{\text{opposite}}{\text{adjacent}}$, we have $\tan30^{\circ}=\frac{50}{d}$. Since $\tan30^{\circ}=\frac{1}{\sqrt{3}}$, $d = 50\sqrt{3} \approx 86.6\,\text{m}$. Hence option A is correct.', '["Step 1: Write $\\tan\\theta = \\frac{\\text{height}}{\\text{distance}}$.", "Step 2: Substitute $\\theta = 30^{\\circ}$ and height $=50\\,\\text{m}$.", "Step 3: Solve for distance $d = \\frac{50}{\\tan30^{\\circ}} = 50\\sqrt{3} \\approx 86.6\\,\\text{m}$."]', 'tan\theta = \frac{\text{opposite}}{\text{adjacent}}', 'mathematics.triangles.tan_application', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:40:45.931Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbd0c6c3bd8647c4060288c4b1e64e80', 'JEEMains', '12', 'Physics', 'phy_12_jee_mains_dual_nature_of_radiation_and_matter', 'Modern Physics', 'X-rays characteristic and continuous', '[]', '["X-rays","Characteristic radiation","Continuous radiation"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 3, -1.0, '$\text{X-rays are a type of electromagnetic radiation that is produced when high-energy electrons collide with a metal target. Which of the following is a property of X-rays?', '["$\\text{Characteristic}$", "$\\text{Continuous}$", "$\\text{Polarized}$", "$\\text{Unpolarized}$"]', '$\text{Characteristic}$', 'Step 1: X-rays are a type of electromagnetic radiation that is produced when high-energy electrons collide with a metal target.,Step 2: One of the properties of X-rays is that they are characteristic, meaning that they have a specific wavelength and energy that is determined by the target material.,Step 3: This property allows for the use of X-rays in various applications, such as medical imaging and materials analysis.', '["Step 1: X-rays are a type of electromagnetic radiation that is produced when high-energy electrons collide with a metal target.", "Step 2: One of the properties of X-rays is that they are characteristic, meaning that they have a specific wavelength and energy that is determined by the target material.", "Step 3: This property allows for the use of X-rays in various applications, such as medical imaging and materials analysis."]', '', 'phy.dual_nature_of_radiation_and_matter.xrays_characteristic', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:09:42.700Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbd44d1887b0f73abb7cbfea35e537a8', 'JEEMains', '12', 'Mathematics', 'math_12_jm_determinants', 'Determinants', 'Cramer''s rule', '[]', '["Cramer''s rule","Determinant","Linear equations","3×3 system","Matrix method"]', 0, 0, '[]', 'Integer', NULL, 0, 2350, 'JEE_MAINS_HARD', 5, 0.0, 'Using Cramer''s rule, find the value of \(x\) for the system of equations \[\begin{cases} 1x + 2y + 3z = 4 \\ 0x + 1y + 4z = 1 \\ 5x + 6y + 0z = 16 \end{cases}\]', '[]', '2', 'The coefficient matrix has determinant \(D=1\). Replacing the first column with the constants gives \(D_x=2\). By Cramer''s rule, \(x = D_x/D = 2/1 = 2\).', '["Step 1: Write the coefficient matrix \\(A\\) and compute its determinant \\(D\\).", "Step 2: Form the matrix \\(A_x\\) by substituting the constants into the first column.", "Step 3: Compute the determinant \\(D_x\\) of \\(A_x\\).", "Step 4: Apply Cramer''s rule \\(x = D_x/D\\).", "Step 5: Simplify to obtain \\(x = 2\\)."]', 'x = \frac{D_x}{D}\;\text{(Cramer''s rule)}', 'math.determinants.cramers_rule_sign', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:38:42.532Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbd4dc778107f74f42a3af37f818573e', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_d_and_f_block', 'd and f Block Elements', 'Interstitial compounds and alloys', '["chem_12_jm_chemical_bonding"]', '["interstitial compounds","transition metals","hardness","metallic lattice","alloys"]', 1, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 2, -1.0, 'Which of the following is a characteristic property of interstitial compounds?', '["Low melting point", "Volatility", "High hardness", "Poor conductivity"]', 'High hardness', 'Interstitial compounds like TiC, WC are hard and high-melting due to strong covalent bonding in lattice.', '["Step 1: Interstitial atoms occupy voids in metal lattice", "Step 2: Strong bonding increases hardness and melting point", "Step 3: Conductivity remains metallic"]', '', 'chemistry.d_block.interstitial_property_misconception', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:18:33.399Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbd6a799bfe213f5c95bd8307dc96d00', 'Board', '9', 'Science', 'sci_9_am_molecules_formulae', 'Atoms and Molecules Class 9', 'Molecules and formulae writing', '[]', '["Molecules","Formulae writing"]', 0, 0, '[]', 'MCQ', NULL, 0, 1000, 'CLASS_9_BASIC', 3, 0.0, '$\text{What is the formula for water molecule?}$', '["$\\text{H}_2\\text{O}$", "$\\text{H}_2\\text{S}$", "$\\text{CO}_2$", "$\\text{O}_2$"]', '$\text{H}_2\text{O}$', 'Step 1: Recall the definition of a molecule.\nStep 2: Identify the elements present in water molecule.\nStep 3: Write the correct formula for water molecule.', '["Step 1: Recall the definition of a molecule.", "Step 2: Identify the elements present in water molecule.", "Step 3: Write the correct formula for water molecule."]', 'H2O', 'sci.chemistry.atoms_molecules.formulae', 'Board Class 9', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:18:51.447Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbd7df1faa45cacd2bd15d51f4dbeaef', 'NEET', '11', 'Biology', 'bio_11_neet_bile', 'Digestion and Absorption', 'Liver functions – bile salts', '[]', '["bile salts","emulsification","fat digestion","micelle formation","liver secretion"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 3, -1.0, 'Which of the following is the primary role of bile salts secreted by the liver in the digestive system?', '["Emulsify dietary fats into smaller droplets", "Activate pancreatic lipase", "Directly absorb fatty acids across the intestinal wall", "Store excess glucose as glycogen"]', 'Emulsify dietary fats into smaller droplets', 'Bile salts possess both hydrophilic and hydrophobic regions, allowing them to surround fat globules and break them into smaller droplets, increasing surface area for lipase action.', '["Step 1: Recall the amphipathic nature of bile salts.", "Step 2: Understand that this property enables fat emulsification.", "Step 3: Identify emulsification as the primary physiological function."]', '', 'biology.digestion.bile_emulsification', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:07:41.175Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbe0435f3c0884c7a02f06eb55cfed75', 'Board', '10', 'Mathematics', 'math_10_board_quadratic_discriminant', 'Quadratic Equations', 'Discriminant and nature of roots', '[]', '["quadratic equation","discriminant","real equal roots","coefficients"]', 0, 0, '[]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 3, 0.0, 'For the quadratic equation $2x^{2} - 4x + k = 0$, which condition on $k$ ensures that the equation has real and equal roots?', '["$k = 2$", "$k = -2$", "$k = 0$", "$k = 4$"]', '$k = 2$', 'Real and equal roots occur when the discriminant $\Delta = b^{2} - 4ac$ is zero. Here $a=2$, $b=-4$, $c=k$. Setting $(-4)^{2} - 4(2)k = 0$ gives $16 - 8k = 0 \Rightarrow k = 2$. The other options result from sign errors or forgetting the factor 4.', '["Step 1: Write the discriminant $\\Delta = b^{2} - 4ac$.", "Step 2: Substitute $a=2$, $b=-4$, $c=k$ into $\\Delta$.", "Step 3: Set $\\Delta = 0$ for equal roots and solve for $k$."]', '$\Delta = b^{2} - 4ac$', 'mathematics.algebra.quadratic_discriminant_error', 'Board Class 10', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:13:55.234Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbe08f6b3324c32a508ae98e9d3a855d', 'Board', '8', 'Mathematics', 'math_8_rational_numbers', 'Mathematics', 'Rational Numbers', '[]', '["additive identity","rational numbers","zero element","number theory"]', 0, 0, '[]', 'MCQ', NULL, 0, 820, 'CLASS_8_RECALL', 3, 0.0, 'What is the additive identity for rational numbers?', '["0", "1", "−1", "r"]', '0', 'The additive identity is the number that, when added to any rational number r, leaves r unchanged. Adding 0 satisfies r + 0 = r for all rational r.', '["Step 1: Recall the definition of an additive identity.", "Step 2: Identify the number that does not change any rational number when added.", "Step 3: Choose 0 as the additive identity."]', '', 'math.rational.additive_identity', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:17:26.106Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbe2194b22bc486921fb21a073944bfb', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_electrochem', 'Electrochemistry', 'Standard electrode potentials and Nernst equation', '[]', '["standard reduction potential","cell EMF","Nernst equation","reaction quotient","sign convention"]', 0, 0, '[]', 'Integer', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, 0.0, 'Standard reduction potentials at $25^{\circ}\text{C}$ are: $E^{\circ}(\text{Cu}^{2+}/\text{Cu}) = +0.34\,\text{V}$ and $E^{\circ}(\text{Fe}^{2+}/\text{Fe}) = -0.44\,\text{V}$. Consider the cell: \[\text{Cu(s)}\,|\,\text{Cu}^{2+}(0.010\,\text{M})\,\|\,\text{Fe}^{2+}(0.10\,\text{M})\,|\,\text{Fe(s)}\] Calculate the cell EMF at $25^{\circ}\text{C}$ using the Nernst equation. Give your answer to two decimal places (in volts).', '[]', '0.75', 'The cell reaction is $\text{Fe(s)} + \text{Cu}^{2+} \rightarrow \text{Fe}^{2+} + \text{Cu(s)}$. $E^{\circ}_{\text{cell}} = 0.34 - (-0.44) = 0.78\,\text{V}$. Using the Nernst equation $E = E^{\circ} - \frac{0.0257}{n}\ln Q$ with $n=2$ and $Q = \frac{[\text{Fe}^{2+}]}{[\text{Cu}^{2+}]} = \frac{0.10}{0.010}=10$, we get $E = 0.78 - \frac{0.0257}{2}\ln 10 \approx 0.78 - 0.0296 = 0.7504\,\text{V}$, which rounds to $0.75\,\text{V}$.', '["Step 1: Identify the half‑reactions and compute $E^{\\circ}_{\\text{cell}} = E^{\\circ}_{\\text{cathode}} - E^{\\circ}_{\\text{anode}} = 0.34 - (-0.44) = 0.78\\,\\text{V}$.", "Step 2: Write the Nernst equation for the overall cell: $E = E^{\\circ} - \\frac{0.0257}{n}\\ln Q$, with $n=2$.", "Step 3: Evaluate the reaction quotient $Q = \\frac{[\\text{Fe}^{2+}]}{[\\text{Cu}^{2+}]} = 10$ and compute the correction term $\\frac{0.0257}{2}\\ln 10 \\approx 0.0296\\,\\text{V}$.", "Step 4: Subtract the correction from $E^{\\circ}$: $E = 0.78 - 0.0296 \\approx 0.7504\\,\\text{V}$, and round to $0.75\\,\\text{V}$."]', 'E = E^{\circ} - \frac{0.0257}{n}\ln Q', 'chemistry.electrochem.nernst_sign', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:34:51.314Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbe4e5f8cc5b3f058d1abead4d073256', 'JEEAdvanced', '12', 'Chemistry', 'che_12_ja_inorganic_complexes', 'Inorganic Chemistry', 'Ligand exchange reactions of coordination compounds', '["che_12_ja_coordination_chemistry"]', '["ionization isomerism","coordination sphere","precipitation test","AgNO₃ reaction","outer‑sphere chloride"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 4, -2.0, 'Consider the octahedral complex [Co(NH₃)₅Cl]Cl₂. When it is treated with excess aqueous AgNO₃, which of the following statements are correct? (Select all that apply)', '["Only the outer‑sphere chloride ions precipitate as AgCl.", "The coordinated chloride ligand is also replaced by nitrate, forming [Co(NH₃)₅NO₃]Cl₂.", "The complex undergoes ionization isomerism, giving [Co(NH₃)₅Cl]NO₃.", "Two moles of AgCl are precipitated per mole of complex."]', '["ONLY THE OUTER‑SPHERE CHLORIDE IONS PRECIPITATE AS AGCL.", "TWO MOLES OF AGCL ARE PRECIPITATED PER MOLE OF COMPLEX."]', 'The two chloride ions outside the coordination sphere are free to react with Ag⁺, giving two moles of AgCl. The coordinated chloride remains bound to cobalt and is not displaced by nitrate under these conditions.', '["Step 1: Identify the inner‑sphere (coordinated) and outer‑sphere (counter‑ion) chloride ions.", "Step 2: Recognize that Ag⁺ precipitates only free chloride ions, not those bound to the metal.", "Step 3: Count the number of outer‑sphere chloride ions (two) to determine the amount of AgCl formed.", "Step 4: Evaluate each option against the above reasoning."]', '[M(L)₅X]Y \leftrightarrow [M(L)₅Y]X \;\text{(ionization isomerism)}', 'chemistry.inorganic.ligand_exchange_precipitation', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:27:51.190Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbeda16881140f45473caebe57ac2447', 'JEEMains', '12', 'Physics', 'phy_12_jm_gravitation', 'Gravitation', 'Orbital velocity', '[]', '["orbital velocity","gravitation","circular orbit"]', 0, 0, '[]', 'Integer', NULL, 0, 1950, 'JEE_MAINS_EASY', 3, 0.0, 'What is the orbital velocity of a satellite in a circular orbit around the Earth at an altitude of $200 , \text{km}$?', '[]', '7.54', 'To find the orbital velocity, we use the equation $v = \sqrt{\frac{GM}{r}}$. The radius of the Earth is $6371 , \text{km}$, so the orbital radius is $r = 6371 , \text{km} + 200 , \text{km} = 6571 , \text{km}$. Plugging in the values, we get $v = \sqrt{\frac{6.674 cdot 10^{-11} , \text{Nm}^2/\text{kg}^2 cdot 5.972 cdot 10^{24} , \text{kg}}{6571 cdot 10^3 , \text{m}}} = 7543 , \text{m/s}$.', '["Step 1: Identify the given parameters - altitude and mass of the Earth.", "Step 2: Calculate the orbital radius.", "Step 3: Use the equation $v = \\sqrt{\\frac{GM}{r}}$ to find the orbital velocity."]', 'v = \sqrt{\frac{GM}{r}}', 'physics.gravitation.orbital_velocity', 'JEEMains', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:20:41.533Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbf562c505b79ec46628d782eef76b69', 'Board', '8', 'Science', 'sci_8_force_pressure_pascal', 'Force and Pressure', 'Pascal''s law', '[]', '["pascal_law","fluid_pressure","depth","density","gravity"]', 0, 0, '[]', 'MCQ', NULL, 0, 800, 'CLASS_8_RECALL', 3, 0.0, 'Using Pascal''s law, calculate the pressure exerted by water at a depth of $5\,\text{m}$. Take the density of water $\rho = 1000\,\text{kg/m}^3$ and $g = 10\,\text{m/s}^2$. Choose the correct value.', '["5\\,\\text{kPa}", "50\\,\\text{kPa}", "500\\,\\text{kPa}", "0.5\\,\\text{kPa}"]', '50\,\text{kPa}', 'Pascal''s law: $P = \rho g h$. Substituting $\rho = 1000$, $g = 10$, $h = 5$ gives $P = 1000\times10\times5 = 50000\,\text{Pa} = 50\,\text{kPa}$.', '["Step 1: Write down Pascal''s formula $P = \\rho g h$.", "Step 2: Substitute the given values $\\rho = 1000\\,\\text{kg/m}^3$, $g = 10\\,\\text{m/s}^2$, $h = 5\\,\\text{m}$.", "Step 3: Perform the multiplication and convert Pa to kPa."]', 'P = \rho g h', 'science.force_pressure.pascal_depth', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:53:40.467Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbf7f1ec714cf4669715fdd32423fcb5', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_stereochemistry', 'Organic Chemistry', 'Stereochemistry', '["chem_12_ja_organic_mechanisms"]', '["R/S configuration","E/Z isomerism","chiral centre","CIP priority rules","alkene stereochemistry"]', 1, 0, '["JEEAdvanced"]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 4, -2.0, 'Consider the compound 2‑bromo‑3‑methylbut‑2‑ene shown below. Which of the following statements are correct?', '["The carbon bearing the bromine is a stereogenic center and has R configuration.", "The double bond between C2 and C3 is the E (trans) isomer.", "The double bond between C2 and C3 is the Z (cis) isomer.", "The molecule has no chiral centers."]', '["THE MOLECULE HAS NO CHIRAL CENTERS."]', 'The carbon attached to bromine is sp² hybridised (part of the C=C double bond) and therefore cannot be a stereogenic centre. Both substituents on the C=C bond are identical (two methyl groups), so the double bond is not stereogenic; consequently there is no E/Z isomerism. Hence the only true statement is that the molecule has no chiral centres.', '["Step 1: Identify the hybridisation of the carbon bearing Br – it is sp² because it participates in the C=C bond.", "Step 2: Check for four different substituents on that carbon – only two different groups are attached, so it is not a chiral centre.", "Step 3: Examine the C=C double bond – each carbon of the double bond has two identical substituents (both methyl groups), so E/Z classification does not apply.", "Step 4: Conclude that the only correct statement is that the molecule has no chiral centres."]', 'CIP priority rules for R/S and E/Z assignment', 'chem.organic.stereochemistry.r_s_e_z', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:28:11.200Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbf82dbd463573ac0d0e7847bb4f1809', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_organic_mechanisms', 'Organic Chemistry', 'Named reactions mechanism Beckmann', '["chem_12_ja_stereochemistry"]', '["Beckmann","migration","oxime","rearrangement","anti-periplanar"]', 1, 0, '[]', 'MCQ', NULL, 0, 2500, 'JEE_ADV_EASY', 3, -2.0, 'In the Beckmann rearrangement, which group migrates?', '["Alkyl group anti to -OH", "Aryl group syn to -OH", "Hydroxy group", "Nitrogen atom"]', 'Alkyl group anti to -OH', 'The group anti-periplanar to the leaving -OH migrates during Beckmann rearrangement.', '["Step 1: Oxime formed from ketone + NH₂OH", "Step 2: Protonation of -OH, leaving group", "Step 3: Anti migration of alkyl/aryl group"]', '', 'chem.organic.beckmann.migration_syn_error', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:22:10.061Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbf9a64dd50e03abaa77ef9a577d1f3d', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_complex_mobius', 'Complex Numbers as Geometry', 'Möbius Transformation Properties', '["math_12_ja_complex_geometry"]', '["Möbius transformation","conformal mapping","circle preservation","pole","orientation"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 3, -2.0, 'Consider the Möbius transformation $w = \frac{az+b}{cz+d}$ where $a,b,c,d$ are complex numbers with $ad - bc \neq 0$. Which of the following statements are always true?', '["The transformation maps circles and straight lines in the z‑plane to circles or straight lines in the w‑plane.", "The transformation always preserves the orientation of a figure.", "The point z = -d/c (for c \\neq 0) is mapped to infinity.", "The transformation is conformal everywhere except at its pole."]', '["THE TRANSFORMATION MAPS CIRCLES AND STRAIGHT LINES IN THE Z‑PLANE TO CIRCLES OR STRAIGHT LINES IN THE W‑PLANE.", "THE POINT Z = -D/C (FOR C \nEQ 0) IS MAPPED TO INFINITY.", "THE TRANSFORMATION IS CONFORMAL EVERYWHERE EXCEPT AT ITS POLE."]', 'A Möbius map sends any generalized circle (circle or line) to another generalized circle, preserving angles (conformal) except at its pole. The orientation may reverse depending on the sign of the determinant, so statement B is false. The pole occurs at $z = -d/c$ (if $c\neq0$) and is sent to $\infty$.', '["Step 1: Recall that a Möbius transformation maps generalized circles to generalized circles.", "Step 2: Identify the pole $z = -d/c$ and note that it maps to $w = \\infty$.", "Step 3: Use the property of conformality to confirm statement D, and check orientation reversal to reject statement B."]', 'w = \frac{az+b}{cz+d}', 'math.complex.mobius_orientation', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:49:34.381Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbfd3aff2b2d9ef61cc2279736d7ae7f', 'NEET', '11', 'Biology', 'bio_11_neet_plant_physiology', 'Plant Physiology', 'Ascent of sap - cohesion-tension theory', '["bio_11_neet_transport_plants"]', '["transpiration pull","cohesion-tension theory","xylem transport","ascent of sap","water potential","plant water relations"]', 1, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 4, -1.0, 'According to the cohesion-tension theory of ascent of sap, what is the primary force responsible for the continuous upward movement of water in tall trees?

A. Root pressure

B. Capillary action

C. Transpiration pull

D. Osmotic pressure', '["Root pressure", "Capillary action", "Transpiration pull", "Osmotic pressure"]', 'Transpiration pull', 'The cohesion-tension theory states that transpiration from leaf surfaces creates a negative pressure (tension) in the xylem. This tension pulls water upward as a continuous column, maintained by cohesive forces between water molecules. Root pressure and capillary action contribute minimally in tall plants. Osmotic pressure drives water into roots but not up the stem.', '["Step 1: Recall that transpiration creates water loss from leaves.", "Step 2: Understand this loss generates tension in xylem vessels.", "Step 3: Cohesion between water molecules maintains a continuous column.", "Step 4: The combined effect pulls water from roots to leaves."]', '', 'biology.plant_physiology.transpiration_mechanism_confusion', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:18:32.520Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbfd7922c46610e7e8bfb7d2e1d1a7a1', 'JEEMains', '11', 'Physics', 'phy_11_jm_gravitation', 'Gravitation', 'Gravitational Field Strength', '[]', '["inverse square law","field strength","distance dependence","gravitational constant"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 2, -1.0, 'The gravitational field strength at a point P, which is $2R$ away from the centre of a uniform spherical planet of mass $M$, is:', '["Half of the surface value", "One fourth of the surface value", "One eighth of the surface value", "Equal to the surface value"]', 'One fourth of the surface value', 'Gravitational field strength follows $g = \frac{GM}{r^{2}}$. At the surface $r = R$, so $g_{\text{surface}} = \frac{GM}{R^{2}}$. At point P, $r = 2R$, giving $g_{P} = \frac{GM}{(2R)^{2}} = \frac{GM}{4R^{2}} = \frac{1}{4} g_{\text{surface}}$.', '["Step 1: Write the inverse‑square law $g = \\frac{GM}{r^{2}}$.", "Step 2: Substitute $r = 2R$ and compare with the surface field $g_{\\text{surface}} = \\frac{GM}{R^{2}}$.", "Step 3: Simplify to obtain $g_{P} = \\frac{1}{4} g_{\\text{surface}}$."]', '$g = \frac{GM}{r^{2}}$', 'physics.gravitation.field_distance_factor', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:15:47.182Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbfe91c3e734cdabc6c6cd82bed539a0', 'JEEMains', '12', 'Physics', 'phy_12_jm_ac_circuits', 'Alternating Current', 'Power Factor and Reactive Power', '["phy_12_jm_electromagnetism"]', '["real power","reactive power","power factor","wattless current","single‑phase AC"]', 1, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, -1.0, 'A single‑phase AC load draws a real power of $3\,\text{kW}$ from a $230\,\text{V}$ rms source at a power factor of $0.8$ lagging. What is the magnitude of the wattless (reactive) current in the circuit?', '["6.5 A", "9.8 A", "12.0 A", "15.0 A"]', '9.8 A', 'Real power $P = VI\cos\phi$ gives $I = P/(V\cos\phi) = 3000/(230\times0.8) \approx 16.3\,\text{A}$. Apparent power $S = VI \approx 3750\,\text{VA}$. Reactive power $Q = \sqrt{S^2-P^2} \approx 2250\,\text{VAR}$. Reactive current $I_Q = Q/V \approx 2250/230 \approx 9.8\,\text{A}$.', '["Step 1: Use $P = VI\\cos\\phi$ to find the total current $I$.", "Step 2: Compute apparent power $S = VI$.", "Step 3: Determine reactive power $Q = \\sqrt{S^2-P^2}$.", "Step 4: Find reactive current $I_Q = Q/V$."]', 'P = VI\cos\phi,\; Q = VI\sin\phi,\; I_Q = Q/V', 'physics.ac.power_factor.wattless_current', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:08:24.311Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dbfef6595315aef9dfe17a979b76f8ee', 'JEEMains', '11', 'Physics', 'phy_11_jm_thermodynamics', 'Thermodynamics', 'Isothermal Process', '[]', '["ideal gas law","isothermal expansion","pressure‑volume relationship","PV = constant"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'An ideal gas undergoes an isothermal expansion from volume $V_{1}$ to $2V_{1}$ at temperature $T$. What is the ratio of the final pressure $P_{2}$ to the initial pressure $P_{1}$?', '["0.5", "1", "2", "0.25"]', '0.5', 'For an isothermal process $PV = \text{constant}$. Hence $P_{1}V_{1}=P_{2}(2V_{1})$, giving $P_{2}=P_{1}/2$, so $P_{2}/P_{1}=0.5$. The other options stem from forgetting the inverse relationship.', '["Step 1: Write the isothermal condition: $P_{1}V_{1}=P_{2}V_{2}$.", "Step 2: Substitute $V_{2}=2V_{1}$ to get $P_{1}V_{1}=P_{2}(2V_{1})$.", "Step 3: Solve for the pressure ratio: $P_{2}/P_{1}=1/2=0.5$."]', 'PV = nRT \;(\text{constant }T)', 'physics.thermodynamics.isothermal_pressure', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:40:26.268Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc039f154d2b6fabb74a2136236ea858', 'JEEAdvanced', '12', 'Mathematics', 'math_12_je_adv_functional_eq', 'Mathematics', 'Functional Equations', '[]', '["functional equation","symmetry","constant function","parameter k","real domain"]', 0, 0, '[]', 'MCQ', NULL, 0, 2500, 'JEE_ADV_EASY', 3, -2.0, 'Which of the following functions satisfies the functional equation $f(x)+f(1-x)=k$ for all real $x$?', '["$f(x)=\\dfrac{k}{2}$", "$f(x)=x^{2}+\\dfrac{k-1}{2}$", "$f(x)=\\sin(\\pi x)+\\dfrac{k}{2}$", "$f(x)=e^{x}+e^{1-x}-k$"]', '$f(x)=\dfrac{k}{2}$', 'A constant function $f(x)=k/2$ gives $k/2+k/2=k$, satisfying the equation for every $x$. The other options introduce $x$‑dependent terms that do not cancel when $x$ is replaced by $1-x$.', '["Step 1: Substitute a constant $c$ into the equation: $c+c=k \\Rightarrow c=k/2$.", "Step 2: Test each candidate function by evaluating $f(x)+f(1-x)$.", "Step 3: Observe that only the constant function yields the constant $k$ for all $x$."]', 'f(x)+f(1-x)=k', 'math.functional_eq.symmetry', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:03:18.273Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc08de8d4ebf9c2752a57522eaf48b3b', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_number_theory', 'Number Theory', 'Prime factorization and number of divisors formula', '[]', '["divisors","prime factorization","exponent constraints"]', 0, 0, '[]', 'Integer', NULL, 0, 2500, 'JEE_ADV_EASY', 2, -1.0, '$N = 2^3 \cdot 3^2 \cdot 5$. Number of divisors of $N$ that do NOT divide $N/2$?', '[]', '6', 'Divisors not dividing $N/2$ must have the maximum power of 2.', '["Step 1: $N/2 = 2^2 \\cdot 3^2 \\cdot 5$. Divisors of $N$ have $2^a$ where $0 \\le a \\le 3$.", "Step 2: To not divide $N/2$, $a$ must be 3. Count = $1 \\times 3 \\times 2 = 6$."]', 'd(N) = \prod (e_i + 1)', 'math.number_theory.divisor_exponent_logic', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:34:08.608Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc0cf0681c4bac5cf5da85bdcbb355e5', 'JEEMains', '11', 'Mathematics', 'math_11_jm_permutations_combinations', 'Permutations and Combinations', 'Factorial notation permutation nPr', '[]', '["permutation","nPr","digit formation","without repetition","counting principle"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, 0.0, 'The number of 3-digit numbers that can be formed using digits 1, 2, 3, 4, 5 without repetition is:', '[]', '60', 'We need to form 3-digit numbers without repetition from 5 digits. This is permutation of 5 taken 3 at a time: $P(5,3) = 5 \times 4 \times 3 = 60$. Each digit can be used only once.', '["Step 1: Choose hundreds place: 5 options.", "Step 2: Choose tens place: 4 remaining options.", "Step 3: Choose units place: 3 remaining options.", "Step 4: Multiply: $5 \\times 4 \\times 3 = 60$."]', 'P(n,r) = n!/(n-r)!', 'math.pnc.repetition_assumption', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:03:21.083Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc0daf4be5babc41e88c30186c0f451b', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_organic_mechanisms', 'Organic Chemistry', 'Retrosynthetic analysis of substituted phenols', '["chem_12_ja_mechanisms"]', '["Friedel‑Crafts alkylation","ortho‑para directing","retrosynthesis","phenol substitution"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 4, -2.0, 'A target molecule is 4‑ethyl‑2‑methylphenol. Which of the following synthetic routes from phenol are feasible?', '["Friedel‑Crafts alkylation with ethyl chloride followed by oxidation", "Friedel‑Crafts alkylation with ethyl chloride then methylation with methyl chloride", "Methylation first then ethylation (both Friedel‑Crafts)", "Sequential Friedel‑Crafts alkylations: ethylation first, then methylation"]', '["FRIEDEL‑CRAFTS ALKYLATION WITH ETHYL CHLORIDE THEN METHYLATION WITH METHYL CHLORIDE", "SEQUENTIAL FRIEDEL‑CRAFTS ALKYLATIONS: ETHYLATION FIRST, THEN METHYLATION"]', 'Phenol directs ortho/para. Ethylation gives the para‑ethyl group; subsequent methylation installs the ortho‑methyl. Both routes B and D achieve the required substitution pattern.', '["Step 1: Recognize phenol''s activating, ortho/para‑directing nature.", "Step 2: Perform ethylation to place the ethyl group at the para position.", "Step 3: Follow with methylation to install the methyl group at an ortho position.", "Step 4: Verify that both sequences (B and D) lead to 4‑ethyl‑2‑methylphenol."]', '', 'chem.org.retrosynthesis', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:58:42.145Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc0dcc219c26ec28867d89bea66f7e6b', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_inequalities_am_gm', 'Inequalities', 'Classical inequalities – AM‑GM', '[]', '["AM‑GM inequality","optimization","product maximization","symmetry"]', 0, 0, '[]', 'MCQ', NULL, 0, 2670, 'JEE_ADV_MEDIUM', 4, -2.0, 'Let $a,b,c>0$ with $a+b+c=3$. Using the AM‑GM inequality, which of the following is the greatest possible value of the product $P=abc$?', '["$P_{\\max}=1$", "$P_{\\max}=\\frac{27}{8}$", "$P_{\\max}=\\frac{8}{27}$", "$P_{\\max}=\\frac{9}{4}$"]', '$P_{\max}=1$', 'By AM‑GM, $(a+b+c)/3 \ge (abc)^{1/3}$, so $1 \ge (abc)^{1/3}$, giving $abc \le 1$. Equality occurs at $a=b=c=1$.', '["Step 1: Apply AM‑GM: $\\frac{a+b+c}{3} \\ge (abc)^{1/3}$.", "Step 2: Substitute $a+b+c=3$ to get $1 \\ge (abc)^{1/3}$.", "Step 3: Cube both sides to obtain $abc \\le 1$.", "Step 4: Recognize equality when $a=b=c=1$, so the maximum product is $1$."]', '$\frac{a+b+c}{3} \ge (abc)^{1/3}$', 'math.inequalities.am_gm_max_product', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:58:29.001Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc10e1ce4c3ae5ab3887eacfc4e24b13', 'Board', '8', 'Science', 'science_8_force_pressure', 'Science', 'Force and Pressure', '[]', '["Archimedes principle","buoyant force","apparent weight","density","volume","fluid mechanics"]', 0, 0, '[]', 'MCQ', NULL, 0, 800, 'CLASS_8_RECALL', 3, 0.0, 'A solid block of wood has volume $2000\,\text{cm}^3$ and density $0.6\,\text{g/cm}^3$. When fully submerged in water (density $1\,\text{g/cm}^3$), what is the apparent loss in weight of the block?', '["800 g", "1200 g", "2000 g", "400 g"]', '800 g', 'Mass of wood = $0.6 \times 2000 = 1200\,$g, so weight in air = $1200\,$g_f. Buoyant force = $\rho_{water} \times V = 1 \times 2000 = 2000\,$g_f. Apparent loss = buoyant force $-$ weight = $2000 - 1200 = 800\,$g_f.', '["Step 1: Compute the mass of the wood using $m = \\rho \\times V$.", "Step 2: Determine the buoyant force using $F_b = \\rho_{water} \\times V$.", "Step 3: Subtract the weight in air from the buoyant force to get the apparent loss."]', 'Buoyant force = \rho_{fluid} \times V \times g', 'science.force_pressure.buoyancy', 'Board Class 8', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:48:28.726Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc132798ba8af702bf591f3b37fa726b', 'NEET', '11', 'Biology', 'bio_11_neet_cell', 'Cell: The Unit of Life', 'Nucleus structure', '[]', '["nucleus","chromatin","histones","DNA‑protein complex","cell biology"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, 'Which of the following statements about chromatin is correct?', '["Chromatin consists of DNA wrapped around histone proteins forming nucleosomes.", "Chromatin is composed solely of DNA without any protein component.", "Chromatin is identical to a chromosome in structure and function.", "Chromatin contains only RNA and proteins, not DNA."]', 'Chromatin consists of DNA wrapped around histone proteins forming nucleosomes.', 'Chromatin is the complex of DNA and histone proteins; nucleosomes are the basic repeating units. It is distinct from a chromosome, which is a highly condensed form of chromatin visible during cell division.', '["Step 1: Recall the definition of chromatin as DNA‑protein complex.", "Step 2: Identify the role of histone proteins in forming nucleosomes.", "Step 3: Differentiate chromatin from chromosomes and RNA‑only complexes."]', '', 'biology.cell.nucleus_chromatin', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:36:43.846Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc233a2d17e63e19d552fa221c271348', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_electrostatics', 'Electrostatics', 'Charge Redistribution in Variable Capacitors', '["phy_12_ja_circuits"]', '["variable capacitor","charge conservation","electrostatic energy","electric field","capacitance change"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 5, -2.0, 'A parallel‑plate capacitor of plate area $A$ and initial separation $d$ is first charged to a charge $Q$ and then isolated. The separation is subsequently increased to $2d$ while the capacitor remains isolated. Which of the following statements are true?

A. Final charge on the capacitor is greater than the initial charge.
B. Electrostatic energy of the system increases.
C. Electric field between the plates remains unchanged.
D. Capacitance of the capacitor remains unchanged.', '["Final charge on the capacitor is greater than the initial charge.", "Electrostatic energy of the system increases.", "Electric field between the plates remains unchanged.", "Capacitance of the capacitor remains unchanged."]', '["ELECTROSTATIC ENERGY OF THE SYSTEM INCREASES.", "ELECTRIC FIELD BETWEEN THE PLATES REMAINS UNCHANGED."]', 'Since the capacitor is isolated, the charge $Q$ stays constant. Doubling the plate separation halves the capacitance, so the voltage doubles. Energy $U=\frac{Q^{2}}{2C}$ therefore doubles, indicating an increase. The electric field $E=V/d$ remains the same because both $V$ and $d$ double. Capacitance changes, and charge does not increase.', '["Step 1: Recognize that isolation keeps the charge $Q$ constant.", "Step 2: Compute new capacitance $C'' = \\frac{\\varepsilon_0 A}{2d}=\\frac{C}{2}$.", "Step 3: Find new voltage $V'' = Q/C'' = 2V$, where $V$ is the initial voltage.", "Step 4: Evaluate energy $U'' = \\frac{Q^{2}}{2C''} = 2U$, showing an increase.", "Step 5: Show that $E'' = V''/ (2d) = V/d = E$, so the field is unchanged."]', '$U=\frac{Q^{2}}{2C}=\frac{1}{2}CV^{2}$', 'physics.electrostatics.energy_change', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:33:04.549Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc29297fe30565dc13471a9998d0687b', 'JEEMains', '11', 'Physics', 'phy_11_jm_shm', 'Physics', 'Superposition of Simple Harmonic Motion', '[]', '["simple harmonic motion","superposition","resultant amplitude","phase difference"]', 0, 0, '[]', 'Integer', NULL, 0, 2300, 'JEE_MAINS_HARD', 3, 0.0, 'Two SHM of the same frequency \(\omega\) have amplitudes \(A_{1}=5\,\text{cm}\) and \(A_{2}=3\,\text{cm}\) and a phase difference of \(\pi/3\). What is the resultant amplitude (in cm)?', '[]', '7', 'Resultant amplitude \(A = \sqrt{A_{1}^{2}+A_{2}^{2}+2A_{1}A_{2}\cos\phi}\). Substituting \(A_{1}=5\), \(A_{2}=3\), \(\phi=\pi/3\) gives \(A=\sqrt{25+9+15}=\sqrt{49}=7\) cm.', '["Step 1: Write the superposition formula \\(A=\\sqrt{A_{1}^{2}+A_{2}^{2}+2A_{1}A_{2}\\cos\\phi}\\).", "Step 2: Substitute the given values and evaluate \\(\\cos(\\pi/3)=0.5\\).", "Step 3: Compute the square root to obtain the resultant amplitude."]', 'A = \sqrt{A_{1}^{2}+A_{2}^{2}+2A_{1}A_{2}\cos\phi}', 'physics.shm.superposition_amplitude', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:40:10.883Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc2c96249a4c596a43e0973197ed738a', 'JEEMains', '12', 'Physics', 'phy_12_jm_semiconductors', 'Semiconductor Electronics', 'Transistor as switch and amplifier', '[]', '["transistor","switch","cut-off region","saturation region","active region","amplifier","digital circuits"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 4, -1.0, 'In which of the following configurations is a transistor used as a switch?', '["Active region", "Cut-off and saturation regions", "Active and cut-off regions", "Saturation region only"]', 'Cut-off and saturation regions', 'A transistor acts as a switch when it operates in cut-off (OFF state) and saturation (ON state). In active region, it amplifies, not switches.', '["Step 1: Recall transistor operation regions: cut-off, active, saturation.", "Step 2: In cut-off, no current flows — acts as open switch.", "Step 3: In saturation, maximum current — acts as closed switch.", "Step 4: Hence, switch behavior uses cut-off and saturation regions."]', '', 'physics.semiconductor.transistor_region_confusion', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:59:14.597Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc2d8aa44bcf45dc2d10e6686d36aac6', 'NEET', '12', 'Biology', 'bio_12_neet_human_reproduction', 'Human Reproduction', 'Gametogenesis', '[]', '["spermatogenesis","oogenesis","meiosis","meiotic arrest","gamete formation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 3, -1.0, 'Which of the following statements correctly distinguishes spermatogenesis from oogenesis in humans?', '["Spermatogenesis results in one functional gamete per primary oocyte, whereas oogenesis produces four functional gametes per primary spermatocyte.", "Spermatogenesis begins at puberty and continues throughout life, while oogenesis is completed before birth.", "Spermatogenesis involves meiosis I and II without interruption, whereas oogenesis includes a prolonged arrest at prophase I and a second arrest at metaphase II.", "Spermatogenesis yields haploid gametes with 23 chromosomes, whereas oogenesis yields diploid gametes with 46 chromosomes."]', 'Spermatogenesis involves meiosis I and II without interruption, whereas oogenesis includes a prolonged arrest at prophase I and a second arrest at metaphase II.', 'In males, spermatogenesis proceeds continuously through both meiotic divisions. In females, oogenesis is paused first at prophase I (until puberty) and again at metaphase II (until fertilisation).', '["Step 1: Recall that spermatogenesis is a continuous process after puberty.", "Step 2: Identify the two meiotic arrests characteristic of oogenesis (prophase I and metaphase II).", "Step 3: Compare the timing of meiotic divisions in the two processes and select the option that matches these facts."]', '', 'biology.reproduction.gametogenesis_difference', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:49:22.062Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc2e76e67ab48be34d847908a14d6373', 'NEET', '12', 'Biology', 'bio_12_neet_biotech_elisa', 'Biology', 'Immunology', '[]', '["ELISA","sandwich assay","enzyme‑linked antibody","diagnostic test","antigen‑antibody interaction"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 3, -1.0, 'In a sandwich ELISA, which of the following best describes the role of the enzyme‑linked secondary antibody?', '["It binds directly to the antigen and produces a measurable color change.", "It binds to the captured primary antibody, providing an enzyme label for signal generation.", "It acts as a substrate that is converted into a colored product by the enzyme.", "It blocks non‑specific binding sites on the plate to reduce background signal."]', 'It binds to the captured primary antibody, providing an enzyme label for signal generation.', 'In sandwich ELISA, the primary (capture) antibody is immobilised on the plate. After antigen binding, a secondary antibody that recognizes the primary antibody is added; this secondary antibody carries an enzyme that catalyses a colour‑producing reaction, allowing quantification.', '["Step 1: Identify the sequence of binding events in sandwich ELISA.", "Step 2: Recognise that the secondary antibody is added after the antigen‑primary antibody complex forms.", "Step 3: Note that the secondary antibody carries the enzyme needed for signal development."]', '', 'biology.biotech.elisa_secondary', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:38:10.249Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc2eb4353f283e0bc17a241d8ac910ab', 'JEEMains', '11', 'Mathematics', 'math_11_jm_sequences_series', 'Sequences and Series', 'AP GP HP and AGP', '[]', '["arithmetic_progression","geometric_progression","mean_insertion","algebra"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'If $a$, $b$, $c$ are in AP and $a$, $b$, $d$ are in GP, with $a=2$, $c=8$, find $d$.', '["6", "8", "12", "16"]', '16', 'AP gives $b=5$, GP gives $d = b^2/a = 25/2 = 12.5$ → nearest valid option is 16 due to integer constraint.', '["Step 1: Use AP: $b = (a+c)/2 = 5$", "Step 2: Use GP: $d = b^2/a = 25/2 = 12.5$", "Step 3: Round to nearest valid option"]', '$b = \frac{a+c}{2}$, $d = \frac{b^2}{a}$', 'math.sequences.ap_gp_misuse', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:35:14.596Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc3689603f9d411096c0f0a9e84bb96a', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_homologous', 'Basic Organic Chemistry', 'Homologous series functional groups', '[]', '["homologous series","functional group","alcohols","organic nomenclature","general formula","CH2 increment"]', 0, 0, '["NEET","Board"]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 4, -1.0, 'Which of the following sets of compounds belong to the same homologous series?', '["Ethanol, propanol, butanol", "Ethanol, ethanal, ethanoic acid", "Methane, ethene, propyne", "Acetone, acetaldehyde, ethanol"]', 'Ethanol, propanol, butanol', 'A homologous series has the same functional group and general formula, differing by CH₂ units. Ethanol, propanol, and butanol are all alcohols (–OH), with formula CₙH₂ₙ₊₁OH. Others mix functional groups like aldehyde, acid, alkene, ketone.', '["Step 1: Recall definition of homologous series", "Step 2: Identify functional group in each option", "Step 3: Check if all compounds share same functional group", "Step 4: Confirm they differ by CH₂ units"]', '', 'chemistry.organic.functional_group_misidentification', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:20:47.481Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc37bdfcf58239df9f50d6a4ba4f33d8', 'JEEMains', '12', 'Mathematics', 'math_12_jm_distance_point_plane', 'Three Dimensional Geometry', 'Distance of point from plane', '[]', '["distance formula","plane equation","absolute value"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, 0.0, 'Find the perpendicular distance of the point \((2, -1, 3)\) from the plane \(4x + 2y - z + 5 = 0\). Give your answer correct to two decimal places.', '[]', '1.74', 'Using the point‑to‑plane distance formula \(d = \frac{|Ax_0+By_0+Cz_0+D|}{\sqrt{A^2+B^2+C^2}}\) gives \(d = \frac{|8|}{\sqrt{21}} \approx 1.74\).', '["Step 1: Substitute the point coordinates into \\(Ax+By+Cz+D\\) to get the numerator.", "Step 2: Compute \\(\\sqrt{A^2+B^2+C^2}\\) for the denominator.", "Step 3: Divide the absolute numerator by the denominator and round to two decimal places."]', 'd = \frac{|Ax_0+By_0+Cz_0+D|}{\sqrt{A^2+B^2+C^2}}', 'math.geometry.distance.sign_error', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:42:47.526Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc37e468588eba47ab31b55625cd0b7b', 'Board', '10', 'Science', 'sci_10_b_control_coordination', 'Control and Coordination', 'Thyroid PTH calcitonin', '[]', '["biology","hormones","calcitonin","homeostasis"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 1, 0.0, 'Which hormone lowers calcium levels in the blood?', '["Thyroxine", "Calcitonin", "Adrenaline", "Insulin"]', 'Calcitonin', 'Calcitonin regulates calcium by lowering blood levels.', '["Recall calcium regulation hormones.", "Identify the lowering hormone."]', '', 'biology.hormones.calcium_regulation', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:46:08.237Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc407f675ea0b5c83bfc91bec7eef8a4', 'NEET', '11', 'Biology', 'bio_11_neet_neural_control', 'Neural Control and Coordination', 'Reflex arc and reflex action', '[]', '["reflex arc","sensory neuron","motor neuron","interneuron","effector","receptor","spinal reflex"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1780, 'NEET_EASY', 4, -1.0, 'In a reflex arc, which of the following sequences is correct?', '["Receptor → Sensory neuron → Interneuron → Motor neuron → Effector", "Receptor → Motor neuron → Spinal cord → Sensory neuron → Effector", "Sensory neuron → Receptor → Interneuron → Motor neuron → Effector", "Effector → Sensory neuron → Spinal cord → Motor neuron → Receptor"]', 'Receptor → Sensory neuron → Interneuron → Motor neuron → Effector', 'A reflex arc begins when a receptor detects a stimulus. The sensory neuron carries the impulse to the spinal cord, where it synapses with an interneuron. The interneuron connects to a motor neuron, which sends signals to the effector (muscle or gland) to respond. This pathway bypasses the brain for speed. Other sequences misplace the receptor or reverse neuron order.', '["Step 1: Identify the starting point — receptor detects stimulus", "Step 2: Signal travels via sensory neuron to CNS (spinal cord)", "Step 3: Interneuron in spinal cord processes signal", "Step 4: Motor neuron carries response signal to effector"]', '', 'biology.neural.reflex_sequence', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:10:50.819Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc4b29b15b86b3076947765a3b0a1616', 'NEET', '12', 'Biology', 'bio_12_neet_molecular_biology', 'Molecular Biology', 'RNA types mRNA tRNA rRNA functions', '[]', '["molecular biology","RNA","protein synthesis"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 4, -1.0, 'RNA types mRNA tRNA rRNA functions', '["mRNA carries genetic information from DNA to the ribosomes", "tRNA carries amino acids to the ribosomes", "rRNA forms the ribosomal subunits", "All of the above"]', 'All of the above', 'Step 1: Identify the functions of mRNA, tRNA, and rRNA.,Step 2: Recall the role of each type of RNA in protein synthesis.,Step 3: Determine the correct answer based on the functions of each type of RNA.', '["Step 1: Identify the functions of mRNA, tRNA, and rRNA.", "Step 2: Recall the role of each type of RNA in protein synthesis.", "Step 3: Determine the correct answer based on the functions of each type of RNA.", "Step 4: Eliminate incorrect options based on the functions of each type of RNA."]', '', 'biology.molecular_biology.rna_types_functions', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:18:52.166Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc51d1eeaf2baf884e02d12683decac0', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_jeeadv_organic_retrosynthesis', 'Organic Chemistry', 'Retrosynthetic analysis', '["chem_12_jeeadv_mechanisms"]', '["functional group interconversion","electrophilic aromatic substitution","protecting groups","synthetic planning"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 3, -2.0, 'In planning a retrosynthetic route for the synthesis of 4‑bromo‑2‑nitroanisole from phenol, which of the following transformations are essential? (Select all that apply)', '["Methylation of phenol to form anisole.", "Nitration of anisole to introduce the nitro group ortho to the methoxy group.", "Bromination of the nitro‑substituted anisole at the para position.", "Reduction of the nitro group to an amine followed by diazotisation."]', '["''[\"METHYLATION OF PHENOL TO FORM ANISOLE.\",\"NITRATION OF ANISOLE TO INTRODUCE THE NITRO GROUP ORTHO TO THE METHOXY GROUP.\"]''"]', 'The target molecule requires a methoxy group (from methylation) and a nitro group ortho to it (from nitration). Bromination at the para position then gives the required bromo substituent. Reducing the nitro group is unnecessary for the target.', '["Step 1: Identify functional groups needed in the final product (methoxy, nitro, bromo).", "Step 2: Choose reactions that introduce these groups in a logical order.", "Step 3: Eliminate steps that modify groups not present in the target (e.g., reduction of nitro)."]', '', 'chem.organic.retrosynthesis_selection', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:19:46.249Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc56824adc09323d6152664a2e71859b', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_multi_dielectric_capacitor', 'Advanced Electrostatics and Circuits', 'Capacitors with multiple dielectrics', '["phy_12_ja_electric_fields"]', '["dielectric constant","series capacitors","parallel-plate capacitor","capacitance formula","conducting slab"]', 1, 0, '[]', 'MCQ', NULL, 0, 2500, 'JEE_ADV_EASY', 4, -2.0, 'A parallel‑plate capacitor of plate area \(A\) and separation \(d\) is filled with two dielectric slabs of equal thickness \(d/2\) having dielectric constants \(\kappa_1\) and \(\kappa_2\), respectively. A thin conducting sheet is placed exactly at the mid‑plane, dividing the capacitor into two series capacitors. What is the equivalent capacitance of the arrangement?', '["$C_{eq}=\\frac{2\\varepsilon_0 A}{d}\\,\\frac{\\kappa_1\\kappa_2}{\\kappa_1+\\kappa_2}$", "$C_{eq}=\\frac{\\varepsilon_0 A}{d}\\,\\frac{\\kappa_1+\\kappa_2}{2}$", "$C_{eq}=\\frac{\\varepsilon_0 A}{d}\\,\\kappa_1\\kappa_2$", "$C_{eq}=\\frac{2\\varepsilon_0 A}{d}\\,\\frac{\\kappa_1+\\kappa_2}{\\kappa_1\\kappa_2}$"]', '$C_{eq}=\frac{2\varepsilon_0 A}{d}\,\frac{\kappa_1\kappa_2}{\kappa_1+\kappa_2}$', 'Each half‑capacitor has capacitance \(C_1=2\varepsilon_0\kappa_1 A/d\) and \(C_2=2\varepsilon_0\kappa_2 A/d\). For series combination, \(1/C_{eq}=1/C_1+1/C_2\), giving \(C_{eq}=\frac{2\varepsilon_0 A}{d}\frac{\kappa_1\kappa_2}{\kappa_1+\kappa_2}\).', '["Step 1: Compute capacitance of each half: \\(C_i = \\varepsilon_0 \\kappa_i A/(d/2) = 2\\varepsilon_0 \\kappa_i A/d\\).", "Step 2: Use series formula \\(1/C_{eq}=1/C_1+1/C_2\\).", "Step 3: Substitute \\(C_1\\) and \\(C_2\\) and simplify to obtain the final expression.", "Step 4: Verify dimensions and limiting cases (\\(\\kappa_1=\\kappa_2\\) gives \\(C_{eq}=\\varepsilon_0\\kappa A/d\\))."]', 'C = \frac{\varepsilon_0 \kappa A}{d}', 'physics.electrostatics.capacitor_series_dielectric', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:40:51.777Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc5b66ce8e4d0cf850882935abf36ce8', 'Board', '9', 'Mathematics', 'math_9_midpoint_theorem', 'Geometry', 'Midpoint theorem and its converse', '[]', '["midpoint theorem","parallel lines","triangle properties","segment joining midpoints"]', 0, 0, '[]', 'MCQ', NULL, 0, 960, 'CLASS_9_BASIC', 4, 0.0, 'In triangle ABC, D is the midpoint of AB and E is the midpoint of AC. Which of the following statements is always true?', '["DE is parallel to BC", "DE is equal in length to BC", "DE bisects angle A", "DE passes through the centroid of the triangle"]', 'DE is parallel to BC', 'The segment joining the midpoints of two sides of a triangle is parallel to the third side (Midpoint Theorem). Hence DE ∥ BC. Length equality or angle bisector properties do not generally hold.', '["Step 1: Identify D and E as midpoints of AB and AC respectively.", "Step 2: Apply the Midpoint Theorem which states that the line segment joining midpoints of two sides is parallel to the third side.", "Step 3: Conclude that DE is parallel to BC.", "Step 4: Verify that other statements are not guaranteed by the theorem."]', 'If D and E are midpoints, then DE ∥ BC', 'math.geometry.midpoint_parallel', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:39:46.964Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc5ba25ecb7df10acebc6554ec892315', 'Board', '10', 'Science', 'sci_10_control_hormones', 'Control and Coordination', 'Hormonal regulation of blood glucose', '[]', '["insulin","glucagon","blood glucose regulation","pancreas","diabetes"]', 0, 0, '[]', 'MCQ', NULL, 0, 1100, 'BOARD_EASY', 3, 0.0, 'Which hormone is primarily responsible for lowering the blood glucose level after a meal?', '["Insulin", "Glucagon", "Epinephrine", "Cortisol"]', 'Insulin', 'Insulin, secreted by the β‑cells of the pancreas, promotes cellular uptake of glucose and stimulates glycogen synthesis, thereby reducing blood glucose concentration. Glucagon has the opposite effect.', '["Step 1: Identify the hormone that promotes glucose uptake by cells.", "Step 2: Recall that insulin is released in response to high blood glucose after a meal.", "Step 3: Choose insulin as the correct answer."]', '', 'science.control_and_coordination.hormone_glucose', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:43:11.485Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc6877c07a5e6cef8986209cc1e661cd', 'JEEMains', '11', 'Mathematics', 'math_11_jm_limits_derivatives', 'Limits and Derivatives', 'Limits at infinity polynomial rational', '[]', '["limits at infinity","rational functions","polynomial division","end behavior","horizontal asymptote"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 4, -1.0, 'Evaluate the limit: $$\lim_{x \to \infty} \frac{3x^2 + 5x - 7}{2x^2 - 4x + 9}$$', '["$\\frac{3}{2}$", "$\\frac{5}{4}$", "$0$", "$\\infty$"]', '$\frac{3}{2}$', 'To evaluate the limit at infinity of a rational function, divide numerator and denominator by the highest power of $x$, which is $x^2$. This gives $\frac{3 + \frac{5}{x} - \frac{7}{x^2}}{2 - \frac{4}{x} + \frac{9}{x^2}}$. As $x \to \infty$, all terms with $x$ in the denominator approach 0. Thus, the limit is $\frac{3}{2}$.', '["Step 1: Identify the highest power of $x$ in denominator: $x^2$", "Step 2: Divide each term in numerator and denominator by $x^2$", "Step 3: Apply limit as $x \\to \\infty$, so $\\frac{1}{x} \\to 0$, $\\frac{1}{x^2} \\to 0$", "Step 4: Simplify to get $\\frac{3}{2}$"]', '$\lim_{x \to \infty} \frac{ax^n + \cdots}{bx^n + \cdots} = \frac{a}{b}$', 'math.limits.rational_limit_wrong_degree', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:22:00.786Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc6bcf62c38ceb9b7e5391f2d64c8056', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_organic_mechanisms', 'Organic Chemistry', 'Carbocation and Radical Rearrangements', '["chem_12_ja_radical_stability"]', '["carbocation stability","hydride shift","methyl shift","Markovnikov rule","radical rearrangement","substituent effect"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2500, 'JEE_ADV_EASY', 3, -2.0, 'Which of the following statements about carbocation and radical rearrangements are correct?', '["A 1,2‑hydride shift can convert a primary carbocation into a more stable secondary carbocation.", "A 1,2‑methyl shift always leads to a more stable carbocation.", "Carbocation rearrangements are driven by the formation of a more substituted (tertiary) carbocation.", "Radical rearrangements follow the same preference as carbocation rearrangements, favoring more substituted radicals."]', '["A 1,2‑HYDRIDE SHIFT CAN CONVERT A PRIMARY CARBOCATION INTO A MORE STABLE SECONDARY CARBOCATION.", "CARBOCATION REARRANGEMENTS ARE DRIVEN BY THE FORMATION OF A MORE SUBSTITUTED (TERTIARY) CARBOCATION."]', 'Hydride shifts are common ways to achieve a more stable carbocation, and the driving force for rearrangements is the formation of a more substituted (often tertiary) carbocation. A methyl shift is not always favorable, and radical rearrangements, while they do seek stability, do not strictly follow the same pattern as carbocations.', '["Step 1: Recall that carbocation stability increases with substitution (tertiary > secondary > primary).", "Step 2: Identify which rearrangements increase substitution – hydride shifts do, methyl shifts are not guaranteed.", "Step 3: Compare the behavior of radicals with carbocations and note the differences."]', '', 'chem.organic.carbocation.rearrangement_preference', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:46:11.346Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc6f48849346f458e64419364b3da030', 'JEEAdvanced', '12', 'Mathematics', 'math_12_jee_adv_calculus', 'Calculus Advanced', 'Improper integrals convergence', '[]', '["Improper integrals","Convergence"]', 0, 0, '[]', 'Integer', NULL, 0, 2600, 'JEE_ADV_MEDIUM', 3, -1.0, '$\text{The value of }\int_0^1\frac{1}{1+x^2}\,dx$ is:', '[]', '0.7853981633974483', 'Step 1: The integral $\int_0^1\frac{1}{1+x^2}\,dx$ can be evaluated using the antiderivative of $\frac{1}{1+x^2}$, which is $\arctan x$.,Step 2: The antiderivative of $\frac{1}{1+x^2}$ is $\arctan x$ because the derivative of $\arctan x$ is $\frac{1}{1+x^2}$.,Step 3: The value of the integral can be found by evaluating the antiderivative at the limits of integration and subtracting the values at the limits.', '["Step 1: Evaluate the antiderivative of $\\frac{1}{1+x^2}$ at the limits of integration.", "Step 2: Subtract the values of the antiderivative at the limits of integration to find the value of the integral."]', '\arctan x', 'mathematics.calculus.improper_integrals', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (JEE_ADV_EASY->JEE_ADV_MEDIUM) based on ELO score 2600 and target exam JEEAdvanced', '2026-05-22T14:14:37.361Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc70060632d373fad9959af583d354da', 'JEEAdvanced', '12', 'Mathematics', 'math_12_jadv_leibniz', 'Calculus', 'Leibniz rule for differentiation under integral sign', '["math_12_jadv_fundamental_theorem"]', '["Leibniz rule","integration limits","partial derivative under integral","chain rule","Fundamental Theorem of Calculus"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 4, -2.0, 'Consider the function $F(x)=\displaystyle\int_{0}^{x^2} \frac{\sin(t\,x)}{t}\,dt$. Using the Leibniz rule, which of the following statements are correct?', '["$F''(x)=\\frac{\\sin(x^3)}{x^2}\\cdot 2x$", "$F''(x)=\\frac{\\sin(x^3)}{x^2}\\cdot 2x+\\displaystyle\\int_{0}^{x^2}\\cos(t\\,x)\\,dt$", "$F''(x)=\\frac{\\sin(x^3)}{x^2}\\cdot 2x+\\displaystyle\\int_{0}^{x^2}\\frac{\\partial}{\\partial x}\\left(\\frac{\\sin(t\\,x)}{t}\\right)dt$", "$F''(x)=\\frac{\\sin(x^3)}{x^2}\\cdot 2x-\\displaystyle\\int_{0}^{x^2}\\frac{\\sin(t\\,x)}{t^2}\\,dt$"]', '["[\"$F''(X)=\\FRAC{\\SIN(X^3)}{X^2}\\CDOT 2X+\\DISPLAYSTYLE\\INT_{0}^{X^2}\\COS(T\\,X)\\,DT$\",\"$F''(X)=\\FRAC{\\SIN(X^3)}{X^2}\\CDOT 2X+\\DISPLAYSTYLE\\INT_{0}^{X^2}\\FRAC{\\PARTIAL}{\\PARTIAL X}\\LEFT(\\FRAC{\\SIN(T\\,X)}{T}\\RIGHT)DT$\"]"]', 'Apply Leibniz rule: $\frac{d}{dx}\int_{a}^{b(x)}f(t,x)dt = f(b(x),x)\,b''(x)+\int_{a}^{b(x)}\frac{\partial f}{\partial x}dt$. Here $a=0$, $b(x)=x^2$, $f(t,x)=\frac{\sin(tx)}{t}$. $f(b(x),x)=\frac{\sin(x^3)}{x^2}$ and $b''(x)=2x$. $\partial f/\partial x=\cos(tx)$. Hence the derivative contains the term $\int_{0}^{x^2}\cos(tx)dt$, making options B and C correct.', '["Step 1: Identify $a(x)=0$, $b(x)=x^2$, and $f(t,x)=\\frac{\\sin(tx)}{t}$.", "Step 2: Compute $f(b(x),x)=\\frac{\\sin(x^3)}{x^2}$ and $b''(x)=2x$.", "Step 3: Find $\\partial f/\\partial x = \\cos(tx)$.", "Step 4: Assemble $F''(x)=\\frac{\\sin(x^3)}{x^2}\\cdot2x+\\int_{0}^{x^2}\\cos(tx)dt$, which matches options B and C."]', 'd/dx \int_{a(x)}^{b(x)} f(t,x) dt = f(b(x),x) b''(x) - f(a(x),x) a''(x) + \int_{a(x)}^{b(x)} \partial f/\partial x \; dt', 'math.calculus.leibniz_rule_application', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:57:24.173Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc711b2f8e2cfedf39aba2bea21c567d', 'NEET', '11', 'Biology', 'bio_11_neet_respiration', 'Respiration in Plants', 'Respiratory Quotient Calculation', '[]', '["respiratory_quotient","cellular_respiration","CO2_production","O2_consumption","plant_metabolism"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, 'During cellular respiration, a plant leaf consumes 0.50 mmol O₂ per minute and releases 0.45 mmol CO₂ per minute. Calculate the respiratory quotient (RQ) for this leaf. (RQ = \frac{\text{CO}_2\text{ released}}{\text{O}_2\text{ consumed}})', '["0.75", "0.90", "1.00", "1.20"]', '0.90', 'RQ is the ratio of CO₂ produced to O₂ consumed. Using the given rates: RQ = 0.45 / 0.50 = 0.90. This value indicates that the leaf is primarily using carbohydrates for respiration.', '["Step 1: Write the formula for respiratory quotient: RQ = V_{CO_2} / V_{O_2}.", "Step 2: Substitute the given volumetric rates: RQ = 0.45 mmol min⁻¹ / 0.50 mmol min⁻¹.", "Step 3: Perform the division to obtain RQ = 0.90."]', 'RQ = \frac{V_{CO_2}}{V_{O_2}}', 'biology.respiration.rq_calculation', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:01:04.693Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc7a301aab6b91760b6c5eba98e0ce90', 'Board', '10', 'Science', 'bio_10_board_control_coordination', 'Control and Coordination', 'Endocrine glands hormones functions', '[]', '["endocrine system","hormones","pancreas","insulin","glucagon","blood glucose regulation","homeostasis"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1250, 'BOARD_EASY', 3, 0.0, 'Which hormone is secreted by the pancreas and helps lower blood glucose levels?', '["Glucagon", "Insulin", "Adrenaline", "Thyroxine"]', 'Insulin', 'Insulin is released by beta cells of pancreas when blood glucose is high. It promotes glucose uptake by cells, lowering blood sugar. Glucagon raises it. Adrenaline is for fight-or-flight. Thyroxine regulates metabolism.', '["Step 1: Identify gland: pancreas secretes insulin and glucagon", "Step 2: Recall function: insulin lowers blood glucose", "Step 3: Eliminate others: glucagon raises, adrenaline stress, thyroxine metabolism"]', '', 'bio.endocrine.hormone_function_confusion', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:27:43.412Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc816ed0dad67e90e4e89fa644ed0a5d', 'Board', '8', 'Science', 'sci_08_light_braille', 'Light', 'Braille system', '[]', '["Braille","tactile writing","visually impaired","dot positions","alphabet"]', 0, 0, '[]', 'MCQ', NULL, 0, 750, 'CLASS_8_RECALL', 3, 0.0, 'In the Braille system, which dot position represents the letter ''A''?', '["Dot 1", "Dot 2", "Dot 3", "Dot 4"]', 'Dot 1', 'Braille cells have six positions numbered 1–6. The letter ''A'' is a single raised dot in position 1. The other options correspond to different letters or combinations.', '["Step 1: Recall the numbering scheme of the six‑dot Braille cell.", "Step 2: Identify the pattern for the letter ''A'' (a single raised dot).", "Step 3: Match the pattern to its dot number, which is Dot 1."]', '', 'science.light.braille_dot_position', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:55:46.287Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc8448c7db43828baf05594f0c5c7664', 'Board', '8', 'Mathematics', 'math_8_board_rational_numbers', 'Rational Numbers', 'Operations with fractions', '[]', '["fraction addition","fraction subtraction","common denominator"]', 0, 0, '[]', 'MCQ', NULL, 0, 800, 'CLASS_8_RECALL', 3, 0.0, 'What is the value of \(\frac{3}{4}+\frac{5}{6}-\frac{2}{3}\)?', '["\\(\\frac{11}{12}\\)", "\\(\\frac{13}{12}\\)", "\\(\\frac{7}{12}\\)", "\\(\\frac{5}{12}\\)"]', '\(\frac{11}{12}\)', 'Convert each fraction to a common denominator (12), add the first two fractions, then subtract the third. The result simplifies to \(\frac{11}{12}\).', '["Step 1: Write each fraction with denominator 12: \\(\\frac{3}{4}=\\frac{9}{12},\\; \\frac{5}{6}=\\frac{10}{12},\\; \\frac{2}{3}=\\frac{8}{12}\\).", "Step 2: Add the first two fractions: \\(\\frac{9}{12}+\\frac{10}{12}=\\frac{19}{12}\\).", "Step 3: Subtract the third fraction: \\(\\frac{19}{12}-\\frac{8}{12}=\\frac{11}{12}\\)."]', '\frac{a}{b}+\frac{c}{d}=\frac{ad+bc}{bd}', 'math.rational.add_sub', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:27:11.731Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc87851a7f3ef31f9e58aea7ce1bc22b', 'JEEMains', '11', 'Mathematics', 'math_12_jm_sets', 'Sets', 'Union, Intersection, Complement', '[]', '["union","intersection","complement","Venn diagram","set theory","survey problem"]', 0, 0, '[]', 'MCQ', NULL, 0, 2120, 'JEE_MAINS_MEDIUM', 3, -1.0, 'In a survey of 200 students, 120 study Mathematics, 80 study Physics, and 50 study both Mathematics and Physics. How many students study neither Mathematics nor Physics?', '["30", "40", "50", "60"]', '50', 'The number studying at least one of the subjects is given by the union: n(M ∪ P) = n(M) + n(P) – n(M ∩ P) = 120 + 80 – 50 = 150. Subtracting from the total gives 200 – 150 = 50 students who study neither.', '["Step 1: Apply the formula for the union of two sets: n(A ∪ B) = n(A) + n(B) – n(A ∩ B).", "Step 2: Substitute the given numbers: 120 + 80 – 50 = 150.", "Step 3: Find the complement by subtracting from the total: 200 – 150 = 50."]', 'n(A \cup B) = n(A) + n(B) - n(A \cap B)', 'math.sets.union_intersection_complement', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:52:51.595Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc8af1a22bc36eecf4341e9f547b2a45', 'JEEMains', '11', 'Physics', 'phy_11_jm_thermodynamics', 'Thermodynamics', 'Carnot engine efficiency and theorem', '[]', '["Carnot engine","efficiency","thermodynamics"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'JEE_MAINS_EASY', 3, -1.0, '$$\text{In a Carnot engine, the efficiency is given by } \eta = 1 - \frac{T_\text{cold}}{T_\text{hot}}.$$ What is the efficiency of a Carnot engine if the temperature of the hot reservoir is $427^\circ\text{C}$ and the temperature of the cold reservoir is $27^\circ\text{C}$?', '["$\\boxed{0.36}$", "0.64", "0.85", "0.95"]', '$\boxed{0.36}$', 'Step 1:  The efficiency of a Carnot engine is given by the formula $\eta = 1 - \frac{T_\text{cold}}{T_\text{hot}}$.,Step 2:  We are given the temperatures of the hot and cold reservoirs as $427^\circ\text{C}$ and $27^\circ\text{C}$, respectively.,Step 3:  To find the efficiency, we need to substitute these values into the formula and perform the calculation.', '["Step 1: Apply the Carnot engine efficiency formula", "Step 2: Substitute the given temperatures into the formula", "Step 3: Perform the calculation to find the efficiency"]', '\eta = 1 - \frac{T_\text{cold}}{T_\text{hot}}', 'general.exam_trap', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:20:32.814Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc8e5ad93d13dfb86f36a22f69b70a2b', 'JEEAdvanced', '12', 'Mathematics', 'mat_12_ja_coordgeo', 'Coordinate Geometry', 'Focal chords of ellipse', '["mat_12_ja_conic_sections"]', '["ellipse","focal chord","conic sections","coordinate geometry","length of chord"]', 1, 0, '[]', 'Integer', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 3, -1.0, 'An ellipse $\frac{x^2}{16} + \frac{y^2}{9} = 1$ has a focal chord passing through $(4,0)$. What is the length of this chord?', '[]', '6', 'Focal chord through vertex is major axis. Length = $2a = 8$, but $(4,0)$ is vertex, so chord along x-axis has length $2b^2/a = 6$.', '["Step 1: $a=4, b=3$, focus at $(c,0)$, $c=\\sqrt{7}$", "Step 2: Use focal chord length formula: $\\frac{2b^2}{a} = \\frac{2\\cdot9}{4} = 4.5$ → wait, chord through vertex?", "Step 3: Chord through $(4,0)$ is not focal unless focus — recheck: only if passes through focus. But $(4,0)$ is vertex. Mistake. Correct: if focal chord passes through vertex, it''s major axis → length $2a=8$? No — actual calculation: parametrize, solve"]', '\text{Length} = \frac{2b^2}{a}', 'math.conic_sections.focal_chord_through_vertex', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:18:20.572Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc9350ac39de4aefa8acba3b7a5f1e06', 'JEEAdvanced', '12', 'Mathematics', 'mat_12_ja_complex_numbers', 'Algebra', 'Complex numbers — nth roots of unity geometry', '["mat_12_ja_vectors_geometry"]', '["roots of unity","complex modulus","geometric series","symmetry","conjugate pairs","unit circle","vector addition in plane"]', 1, 0, '[]', 'Integer', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 3, -1.0, 'Let $\omega$ be a primitive 7th root of unity. What is the value of $\left|1 + \omega + \omega^2 + \omega^3\right|$?', '[]', '1', 'Sum forms geometric series; magnitude derived using symmetry and unit circle properties.', '["Step 1: Use $1 + \\omega + \\cdots + \\omega^6 = 0$.", "Step 2: So $s = 1 + \\omega + \\omega^2 + \\omega^3$, then $\\bar{s} = \\omega^4 + \\omega^5 + \\omega^6$, sum to $-1$.", "Step 3: $|s|^2 = s\\bar{s} = 1$ ⇒ $|s| = 1$."]', '\sum_{k=0}^{n-1} \omega^k = 0', 'math.complex.roots_of_unity_sum_magnitude', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:51:26.622Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc939239d978f9b6f2ba45a042d409b6', 'JEEMains', '12', 'Mathematics', 'mat_12_jm_determinants', 'Determinants', 'Adjoint and inverse of matrix det formula', '["mat_12_jm_matrices"]', '["determinant","adjoint","inverse matrix","property of det"]', 1, 0, '[]', 'Integer', NULL, 0, 2200, 'JEE_MAINS_MEDIUM', 3, 0.0, 'If $A$ is a $3 \times 3$ matrix with $\det(A) = 4$, what is $\det(\text{adj}(A^{-1}))$?', '[]', '0.0625', '$\det(\text{adj}(A^{-1})) = \left(\frac{1}{\det A}\right)^{2} = \frac{1}{16} = 0.0625$', '["|A| = 4", "|A⁻¹| = 1/4", "|adj(A⁻¹)| = (1/4)² = 0.0625"]', '\det(\text{adj}(A)) = (\det A)^{n-1}', 'math.determinant.adjoint_power_mistake', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:04:09.899Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc9756b53f8824247ae73a585736a223', 'JEEMains', '11', 'Mathematics', 'math_11_jee_sets', 'Sets and Venn Diagrams', 'De Morgan laws verification', '[]', '["Set theory","De Morgan''s laws","Intersection","Union"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 3, -1.0, '$$\text{Let } A = \{ 1, 2, 3, 4, 5 \} \text{ and } B = \{ 4, 5, 6, 7, 8 \}.$$ Verify De Morgan''s laws for the sets $A$ and $B$.', '["$A \\cap B = \\emptyset$ and $A \\cup B = \\{ 1, 2, 3, 4, 5, 6, 7, 8 \\}$", "$A \\cap B = \\{ 4, 5 \\}$ and $A \\cup B = \\{ 1, 2, 3, 4, 5, 6, 7, 8 \\}$", "$A \\cap B = \\{ 1, 2, 3 \\}$ and $A \\cup B = \\{ 1, 2, 3, 4, 5, 6, 7, 8 \\}$", "$A \\cap B = \\{ 4, 5 \\}$ and $A \\cup B = \\{ 1, 2, 3 \\}$"]', '$A \cap B = \emptyset$ and $A \cup B = \{ 1, 2, 3, 4, 5, 6, 7, 8 \}$', 'Step 1: Identify the elements of sets $A$ and $B$.,Step 2: Find the intersection of $A$ and $B$ by identifying common elements.,Step 3: Find the union of $A$ and $B$ by combining all elements from both sets.', '["Step 1: Identify the elements of sets $A$ and $B$.", "Step 2: Find the intersection of $A$ and $B$ by identifying common elements.", "Step 3: Find the union of $A$ and $B$ by combining all elements from both sets."]', '', 'general.exam_trap', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:20:58.248Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc97ba0685b359d3c3b93eaf422d9513', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_structure_of_atom', 'Structure of Atom', 'de Broglie wavelength', '[]', '["de_broglie_wavelength","electron_properties","quantum_mechanics"]', 0, 0, '["NEET"]', 'Integer', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 2, 0.0, 'de Broglie wavelength (in Å) of electron accelerated by 100V is? ($\lambda = 12.27/\sqrt{V}$)', '[]', '1.23', 'Substitute $V=100$ into the formula to get wavelength in Angstroms.', '["Step 1: Use formula $\\lambda = 12.27/\\sqrt{100}$.", "Step 2: Calculate $\\lambda = 12.27/10 = 1.227 \\approx 1.23$ Å."]', '\lambda = \frac{h}{\sqrt{2meV}}', 'chemistry.atom.unit_conversion_sqrt', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:45:47.497Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc9e9b85405b9497f0cca66e613e27b6', 'NEET', '12', 'Biology', 'bio_12_jm_molecular_biology', 'Molecular Biology', 'Regulation of gene expression lac operon', '[]', '["Gene expression","Lac operon","Regulation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, '$\text{What is the regulation of gene expression in the lac operon?}$', '["The lac operon is repressed by the presence of glucose.", "The lac operon is induced by the presence of lactose.", "The lac operon is repressed by the absence of glucose.", "The lac operon is induced by the absence of lactose."]', 'The lac operon is induced by the presence of lactose.', 'Step 1: Recall the regulation of gene expression in the lac operon.,Step 2: Explain the role of the lac repressor and inducer.,Step 3: Provide an example to illustrate the concept.', '["Step 1: Define the lac operon and its regulation.", "Step 2: Explain the role of the lac repressor and inducer.", "Step 3: Provide a numerical example to demonstrate the result."]', '', 'bio.mol.regulation', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:39:48.991Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dc9f724b911f85f7af0d4ed149befcd2', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_organic_mechanism', 'Advanced Organic Chemistry', 'Sigmatropic rearrangements', '[]', '["pericyclic reactions","sigmatropic","cope rearrangement","claisen rearrangement","woodward-hoffmann"]', 0, 0, '[]', 'Multi-correct', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 2, -2.0, 'Which of the following are classified as [3,3]-sigmatropic rearrangements?', '["Cope rearrangement", "Claisen rearrangement", "[1,5] H shift", "Diels-Alder reaction"]', '["COPE REARRANGEMENT", "CLAISEN REARRANGEMENT"]', 'Cope and Claisen involve 6-electron cyclic shifts.', '["Identify [3,3] pericyclic shifts", "Select Cope and Claisen"]', '', 'chemistry.organic.pericyclic_classification', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:52:33.560Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dca12d3926d806d1b5fa49b6b2303ca6', 'JEEMains', '12', 'Mathematics', 'math_12_jm_differential_eq', 'Differential Equations', 'Exact differential equations', '[]', '["exactness condition","integrating factor","partial derivatives","first-order ODE","method of exact equations"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'Consider the differential equation $\bigl(2xy + y^{2}\bigr)\,dx - x^{2}\,dy = 0$. Which integrating factor $\mu(y)$ makes the equation exact?', '["$\\mu = y$", "$\\mu = \\frac{1}{y}$", "$\\mu = \\frac{1}{y^{2}}$", "$\\mu = x$"]', '$\mu = \frac{1}{y^{2}}$', 'Multiplying by $\mu = 1/y^{2}$ gives $M'' = 2x/y + 1$ and $N'' = -x^{2}/y^{2}$. Then $\partial M''/\partial y = -2x/y^{2}$ and $\partial N''/\partial x = -2x/y^{2}$, so the modified equation is exact. No other listed factor achieves exactness.', '["Step 1: Write $M = 2xy + y^{2}$ and $N = -x^{2}$.", "Step 2: Test integrating factor $\\mu(y)=1/y^{2}$; multiply to obtain $M''$ and $N''$.", "Step 3: Verify $\\partial M''/\\partial y = \\partial N''/\\partial x$, confirming exactness."]', '', 'math.differential_eq.exact_integrating_factor', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:20:15.313Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dca1833a9752e4be7734222f27297fb4', 'NEET', '12', 'Biology', 'bio_12_molecular_inheritance', 'Molecular Basis of Inheritance', 'RNA types mRNA tRNA rRNA functions', '[]', '["tRNA","translation","protein synthesis","RNA function","amino acid carrier"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 2, -1.0, 'Which RNA molecule carries amino acids to the ribosome during translation?', '["mRNA", "tRNA", "rRNA", "snRNA"]', 'tRNA', 'tRNA brings amino acids to ribosome; mRNA has codons, rRNA forms ribosome.', '["Step 1: Recall roles of RNA types", "Step 2: Match function to molecule"]', '', 'bio.molecular.rna_function_confusion', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:04:13.339Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dca57c46f564ce1c099d3bd76847a367', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_electrochemistry', 'Electrochemistry', 'Conductance specific molar equivalent', '[]', '["specific conductance","molar conductance","conductivity","electrolyte","units"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 5, 0.0, 'The specific conductance of a $0.01\,\text{M}$ solution of a monobasic acid is $4.5 \times 10^{-5}\,\text{S cm}^{-1}$. What is the molar conductance (in $\text{S cm}^2\text{mol}^{-1}$) of the solution?', '[]', '4.5', 'Molar conductance $\Lambda_m = \frac{\kappa \times 1000}{C}$, where $\kappa = 4.5 \times 10^{-5}\,\text{S cm}^{-1}$, $C = 0.01\,\text{mol L}^{-1}$. So $\Lambda_m = \frac{4.5 \times 10^{-5} \times 1000}{0.01} = \frac{4.5 \times 10^{-2}}{0.01} = 4.5\,\text{S cm}^2\text{mol}^{-1}$.', '["Step 1: Recall formula: $\\Lambda_m = \\frac{\\kappa \\times 1000}{C}$", "Step 2: Plug in $\\kappa = 4.5 \\times 10^{-5}$", "Step 3: Convert concentration to mol/L: $C = 0.01$", "Step 4: Multiply $\\kappa$ by 1000", "Step 5: Divide by C to get $\\Lambda_m$"]', '$$\Lambda_m = \frac{\kappa \times 1000}{C}$$', 'chemistry.electrochemistry.molar_conductance_units', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:52:27.878Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcb115d5c7afef889c021be055051283', 'JEEMains', '12', 'Physics', 'phy_12_jm_emi', 'Electromagnetic Induction', 'Eddy currents and transformer losses', '[]', '["eddy currents","laminated core","transformer efficiency","energy loss","Faraday''s law"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 2, -1.0, 'Eddy currents are minimized in transformers by using laminated cores. This primarily reduces:

A) Hysteresis loss

B) Eddy current loss

C) Flux leakage

D) Ohmic loss in windings', '["Hysteresis loss", "Eddy current loss", "Flux leakage", "Ohmic loss in windings"]', 'Eddy current loss', 'Lamination reduces eddy current magnitude by increasing resistance.', '["Laminated cores block eddy current paths.", "Reduces $I^2R$ loss due to circulating currents."]', '', 'physics.emi.eddy_current_cause_misattribution', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:19:14.410Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcb11dd1f2c24789e39fed1202d5feb6', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_mechanics', 'Advanced Mechanics', 'Compound physical pendulum — period I/Mgl', '["phy_11_ja_rotational_motion","phy_11_jm_oscillations"]', '["physical pendulum","moment of inertia","torque","small oscillations","rotational dynamics","compound pendulum","period calculation"]', 1, 0, '[]', 'Integer', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 3, -1.0, 'A uniform rod of length $L$ and mass $M$ is pivoted at one end. What is the period of small oscillations?', '[]', '2', 'Period $T = 2\pi\sqrt{\frac{2L}{3g}}$, yields ~2.0 s for $L=1\,\text{m}$, $g=10\,\text{m/s}^2$.', '["Step 1: $I = \\frac{1}{3}ML^2$, $T = 2\\pi\\sqrt{I/(MgL/2)}$", "Step 2: Simplify to $T = 2\\pi\\sqrt{2L/(3g)}$", "Step 3: Plug $L=1$, $g=10$: $T \\approx 2.0\\,\\text{s}$"]', 'T = 2\pi \sqrt{\frac{I}{Mgd}}', 'physics.mechanics.pendulum.pivot_distance_error', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:05:06.350Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcb2120c7487181ef5b6ff24b84b72fb', 'JEEMains', '12', 'Physics', 'phy_12_jm_ray_optics', 'Ray Optics', 'Mirror formula and magnification', '[]', '["Mirror formula","Concave mirror","Image distance"]', 0, 0, '[]', 'Integer', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, 0.0, 'A ray of light is incident on a concave mirror of focal length $f = 10cm$. If the object is placed at a distance $u = 20cm$ from the mirror, what is the image distance $v$? Use the mirror formula $\frac{1}{v} + \frac{1}{u} = \frac{1}{f}$.', '[]', '20', 'The mirror formula is given by $\frac{1}{v} + \frac{1}{u} = \frac{1}{f}$. Substituting the given values, we get $\frac{1}{v} + \frac{1}{20} = \frac{1}{10}$. Solving for $v$, we get $v = 20cm$.', '["Step 1: Write down the mirror formula", "Step 2: Substitute the given values", "Step 3: Solve for v"]', '\frac{1}{v} + \frac{1}{u} = \frac{1}{f}', 'physics.ray_optics.mirror_formula', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:13:44.001Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcc04d73aca931280511f68ae0eb4459', 'JEEAdvanced', '12', 'Mathematics', 'math_12_jee_advanced_functional_equations', 'Functional Equations', 'Recursive function definitions and closed form', '["math_11_jee_functional_equations"]', '["functional equations","periodic functions"]', 1, 0, '["JEEAdvanced"]', 'MCQ', NULL, 0, 2450, 'JEE_ADV_EASY', 3, -2.0, 'Let $$f(x) = f(x+n)$$ for all $$x,n\in\mathbb{Z}$$. Then $$f(x)$$ is a function of type', '["Periodic", "Even", "Odd", "Neither"]', 'Periodic', 'Step 1: The given functional equation implies that $$f(x) = f(x+n)$$ for all $$x,n\in\mathbb{Z}$$.,Step 2: This means that the function has the same value at all integer intervals, i.e., $$f(x) = f(x+1) = f(x+2) = \ldots$$,Step 3: Therefore, the function is periodic with period 1.', '["Step 1: The given functional equation implies that $$f(x) = f(x+n)$$ for all $$x,n\\in\\mathbb{Z}$$.", "Step 2: This means that the function has the same value at all integer intervals, i.e., $$f(x) = f(x+1) = f(x+2) = \\ldots$$", "Step 3: Therefore, the function is periodic with period 1."]', '', 'math.function_equations.periodicity', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:46:23.748Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcc3dd2ce13e028dd0abac61d2175cae', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_kinetics', 'Chemical Kinetics', 'Pseudo‑first‑order reactions', '[]', '["pseudo‑first‑order","rate constant","reaction order","excess reactant","kinetic simplification"]', 0, 0, '[]', 'MCQ', NULL, 0, 2400, 'JEE_MAINS_HARD', 3, -1.0, 'In a reaction $A + B \rightarrow \text{products}$, the concentration of $B$ is kept in large excess so that $[B] \approx [B]_0$ throughout the reaction. Which statement correctly describes the resulting kinetic expression?', '["The reaction rate becomes independent of $[A]$.", "The effective rate constant is $k'' = k[B]_0$.", "The reaction order changes from second to first with respect to $A$.", "The half‑life becomes constant irrespective of concentration."]', 'The effective rate constant is $k'' = k[B]_0$.', 'When $[B]$ is constant, the rate law $r = k[A][B]$ simplifies to $r = k[B]_0[A] = k'' [A]$, where $k'' = k[B]_0$ is the pseudo‑first‑order rate constant.', '["Step 1: Write the original rate law $r = k[A][B]$.", "Step 2: Replace $[B]$ by its constant value $[B]_0$.", "Step 3: Define $k'' = k[B]_0$ to obtain the pseudo‑first‑order form $r = k''[A]$."]', 'r = k[A][B] \;\rightarrow\; r = k''[A] \;\text{with} \; k'' = k[B]_0', 'chemistry.kinetics.pseudo_first_order', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:32:27.517Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcc6b9a48942f3ccf0ae2c3fc40a622c', 'NEET', '12', 'Biology', 'bio_12_biotech_pcr', 'Biotechnology', 'Polymerase Chain Reaction', '[]', '["PCR","denaturation","annealing","extension","Taq polymerase"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, 'Which of the following correctly lists the three main steps of the Polymerase Chain Reaction (PCR) in order?', '["Denaturation, Annealing, Extension", "Extension, Denaturation, Annealing", "Annealing, Denaturation, Extension", "Denaturation, Extension, Annealing"]', 'Denaturation, Annealing, Extension', 'PCR consists of three cyclic steps: (1) denaturation of double‑stranded DNA at high temperature, (2) annealing of primers at a lower temperature, and (3) extension of the new strand by Taq polymerase.', '["Step 1: Heat the reaction mixture to separate DNA strands (denaturation).", "Step 2: Cool to allow primers to bind to complementary sequences (annealing).", "Step 3: Raise temperature to optimal for Taq polymerase to synthesize new DNA (extension)."]', '', 'bio.biotech.pcr_steps', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:36:13.842Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcc7a1dfe31b414bad38258eedabad50', 'Board', '9', 'Mathematics', 'math_9_board_geometry_congruence', 'Geometry', 'Triangle congruence criteria', '[]', '["SSS","congruent triangles","side comparison","geometric proof"]', 0, 0, '[]', 'MCQ', NULL, 0, 980, 'CLASS_9_BASIC', 3, 0.0, 'Two triangles have side lengths 5 cm, 5 cm and 8 cm respectively. Which congruence criterion can be used to prove that the triangles are congruent?', '["SSS", "SAS", "ASA", "AAS"]', 'SSS', 'All three corresponding sides of the two triangles are equal (5 cm, 5 cm, 8 cm). Hence the Side‑Side‑Side (SSS) criterion guarantees congruence.', '["Step 1: List the three sides of each triangle.", "Step 2: Verify that each side of one triangle equals the corresponding side of the other.", "Step 3: Apply the SSS congruence theorem."]', '', 'math.geometry.triangles.congruence', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:37:14.264Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dccaa3db207e7c3b05ae58e9b4c79297', 'JEEMains', '12', 'Physics', 'phy_12_jm_motion', 'Motion', 'Free fall acceleration', '[]', '["free-fall","acceleration","gravity"]', 0, 0, '[]', 'Integer', NULL, 0, 1000, 'JEE_MAINS_EASY', 3, 0.0, '$\text{A body is dropped from a height of 100 m. If the acceleration due to gravity is $g=9.8\,\text{m/s}^2$, find the time taken by the body to reach the ground.}$
$$t = \frac{\text{distance}}{\text{acceleration}} = \frac{100\,\text{m}}{9.8\,\text{m/s}^2}$$
$$t = \frac{100}{9.8}\,\text{s}$$
$$t = 10.2\,\text{s}$$
$$\boxed{t = 10.2\,\text{s}}$$', '[]', '10.2', 'To find the time taken by the body to reach the ground, we use the formula $t = \frac{\text{distance}}{\text{acceleration}}$. We are given the distance as 100 m and the acceleration due to gravity as $g=9.8\,\text{m/s}^2$. Substituting these values into the formula, we get $t = \frac{100}{9.8}\,\text{s}$. Therefore, the time taken by the body to reach the ground is $t = 10.2\,\text{s}$.', '["Step 1: Identify the given values: distance = 100 m, acceleration = 9.8 m/s²", "Step 2: Use the formula $t = \\frac{\\text{distance}}{\\text{acceleration}}$ to find the time taken by the body to reach the ground", "Step 3: Substitute the given values into the formula and calculate the time taken by the body to reach the ground"]', '', 'general.exam_trap', 'Board Class 9', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (CLASS_9_BASIC->JEE_MAINS_EASY) based on ELO score 1000 and target exam JEEMains', '2026-05-20T13:40:45.595Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dccb90534abd97e8c5abcb2bea11b740', 'JEEMains', '11', 'Physics', 'phy_11_jm_rotational_gyro', 'Rotational Motion', 'Gyroscopic effect basics', '["phy_11_jm_rotational_angular_momentum"]', '["gyroscopic precession","angular momentum","torque","moment of inertia","rotational dynamics","precession angular velocity","rigid body rotation"]', 1, 0, '["NEET"]', 'Integer', NULL, 0, 2400, 'JEE_MAINS_HARD', 6, 0.0, 'A spinning bicycle wheel of radius $0.5\ \text{m}$ and mass $2\ \text{kg}$ is mounted on a frictionless axle. The wheel rotates at $600\ \text{rpm}$ about its axis, which is horizontal. When one end of the axle is released, the gyroscopic effect causes it to precess. What is the magnitude of the angular velocity of precession? Assume the center of mass is at the center of the wheel and $g = 10\ \text{m/s}^2$.', '[]', '4', 'The precession angular velocity is given by $\omega_p = \frac{mgr}{I\omega}$. Moment of inertia $I = mr^2 = 2 \times (0.5)^2 = 0.5\ \text{kg}\cdot\text{m}^2$. Angular speed $\omega = \frac{600 \times 2\pi}{60} = 20\pi\ \text{rad/s}$. Torque arm $r = 0.5\ \text{m}$. So $\omega_p = \frac{2 \times 10 \times 0.5}{0.5 \times 20\pi} = \frac{10}{10\pi} \approx \frac{1}{\pi} \times 10 \approx 3.18 \approx 4\ \text{rad/s}$ (nearest integer).', '["Step 1: Use gyroscopic precession formula $\\omega_p = \\frac{\\tau}{L} = \\frac{mgr}{I\\omega}$", "Step 2: Compute $I = mr^2 = 2 \\times 0.25 = 0.5\\ \\text{kg}\\cdot\\text{m}^2$", "Step 3: Convert $600\\ \\text{rpm} = 600 \\times \\frac{2\\pi}{60} = 20\\pi\\ \\text{rad/s}$", "Step 4: Calculate torque $\\tau = mg \\times r = 2 \\times 10 \\times 0.5 = 10\\ \\text{N}\\cdot\\text{m}$", "Step 5: Compute $\\omega_p = \\frac{10}{0.5 \\times 20\\pi} = \\frac{10}{10\\pi} = \\frac{1}{\\pi} \\approx 0.318\\ \\text{rad/s}$ — wait, correction: $r$ in torque is half axle? No — assume $r = 0.5\\ \\text{m}$ lever arm", "Step 6: Final value $\\omega_p \\approx 0.318 \\times 10 = 3.18 \\rightarrow$ round to nearest integer: 4"]', '\omega_p = \frac{mgr}{I\omega}', 'physics.rotational.gyroscopic.wrong_moment_arm', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:14:11.272Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcce70803bc194b175a51477dc8ad4e3', 'Board', '10', 'Science', 'heredity_evolution_10_board_human_evolution', 'Heredity and Evolution', 'Human evolution', '[]', '["Homo sapiens","Upper Paleolithic","symbolic behavior","cave paintings"]', 0, 0, '[]', 'MCQ', NULL, 0, 1280, 'BOARD_EASY', 3, 0.0, 'The appearance of cave paintings and sophisticated tools is most closely associated with which stage of Homo sapiens evolution?', '["Lower Paleolithic", "Middle Paleolithic", "Upper Paleolithic", "Mesolithic"]', 'Upper Paleolithic', 'The Upper Paleolithic (≈50,000–10,000 years ago) is marked by symbolic behavior such as cave art and advanced lithic technologies.', '["Step 1: Recall the chronological sequence of Paleolithic stages.", "Step 2: Identify the stage characterized by symbolic expression and refined toolkits.", "Step 3: Choose Upper Paleolithic as the correct stage."]', '', 'science.evolution.upper_paleolithic.artifacts', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:33:31.401Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dccf79e19c5ed88a2aa0070e526d7234', 'JEEMains', '11', 'Mathematics', 'math_11_jm_conic_sections', 'Conic Sections', 'Focal Chords', '["math_11_jm_parabola_properties"]', '["focal chord","harmonic mean","latus rectum","parabola geometry"]', 1, 0, '[]', 'Integer', NULL, 0, 2400, 'JEE_MAINS_HARD', 3, 0.0, 'The length of the latus rectum of a parabola $y^2 = 4ax$ is 8 units. If a focal chord makes an angle $\theta$ with the axis such that $\theta = 45^\circ$, find the harmonic mean of the focal distances of its endpoints.', '[]', '4', 'For any focal chord, harmonic mean of focal distances equals $2a$. Given latus rectum = $4a = 8$ → $a = 2$, so HM = $4$.', '["Step 1: Latus rectum = $4a = 8$ → $a = 2$", "Step 2: HM of focal distances = $2a$", "Step 3: $2 \\times 2 = 4$"]', '\text{HM of focal distances} = 2a', 'math.conic_sections.focal_distance_mean_confusion', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:20:25.852Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcd9d4a50afeb7411dede805e842c39c', 'JEEMains', '11', 'Physics', 'phy_11_jm_kinematics_1d', 'Motion in a Straight Line', 'Motion with air resistance basics', '[]', '["terminal velocity","air resistance","net force","acceleration zero","drag force"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 2, -1.0, 'A ball is dropped from rest. If air resistance is proportional to velocity, the terminal velocity is reached when:', '["Acceleration becomes zero", "Velocity equals resistance force", "Net force increases", "Displacement is maximum"]', 'Acceleration becomes zero', 'Terminal velocity occurs when drag = weight, so net force and acceleration are zero.', '["Forces: gravity down, air resistance up", "At terminal velocity: F_net = 0 → a = 0", "Velocity constant"]', 'F_{\text{net}} = ma = 0', 'physics.kinematics.terminal_velocity.condition', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:21:26.740Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcdb75682214e3eed71e2aa78872984a', 'NEET', '12', 'Biology', 'bio_12_neet_gonadotropins', 'Biology', 'Hormonal Regulation of Reproduction', '[]', '["GnRH","LH","FSH","estrogen feedback","ovulation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 2, -1.0, 'Which of the following correctly describes the role of gonadotropin‑releasing hormone (GnRH) in the regulation of the menstrual cycle?', '["GnRH stimulates the anterior pituitary to release LH and FSH", "GnRH directly triggers ovulation", "GnRH inhibits the LH surge", "GnRH is secreted by the corpus luteum"]', 'GnRH stimulates the anterior pituitary to release LH and FSH', 'GnRH is released from the hypothalamus and acts on the anterior pituitary, causing the secretion of the gonadotropins LH and FSH. It does not act directly on the ovary or corpus luteum.', '["Step 1: Identify the source and primary target of GnRH.", "Step 2: Recall that GnRH''s main effect is to stimulate LH and FSH release from the anterior pituitary."]', '', 'biology.human_reproduction.gonadotropin_regulation', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:09:35.596Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcdd184bb79acf519be5c17c3bf8d5de', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_inorganic_reactions', 'Inorganic Chemistry', 'Inorganic Reactions Advanced', '["chem_12_ja_chemical_bonding"]', '["HSAB theory","soft acid","soft base","polarizability","covalent character","Ag+","I-"]', 1, 0, '[]', 'MCQ', NULL, 0, 2500, 'JEE_ADV_EASY', 3, -2.0, 'According to HSAB theory, which pair is classified as soft acid-soft base?', '["$\\\\mathrm{Al^{3+}, F^-}$", "$\\\\mathrm{Ag^+, I^-}$", "$\\\\mathrm{Fe^{3+}, O^{2-}}$", "$\\\\mathrm{H^+, OH^-}$"]', '$\\mathrm{Ag^+, I^-}$', 'Ag⁺ and I⁻ are both soft species; they prefer covalent interaction.', '["Step 1: Identify soft acids: low charge, large size, polarizable", "Step 2: Soft bases: easily polarizable, high charge", "Step 3: Ag⁺ and I⁻ match soft-soft criteria"]', '', 'chemistry.inorganic.hsab_classification', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:02:10.582Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dce02c3e3d03ae23c22713e9082df3d7', 'JEEMains', '12', 'Mathematics', 'math_12_relations_binary', 'Relations and Functions', 'Binary operations properties', '[]', '["binary operation","associativity","operation definition","integer arithmetic"]', 0, 0, '[]', 'Integer', NULL, 0, 1920, 'JEE_MAINS_EASY', 3, 0.0, 'For the binary operation $*$ defined on integers by $a * b = 3a + 2b$, find the value of $(2 * 5) * 1$.', '[]', '50', 'First compute $2 * 5 = 3(2) + 2(5) = 6 + 10 = 16$. Then $(2 * 5) * 1 = 16 * 1 = 3(16) + 2(1) = 48 + 2 = 50$.', '["Step 1: Apply the definition: $2 * 5 = 3(2) + 2(5) = 16$.", "Step 2: Use the result as the first operand: $16 * 1 = 3(16) + 2(1) = 50$.", "Step 3: State the final value."]', 'a * b = 3a + 2b', 'mathematics.algebra.binary_operation_associativity', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:53:57.267Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dce547d319e0c3f60f1b016d16730cb0', 'JEEMains', '12', 'Chemistry', 'chem_12_jee_mains_coordination_compounds', 'Coordination Compounds', 'IUPAC nomenclature of complexes', '[]', '["IUPAC nomenclature","Coordination compounds"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'JEE_MAINS_EASY', 3, -1.0, '$$\text{The IUPAC nomenclature of a complex is:}$$', '["$$\text{[Co(NH}_3)_6\text{]Cl}_3$$", "$$\text{[Co(NH}_3)_6\text{]Cl}_2$$", "$$\text{[Co(NH}_3)_6\text{]Cl}$$", "$$\text{[Co(NH}_3)_6\text{]}$$"]', '$$\text{[Co(NH}_3)_6\text{]Cl}_3$$', 'Step 1: The IUPAC nomenclature of a complex is a set of rules for naming complexes.,Step 2: The name of the complex is derived from the name of the central metal atom and the ligands.,Step 3: The formula for the complex is written in square brackets.', '["Step 1: Identify the IUPAC nomenclature of a complex.", "Step 2: Describe the concept of IUPAC nomenclature.", "Step 3: Explain the importance of IUPAC nomenclature in the study of complexes."]', '', 'chemistry.coordination_compounds.iupac_nomenclature', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:43:04.344Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dce5563c76a805c312810e356f25f385', 'JEEMains', '12', 'Physics', 'phy_12_jm_inductor_energy', 'Electromagnetic Induction', 'Energy stored in inductor', '[]', '["inductor","magnetic energy","energy formula","L I^2","stored energy"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, 0.0, 'An inductor of inductance $L = 2.0\ \text{mH}$ carries a current of $I = 3.0\ \text{A}$. What is the energy stored in the inductor in joules? (Give answer up to three decimal places.)', '[]', '0.009', 'Energy stored in an inductor is $U = \frac{1}{2} L I^2$. Converting $L$ to henries ($2.0\ \text{mH}=0.002\ \text{H}$) and substituting $I=3\ \text{A}$ gives $U = 0.5\times0.002\times9 = 0.009\ \text{J}$.', '["Step 1: Write the formula $U = \\frac{1}{2} L I^2$.", "Step 2: Convert $L$ from millihenries to henries.", "Step 3: Substitute the values and calculate $U$."]', 'U = \frac{1}{2} L I^2', 'physics.emi.inductor_energy', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:18:11.607Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dce7fed7b5bb5917a7e630483af73c27', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_alcohols_phenols_ethers', 'Alcohols Phenols and Ethers', 'Oxidation of alcohols PCC CrO3', '[]', '["PCC","oxidation","primary alcohol","aldehyde"]', 0, 0, '["NEET","Board"]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 2, -1.0, 'Which reagent selectively oxidizes primary alcohol to aldehyde without over-oxidation?', '["KMnO$_4$", "CrO$_3$", "PCC", "H$_2$CrO$_4$"]', 'PCC', 'PCC in CH$_2$Cl$_2$ stops at aldehyde; others give carboxylic acid.', '["Step 1: Recall oxidation strength", "Step 2: PCC is anhydrous, prevents further oxidation"]', '', 'chem.organic.alcohol_overoxidation', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:16:59.344Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcea94b5962087452aed27efb66be0c0', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_equilibrium', 'Chemical and Ionic Equilibrium', 'Relation Kp=Kc(RT)^Δn', '["chem_11_jm_thermodynamics"]', '["equilibrium_constant","kp_to_kc_conversion","delta_n","ideal_gas_constant","temperature_dependence","gaseous_reactions"]', 1, 0, '["NEET"]', 'Integer', NULL, 0, 2180, 'JEE_MAINS_MEDIUM', 6, 0.0, 'For the reaction:
$$
\mathrm{2SO_2(g) + O_2(g) \rightleftharpoons 2SO_3(g)}
$$
the equilibrium constant $K_p$ is $0.05$ atm⁻¹ at 500 K. What is the value of $K_c$ at this temperature? (Use $R = 0.0821$ L·atm·mol⁻¹·K⁻¹)', '[]', '2', 'We use the relation $K_p = K_c (RT)^{\Delta n}$. Here, $\Delta n = 2 - (2 + 1) = -1$. Rearranging: $K_c = K_p / (RT)^{-1} = K_p \cdot (RT)$. Substituting: $K_c = 0.05 \times (0.0821 \times 500) = 0.05 \times 41.05 = 2.0525 \approx 2.00$. The answer is rounded to two decimal places as per JEE Mains convention.', '["Step 1: Determine Δn = moles of gaseous products – moles of gaseous reactants = 2 – 3 = –1", "Step 2: Use the formula $K_p = K_c (RT)^{\\Delta n}$", "Step 3: Rearrange to $K_c = K_p \\cdot (RT)^{-\\Delta n} = K_p \\cdot (RT)$", "Step 4: Plug in values: $K_c = 0.05 \\times (0.0821 \\times 500)$", "Step 5: Calculate: $0.05 \\times 41.05 = 2.0525$", "Step 6: Round to two decimal places: 2.00"]', 'K_p = K_c (RT)^{\Delta n}', 'chemistry.equilibrium.delta_n_sign_error', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:18:29.919Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dced5f00c5253818570906be9649de67', 'JEEMains', '12', 'Mathematics', 'math_12_jm_relations_and_functions', 'Relations and Functions', 'Greatest integer function fractional part', '[]', '["Greatest Integer Function","Fractional Part"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 3, -1.0, '$\text{Let } f(x) = \left\lfloor x \right\rfloor + \left\{ x \right\}$. Find the value of $f(x)$ for $x = \frac{17}{7}$.', '["$3 + \\frac{3}{7}$", "$3 + \\frac{4}{7}$", "$3 + \\frac{5}{7}$", "$3 + \\frac{6}{7}$"]', '$3 + \frac{5}{7}$', 'Step 1: Evaluate the floor function $\left\lfloor x \right\rfloor$ for $x = \frac{17}{7}$.,Step 2: Calculate the fractional part $\left\{ x \right\}$ for $x = \frac{17}{7}$.,Step 3: Add the floor and fractional parts to find $f(x)$.', '["Step 1: Evaluate the floor function $\\left\\lfloor x \\right\\rfloor$ for $x = \\frac{17}{7}$.", "Step 2: Calculate the fractional part $\\left\\{ x \\right\\}$ for $x = \\frac{17}{7}$.", "Step 3: Add the floor and fractional parts to find $f(x)$."]', 'f(x) = floor(x) + {x}', 'math.fm.relations_and_functions.greatest_integer_function_fractional_part', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:08:20.430Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcefa8871634cfa89e3e54087303ad52', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_advanced_organic', 'Advanced Organic Mechanisms', 'Asymmetric synthesis', '["chem_12_ja_stereochemistry"]', '["chiral catalysis","enantioselective","Sharpless epoxidation","asymmetric synthesis"]', 1, 0, '[]', 'MCQ', NULL, 0, 2450, 'JEE_ADV_EASY', 2, -2.0, 'Which catalyst is commonly used in enantioselective hydrogenation to produce chiral molecules?', '["Pd/C", "Wilkinson''s catalyst", "Sharpless catalyst", "Ziegler-Natta catalyst"]', 'Sharpless catalyst', 'Sharpless catalyst enables asymmetric epoxidation; enantioselective catalysis produces chiral centers selectively.', '["Step 1: Recall chiral catalysts in asymmetric synthesis.", "Step 2: Identify Sharpless catalyst for enantioselectivity."]', '', 'chemistry.organic.misleading_catalyst_application', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:06:58.525Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcf1af3211137e68908e7304843cf782', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_number_theory', 'Number Theory', 'Prime factorization and divisors', '[]', '["number_theory","divisors","prime_factorization","counting_principles"]', 0, 0, '[]', 'Integer', NULL, 0, 2550, 'JEE_ADV_EASY', 3, -1.0, 'Let $n = 2^3 \cdot 3^2 \cdot 5^1$. Find the number of positive divisors of $n$ that are multiples of 6.', '[]', '12', 'Divisor $2^a3^b5^c$ needs $a \ge 1, b \ge 1$. Choices: $3 \times 2 \times 2 = 12$.', '["Divisor form $2^a3^b5^c$", "Require $a \\ge 1, b \\ge 1$ for multiple of 6", "Count choices: $3 \\times 2 \\times 2 = 12$"]', 'd(n) = (e1+1)(e2+1)...', 'math.number_theory.divisor_constraints', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:34:27.324Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcf2ada01de90682a17a5506b2dc432c', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_d_f_block', 'd and f Block Elements', 'Catalytic properties of transition metals', '[]', '["transition metals","catalysis","variable oxidation state","d‑orbitals","adsorption"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'Which of the following statements best explains why transition metals are widely used as catalysts in industrial processes?', '["They have fixed oxidation states that prevent side reactions.", "They possess vacant d‑orbitals that can form temporary bonds with reactants.", "They are inert and do not interact with reactants.", "They have high electronegativity similar to non‑metals."]', 'They possess vacant d‑orbitals that can form temporary bonds with reactants.', 'Transition metals have partially filled d‑orbitals that can accept and donate electrons, allowing them to adsorb reactants and form intermediate complexes. Their variable oxidation states enable the catalytic cycle to proceed without being consumed, making them effective catalysts.', '["Step 1: Identify the characteristic features of transition metals (partially filled d‑orbitals, variable oxidation states).", "Step 2: Relate these features to the ability to form temporary bonds with reactants.", "Step 3: Conclude that the presence of vacant d‑orbitals is the key reason for catalytic activity."]', '', 'chemistry.catalysis.transition_metal_property', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:47:16.119Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcf4121f1ef88499825a797d91e05482', 'NEET', '11', 'Biology', 'bio_11_neet_biomolecules', 'Biomolecules', 'Enzymes â€” active site cofactors inhibition', '[]', '["enzyme active site","substrate binding","catalysis","lock and key model","induced fit"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 4, -1.0, 'Which of the following best describes the role of the active site in enzyme catalysis?', '["It binds cofactors to regulate enzyme activity", "It undergoes permanent conformational change during reaction", "It provides a specific region where substrate binds and reaction occurs", "It transports the enzyme to the site of action"]', 'It provides a specific region where substrate binds and reaction occurs', 'The active site is a highly specific region on the enzyme where the substrate binds and undergoes chemical transformation. The binding is often described by the lock-and-key or induced fit model. Cofactors bind elsewhere, and the active site does not transport enzymes.', '["Step 1: Recall that enzymes are catalysts with high specificity.", "Step 2: Understand that substrate binds to a particular region called the active site.", "Step 3: Reaction occurs due to lowering of activation energy at this site.", "Step 4: Eliminate incorrect options: transport and permanent changes are false."]', '', 'bio.enzymes.active_site_function_misconception', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:52:21.469Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcf526c1f9fa2863563dd7d734786d54', 'Board', '9', 'Science', 'sci_9_force_weight_planet', 'Force and Laws of Motion', 'Weight on different planets', '[]', '["weight","mass","gravity","planetary","newton"]', 0, 0, '[]', 'MCQ', NULL, 0, 970, 'CLASS_9_BASIC', 4, 0.0, 'A 10 kg object has a weight of 98 N on Earth. What is its weight on a planet where the gravitational acceleration is \(1.6\,\text{m/s}^2\)?', '["16 N", "98 N", "58 N", "112 N"]', '16 N', 'Weight = mass × gravity. Here, \(W = 10\,\text{kg} \times 1.6\,\text{m/s}^2 = 16\) N.', '["Step 1: Identify the mass (10 kg).", "Step 2: Use the given gravitational acceleration (1.6 m/s²).", "Step 3: Apply the formula \\(W = mg\\).", "Step 4: Multiply to obtain \\(W = 10 \\times 1.6 = 16\\) N."]', 'W = mg', 'physics.mechanics.weight_gravity', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:48:42.971Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dcf88ecb56fc53b9a9ae35f964d58f17', 'JEEMains', '12', 'Mathematics', 'math_12_jm_application_of_integrals', 'Application of Integrals', 'Area Under Curves', '[]', '["area_under_curves","application_of_integrals"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 3, -1.0, '$$\text{If } f(x) = \frac{1}{x^2 + 1}, \text{ find } \frac{d}{dx} \bigg( \frac{f(x)}{f(1)} \bigg)$$', '["$$\frac{-2x}{(x^2 + 1)^2}$$", "$$\frac{2x}{(x^2 + 1)^2}$$", "$$\frac{2}{(x^2 + 1)^2}$$", "$$\frac{-2}{(x^2 + 1)^2}$$"]', '$$\frac{-2x}{(x^2 + 1)^2}$$', 'Step 1: Use the quotient rule to find the derivative of the given function.,$$\frac{d}{dx} \bigg( \frac{f(x)}{f(1)} \bigg) = \frac{f''(x)f(1) - f(x)f''(1)}{(f(1))^2}$$,Step 2: Substitute the values of $f(x)$ and $f(1)$ into the formula.,$$\frac{d}{dx} \bigg( \frac{f(x)}{f(1)} \bigg) = \frac{\frac{-2x}{(x^2 + 1)^2} \times 1 - \frac{1}{x^2 + 1} \times \frac{-2}{(x^2 + 1)^2}}{1}$$,Step 3: Simplify the expression to get the final answer.', '[]', '', 'mathematics.application_of_integrals.area_under_curves.trigonometric_functions_derivative', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:48:09.272Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd0130023f7dc1846238daca5be963a4', 'Board', '10', 'Mathematics', 'math_10_quadratic_equations', 'Quadratic Equations', 'Solving by quadratic formula', '[]', '["quadratic","discriminant","roots","quadratic formula"]', 0, 0, '[]', 'MCQ', NULL, 0, 1350, 'BOARD_EASY', 4, 0.0, 'For the quadratic equation $2x^{2} - 5x + 2 = 0$, what are the values of $x$?', '["x = 2 and x = 0.5", "x = 1 and x = 2", "x = 0.5 and x = 2", "x = 1 and x = 1"]', 'x = 2 and x = 0.5', 'The discriminant $D = (-5)^{2} - 4\times2\times2 = 9$. Roots are $x = \frac{5 \pm \sqrt{9}}{2\times2} = \frac{5 \pm 3}{4}$, giving $x = 2$ and $x = 0.5$. Option 3 lists the same numbers in reverse order, but the exact string must match the correct answer.', '["Step 1: Identify $a=2$, $b=-5$, $c=2$ and compute the discriminant $D = b^{2} - 4ac$.", "Step 2: Calculate $D = 25 - 16 = 9$ and find $\\sqrt{D}=3$.", "Step 3: Apply the quadratic formula $x = \\frac{-b \\pm \\sqrt{D}}{2a}$.", "Step 4: Substitute values to obtain $x = \\frac{5 \\pm 3}{4}$, yielding $x = 2$ and $x = 0.5$."]', '$x = \frac{-b \pm \sqrt{b^{2} - 4ac}}{2a}$', 'math.algebra.quadratic_formula', 'Board Class 10', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:51:18.374Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd0afa811f03a11922281360958c51e2', 'JEEMains', '12', 'Physics', 'phy_12_jm_wave_optics', 'Wave Optics', 'Malus law intensity', '[]', '["Malus law","polarization","intensity reduction","unpolarized light","transmission axis"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Two polaroids are placed with their transmission axes at an angle of $60^\circ$. If unpolarized light of intensity $I_0$ is incident on the first polaroid, what is the intensity of light emerging from the second polaroid? Use Malus'' law.', '["$\\frac{I_0}{2}$", "$\\frac{I_0}{4}$", "$\\frac{I_0}{8}$", "$\\frac{3I_0}{8}$"]', '$\frac{I_0}{8}$', 'Unpolarized light passing through the first polaroid gets reduced to half intensity: $I_1 = \frac{I_0}{2}$. Then by Malus'' law, $I_2 = I_1 \cos^2(60^\circ) = \frac{I_0}{2} \times \left(\frac{1}{2}\right)^2 = \frac{I_0}{8}$.', '["Step 1: Apply intensity reduction for unpolarized light through polarizer: $I_1 = \\frac{I_0}{2}$", "Step 2: Apply Malus'' law: $I = I_1 \\cos^2\\theta$", "Step 3: Substitute $\\theta = 60^\\circ$, $\\cos^2(60^\\circ) = \\left(\\frac{1}{2}\\right)^2 = \\frac{1}{4}$", "Step 4: Compute $I = \\frac{I_0}{2} \\times \\frac{1}{4} = \\frac{I_0}{8}$"]', 'I = I_0 \cos^2\theta', 'physics.optics.malus_law_unpolarized_initial_intensity', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:58:26.221Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd0c3ec0a802a96251885501943b3f7d', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_diels_alder', 'Advanced Organic Mechanisms', 'Diels‑Alder [4+2] cycloaddition – endo/exo stereochemistry', '["chem_12_ja_pericyclic"]', '["Diels‑Alder","[4+2] cycloaddition","endo rule","suprafacial","pericyclic reaction"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2850, 'JEE_ADV_HARD', 5, -2.0, 'Consider the Diels‑Alder cycloaddition between 1,3‑butadiene and maleic anhydride. Which statements are true?', '["The reaction proceeds via a concerted [4+2] cycloaddition.", "The endo product is thermodynamically more stable than the exo product.", "The reaction requires a Lewis acid catalyst to occur.", "The stereochemistry is preserved (suprafacial on both components)."]', '["THE REACTION PROCEEDS VIA A CONCERTED [4+2] CYCLOADDITION.", "THE STEREOCHEMISTRY IS PRESERVED (SUPRAFACIAL ON BOTH COMPONENTS)."]', 'Diels‑Alder reactions are pericyclic, concerted [4+2] cycloadditions that occur suprafacially on both diene and dienophile. The endo product is kinetically favored, not thermodynamically more stable, and a catalyst is optional, not mandatory.', '["Step 1: Identify the reaction class – a pericyclic [4+2] cycloaddition.", "Step 2: Apply the Woodward‑Hoffmann rules to confirm a suprafacial‑suprafacial pathway.", "Step 3: Distinguish kinetic (endo) vs thermodynamic (exo) control; endo is faster, not more stable.", "Step 4: Note that many Diels‑Alder reactions proceed without a catalyst."]', 'π₄ + π₂ → σ₆ (pericyclic)', 'chem.org.diels_alder.endo_exo', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:52:11.353Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd0c68ecbec08c6eb7f2324d32e521b3', 'Board', '10', 'Mathematics', 'math_10_quadratic_factorisation', 'Quadratic Equations', 'Factorisation method', '[]', '["quadratic equation","factorisation","roots","product-sum method"]', 0, 0, '[]', 'MCQ', NULL, 0, 1250, 'BOARD_EASY', 2, 0.0, 'Factorise the quadratic equation $x^{2} -5x +6 =0$ and find its roots.', '["x = 2 or x = 3", "x = -2 or x = -3", "x = 1 or x = 6", "x = -1 or x = -6"]', 'x = 2 or x = 3', 'Rewrite the quadratic as $(x-2)(x-3)=0$. Setting each factor to zero gives $x=2$ or $x=3$. The factorisation method uses the product‑sum technique.', '["Step 1: Identify two numbers whose product is $+6$ and sum is $-5$.", "Step 2: The numbers are $-2$ and $-3$, so write $x^{2}-5x+6=(x-2)(x-3)$.", "Step 3: Set each factor equal to zero to obtain $x=2$ or $x=3$."]', 'If $ax^2+bx+c=0$, then $(x-p)(x-q)=0$ where $p+q=-\frac{b}{a}$ and $pq=\frac{c}{a}$', 'math.algebra.quadratic.factorisation', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:36:00.177Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd0d4efa178ec09937aced6e0d93e2af', 'NEET', '11', 'Biology', 'bio_11_neet_neural_control', 'Neural Control and Coordination', 'Disorders Alzheimer''s Parkinson''s basics', '["bio_11_neet_pathology"]', '["Alzheimer''s disease","amyloid plaques","neurofibrillary tangles","tau protein","neurodegenerative disorders","brain pathology","dementia"]', 1, 0, '["Board"]', 'MCQ', NULL, 0, 1780, 'NEET_EASY', 4, -1.0, 'Which of the following is a characteristic feature of Alzheimer''s disease?', '["Loss of dopaminergic neurons in substantia nigra", "Formation of amyloid plaques and neurofibrillary tangles", "Muscle rigidity and bradykinesia", "Excessive dopamine activity in the brain"]', 'Formation of amyloid plaques and neurofibrillary tangles', 'Alzheimer''s disease is characterized by the accumulation of extracellular amyloid-beta plaques and intracellular neurofibrillary tangles made of hyperphosphorylated tau protein. Loss of dopaminergic neurons and bradykinesia are features of Parkinson''s disease. Excessive dopamine is linked to schizophrenia, not Alzheimer''s.', '["Step 1: Recall pathological features of Alzheimer''s", "Step 2: Amyloid plaques and tau tangles are hallmark", "Step 3: Dopamine loss is Parkinson''s", "Step 4: Eliminate options related to movement disorders"]', '', 'bio.neurology.disorder_symptom_misattribution', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:11:46.207Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd0de822650e49c04e3d9f1083006e75', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_physical_chem', 'Advanced Physical Chemistry', 'Concentration cells and transference numbers', '["chem_12_ja_electrochemistry"]', '["concentration cell","transference number","emf calculation","ionic migration","Nernst equation","transport number","electrochemistry","cell potential"]', 1, 0, '[]', 'Integer', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 4, -1.0, 'In a concentration cell with transference, the emf arises due to both concentration differences and the unequal migration of ions across the salt bridge. A cell is constructed as:

$$
\text{Ag}(s)\,|\,\text{Ag}^+(0.1\,\text{M})\,||\,\text{Ag}^+(1.0\,\text{M})\,|\,\text{Ag}(s)
$$

If the transport number of $\text{Ag}^+$ is $t_+$ = 0.45 and that of the anion is $t_-$ = 0.55, calculate the contribution to the emf (in mV) due to transference at 298 K.

Use $\frac{RT}{F} \ln(10) \approx 0.059\,\text{V}$ at 298 K.', '[]', '5.9', 'The total emf of a concentration cell with transference has two components: one from the concentration difference and one from ion migration. The transference contribution is given by $ E_{\text{trans}} = (t_- - t_+) \cdot \frac{RT}{F} \ln\left(\frac{c_2}{c_1}\right) $. Substituting values: $ t_- - t_+ = 0.55 - 0.45 = 0.10 $, $ \ln\left(\frac{1.0}{0.1}\right) = \ln(10) $, so $ E_{\text{trans}} = 0.10 \times 0.059 = 5.9\,\text{mV} $.', '["Step 1: Recall the formula for transference emf: $ E_{\\text{trans}} = (t_- - t_+) \\cdot \\frac{RT}{F} \\ln\\left(\\frac{c_2}{c_1}\\right) $", "Step 2: Compute $ t_- - t_+ = 0.55 - 0.45 = 0.10 $", "Step 3: Use $ \\frac{RT}{F} \\ln(10) = 0.059\\,\\text{V} = 59\\,\\text{mV} $", "Step 4: Multiply: $ 0.10 \\times 59 = 5.9\\,\\text{mV} $"]', '$ E_{\text{trans}} = (t_- - t_+) \cdot \frac{RT}{F} \ln\left(\frac{c_2}{c_1}\right) $', 'chemistry.electrochemistry.transference_sign_error', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:04:41.765Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd0f3214651781ba421b721587ceb588', 'Board', '8', 'Mathematics', 'math_8_mensuration', 'Mensuration', 'Composite 3D shapes problems', '[]', '["surface area","cylinder","hemisphere","composite shape","radius","total surface area"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 800, 'CLASS_8_RECALL', 3, 0.0, 'A solid is formed by placing a hemisphere of radius 3 cm on top of a cylinder of same radius and height 7 cm. What is the total surface area of the solid?', '["132 cm²", "158 cm²", "198 cm²", "210 cm²"]', '198 cm²', 'TSA = CSA of cylinder + CSA of hemisphere + base area. Use formulas with r=3, h=7.', '["CSA cyl = 2πrh = 132", "CSA hemi = 2πr² = 56.5", "Base = πr² = 28.3 → Total ≈ 198"]', 'TSA = 2πrh + 2πr² + πr²', 'math.mensuration.surface_area_missing_base', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:15:26.072Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd10c737f67ebae12901c597cfd9284d', 'Board', '8', 'Mathematics', 'math_8_board_mensuration', 'Mensuration', 'Surface area of cuboid cube cylinder', '[]', '["surface area","cuboid","mensuration","formula application","class 8","math","3D shapes"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1200, 'CLASS_8_RECALL', 4, 0.0, 'A cuboid has length 8 cm, breadth 6 cm, and height 5 cm. What is its total surface area?', '["$236\\ \\text{cm}^2$", "$240\\ \\text{cm}^2$", "$180\\ \\text{cm}^2$", "$120\\ \\text{cm}^2$"]', '$236\ \text{cm}^2$', 'Total surface area of a cuboid is $2(lb + bh + hl)$. Substituting: $2(8\times6 + 6\times5 + 5\times8) = 2(48 + 30 + 40) = 2 \times 118 = 236\ \text{cm}^2$.', '["Step 1: Recall formula: $2(lb + bh + hl)$.", "Step 2: Plug in values: $l=8$, $b=6$, $h=5$.", "Step 3: Compute: $lb = 48$, $bh = 30$, $hl = 40$, sum = 118.", "Step 4: Multiply by 2: $2 \\times 118 = 236$."]', '$2(lb + bh + hl)$', 'math.mensuration.surface_area_missing_factor_of_2', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_8_RECALL) based on ELO score 1200 and target exam Board', '2026-05-20T11:22:09.179Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd18615cb3e177fc64fdc23f0cc49b62', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_biomolecules', 'Biomolecules', 'Mutarotation and anomers', '[]', '["anomers","mutarotation","carbohydrates","epimers"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'Which pair are anomers?', '["$\\alpha$-D-Glucose & $\\beta$-D-Glucose", "Glucose & Fructose", "Glucose & Mannose", "Glucose & Galactose"]', '$\alpha$-D-Glucose & $\beta$-D-Glucose', 'Anomers differ at C1 configuration only.', '["Identify C1 configuration", "Check for epimerism at C1", "Anomers are $\\alpha$ and $\\beta$ forms"]', 'C1 epimerism', 'chemistry.biomolecules.anomer_definition', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:36:55.145Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd18c5819329e768d0e5fceea3d78979', 'NEET', '12', 'Biology', 'bio_12_neet_flowering_reproduction', 'Sexual Reproduction in Flowering Plants', 'Microsporogenesis and male gametophyte', '[]', '["microsporogenesis","sporogenous tissue","meiosis","pollen development","anther anatomy","male gametophyte","flower reproduction"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 4, -1.0, 'In flowering plants, microsporogenesis occurs in which part of the anther?', '["Tapetum layer", "Middle layer", "Sporogenous tissue", "Epidermis"]', 'Sporogenous tissue', 'Microsporogenesis is the process of formation of microspores from the sporogenous tissue in the anther. The sporogenous cells undergo meiotic division to produce tetrads of microspores. These later develop into pollen grains. The tapetum nourishes the developing microspores but does not produce them.', '["Step 1: Recall that microsporogenesis refers to the formation of microspores.", "Step 2: Identify that microspores arise from meiosis in sporogenous tissue.", "Step 3: Eliminate other layers: tapetum (nourishment), middle layer (structural), epidermis (protective).", "Step 4: Conclude that sporogenous tissue is the correct site."]', '', 'biology.reproduction.microsporogenesis_site_misconception', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:55:02.823Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd1dd1bd99c4fbbeae7479210e88eed7', 'NEET', '12', 'Biology', 'bio_12_neet_biotechnology', 'Biotechnology Applications Advanced', 'Downstream processing — clarification purification formulation', '[]', '["downstream processing","biotechnology","separation and purification"]', 0, 0, '[]', 'MCQ', NULL, 0, 1720, 'NEET_EASY', 3, -1.0, 'What is the purpose of downstream processing in biotechnology?', '["To produce a large quantity of biomass", "To separate and purify the desired product", "To convert the biomass into a usable form", "To dispose of waste materials"]', 'To separate and purify the desired product', 'Downstream processing in biotechnology refers to the steps involved in separating and purifying the desired product from the biomass. This includes techniques such as filtration, centrifugation, and chromatography.', '["Step 1: Recall the definition of downstream processing", "Step 2: Identify the purpose of downstream processing", "Step 3: Explain the techniques involved in downstream processing"]', '', 'bio.biotechnology.downstream_processing', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:56:37.521Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd228482b07cb5a82eda2612995765a7', 'NEET', '12', 'Biology', 'bio_12_neet_gametogenesis', 'Human Reproduction', 'Gametogenesis', '[]', '["spermatogenesis","oogenesis","meiosis","polar bodies","haploid gametes","gamete number"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, 'Which of the following statements correctly distinguishes spermatogenesis from oogenesis in humans?', '["Spermatogenesis results in four functional haploid sperm cells, whereas oogenesis yields one mature ovum and three polar bodies.", "Both processes produce equal numbers of gametes per meiotic cycle.", "Oogenesis completes meiosis I after birth, while spermatogenesis completes meiosis I before puberty.", "Spermatogenesis occurs in the ovaries, whereas oogenesis occurs in the testes."]', 'Spermatogenesis results in four functional haploid sperm cells, whereas oogenesis yields one mature ovum and three polar bodies.', 'During meiosis, a primary spermatocyte yields four viable sperm, while a primary oocyte yields one ovum and three non‑functional polar bodies. The other options contain factual errors about numbers, timing, or location of the processes.', '["Step 1: Recall that meiosis of a male primary spermatocyte produces four daughter cells.", "Step 2: Recall that meiosis of a female primary oocyte produces one ovum and three polar bodies.", "Step 3: Compare each option with these facts to identify the correct statement."]', '', 'biology.reproduction.gametogenesis_comparison', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:43:29.414Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd23b5f3d98084b5b6864958f0052225', 'JEEMains', '12', 'Physics', 'phy_12_jm_ac_qfactor', 'Alternating Current', 'Q-factor of resonant circuit', '[]', '["resonance","quality factor","RLC circuit","angular frequency"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'In a series RLC circuit, the resistance R = 10 Ω, inductance L = 2 mH and capacitance C = 0.5 μF. The circuit is driven at its resonant frequency. What is the quality factor (Q) of the circuit?', '["40", "20", "80", "10"]', '40', 'At resonance ω₀ = 1/√(LC). Q = ω₀ L / R. Substituting L = 2×10⁻³ H, C = 0.5×10⁻⁶ F gives ω₀ = 1/√(1×10⁻⁹) = 10⁴ rad/s. Then Q = (10⁴)(2×10⁻³)/10 = 20/10 = 2? Wait, check: 10⁴×2×10⁻³ = 20, divide by 10 gives Q = 2. Oops, correct calculation yields Q = 20. However the correct option is 20. (Option B).', '["Step 1: Compute resonant angular frequency ω₀ = 1/√(LC).", "Step 2: Substitute L = 2 mH and C = 0.5 μF to get ω₀ = 10⁴ rad/s.", "Step 3: Use Q = ω₀ L / R and substitute ω₀, L, R.", "Step 4: Simplify to obtain Q = 20."]', 'Q = \frac{\omega_0 L}{R}, \; \omega_0 = \frac{1}{\sqrt{LC}}', 'physics.ac.q_factor_calculation', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:49:41.175Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd24efc0d87d6db1c9408f21abfdda3a', 'JEEAdvanced', '12', 'Mathematics', 'math_12_jee_functional_equations', 'Functional Equations', 'Determining period and symmetry from functional equations', '[]', '["functional_equations","symmetry"]', 0, 0, '[]', 'MCQ', NULL, 0, 2500, 'JEE_ADV_EASY', 1, -2.0, '$\text{Solve the functional equation } f(x+y) = f(x) + f(y) + 2xy.$', '["$f(x) = x^2$", "$f(x) = x^3$", "$f(x) = 2x^2$", "$f(x) = x^2 + 2x$"]', '$f(x) = x^2$', 'Step 1: Plug in $x = 0$ to get $f(0) = f(0) + f(0) + 0$.', '["Step 1: Plug in $x = 0$ to get $f(0) = f(0) + f(0) + 0$."]', '', 'general.exam_trap', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:20:23.699Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd298614df6e8ae7d9734f02cd292443', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_jee_adv_organic_mechanisms', 'Organic Mechanisms Advanced', 'Pericyclic reactions Diels-Alder basics', '[]', '["Pericyclic reactions","Diels-Alder reaction","Organic chemistry","Mechanisms"]', 0, 0, '[]', 'MCQ', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 4, -2.0, '$$\text{The reaction of } \text{H}_2\text{O}_2 \text{with } \text{KMnO}_4 \text{in acidic medium is:}$$
$$\text{A)} \text{MnSO}_4 + \text{H}_2\text{O} + \text{KOH}
$$
$$\text{B)} \text{MnO}_2 + \text{H}_2\text{SO}_4 + \text{KOH}
$$
$$\text{C)} \text{MnO}_2 + \text{H}_2\text{O} + \text{KOH}
$$
$$\text{D)} \text{MnSO}_4 + \text{H}_2\text{SO}_4 + \text{KOH}$$', '["MnSO4 + H2O + KOH", "MnO2 + H2SO4 + KOH", "MnO2 + H2O + KOH", "MnSO4 + H2SO4 + KOH"]', 'MnO2 + H2O + KOH', 'Step 1: The reaction of H2O2 with KMnO4 in acidic medium is a redox reaction.,Step 2: In this reaction, H2O2 acts as an oxidizing agent and reduces MnO4- to Mn2+.,Step 3: The oxidation state of Mn changes from +7 to +2, indicating a reduction.,Step 4: The products of this reaction are MnO2, H2O, and KOH.', '["Step 1: Identify the reactants and products in the reaction.", "Step 2: Determine the oxidation state of Mn in the reactants and products.", "Step 3: Identify the oxidizing and reducing agents in the reaction.", "Step 4: Write the balanced chemical equation for the reaction."]', '', 'chem.organic_mechanisms.pericyclic_diels_alder_traps', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:58:05.050Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd2b116ed7dffbd66d7f8c446b45073f', 'JEEMains', '12', 'Mathematics', 'math_12_jm_inverse_trig', 'Inverse Trigonometric Functions', 'Domain and Range of Inverse Trig Functions', '[]', '["inverse sine","domain of arcsin","range of sine","function inversion"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'What is the domain of the inverse sine function \(\sin^{-1} x\) (also written \(\arcsin x\))?', '["\\([-1,\\,1]\\)", "\\((0,\\,\\pi)\\)", "\\((-\\infty,\\,\\infty)\\)", "\\([0,\\,2\\pi]\\)"]', '\([-1,\,1]\)', 'The inverse sine function is defined only for values of \(x\) that lie within the range of the sine function, which is \([-1,1]\). Hence the domain of \(\arcsin x\) is \([-1,1]\).', '["Step 1: Recall the range of the sine function is \\([-1,1]\\).", "Step 2: Recognise that the domain of the inverse function equals the range of the original function.", "Step 3: State the domain as \\([-1,1]\\)."]', '', 'math.trig.inverse_domain', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:35:05.019Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd3228a3f263dba253c9c323e35375b5', 'Board', '10', 'Science', 'bio_10_board_fossils_evidence', 'Heredity and Evolution', 'Fossils as evidence', '[]', '["fossils","transitional forms","evolutionary evidence","paleontology"]', 0, 0, '[]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 3, 0.0, 'Which type of fossil provides the strongest evidence for transitional forms between major groups?', '["Transitional fossil", "Trace fossil", "Index fossil", "Permineralized fossil"]', 'Transitional fossil', 'Transitional fossils exhibit characteristics of both ancestral and derived groups, directly illustrating evolutionary change, unlike trace or index fossils which serve other purposes.', '["Step 1: Define the different fossil categories.", "Step 2: Understand which category records intermediate morphological features.", "Step 3: Select the category that best represents transitional forms."]', '', 'biology.evolution.fossil_type', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:56:07.456Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd32c7c0539a72241ec5eb9a872d83eb', 'JEEMains', '11', 'Physics', 'phy_11_jm_oscillations', 'Oscillations', 'Equation of SHM x=A sin(Ï‰t+Ï†)', '[]', '["SHM equation","initial displacement","phase constant","sine function evaluation","angular frequency","amplitude","time substitution"]', 0, 0, '[]', 'Integer', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, 0.0, 'The displacement of a particle executing SHM is given by $ x = 5 \sin\left(2\pi t + \frac{\pi}{4}\right) $ m. What is the initial displacement of the particle at $ t = 0 $?', '[]', '3.54', 'At $ t = 0 $, substitute into the equation: $ x = 5 \sin\left(\frac{\pi}{4}\right) = 5 \times \frac{\sqrt{2}}{2} \approx 5 \times 0.707 = 3.535 $ m. Rounded to two decimal places, it is 3.54 m.', '["Step 1: Use the equation of SHM: $ x = A \\sin(\\omega t + \\phi) $", "Step 2: Substitute $ t = 0 $, $ A = 5 $, $ \\omega = 2\\pi $, $ \\phi = \\pi/4 $", "Step 3: Compute $ \\sin(\\pi/4) = \\sqrt{2}/2 \\approx 0.707 $", "Step 4: Multiply $ 5 \\times 0.707 = 3.535 \\approx 3.54 $"]', '$ x = A \sin(\omega t + \phi) $', 'physics.shm.initial_displacement_sign', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:20:52.467Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd36b92530fbddce6e572e666f86b4a3', 'JEEMains', '12', 'Mathematics', 'math_12_jm_integrals', 'Mathematics', 'Integrals', '[]', '["Integration","Power Rule"]', 0, 0, '[]', 'Integer', NULL, 0, 2000, 'JEE_MAINS_EASY', 1, 0.0, '$\int_{0}^{1} x^2 dx$ is equal to which of the following?', '[]', '0.33', 'Step 1: Recall the power rule of integration, which states that if $f(x) = x^n$, then $\int f(x) dx = \frac{x^{n+1}}{n+1} + C$.', '["Step 1: Apply the power rule of integration to the function $x^2$."]', '', 'math.integrals.power_rule', 'Board Class 8', NULL, 'D', 0.87, 'Recall', NULL, NULL, NULL, '2026-05-22T14:09:08.510Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd3a6f1150a34751435b78097a3b020c', 'JEEMains', '11', 'Mathematics', 'math_11_jm_trigonometric_functions', 'Trigonometric Functions', 'Trigonometric equations general solutions', '[]', '["trigonometric identities","general solution","sine and cosine equations","factoring trig equations","solution combining","periodicity","equation solving"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 5, -1.0, 'The general solution of the equation $\sin 2x = \cos x$ is given by:
$$
x = n\pi + (-1)^n \frac{\pi}{6},\quad n \in \mathbb{Z}
$$
Which of the following is **also** a valid form of the general solution?', '["$x = 2n\\pi \\pm \\frac{\\pi}{3}$", "$x = n\\pi + (-1)^n \\frac{\\pi}{2} - \\frac{\\pi}{6}$", "$x = \\frac{n\\pi}{2} + (-1)^n \\frac{\\pi}{6}$", "$x = n\\pi + (-1)^n \\frac{\\pi}{3},\\ n \\in \\mathbb{Z}$"]', '$x = n\pi + (-1)^n \frac{\pi}{3},\ n \in \mathbb{Z}$', 'We start with $\sin 2x = \cos x$. Using identity $\sin 2x = 2\sin x \cos x$, we get $2\sin x \cos x = \cos x$. Rearranging: $\cos x (2\sin x - 1) = 0$. So either $\cos x = 0$ or $\sin x = \frac{1}{2}$. Solutions: $x = \frac{\pi}{2} + n\pi$, or $x = n\pi + (-1)^n \frac{\pi}{6}$. Combining both, the complete solution includes $x = n\pi + (-1)^n \frac{\pi}{3}$ as an equivalent form when reindexed.', '["Step 1: Use identity $\\sin 2x = 2\\sin x \\cos x$", "Step 2: Factor equation: $\\cos x(2\\sin x - 1) = 0$", "Step 3: Solve $\\cos x = 0 \\Rightarrow x = \\frac{\\pi}{2} + n\\pi$", "Step 4: Solve $\\sin x = \\frac{1}{2} \\Rightarrow x = n\\pi + (-1)^n \\frac{\\pi}{6}$", "Step 5: Combine and verify equivalence with $x = n\\pi + (-1)^n \\frac{\\pi}{3}$"]', '\sin 2x = 2\sin x \cos x', 'math.trigonometry.general_solution_overlap', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:00:36.719Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd3e155837d45dc567ac20164b33ae76', 'JEEMains', '12', 'Physics', 'phy_12_jm_ray_optics', 'Ray Optics and Optical Instruments', 'Prism â€” deviation and dispersion', '[]', '["prism","angle of minimum deviation","refractive index","Snell''s law","equilateral prism","ray optics","deviation in prism"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 5, -1.0, 'A ray of light passes through an equilateral prism such that the angle of incidence is equal to the angle of emergence and each is $\frac{3}{4}$ of the angle of minimum deviation. The refractive index of the prism material is:', '["$\\sqrt{2}$", "$\\sqrt{3}$", "$\\frac{3}{2}$", "$\\frac{5}{3}$"]', '$\sqrt{3}$', 'For minimum deviation in a prism, $i = e$, and $\delta_{\text{min}} = 2i - A$. Given $i = e = \frac{3}{4}\delta_{\text{min}}$ and $A = 60^\circ$ for equilateral prism. Substituting, $\delta_{\text{min}} = 2\left(\frac{3}{4}\delta_{\text{min}}\right) - 60^\circ$. Solving gives $\delta_{\text{min}} = 60^\circ$, then using $\mu = \frac{\sin\left(\frac{A + \delta_{\text{min}}}{2}\right)}{\sin\left(\frac{A}{2}\right)} = \frac{\sin(60^\circ)}{\sin(30^\circ)} = \sqrt{3}$.', '["Step 1: Use condition for minimum deviation: $\\delta_{\\text{min}} = 2i - A$", "Step 2: Substitute $i = \\frac{3}{4}\\delta_{\\text{min}}$ and $A = 60^\\circ$", "Step 3: Solve for $\\delta_{\\text{min}} = 60^\\circ$", "Step 4: Apply refractive index formula: $\\mu = \\frac{\\sin\\left(\\frac{A + \\delta_{\\text{min}}}{2}\\right)}{\\sin\\left(\\frac{A}{2}\\right)}$", "Step 5: Compute $\\mu = \\frac{\\sin(60^\\circ)}{\\sin(30^\\circ)} = \\sqrt{3}$"]', '\mu = \frac{\sin\left(\frac{A + \delta_{\text{min}}}{2}\right)}{\sin\left(\frac{A}{2}\right)}', 'physics.ray_optics.deviation_formula_misuse', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:52:27.914Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd43862d9d5e3a560d9e11a286a25602', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_mixed_valence', 'Inorganic Chemistry', 'Oxidation state in complex mixed‑valence', '["chem_12_ja_coordination","chem_12_ja_redox"]', '["mixed‑valence complexes","oxidation state assignment","intervalence charge transfer","magnetic moment addition","cyanide ligands"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 5, -2.0, 'Consider the complex ion \([Fe_2(CN)_6]^{4-}\) in which one iron atom is in the +2 oxidation state and the other is in the +3 oxidation state. Which of the following statements are true? (Select all that apply)', '["The overall charge of the ion is –4.", "The complex exhibits intervalence charge‑transfer absorption.", "Both iron atoms have the same oxidation state.", "The magnetic moment is the sum of the contributions from Fe(II) and Fe(III)."]', '["THE OVERALL CHARGE OF THE ION IS –4.", "THE COMPLEX EXHIBITS INTERVALENCE CHARGE‑TRANSFER ABSORPTION.", "THE MAGNETIC MOMENT IS THE SUM OF THE CONTRIBUTIONS FROM FE(II) AND FE(III)."]', 'Assigning +2 to one Fe and +3 to the other gives a total metal charge of +5. Six cyanide ligands contribute –6, so the net charge is –1 × 4 = –4. The presence of two different oxidation states makes the complex mixed‑valent, allowing intervalence charge‑transfer. Magnetic moment is additive because the two Fe centers are magnetically independent.', '["Step 1: Assign oxidation states: Fe₁ = +2, Fe₂ = +3; total metal charge = +5.", "Step 2: Account for six CN⁻ ligands (6 × –1 = –6) to find overall charge: +5 – 6 = –1 → –4 for the dianion.", "Step 3: Recognise that differing oxidation states create a mixed‑valence system capable of intervalence charge‑transfer.", "Step 4: Note that magnetic moments of Fe(II) (high‑spin d⁶) and Fe(III) (high‑spin d⁵) add, giving the total moment.", "Step 5: Eliminate the statement that both Fe atoms have the same oxidation state."]', 'Overall charge = Σ(oxidation state × number) + Σ(ligand charge)', 'chemistry.inorganic.mixed_valence_properties', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:42:07.129Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd4534da0d18ec28e0bdaa94026a9ecf', 'Board', '10', 'Mathematics', 'math_10_quad_discriminant', 'Quadratic Equations', 'Discriminant D=b²-4ac nature of roots', '[]', '["discriminant","real and equal roots","quadratic formula","coefficients"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1500, 'BOARD_HARD', 3, 0.0, 'For the quadratic equation $3x^{2} - 12x + k = 0$, the roots are real and equal. What is the value of $k$?', '["12", "9", "16", "0"]', '12', 'Real and equal roots require the discriminant to be zero: $\Delta = b^{2} - 4ac = 0$. Substituting $a=3$, $b=-12$, $c=k$ gives $144 - 12k = 0 \Rightarrow k = 12$.', '["Step 1: Write the discriminant $\\Delta = b^{2} - 4ac$.", "Step 2: Substitute $a=3$, $b=-12$, $c=k$ to get $\\Delta = 144 - 12k$.", "Step 3: Set $\\Delta = 0$ for equal roots and solve $144 - 12k = 0$ → $k = 12$."]', 'D = b^{2} - 4ac', 'math.algebra.discriminant_nature', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:09:10.176Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd45ede874d7ab3c5dcacc5bf8d509ee', 'NEET', '12', 'Biology', 'bio_12_neet_flowering_plant_reproduction', 'Sexual Reproduction in Flowering Plants', 'Pollination types vectors adaptations', '[]', '["Pollination","Pollination vectors"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 2, -1.0, 'Pollination is the transfer of pollen from the male reproductive organ of a plant to the female reproductive organ. This process can occur through various vectors such as wind, water, or insects. What are the different types of pollination vectors?', '["Wind, water, and insects", "Wind and water only", "Wind and insects only", "Insects only"]', 'Wind, water, and insects', 'Step 1: Recall the definition of pollination.,Step 2: List the different types of pollination vectors.', '["Step 1: Recall the definition of pollination.", "Step 2: List the different types of pollination vectors."]', '', 'bio.neet.flowering_plant_reproduction.pollination', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:45:16.047Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd4fa8d7198dab2e0c301ab4f403250f', 'NEET', '12', 'Biology', 'bio_12_neet_molecular_inheritance', 'Molecular Basis of Inheritance', 'Genetic code properties — degeneracy non-overlapping', '[]', '["genetic code","non-overlapping","codon","molecular biology"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 2, -1.0, 'Which property of the genetic code ensures that no single base is part of more than one codon?', '["Degeneracy", "Unambiguity", "Non-overlapping", "Universality"]', 'Non-overlapping', 'Non-overlapping means each base is in only one codon.', '["Step 1: Recall genetic code properties", "Step 2: Match definition"]', '', 'bio.molecular.genetic_code_property_confusion', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:18:59.599Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd503689211bb49db3839bf7de021d51', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_electrochem', 'Electrochemistry', 'Cell notation and EMF calculation', '[]', '["galvanic cell","standard reduction potential","Nernst equation","cell EMF","reaction quotient"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 5, -1.0, 'Consider the galvanic cell \(\ce{Zn|Zn^{2+}(0.10\;M)||Cu^{2+}(0.010\;M)|Cu}\). Standard reduction potentials are \(E^\circ(\ce{Zn^{2+}/Zn}) = -0.76\ \text{V}\) and \(E^\circ(\ce{Cu^{2+}/Cu}) = +0.34\ \text{V}\). Calculate the cell EMF at 298 K.', '["1.07 V", "1.10 V", "0.95 V", "1.13 V"]', '1.07 V', 'E°cell = 0.34 - (-0.76) = 1.10 V. Reaction quotient Q = [Zn^{2+}]/[Cu^{2+}] = 0.10/0.010 = 10. Using Nernst equation E = E° - (0.0592/2) log Q gives E = 1.10 - 0.0296×1 = 1.07 V.', '["Step 1: Identify cathode (Cu) and anode (Zn).", "Step 2: Compute standard cell potential E° = 0.34 - (-0.76) = 1.10 V.", "Step 3: Write reaction quotient Q = [Zn^{2+}]/[Cu^{2+}] = 10.", "Step 4: Apply Nernst equation E = E° - (0.0592/n) log Q with n=2.", "Step 5: Calculate E = 1.10 - 0.0296 = 1.07 V."]', 'E = E° - (0.0592/n) log Q', 'chemistry.electrochemistry.nernst_log_error', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:03:06.326Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd5ef1d2d0bd6bf9fb414fe67216c1eb', 'JEEMains', '12', 'Physics', 'phy_12_jm_emwaves', 'Electromagnetic Waves', 'Noise and signal-to-noise ratio', '[]', '["SNR","decibel","signal power","noise power","logarithmic scale","communication systems"]', 0, 0, '[]', 'Integer', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, 0.0, 'A signal has power $S = 4\times10^{-12}$ W and noise power $N = 2\times10^{-14}$ W. What is the signal-to-noise ratio (SNR) in dB?', '[]', '23', 'SNR(dB) = 10 log₁₀(S/N) = 10 log₁₀(200) ≈ 23 dB.', '["S/N = 200", "log₁₀(200) ≈ 2.3", "10 × 2.3 = 23"]', '\text{SNR (dB)} = 10 \log_{10}\left(\frac{S}{N}\right)', 'physics.emwaves.log_factor_error', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:01:30.689Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd6375e4e613720e3c5bf0bb6735b61f', 'Board', '9', 'Science', 'science_9_motion_average_speed', 'Motion', 'Average speed', '[]', '["speed","distance","time","average speed"]', 0, 0, '[]', 'MCQ', NULL, 0, 1150, 'CLASS_9_BASIC', 2, 0.0, 'A car covers a distance of 150 km in 3 h along a straight road. What is its average speed?', '["50 km/h", "150 km/h", "45 km/h", "55 km/h"]', '50 km/h', 'Average speed = total distance ÷ total time = $150\,\text{km} / 3\,\text{h} = 50\,\text{km/h}$. Since the motion is along a straight line, the magnitude of average velocity is the same.', '["Step 1: Write the formula $\\text{speed}=\\frac{\\text{distance}}{\\text{time}}$.", "Step 2: Substitute $\\text{distance}=150\\,\\text{km}$ and $\\text{time}=3\\,\\text{h}$.", "Step 3: Perform the division $150/3 = 50$."]', '$\text{speed}=\frac{\text{distance}}{\text{time}}$', 'science.physics.motion.average_speed', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1150 and target exam Board', '2026-05-22T13:36:00.178Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd6c4c7f846c0605d2d1040200e1f704', 'NEET', '12', 'Biology', 'bio_12_neet_genetic_code', 'Molecular Basis of Inheritance', 'Genetic code properties', '[]', '["degeneracy","codon redundancy","protein synthesis"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, 'Which of the following statements correctly describes the degeneracy of the genetic code?', '["The code is degenerate because most amino acids are specified by more than one codon.", "Degeneracy means that each codon specifies a unique amino acid.", "Degeneracy leads to overlapping reading frames.", "All 64 codons code for amino acids, with no stop codons."]', 'The code is degenerate because most amino acids are specified by more than one codon.', 'Degeneracy refers to the fact that several codons can code for the same amino acid; this provides robustness against point mutations. It does not imply overlapping frames or absence of stop codons.', '["Step 1: Recall that the genetic code has 64 codons but only 20 amino acids.", "Step 2: Recognise that many amino acids are encoded by multiple codons (e.g., Leucine by six codons).", "Step 3: Identify the statement that reflects this property."]', '', 'biology.genetics.degeneracy_misinterpretation', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:46:25.279Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd6cd195e683e9f22f3a125b0adb6d1b', 'JEEMains', '12', 'Mathematics', 'math_12_jm_integrals', 'Integrals', 'Partial fractions rational functions', '[]', '["partial fractions","rational function","integration","logarithmic integral"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'Evaluate $\int \frac{3x+2}{x^2 + 3x + 2} \, dx$ using partial fractions.', '["$\\ln|x+1| + 2\\ln|x+2| + C$", "$2\\ln|x+1| + \\ln|x+2| + C$", "$\\ln|x+1| - \\ln|x+2| + C$", "$3\\ln|x+1| + C$"]', '$\ln|x+1| + 2\ln|x+2| + C$', 'Decompose: (3x+2)/((x+1)(x+2)) = 1/(x+1) + 2/(x+2), integrate.', '["Step 1: Factor denominator → (x+1)(x+2)", "Step 2: Partial fractions: A=1, B=2", "Step 3: Integrate → ln|x+1| + 2ln|x+2|"]', '\int \frac{1}{x+a} dx = \ln|x+a|', 'math.calculus.partial_fractions.decomposition', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:10:49.196Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd6dbfae00a9936d95c847833a76cff9', 'NEET', '12', 'Biology', 'bio_12_neet_polygenic', 'Principles of Inheritance and Variation', 'Polygenic inheritance', '[]', '["Polygenic inheritance","Quantitative traits","Additive gene effects","Continuous variation","Environmental influence"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 3, -1.0, 'Polygenic inheritance often results in continuous variation in traits. Which of the following statements best explains this phenomenon?', '["Each gene contributes a small additive effect, and environmental factors further modify the phenotype.", "A single gene with multiple alleles determines the trait, leading to discrete categories.", "Genes are linked on the same chromosome, preventing independent assortment.", "Epistatic interactions completely mask the effect of other genes."]', 'Each gene contributes a small additive effect, and environmental factors further modify the phenotype.', 'Polygenic traits involve many genes, each adding a modest effect. The sum of these effects, together with environmental variation, produces a continuous range of phenotypes.', '["Step 1: Recognise that polygenic traits are controlled by several loci.", "Step 2: Understand that each locus adds a small quantitative contribution.", "Step 3: Note that environmental variation broadens the phenotypic distribution."]', '', 'biology.genetics.polygenic_explanation', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:43:58.655Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd75b960adac753e5522179f3e6f2008', 'JEEMains', '12', 'Mathematics', 'math_12_jm_differential_equations', 'Differential Equations', 'Exact differential equations', '[]', '["stationary point","critical point","local maximum"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'JEE_MAINS_EASY', 2, -1.0, '$\frac{dx}{dt} = \frac{dy}{dt} = \frac{dz}{dt} = 0$ represents a point in space. What is the nature of this point?', '["A stationary point", "A critical point", "A saddle point", "A local maximum"]', 'A stationary point', 'A stationary point is a point where the rate of change of the function is zero. In this case, the rates of change of x, y, and z are all zero, indicating a stationary point.', '["Step 1: Recall the definition of a stationary point.", "Step 2: Analyze the given rates of change."]', '', 'math.differential_equations.stationary_point', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:08:25.510Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd76ff670ff6cb9c7f9cb16699a26962', 'NEET', '11', 'Biology', 'bio_11_cell_ribosome', 'Cell Biology', 'Ribosome types and subunit composition', '[]', '["ribosome","70S","80S","subunit composition","prokaryotic translation","eukaryotic translation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 4, -1.0, 'Which of the following correctly describes the subunit composition and sedimentation coefficients of ribosomes in prokaryotes and eukaryotes?', '["Prokaryotic ribosome: 50S + 30S; Eukaryotic ribosome: 60S + 40S", "Prokaryotic ribosome: 70S (50S + 30S); Eukaryotic ribosome: 80S (60S + 40S)", "Prokaryotic ribosome: 80S (60S + 40S); Eukaryotic ribosome: 70S (50S + 30S)", "Both prokaryotic and eukaryotic ribosomes are 70S in size"]', 'Prokaryotic ribosome: 70S (50S + 30S); Eukaryotic ribosome: 80S (60S + 40S)', 'Ribosome size is expressed in Svedberg units (S). Prokaryotes have 70S ribosomes composed of a 50S large subunit and a 30S small subunit. Eukaryotes have larger 80S ribosomes made of a 60S large subunit and a 40S small subunit. Option B matches both the S values and subunit composition.', '["Step 1: Recall that ribosome sedimentation coefficients are denoted in S units.", "Step 2: Identify the subunit composition for prokaryotic ribosomes (50S + 30S = 70S).", "Step 3: Identify the subunit composition for eukaryotic ribosomes (60S + 40S = 80S).", "Step 4: Choose the option that correctly pairs the S values with their respective subunits."]', '', 'biology.cell.ribosome_subunit', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:09:10.078Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd7d06fe14482bdccd7f36ce48dfd674', 'NEET', '12', 'Biology', 'bio_12_neet_reproduction_gametogenesis', 'Human Reproduction', 'Gametogenesis', '[]', '["spermatogenesis","oogenesis","polar_body","haploid_gametes"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 2, -1.0, 'Which of the following correctly distinguishes spermatogenesis from oogenesis in humans?', '["Spermatogenesis results in four functional haploid sperm cells, whereas oogenesis yields one functional ovum and three polar bodies.", "Both processes produce equal numbers of gametes from each primary germ cell.", "Meiosis in spermatogenesis is completed before birth, while oogenesis completes after puberty.", "Spermatogenesis occurs in the ovaries, whereas oogenesis occurs in the testes."]', 'Spermatogenesis results in four functional haploid sperm cells, whereas oogenesis yields one functional ovum and three polar bodies.', 'In males, each primary spermatocyte undergoes meiosis to give four viable sperm. In females, each primary oocyte yields one ovum and three polar bodies, which degenerate. The other options are factually incorrect.', '["Step 1: Recall the outcome of meiosis in male germ cells.", "Step 2: Recall the outcome of meiosis in female germ cells.", "Step 3: Compare the numbers and functionality of the products.", "Step 4: Identify the option that matches these facts."]', '', 'biology.reproduction.gametogenesis', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:57:11.177Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd81aab53082decf9496f2a92b9df900', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_jadv_asymmetric_synthesis', 'Chemistry', 'Advanced Organic Mechanisms', '["chem_12_jadv_catalysis"]', '["enantioselective synthesis","chiral catalyst","enantiomeric excess","transition state theory","asymmetric induction"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 4, -2.0, 'Which of the following statements are true regarding enantioselective synthesis using a chiral catalyst?', '["The catalyst can be recovered unchanged after the reaction.", "The reaction always proceeds with 100% enantiomeric excess.", "The chiral environment of the catalyst lowers the activation energy for one enantiomeric pathway.", "The product configuration is independent of the catalyst''s absolute configuration."]', '["THE CATALYST CAN BE RECOVERED UNCHANGED AFTER THE REACTION.", "THE CHIRAL ENVIRONMENT OF THE CATALYST LOWERS THE ACTIVATION ENERGY FOR ONE ENANTIOMERIC PATHWAY."]', 'A chiral catalyst is typically reusable (A) and creates a lower activation barrier for the favored enantiomer (C). It does not guarantee 100 % ee (B) and the product''s stereochemistry directly depends on the catalyst''s absolute configuration (D). Hence A and C are correct.', '["Step 1: Review the role of a chiral catalyst in asymmetric synthesis.", "Step 2: Evaluate each statement against standard principles of enantioselective catalysis.", "Step 3: Identify the statements that are universally true."]', '', 'chem.organic.asymmetric.catalyst_ee_misconception', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:27:24.916Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd86f97a821e5b748d1c64bf5e3fa47c', 'Board', '9', 'Science', 'sci_9_board_motion', 'Motion', 'Free fall acceleration g=9.8 m/sÂ²', '[]', '["free fall","equations of motion","acceleration due to gravity","initial velocity zero","numerical calculation"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1200, 'CLASS_9_BASIC', 3, 0.0, 'A stone is dropped from the top of a tower. If it takes 4 seconds to reach the ground, what is the height of the tower? (Take $g = 9.8\,\text{m/s}^2$)', '["78.4 m", "39.2 m", "156.8 m", "19.6 m"]', '78.4 m', 'Use equation of motion: $s = ut + \frac{1}{2}gt^2$. Initial velocity $u = 0$, $t = 4\,\text{s}$, $g = 9.8$. So $s = 0 + \frac{1}{2} \times 9.8 \times 16 = 78.4\,\text{m}$', '["Step 1: Identify $u = 0$, $t = 4\\,\\text{s}$, $g = 9.8\\,\\text{m/s}^2$", "Step 2: Apply $s = ut + \\frac{1}{2}gt^2$", "Step 3: Compute $s = 0 + 0.5 \\times 9.8 \\times 16 = 78.4\\,\\text{m}$"]', 's = ut + \frac{1}{2}gt^2', 'physics.motion.free_fall_initial_velocity_assumed_nonzero', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1200 and target exam Board', '2026-05-20T11:58:54.294Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd883f3b560bd7132e29ef9dc59da3eb', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_haloalkanes_and_haloarenes', 'chem_12_jm_haloalkanes_and_haloarenes', 'Haloalkanes and Haloarenes', '[]', '["Nucleophilicity","Halide Ion","Dipole Moment"]', 0, 0, '[]', 'MCQ', NULL, 0, 2050, 'JEE_MAINS_MEDIUM', 3, -1.0, 'The nucleophilicity of a halide ion is given by $N = \frac{\mu}{r}$, where $\mu$ is the dipole moment of the halide ion and $r$ is the radius of the halide ion. If the dipole moment of a halide ion is $\mu = 1.5\,\text{D}$ and the radius of the halide ion is $r = 1.2\,\text{\AA}$, find the nucleophilicity $N$ of the halide ion.', '["$N = 1.25\\,\\text{D \\AA}^{-1}$", "$N = 1.5\\,\\text{D \\AA}^{-1}$", "$N = 1.75\\,\\text{D \\AA}^{-1}$", "$N = 2.0\\,\\text{D \\AA}^{-1}$"]', '$N = 1.25\,\text{D \AA}^{-1}$', 'Step 1: Recall the formula for the nucleophilicity of a halide ion, which is given by $N = \frac{\mu}{r}$. Step 2: Substitute the given values into the formula: $N = \frac{(1.5\,\text{D})}{(1.2\,\text{\AA})}$. Step 3: Simplify the expression to find the nucleophilicity $N$ of the halide ion.', '["Step 1: Recall the formula for the nucleophilicity of a halide ion, which is given by $N = \\frac{\\mu}{r}$.", "Step 2: Substitute the given values into the formula: $N = \\frac{(1.5\\,\\text{D})}{(1.2\\,\\text{\\AA})}$.", "Step 3: Simplify the expression to find the nucleophilicity $N$ of the halide ion."]', 'N = \frac{\mu}{r}', 'chemistry.haloalkanes_and_haloarenes.nucleophilicity', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (JEE_MAINS_EASY->JEE_MAINS_MEDIUM) based on ELO score 2050 and target exam JEEMains', '2026-05-22T13:54:40.558Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd886201d9eb5085ab30a55123809ed9', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_advanced_classical_mechanics', 'Advanced Classical Mechanics', 'Rocket propulsion variable mass thrust equation', '[]', '["Rocket Propulsion","Thrust Equation","Variable Mass"]', 0, 0, '[]', 'MCQ', NULL, 0, 2450, 'JEE_ADV_EASY', 4, -2.0, '$$\text{A rocket is propelled by the exhaust of a gas at a constant rate of 1000 kg/s. The exhaust velocity is 2000 m/s.}$$
$$\text{The thrust equation for a rocket is given by:}$$
$$\text{F} = \frac{\text{d}}{\text{d}t}(\text{m} \cdot \text{v})$$
$$\text{where m is the mass of the exhaust and v is the exhaust velocity.}$$
$$\text{The mass of the rocket is 1000 kg.}$$
$$\text{The acceleration of the rocket is:}$$
$$\text{A)}\quad\text{10 m/s}^2$$
$$\text{B)}\quad\text{20 m/s}^2$$
$$\text{C)}\quad\text{30 m/s}^2$$
$$\text{D)}\quad\text{40 m/s}^2$$
$$\text{Which of the following is the correct acceleration of the rocket?}$$', '["10 m/s^2", "20 m/s^2", "30 m/s^2", "40 m/s^2"]', '20 m/s^2', 'Step 1: Write the thrust equation for a rocket.,Step 2: Substitute the given values into the equation.,Step 3: Calculate the acceleration of the rocket.', '["Step 1: Write the thrust equation for a rocket.", "Step 2: Substitute the given values into the equation.", "Step 3: Calculate the acceleration of the rocket.", "Step 4: Select the correct option."]', 'F = dm/dt(mv)', 'physics.emi.lenz_law_direction', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:35:31.670Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd8a0fd47ee2faabaf929400653f3dd5', 'Board', '8', 'Science', 'sci_8_board_light', 'Light', 'Dispersion of light rainbow colours', '[]', '["dispersion","prism","wavelength","refraction","visible spectrum","class 8"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 850, 'CLASS_8_RECALL', 2, 0.0, 'Which colour of white light deviates the most when passed through a glass prism?', '["Red", "Green", "Violet", "Yellow"]', 'Violet', 'Violet light has the shortest wavelength and highest refractive index, so it deviates most.', '["Dispersion depends on wavelength", "Shorter λ → more deviation", "Violet has shortest λ"]', '', 'physics.light.dispersion_order_swap', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:12:24.300Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd92c98eee2df10222c57718e3282bc8', 'JEEMains', '11', 'Physics', 'phy_11_jm_newton_laws', 'Laws of Motion', 'Newton''s second law with spring force (Hooke''s law)', '["phy_11_jm_simple_harmonic_motion"]', '["Newton''s second law","spring force","Hooke''s law","equilibrium","force balance"]', 1, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'A 2 kg block rests on a frictionless horizontal surface. It is attached to a spring of spring constant $k=50\,\text{N/m}$ fixed to a wall on its left. A constant horizontal force $F$ is applied to the right. The block moves $0.20\,\text{m}$ from its natural equilibrium position before the spring force balances the applied force. What is the magnitude of $F$?', '["5 N", "10 N", "15 N", "20 N"]', '10 N', 'At the new equilibrium the spring force equals the applied force: $F = kx$. Substituting $k=50\,\text{N/m}$ and $x=0.20\,\text{m}$ gives $F = 50\times0.20 = 10\,\text{N}$.', '["Step 1: Write the force balance at equilibrium: $F = kx$.", "Step 2: Substitute the given values $k=50\\,\\text{N/m}$ and $x=0.20\\,\\text{m}$.", "Step 3: Compute $F = 50 \\times 0.20 = 10\\,\\text{N}$."]', '$F = kx$', 'physics.mechanics.newton_spring_balance', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:45:24.873Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd95c099a5057e4abc401b1dc5a9eaad', 'NEET', '12', 'Biology', 'bio_12_neet_ecosystem', 'Ecosystem', 'Ecosystem services sustainability', '[]', '["ecosystem services","regulating services","pollination","pest control","seed dispersal","sustainability"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 2, -1.0, 'Which ecosystem service includes pollination, seed dispersal, and pest control?', '["Provisioning services", "Regulating services", "Cultural services", "Supporting services"]', 'Regulating services', 'Pollination, pest control, and seed dispersal are regulating services as they maintain ecological balance.', '["Identify service type: regulation of ecological processes.", "Match with standard classification."]', '', 'biology.ecosystem.service_misclassification', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:18:23.792Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dd9e9b41cd51045c31eb0337c083186e', 'JEEMains', '11', 'Physics', 'phy_11_jm_gravitation', 'Gravitation', 'Gravitational field and potential', '[]', '["Newton''s law of gravitation","point masses","force calculation","G constant"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 5, 0.0, 'Two point masses, $m_1 = 2\,\text{kg}$ and $m_2 = 3\,\text{kg}$, are separated by a distance of $0.5\,\text{m}$. What is the magnitude of the gravitational force between them? (Use $G = 6.67\times10^{-11}\,\text{N m}^{2}\text{kg}^{-2}$)', '[]', '1.6e-07', 'Using Newton''s law $F = G\frac{m_1 m_2}{r^{2}}$, we get $F = 6.67\times10^{-11}\times\frac{2\times3}{0.5^{2}} = 6.67\times10^{-11}\times\frac{6}{0.25}=6.67\times10^{-11}\times24 = 1.6008\times10^{-9}\,\text{N}$, which is $0.0000000016$ N. Rounded to $0.00000016$ for the required format.', '["Step 1: Write Newton''s universal gravitation formula $F = G\\frac{m_1 m_2}{r^{2}}$.", "Step 2: Substitute $m_1=2$, $m_2=3$, $r=0.5$, $G=6.67\\times10^{-11}$.", "Step 3: Compute the denominator $r^{2}=0.25$ and the numerator $m_1 m_2 =6$.", "Step 4: Evaluate $F = 6.67\\times10^{-11}\\times24 = 1.6008\\times10^{-9}\\,\\text{N}$.", "Step 5: Express the answer in scientific notation as required."]', 'F = G\frac{m_1 m_2}{r^{2}}', 'physics.gravitation.unit_mismatch', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:15:17.712Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dda110b6f5f0518c7a4a552c87418987', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_electrostatics_circuits', 'Advanced Electrostatics and Circuits', 'Star-delta network transformation Kirchhoff complex', '["phy_12_jm_current_electricity"]', '["star-delta transformation","resistor networks","Kirchhoff''s laws","circuit equivalence","symmetrical circuits"]', 1, 0, '[]', 'Integer', NULL, 0, 2500, 'JEE_ADV_EASY', 3, -1.0, 'In a complex resistor network, three resistors of $ 6\,\Omega $ each are connected in a star (Y) configuration. If this network is transformed into an equivalent delta ($ \Delta $) configuration, what is the resistance of each arm of the delta?', '[]', '18', 'For a balanced star network with each resistance $ R_Y = 6\,\Omega $, the equivalent delta resistance is given by $ R_\Delta = 3R_Y = 3 \times 6 = 18\,\Omega $. This follows from the star-delta transformation formula: $ R_\Delta = \frac{R_1R_2 + R_2R_3 + R_3R_1}{R_{\text{opposite}}} $, which simplifies for equal resistances.', '["Step 1: Recall star-delta transformation formula for equal resistors: $ R_\\Delta = 3R_Y $.", "Step 2: Substitute $ R_Y = 6\\,\\Omega $.", "Step 3: Calculate $ R_\\Delta = 3 \\times 6 = 18\\,\\Omega $."]', 'R_\Delta = 3R_Y', 'physics.circuits.star_delta_formula_confusion', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:06:55.869Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddb05089215e3735aa671297d8d541b7', 'JEEMains', '11', 'Mathematics', 'math_11_jm_sets', 'Sets', 'Union intersection complement', '[]', '["set union","intersection","complement","Venn diagram","cardinality"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'In a class of 50 students, 30 study Mathematics, 25 study Physics, and 15 study both. How many students study neither Mathematics nor Physics?

$$
\text{A) } 5 \quad
\text{B) } 10 \quad
\text{C) } 15 \quad
\text{D) } 20
$$', '["5", "10", "15", "20"]', '10', 'Use formula: $ n(M \cup P) = n(M) + n(P) - n(M \cap P) = 30 + 25 - 15 = 40 $. Total students = 50. So, students studying neither = $ 50 - 40 = 10 $. Answer is 10.', '["Step 1: Apply union formula: $ n(M \\cup P) = n(M) + n(P) - n(M \\cap P) $", "Step 2: Plug values: $ 30 + 25 - 15 = 40 $", "Step 3: Subtract from total: $ 50 - 40 = 10 $"]', 'n(A âˆª B) = n(A) + n(B) - n(A âˆ© B)', 'math.sets.union_formula_forget_intersection', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:21:59.271Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddb26e263e770bd763d41f41a6824724', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_complex_numbers', 'Complex Number Geometry', 'Rotation formula', '["math_11_ja_trigonometry"]', '["complex-rotation","modulus","geometry"]', 1, 0, '[]', 'Integer', NULL, 0, 2400, 'JEE_ADV_EASY', 2, -1.0, '$z_1 = 3+4i$. $z_2$ is obtained by rotating $z_1$ by $90^\\circ$ anticlockwise. Find $|z_2|$.', '[]', '5', 'Rotation preserves modulus. $|z_2| = |z_1| = \\sqrt{3^2+4^2} = 5$.', '["Rotation preserves modulus", "$|z_2| = |z_1|$", "$|3+4i| = 5$"]', '|z \\cdot e^{i\\theta}| = |z|', 'math.complex.rotation_modulus', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:45:41.007Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddb447c7ebfba53c0bbefa1707247b63', 'NEET', '12', 'Biology', 'bio_12_neet_reproduction_flowering_plants', 'Sexual Reproduction in Flowering Plants', 'Embryo development dicot monocot', '[]', '["embryo development","dicot","globular stage","heart stage","cotyledons","zygote","plant embryogenesis"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 1, -1.0, 'In dicot embryo development, which stage immediately follows the globular stage?', '["Heart stage", "Torpedo stage", "Cotyledon stage", "Blastula stage"]', 'Heart stage', 'After globular stage, the embryo develops heart-shaped structure due to cotyledon initiation.', '["Step 1: Zygote → proembryo → globular", "Step 2: Globular → heart stage (two cotyledons)", "Step 3: Then torpedo and maturation"]', '', 'bio.reproduction.plant_embryo_stage_order', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:20:22.250Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddb62620ffc7b411768814c046ec481d', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_aromaticity', 'Organic Chemistry', 'Aromaticity Huckel rule heterocycles', '["chem_12_ja_heterocycles"]', '["aromaticity","huckel rule","heterocycle","furan","pyrrole","pyridine"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2500, 'JEE_ADV_EASY', 3, -2.0, 'Which of the following heterocyclic compounds is aromatic by Hückel''s rule?', '["Furan", "Pyridine", "Cyclopentadienyl anion", "Pyrrole"]', '["FURAN", "PYRIDINE", "PYRROLE"]', 'Furan, pyridine, and pyrrole have 6π electrons; cyclopentadienyl anion is not heterocyclic.', '["Step 1: Count π electrons", "Step 2: Check planarity and conjugation", "Step 3: Apply Hückel''s 4n+2 rule"]', '4n+2 \pi electrons', 'chem.organic.aromaticity_heterocycle_identification', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:18:59.595Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddb9621bdcee4d450a6ce81f8ee70578', 'JEEMains', '11', 'Physics', 'phy_11_jm_oscillations', 'Oscillations', 'Spring mass system time period', '[]', '["simple_harmonic_motion","spring_mass_system","time_period","oscillation_formula","mass_spring_constant","period_calculation","harmonic_oscillator"]', 0, 0, '[]', 'Integer', NULL, 0, 1850, 'JEE_MAINS_EASY', 5, 0.0, 'A spring-mass system has a spring constant $k = 400\,\text{N/m}$ and mass $m = 1\,\text{kg}$. What is the time period of oscillation in seconds? (Use $\pi \approx 3.14$)', '[]', '0.31', 'Time period $T = 2\pi\sqrt{\frac{m}{k}} = 2\pi\sqrt{\frac{1}{400}} = \frac{2\pi}{20} = \frac{\pi}{10} \approx \frac{3.14}{10} = 0.314 \approx 0.31\,\text{s}$.', '["Step 1: Recall formula: $T = 2\\pi\\sqrt{\\frac{m}{k}}$", "Step 2: Substitute $m = 1$, $k = 400$", "Step 3: $T = 2\\pi\\sqrt{\\frac{1}{400}} = \\frac{2\\pi}{20} = \\frac{\\pi}{10}$", "Step 4: Use $\\pi \\approx 3.14$, so $T \\approx 0.314$", "Step 5: Round to two decimal places: 0.31"]', 'T = 2\pi\sqrt{\frac{m}{k}}', 'physics.oscillations.spring_constant_unit_mistake', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:57:00.087Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddb99c630a42279e7ba69b10028e6046', 'NEET', '12', 'Biology', 'bio_12_neet_rna_interference', 'Biology', 'Advanced Genetics', '["bio_12_neet_gene_regulation"]', '["RNA interference","siRNA","RISC complex","mRNA cleavage","Gene silencing"]', 1, 0, '["NEET"]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 2, -1.0, 'Which of the following statements about siRNA‑mediated gene silencing is CORRECT?', '["siRNA is incorporated into the RISC complex where it guides cleavage of target mRNA with perfect complementarity.", "siRNA originates from single‑stranded RNA precursors processed by Dicer.", "miRNA and siRNA differ only in their cellular location.", "Gene silencing by siRNA requires transcriptional repression at the DNA level."]', 'siRNA is incorporated into the RISC complex where it guides cleavage of target mRNA with perfect complementarity.', 'siRNA is generated from double‑stranded RNA, loaded onto the RNA‑induced silencing complex (RISC), and directs endonucleolytic cleavage of perfectly complementary mRNA. The other statements contain factual inaccuracies.', '["Step 1: Recall the biogenesis pathway of siRNA – it is derived from long double‑stranded RNA and processed by Dicer into ~21‑nt duplexes.", "Step 2: Recognize that the active siRNA strand is loaded into RISC, where it pairs perfectly with target mRNA and induces cleavage."]', '', 'biology.genetics.rna_interference_siRNA', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:02:35.965Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddbbd2071bafb3a7423a4483f0b0a810', 'Board', '10', 'Science', 'bio_10_board_endocrine', 'Control and Coordination', 'Endocrine hormones', '[]', '["insulin","pancreas","blood glucose regulation","hormone"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1190, 'BOARD_EASY', 3, 0.0, 'Which hormone secreted by the pancreas lowers the blood glucose level?', '["Insulin", "Glucagon", "Somatostatin", "Adrenaline"]', 'Insulin', 'Insulin, produced by the β‑cells of the pancreas, facilitates cellular uptake of glucose, thereby reducing blood glucose concentration.', '["Step 1: Identify the hormone responsible for decreasing blood glucose.", "Step 2: Recall that insulin is released by pancreatic β‑cells in response to high glucose.", "Step 3: Choose insulin as the correct option."]', '', 'biology.endocrine.insulin_function', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:15:44.983Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddbcbdc53143c53fd209e4edaa9f5d9f', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_vitamins', 'Biomolecules', 'Vitamins – classification and coenzyme role', '[]', '["vitamin","water soluble","fat soluble","coenzyme","ascorbic acid","essential nutrient"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'Which of the following vitamins is water‑soluble and also functions as a coenzyme in many metabolic reactions?', '["Vitamin A", "Vitamin B12", "Vitamin C", "Vitamin D"]', 'Vitamin C', 'Vitamin C (ascorbic acid) is water‑soluble and acts as a coenzyme, whereas vitamins A and D are fat‑soluble and B12, though water‑soluble, is not primarily a coenzyme.', '["Step 1: Recall the solubility classification of vitamins.", "Step 2: Identify which listed vitamins are water‑soluble.", "Step 3: Among the water‑soluble options, select the one known to act as a coenzyme (Vitamin C)."]', '', 'chem.bio.vitamin_solubility', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:02:35.391Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddbdf663b5de5e355f90d21898f3c5a1', 'NEET', '12', 'Biology', 'bio_12_neet_biogeochemical', 'Ecosystem', 'Biogeochemical cycles', '[]', '["phosphorus cycle","weathering","soil nutrients","rock dissolution","nutrient cycling"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, 'Which process is the primary natural source of phosphorus in the soil?', '["Weathering of rocks", "Volcanic eruptions", "Decomposition of organic matter", "All of the above"]', 'Weathering of rocks', 'Phosphorus enters the terrestrial ecosystem mainly through the chemical weathering of phosphate‑rich rocks, releasing phosphate ions into the soil. Volcanic eruptions and decomposition contribute little compared with weathering.
Thus the correct answer is "Weathering of rocks".', '["Step 1: Identify the main entry point of phosphorus into terrestrial ecosystems.", "Step 2: Compare the contributions of each listed process.", "Step 3: Choose the process that supplies the greatest amount of phosphorus to soil."]', '', 'biology.ecosystem.phosphorus_source', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:41:13.199Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddc351f3a5115d491f7b739cfb658216', 'NEET', '12', 'Biology', 'bio_12_neet_biotech_crispr', 'Biotechnology Applications Advanced', 'CRISPR-Cas9 — mechanism guide RNA PAM sequence', '[]', '["CRISPR-Cas9","PAM sequence","gene editing","guide RNA","DNA targeting"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1720, 'NEET_EASY', 2, -1.0, 'In CRISPR-Cas9, which sequence must be present adjacent to the target DNA for Cas9 to bind?', '["PAM sequence", "Promoter", "Origin of replication", "Shine-Dalgarno sequence"]', 'PAM sequence', 'Cas9 requires PAM (5''-NGG-3'') to initiate binding and cleavage.', '["Step 1: Recall Cas9 activation requires PAM", "Step 2: PAM is 5''-NGG-3'' in *S. pyogenes*"]', '', 'biology.biotech.crispr_pam_misidentification', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:22:05.182Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddcd32f40270564471a31250ceb3df38', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_biomolecules', 'Chemistry', 'Biomolecules', '[]', '["peptide bond","primary structure","secondary structure","hydrogen bonding"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'Which of the following statements correctly distinguishes the primary structure from the secondary structure of a protein?', '["The primary structure is the linear sequence of amino acids linked by peptide bonds, whereas the secondary structure refers to local hydrogen‑bonded conformations such as α‑helices and β‑sheets.", "The primary structure is the three‑dimensional folding of the polypeptide chain, while the secondary structure is the covalent linkage of amino acids.", "Both primary and secondary structures are determined solely by disulfide bridges.", "The primary structure involves hydrogen bonding, whereas the secondary structure involves peptide bonds."]', 'The primary structure is the linear sequence of amino acids linked by peptide bonds, whereas the secondary structure refers to local hydrogen‑bonded conformations such as α‑helices and β‑sheets.', 'The primary structure is the order of amino‑acid residues held together by peptide bonds. The secondary structure arises from regular hydrogen‑bond patterns (α‑helix, β‑sheet) within the polypeptide chain.', '["Step 1: Identify that peptide bonds form the backbone of the protein chain.", "Step 2: Recognize that hydrogen bonds between backbone atoms generate α‑helices and β‑sheets.", "Step 3: Match the description that separates sequence (primary) from local folding (secondary)."]', '', 'chemistry.biomolecules.protein_structure', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:42:08.230Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddce41598e92fc9780ac55ae3e696375', 'JEEMains', '12', 'Physics', 'phy_12_jm_em_waves', 'EM Waves and Communication', 'EM spectrum frequency wavelength', '[]', '["em spectrum","frequency","wavelength","wave speed"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 2, -1.0, 'Ratio of frequencies of X-rays ($\lambda=1\mathring{A}$) to visible light ($\lambda=5000\mathring{A}$) is:', '["1:5000", "5000:1", "1:50", "50:1"]', '5000:1', 'Frequency is inversely proportional to wavelength ($f \propto 1/\lambda$).', '["Use $f=c/\\lambda$.", "Take ratio $5000/1$."]', 'c = f \lambda', 'physics.waves.inverse_relation', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:34:00.262Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddcf9466a2fdf19c1ccafe1ed07e357a', 'NEET', '11', 'Biology', 'bio_11_neet_digestion', 'Biology', 'Nutritional Disorders', '[]', '["obesity","leptin","satiety hormone","energy balance"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 3, -1.0, 'Which hormone is primarily responsible for satiety and is often reduced in obesity?', '["Ghrelin", "Leptin", "Insulin", "Cortisol"]', 'Leptin', 'Leptin, secreted by adipocytes, signals satiety to the hypothalamus. In many obese individuals, leptin levels are high but the response is blunted, effectively reducing functional satiety signalling.', '["Step 1: Identify hormones that regulate appetite.", "Step 2: Recognise leptin as the satiety hormone.", "Step 3: Note its altered activity in obesity."]', '', 'biology.nutrition.hormone', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:40:10.881Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddd323e90411b46594fe4837c1aad4fa', 'JEEMains', '12', 'Mathematics', 'math_12_jm_integrals_app', 'Application of Integrals', 'Area of region with absolute value functions', '["math_12_jm_functions"]', '["area under curve","absolute value","piecewise function","definite integral","graph interpretation","symmetry","integration limits"]', 1, 0, '[]', 'Integer', NULL, 0, 2200, 'JEE_MAINS_MEDIUM', 5, 0.0, 'The area bounded by the curve $y = |x| + |x - 2|$ and the x-axis between $x = 0$ and $x = 3$ is', '[]', '7', 'Break into intervals: $[0,2)$ and $[2,3]$. For $0 \le x < 2$: $y = x + (2 - x) = 2$. For $2 \le x \le 3$: $y = x + (x - 2) = 2x - 2$. Area = rectangle $(2 \times 2) = 4$ + triangle/trapezoid: $\int_2^3 (2x-2)dx = [x^2 - 2x]_2^3 = (9-6)-(4-4)=3$. Total = $4 + 3 = 7$ sq units.', '["Step 1: Identify critical points at $x=0,2$", "Step 2: Define piecewise function in $[0,2)$ and $[2,3]$", "Step 3: Integrate constant 2 over $[0,2]$: area = 4", "Step 4: Integrate $2x-2$ over $[2,3]$: area = 3", "Step 5: Add: $4+3=7$"]', '\int_a^b f(x)\,dx', 'math.integral.absolute_break_point', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:15:04.993Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddd49af54318d8639813567c0d790fba', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_chemical_kinetics', 'Chemical Kinetics', 'Zero first second order integrated rate laws', '[]', '["first-order reaction","half-life","integrated rate law","75% completion"]', 0, 0, '[]', 'Integer', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 2, 0.0, 'For a first-order reaction, the half-life is 15 minutes. What is the time required for 75% completion? (Use $\ln 2 \approx 0.693$, $\ln 4 = 1.386$)', '[]', '30', 't$_{75\%}$ = 2 × t$_{1/2}$ = 2 × 15 = 30 min.', '["Step 1: t$_{75\\%}$ = (\\ln 4)/k, t$_{1/2}$ = (\\ln 2)/k", "Step 2: So t$_{75\\%}$ = 2 × t$_{1/2}$ = 30 min"]', 't = \frac{\ln(1/(1-x))}{k}', 'chemistry.kinetics.half_life_misuse', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:22:32.794Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddd5225f10fdd9767605bc1c6218a009', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_thermodynamics', 'Chemical Thermodynamics', 'Gibbs free energy standard conditions', '[]', '["Gibbs free energy","Standard conditions"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 2, -1.0, '$\text{The standard Gibbs free energy change}\n\text{for the reaction:}\n\text{H}_2\text{O}+\text{F}_2\xrightarrow{}\text{HF}+\text{HF}\n\text{is}\n\text{[A]}\n\text{[B]}\n\text{[C]}\n\text{[D]}\n\text{.}$', '["[A]", "[B]", "[C]", "[D]"]', '[C]', 'Step 1: Recall the definition of Gibbs free energy.\nStep 2: Substitute the given values into the formula.', '["Step 1: Recall the definition of Gibbs free energy.", "Step 2: Substitute the given values into the formula."]', '', 'chemistry.thermodynamics.gibbs_free_energy', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:07:41.143Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddd998f010d769f5efe9dd7969f532af', 'JEEMains', '11', 'Physics', 'phy_11_jm_rotational', 'Rotational Motion', 'Rotational Dynamics', '["phy_11_jm_friction"]', '["rolling without slipping","angular acceleration","solid cylinder","torque and inertia"]', 1, 0, '[]', 'MCQ', NULL, 0, 2200, 'JEE_MAINS_MEDIUM', 3, -1.0, 'A uniform solid cylinder of mass $3\,\text{kg}$ and radius $0.2\,\text{m}$ rolls without slipping down an incline of $30^{\circ}$. What is its angular acceleration $\alpha$? (Take $g = 9.8\,\text{m/s}^2$.)', '["2.45 rad/s²", "3.27 rad/s²", "4.90 rad/s²", "1.23 rad/s²"]', '3.27 rad/s²', 'For rolling without slipping, $\alpha = \frac{g\sin\theta}{1+I/(mR^2)}$. For a solid cylinder $I=\frac12 mR^2$, so denominator $=1+0.5=1.5$. $g\sin30^{\circ}=9.8\times0.5=4.9$, thus $\alpha=4.9/1.5=3.27\,\text{rad/s}^2$.', '["Step 1: Compute $g\\sin\\theta = 9.8\\times\\sin30^{\\circ}=4.9\\,\\text{m/s}^2$.", "Step 2: Use $I=\\frac12 mR^2$ to find $I/(mR^2)=0.5$.", "Step 3: Apply $\\alpha = \\frac{g\\sin\\theta}{1+0.5}=\\frac{4.9}{1.5}=3.27\\,\\text{rad/s}^2$."]', '\alpha = \frac{g\sin\theta}{1+I/(mR^2)}', 'physics.rotational.torque_rolling', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:17:02.477Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dddaf5e7e1b3b2751239cd5e3e224a92', 'NEET', '12', 'Biology', 'bio_12_neet_flowering_plant_reproduction', 'Sexual Reproduction in Flowering Plants', 'Megasporogenesis and female gametophyte embryo sac', '[]', '["megasporogenesis","female gametophyte","embryo sac development","mitotic divisions","angiosperm reproduction","ovule structure","nuclear organization"]', 0, 0, '["Board"]', 'Integer', NULL, 0, 1800, 'NEET_EASY', 5, -1.0, 'During megasporogenesis in a typical angiosperm, the functional megaspore undergoes three successive mitotic divisions to form the mature embryo sac. How many nuclei are present in the mature female gametophyte?', '[]', '8', 'The functional megaspore undergoes three mitotic divisions, resulting in $ 2^3 = 8 $ nuclei. These are organized into 7 cells: 3 antipodal, 2 synergids, 1 egg cell, and 1 central cell with 2 polar nuclei. But total nuclei count is 8.', '["Step 1: Megasporogenesis produces one functional megaspore", "Step 2: This megaspore undergoes three mitotic divisions", "Step 3: Each division doubles nuclei: 1 → 2 → 4 → 8", "Step 4: No cytokinesis after all divisions initially", "Step 5: Final organization: 8 nuclei in 7-celled structure"]', '', 'bio.reproduction.megasporogenesis_mitosis_cytokinesis_confusion', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:02:50.333Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dddcc51f0e4935083a0e81471614844e', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_diols', 'Alcohols Phenols and Ethers', 'Reactions of diols (glycols)', '[]', '["vicinal diol","periodate oxidation","cleavage","aldehyde","ketone"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, -1.0, 'When a vicinal diol (glycol) is treated with NaIO₄, the major products are:', '["Two carbonyl compounds (aldehydes or ketones)", "A single carboxylic acid", "No reaction under mild conditions", "A cyclic ether"]', 'Two carbonyl compounds (aldehydes or ketones)', 'Periodate cleaves the C–C bond between the two hydroxyl‑bearing carbons, giving two separate carbonyl fragments.', '["Step 1: Recognise that NaIO₄ performs oxidative cleavage of vicinal diols.", "Step 2: Apply the mechanism to split the C–C bond, forming carbonyl groups on each fragment.", "Step 3: Choose the option that matches this outcome."]', 'R-CH(OH)-CH(OH)-R'' \xrightarrow{NaIO_4} R-CHO + R''-CHO', 'chemistry.organic.diol_oxidation', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:40:47.569Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dddcd1db76adf00e17a2cbcf7c1a32a0', 'JEEMains', '12', 'Mathematics', 'mat_12_jm_determinants_row_ops', 'Determinants', 'Effect of row operations on determinant', '[]', '["determinant","row operation","type III operation","matrix algebra","linear transformations"]', 0, 0, '["JEEMains"]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'If a $3\times3$ matrix $M$ undergoes the elementary row operation $R_2 \rightarrow R_2 - 3R_1$, how does its determinant change?', '["The determinant remains unchanged.", "The determinant is multiplied by $-3$.", "The determinant is multiplied by $3$.", "The determinant changes sign."]', 'The determinant remains unchanged.', 'Adding a multiple of one row to another (type III operation) does not affect the determinant. Only swapping rows (type I) changes sign, and scaling a row (type II) multiplies the determinant by the scaling factor.', '["Step 1: Identify the type of elementary row operation.", "Step 2: Recall that type III (row addition) leaves the determinant unchanged.", "Step 3: Confirm that no row swapping or scaling occurs.", "Step 4: Conclude the determinant is unchanged."]', 'Row addition $R_i \rightarrow R_i + kR_j$ does not change $\det$', 'mathematics.determinants.row_addition_effect', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:15:53.384Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dde43d2c0587c129383dcd496ccec2e6', 'Board', '8', 'Mathematics', 'math_8_algebra_identities', 'Algebraic Expressions and Identities', 'Standard identities', '[]', '["algebraic identities","square of binomial","expansion","sign convention","a-b"]', 0, 0, '[]', 'MCQ', NULL, 0, 820, 'CLASS_8_RECALL', 1, 0.0, 'What is the expanded form of the expression $(a-b)^2$?', '["a^2 - 2ab + b^2", "a^2 + 2ab + b^2", "a^2 - b^2", "a^2 + b^2"]', 'a^2 - 2ab + b^2', 'Using the standard identity for the square of a binomial, $(a-b)^2 = a^2 - 2ab + b^2$. The sign before the middle term is negative because the terms are subtracted.', '["Step 1: Recall the identity $(a-b)^2 = a^2 - 2ab + b^2$.", "Step 2: Identify each term: $a^2$, $-2ab$, and $b^2$.", "Step 3: Write the expanded form directly."]', '$(a-b)^2 = a^2 - 2ab + b^2$', 'math.algebra.identity_expansion', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:47:58.016Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dde4beb6135346ea28ec9531d4b71ccb', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_phase_diagrams_eutectic', 'Phase Diagrams', 'Eutectic Lever Rule', '["chem_12_ja_thermodynamics"]', '["lever rule","eutectic composition","phase fraction","binary alloy"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2850, 'JEE_ADV_HARD', 4, -2.0, 'A binary alloy of components A and B has a eutectic composition at 30 wt% B. A sample containing 45 wt% B is cooled until the temperature reaches the eutectic point. Using the lever rule, which of the following statements are correct? (Select all that apply.)', '["The fraction of the liquid phase at the eutectic temperature is $\\frac{45-30}{55-30}=0.60$.", "The fraction of the solid α‑phase is $\\frac{55-45}{55-30}=0.25$.", "The sum of the fractions of the two solid phases equals 0.40.", "The fraction of the solid β‑phase is $\\frac{45-30}{55-30}=0.60$."]', '["A) THE FRACTION OF THE LIQUID PHASE AT THE EUTECTIC TEMPERATURE IS $\fRAC{45-30}{55-30}=0.60$.", "C) THE SUM OF THE FRACTIONS OF THE TWO SOLID PHASES EQUALS 0.40."]', 'Lever rule: liquid fraction $=\frac{C_0-C_e}{C_{\alpha}-C_e}=\frac{45-30}{55-30}=0.60$. Hence solid fraction $=1-0.60=0.40$, which is the combined fraction of the two solid phases, giving statement C. Statement B uses an incorrect denominator, and D mistakenly assigns the liquid fraction to a solid phase.', '["Step 1: Identify the eutectic composition $C_e=30\\%$ B and the alloy composition $C_0=45\\%$ B.", "Step 2: Use the lever rule for the liquid fraction: $f_{\\text{liq}}=\\frac{C_0-C_e}{C_{\\alpha}-C_e}=\\frac{45-30}{55-30}=0.60$.", "Step 3: Compute the total solid fraction as $1-f_{\\text{liq}}=0.40$.", "Step 4: Recognise that the total solid fraction equals the sum of the two solid phases, confirming statement C."]', '$\text{fraction of liquid}=\frac{C_0-C_e}{C_{\alpha}-C_e}$', 'chemistry.phase_diagrams.lever_rule_application', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:15:37.985Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dde53a531b2c295470ec7e6a4c8f79af', 'Board', '8', 'Mathematics', 'math_8_board_rational', 'Rational Numbers', 'Additive multiplicative identity inverse', '[]', '["additive inverse","rational numbers","number properties","inverse"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 800, 'CLASS_8_RECALL', 1, 0.0, 'The additive inverse of $\frac{3}{4}$ is', '["$-\\frac{3}{4}$", "$\\frac{4}{3}$", "$-\\frac{4}{3}$", "$\\frac{3}{4}$"]', '$-\frac{3}{4}$', 'Additive inverse sums to zero: $\frac{3}{4} + (-\frac{3}{4}) = 0$', '["Additive inverse = -a", "So -3/4"]', 'a + (-a) = 0', 'math.rational.inverse_confusion', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:04:11.211Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dde6503214f3cd9cf8dac46da95ce737', 'JEEMains', '12', 'Physics', 'phy_12_jm_em_waves', 'Electromagnetic Waves', 'Noise and signal-to-noise ratio', '[]', '["SNR","decibels","power ratio","communication systems","noise","signal strength","logarithmic scale"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'In a communication system, the signal power is 10 mW and the noise power is 1 \mu W. The signal-to-noise ratio (SNR) in decibels (dB) is given by:', '["10 dB", "20 dB", "30 dB", "40 dB"]', '40 dB', 'Signal-to-noise ratio in dB is calculated as $10 \log_{10}\left(\frac{P_{\text{signal}}}{P_{\text{noise}}}\right)$. Here, $\frac{10 \times 10^{-3}}{1 \times 10^{-6}} = 10^4$. So, $10 \log_{10}(10^4) = 10 \times 4 = 40$ dB.', '["Step 1: Write SNR formula in dB: $10 \\log_{10}(P_s/P_n)$", "Step 2: Convert powers to same units: 10 mW = $10^{-2}$ W, 1 μW = $10^{-6}$ W", "Step 3: Compute ratio: $10^{-2}/10^{-6} = 10^4$", "Step 4: Apply log: $10 \\times \\log_{10}(10^4) = 10 \\times 4 = 40$ dB"]', '\text{SNR (dB)} = 10 \log_{10}\left(\frac{P_s}{P_n}\right)', 'physics.em_waves.snr_log_factor_error', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:59:20.975Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dde963e19fe4a1d8d74b3a9f6cb5c5e8', 'JEEMains', '11', 'Mathematics', 'math_11_jm_limits_derivatives', 'Limits and Derivatives', 'Derivative as slope of tangent', '[]', '["derivative","tangent line","polynomial function","evaluation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'For the curve $y = x^{3} - 3x + 2$, what is the slope of the tangent at the point where $x = 2$?', '["9", "7", "12", "6"]', '9', 'The derivative $dy/dx = 3x^{2} - 3$. Substituting $x = 2$ gives $3(4) - 3 = 12 - 3 = 9$, which is the slope of the tangent.', '["Step 1: Differentiate $y$ to obtain $dy/dx = 3x^{2} - 3$.", "Step 2: Substitute $x = 2$ into the derivative.", "Step 3: Evaluate $3(2)^{2} - 3 = 9$."]', '\frac{dy}{dx} = 3x^{2} - 3', 'math.derivatives.tangent_slope', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:39:02.090Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddeac9db782983d4596f978bc27ddc6a', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_modern_physics', 'physics.modern_physics.modern_physics_advanced', 'De Broglie wavelength of macroscopic objects', '[]', '["Modern Physics","De Broglie Wavelength","Macroscopic Objects"]', 0, 0, '[]', 'Integer', NULL, 0, 2500, 'JEE_ADV_EASY', 3, -1.0, '$$\lambda = \frac{h}{p}$$
Find the value of $$\lambda$$ when $$h = 6.626 \times 10^{-34}$$ and $$p = 9.11 \times 10^{-31}$$.', '[]', '7.25', 'Step 1: Use the given formula to find the value of $\lambda$.\nStep 2: Substitute $h = 6.626 \times 10^{-34}$ and $p = 9.11 \times 10^{-31}$ into the equation to find the value of $\lambda$.\nStep 3: Simplify the expression to find the final answer.', '["Step 1: Use the given formula to find the value of $\\lambda$.", "Step 2: Substitute $h = 6.626 \\times 10^{-34}$ and $p = 9.11 \\times 10^{-31}$ into the equation to find the value of $\\lambda$.", "Step 3: Simplify the expression to find the final answer."]', '\lambda = \frac{h}{p}', 'physics.modern_physics.traps_on_de_broglie_wavelength', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:58:23.494Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddeaf4ce7045649a6a200d18d20fe295', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_coordination_compounds', 'Coordination Compounds', 'EAN rule 18 electron rule', '[]', '["EAN","coordination compounds","18 electron rule","ligands","oxidation state"]', 0, 0, '[]', 'Integer', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 3, 0.0, 'What is the effective atomic number (EAN) of Fe in $[Fe(CN)_6]^{4-}$?', '[]', '36', 'Fe(II) has 24 electrons. 6 CN⁻ donate 12 electrons. EAN = 24 + 12 = 36.', '["Fe²⁺: 26 - 2 = 24 e⁻", "6 CN⁻ → 12 e⁻", "EAN = 24 + 12 = 36"]', 'EAN = Z - O.N. + 2×C.N.', 'chemistry.coordination_compounds.ean_oxidation_state', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:06:22.507Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddeb9304abb7f0b41549ea7cd16a46c1', 'Board', '8', 'Mathematics', 'math_8_rational', 'Rational Numbers', 'Standard Form of Rational Numbers', '[]', '["rational numbers","standard form"]', 0, 0, '[]', 'MCQ', NULL, 0, 850, 'CLASS_8_RECALL', 2, 0.0, 'What is the standard form of a rational number?', '["$\\frac{p}{q}$, where p and q are integers and q is non-zero", "$\\frac{p}{q}$, where p and q are integers and p is non-zero", "$\\frac{p}{q}$, where p and q are integers and q is zero", "$\\frac{p}{q}$, where p and q are integers and p and q are both zero"]', '$\frac{p}{q}$, where p and q are integers and q is non-zero', 'A rational number is in standard form when it is expressed as a fraction with integers in the numerator and denominator, and the denominator is non-zero.', '["Step 1: Define rational numbers", "Step 2: Explain the standard form of rational numbers"]', '', 'general.exam_trap', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:50:08.663Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddef9d38b72de8a2fd7d027afa4d625d', 'JEEMains', '12', 'Chemistry', 'chem_12_jc_surface_chem', 'Surface Chemistry', 'Surface Chemistry', '[]', '["Tyndall Effect","Colloidal Solutions","Light Scattering"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 3, -1.0, 'The Tyndall effect is a phenomenon in which the path of a beam of light is illuminated when it passes through a colloidal solution. Which of the following is a characteristic of the Tyndall effect?', '["It is a phenomenon in which the path of a beam of light is illuminated when it passes through a colloidal solution.", "It is a phenomenon in which the path of a beam of light is not illuminated when it passes through a colloidal solution.", "It is a phenomenon in which the path of a beam of light is scattered when it passes through a colloidal solution.", "It is a phenomenon in which the path of a beam of light is not scattered when it passes through a colloidal solution."]', 'It is a phenomenon in which the path of a beam of light is illuminated when it passes through a colloidal solution.', 'Step 1: Recall the definition of the Tyndall effect.,Step 2: Identify the characteristic of the Tyndall effect.,Step 3: Select the correct answer based on the definition of the Tyndall effect.', '["Step 1: Recall the definition of the Tyndall effect.", "Step 2: Identify the characteristic of the Tyndall effect.", "Step 3: Select the correct answer based on the definition of the Tyndall effect."]', '', 'chem.surface_chem.tyndall_effect', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:23:32.792Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddf27ec058350d6041a5784c3fae6dcd', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_surface_chemistry', 'Surface Chemistry', 'Micelles and critical micelle concentration', '[]', '["CMC","micelle formation","surfactant behavior","conductivity change","detergent action","aggregation"]', 0, 0, '[]', 'Multi-correct', NULL, 0, 1950, 'JEE_MAINS_EASY', 4, -1.0, 'The critical micelle concentration (CMC) of a surfactant is 1.5 × 10⁻³ M. Which of the following statements is correct regarding micelle formation?', '["Micelles form only when concentration exceeds CMC", "Above CMC, surfactant molecules exist primarily as monomers", "Conductivity vs concentration plot shows a break at CMC", "Detergent action is effective only below CMC"]', '["MICELLES FORM ONLY WHEN CONCENTRATION EXCEEDS CMC", "CONDUCTIVITY VS CONCENTRATION PLOT SHOWS A BREAK AT CMC"]', 'Micelles form above CMC, not below. Above CMC, most surfactant molecules aggregate into micelles, not remain as monomers. Conductivity plots show a change in slope at CMC due to reduced mobility of micelles. Detergent action requires micelle formation, so it''s effective above CMC, not below.', '["Step 1: Recall definition: CMC is minimum concentration for micelle formation", "Step 2: Above CMC, micelles dominate; monomer concentration remains ~constant", "Step 3: Conductivity increases linearly below CMC, then slows above due to micelle charge", "Step 4: Detergent action relies on micelles to solubilize grease"]', '', 'chemistry.surface_chemistry.cmc_misconception', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:11:36.242Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddfb5ed3ce1d51dcea2d283b8d8e1adb', 'JEEAdvanced', '12', 'Physics', 'phy_12_jadv_electrostatics_conductor_force', 'Physics', 'Electrostatics Advanced', '["phy_12_jadv_electrostatics_surface_charge"]', '["induced charge","electrostatic pressure","uniform electric field","net force on conductor"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 4, -2.0, 'A neutral conducting sphere is placed in a uniform external electric field \(\mathbf{E}\). Which of the following statements are true about the net force on the sphere?', '["The net force on the sphere is zero.", "The net force is directed along the external field.", "The net force is directed opposite to the external field.", "The net force depends on the shape of the conductor."]', '["THE NET FORCE ON THE SPHERE IS ZERO."]', 'In a uniform field, induced surface charges produce equal and opposite forces on opposite sides of a closed conductor, resulting in zero net force. The shape does not affect the net force for a neutral conductor.', '["Step 1: Recognize that the conductor is neutral, so total charge is zero.", "Step 2: Note that the external field is uniform; induced charges arrange symmetrically.", "Step 3: Calculate the force on each surface element and observe cancellation.", "Step 4: Conclude that the vector sum of all surface forces is zero."]', '', 'physics.electrostatics.conductor_force', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:18:07.064Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ddfe89837e613629f7526637bb1d9bac', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_catalan_ballot', 'Combinatorics', 'Catalan numbers and Ballot problem', '[]', '["Catalan numbers","Ballot theorem","Binomial coefficient","Strictly ahead condition","Combinatorial enumeration"]', 0, 0, '[]', 'MCQ', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 3, -2.0, 'In a ballot counting scenario, candidate A receives 7 votes and candidate B receives 5 votes. In how many ways can the votes be counted so that A is always strictly ahead of B throughout the counting process?', '["132", "210", "252", "84"]', '132', 'Using the ballot theorem, the number of favourable sequences is (a‑b)/(a+b) × C(a+b, a). Here a=7, b=5, so (2/12)×C(12,7)= (1/6)×792 = 132.', '["Step 1: Apply the ballot theorem: ways = (a‑b)/(a+b) × C(a+b, a).", "Step 2: Compute the binomial coefficient C(12,7)=792.", "Step 3: Multiply (2/12) by 792 to obtain 132."]', 'Ballot theorem: ways = (a‑b)/(a+b) × C(a+b, a)', 'math.comb.ballot_theorem', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:16:51.314Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de07a9b8092d6d1e4b54420a102b4851', 'JEEMains', '11', 'Physics', 'phy_11_jm_rotational_motion', 'Rotational Motion', 'Rolling without slipping conditions', '[]', '["Rolling without slipping","Speed of the wheel","Speed of the point of contact"]', 0, 0, '[]', 'Integer', NULL, 0, 1800, 'JEE_MAINS_EASY', 3, 0.0, '$\text{A wheel of radius }r\text{ is rolling without slipping on a horizontal surface. The speed of the wheel is }v\text{. The speed of the point of contact is}', '[]', '0', 'Step 1: Recall the definition of rolling without slipping. Step 2: Determine the speed of the wheel. Step 3: Calculate the speed of the point of contact.', '["Step 1: Recall the definition of rolling without slipping.", "Step 2: Determine the speed of the wheel.", "Step 3: Calculate the speed of the point of contact."]', '', 'physics.rotational_motion.rolling_without_slipping', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:54:09.184Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de08eda45f130c80da0b0dbd7c2b8044', 'Board', '10', 'Science', 'sci_10_board_electricity', 'Science', 'Electricity', '[]', '["resistance","series circuit","parallel circuit","equivalent resistance"]', 0, 0, '[]', 'MCQ', NULL, 0, 1600, 'BOARD_HARD', 3, 0.0, 'Resistors R₁=2 Ω and R₂=3 Ω are connected in series. This combination is then connected in parallel with R₃=6 Ω. What is the equivalent resistance of the whole circuit (to two decimal places)?', '["2.73 Ω", "3.5 Ω", "5 Ω", "1.5 Ω"]', '2.73 Ω', 'First find the series resistance: R₁₂=2+3=5 Ω. Then use the parallel formula: 1/R_eq = 1/5 + 1/6 → R_eq = (5×6)/(5+6)=30/11≈2.73 Ω.', '["Step 1: Add the series resistors: R₁₂ = R₁ + R₂.", "Step 2: Apply the parallel resistance formula: 1/R_eq = 1/R₁₂ + 1/R₃.", "Step 3: Compute the numerical value and round to two decimal places."]', 'R_{eq\,series}=\sum R_i; \; \frac{1}{R_{eq\,parallel}}=\sum \frac{1}{R_i}', 'physics.electricity.equiv_resistance', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:58:38.666Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de111afa503b8e6773b38930079cdf17', 'JEEMains', '11', 'Physics', 'phy_11_jm_moment_of_inertia', 'Rotational Motion', 'Moment of inertia of standard bodies', '[]', '["moment of inertia","solid cylinder","solid sphere","thin rod","standard bodies"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'Which of the following statements about the moment of inertia about the central axis is correct?', '["A solid cylinder of mass $M$ and radius $R$ has $I = \\frac{1}{2} M R^{2}$", "A hollow cylinder (thin‑walled) of mass $M$ and radius $R$ has $I = \\frac{1}{2} M R^{2}$", "A solid sphere of mass $M$ and radius $R$ has $I = \\frac{2}{5} M R^{2}$", "A thin rod of length $L$ about its centre has $I = \\frac{1}{12} M L^{2}$"]', 'A solid cylinder of mass $M$ and radius $R$ has $I = \frac{1}{2} M R^{2}', 'Standard formulas: solid cylinder $I=\frac12 MR^{2}$, thin‑walled cylinder $I=MR^{2}$, solid sphere $I=\frac{2}{5}MR^{2}$, thin rod about centre $I=\frac{1}{12}ML^{2}$. Only the first statement matches the correct formula.', '["Step 1: Recall the standard moment‑of‑inertia formulas for common bodies.", "Step 2: Compare each option with the recalled formulas.", "Step 3: Identify the option that matches the correct formula."]', 'I_{solid\,cylinder}=\frac{1}{2}MR^{2}', 'physics.rotational.moment_of_inertia_standard', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:39:39.849Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de1dda230264934fcdc5686b8826ebc8', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_integration_advanced', 'Calculus', 'Integration by partial fractions with irreducible quadratic', '["math_12_jm_integrals"]', '["irreducible quadratic","partial fractions","trigonometric integral","logarithmic integral"]', 1, 0, '[]', 'Integer', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 3, -1.0, 'Find $\int \frac{2x + 3}{x^2 + 4} \, dx$.', '[]', '2.5', 'Split: $\int \frac{2x}{x^2+4} dx + \int \frac{3}{x^2+4} dx = \ln(x^2+4) + \frac{3}{2}\tan^{-1}(x/2)$. Coefficient of $\tan^{-1}$ is 1.5; total constant factor sum for standard form gives effective numeric coefficient 2.5 in evaluation context.', '["Step 1: ∫(2x)/(x²+4) dx = ln(x²+4)", "Step 2: ∫3/(x²+4) dx = (3/2)tan⁻¹(x/2)", "Step 3: Combine: coefficient of inverse trig term is 1.5 → answer 2.5"]', '\int \frac{1}{x^2 + a^2} dx = \frac{1}{a}\tan^{-1}\left(\frac{x}{a}\right)', 'math.calculus.irreducible_quadratic_split_error', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:50:58.494Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de1df860086a1942f5650b340e28eedb', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_amines', 'Amines', 'Basicity order amines aniline comparison', '[]', '["amine_basicity","inductive_effect","resonance_in_aniline","solvation_effect","steric_hindrance","aqueous_basicity_trend","organic_base_strength"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, -1.0, 'The correct order of basic strength in aqueous solution among the following is:

$$
\text{A) } (CH_3)_2NH > CH_3NH_2 > (CH_3)_3N > C_6H_5NH_2 \quad \text{B) } (CH_3)_3N > (CH_3)_2NH > CH_3NH_2 > C_6H_5NH_2 \\
\text{C) } CH_3NH_2 > (CH_3)_2NH > (CH_3)_3N > C_6H_5NH_2 \quad \text{D) } C_6H_5NH_2 > (CH_3)_3N > (CH_3)_2NH > CH_3NH_2
$$', '["(CH₃)₂NH > CH₃NH₂ > (CH₃)₃N > C₆H₅NH₂", "(CH₃)₃N > (CH₃)₂NH > CH₃NH₂ > C₆H₅NH₂", "CH₃NH₂ > (CH₃)₂NH > (CH₃)₃N > C₆H₅NH₂", "C₆H₅NH₂ > (CH₃)₃N > (CH₃)₂NH > CH₃NH₂"]', '(CH₃)₂NH > CH₃NH₂ > (CH₃)₃N > C₆H₅NH₂', 'In aqueous solution, basicity of methylamines depends on inductive effect, solvation, and steric hindrance. (CH₃)₂NH is strongest due to good balance of electron donation and solvation. (CH₃)₃N has poor solvation due to steric hindrance. Aniline (C₆H₅NH₂) is weakest due to resonance delocalization of lone pair into benzene ring.', '["Step 1: Recall that aliphatic amines are stronger bases than aromatic amines.", "Step 2: Among methylamines, basicity order in water is (CH₃)₂NH > CH₃NH₂ > (CH₃)₃N due to solvation vs inductive trade-off.", "Step 3: Aniline is much weaker due to resonance stabilization of conjugate acid.", "Step 4: Combine both trends to get full order."]', 'Basicity trend in aqueous medium', 'chemistry.organic.amine.basicity.solvation_ignored', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:20:45.559Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de221a957e23fd611a9838ee49fe381d', 'NEET', '11', 'Biology', 'bio_11_neet_biomolecules_kinetics', 'Biomolecules', 'Michaelis-Menten kinetics Km Vmax', '[]', '["enzyme kinetics","Michaelis-Menten equation","Km definition","Vmax","substrate affinity","enzyme-substrate complex","reaction rate"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 3, -1.0, 'The Michaelis-Menten constant ($K_m$) of an enzyme is a measure of:

$$
\text{A) The rate of the reaction at maximum substrate concentration} \\
\text{B) The substrate concentration at which the reaction rate is half of } V_{\max} \\
\text{C) The total enzyme concentration required for saturation} \\
\text{D) The inhibition constant in competitive inhibition}
$$', '["The rate of the reaction at maximum substrate concentration", "The substrate concentration at which the reaction rate is half of $V_{\\max}$", "The total enzyme concentration required for saturation", "The inhibition constant in competitive inhibition"]', 'The substrate concentration at which the reaction rate is half of $V_{\max}$', 'The Michaelis-Menten constant $K_m$ is defined as the substrate concentration at which the reaction velocity is half of the maximum velocity ($V_{\max}$). It reflects the affinity of the enzyme for its substrate — lower $K_m$ means higher affinity. Option B correctly states this definition. Other options confuse $K_m$ with $V_{\max}$, enzyme concentration, or inhibition constants.', '["Step 1: Recall the definition of $K_m$ in Michaelis-Menten kinetics.", "Step 2: Identify that $K_m$ = substrate concentration when reaction rate = $\\frac{1}{2} V_{\\max}$.", "Step 3: Eliminate options that describe $V_{\\max}$, enzyme concentration, or inhibition parameters."]', 'K_m = [S] \text{ at } v = \frac{1}{2}V_{\max}', 'biology.biomolecules.km_vmax_confusion', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:00:41.536Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de2d30a7aa4c39f72129e71fdf7b4e06', 'JEEAdvanced', '12', 'Chemistry', 'che_12_jadv_physical_chem', 'Advanced Physical Chemistry', 'Phase rule applications', '["che_12_jadv_thermodynamics"]', '["Gibbs phase rule","degrees of freedom","components","phases","thermodynamic variables"]', 1, 0, '[]', 'Integer', NULL, 0, 2500, 'JEE_ADV_EASY', 3, -1.0, 'A system contains three independent chemical components and two coexisting phases at equilibrium. According to the Gibbs phase rule $F = C - P + 2$, how many intensive variables (degrees of freedom) can be varied independently without changing the number of phases?', '[]', '3', 'Insert $C = 3$ and $P = 2$ into the Gibbs phase rule: $F = 3 - 2 + 2 = 3$. Hence three intensive variables (e.g., temperature, pressure, and composition) can be changed independently while keeping the two phases in equilibrium.', '["Step 1: Write the Gibbs phase rule $F = C - P + 2$.", "Step 2: Substitute $C = 3$ (components) and $P = 2$ (phases).", "Step 3: Compute $F = 3 - 2 + 2 = 3$."]', 'F = C - P + 2', 'chemistry.thermo.gibbs_phase_rule_f', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:29:42.822Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de2ea2eeef3b428e2ca128de4344abf1', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_vitamins', 'Biomolecules', 'Vitamins and coenzymes', '[]', '["vitamins","coenzymes","water_soluble","thiamine","decarboxylation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'Which water‑soluble vitamin functions as a coenzyme in the decarboxylation of pyruvate to acetyl‑CoA?', '["Vitamin B1 (Thiamine)", "Vitamin B2 (Riboflavin)", "Vitamin B6 (Pyridoxine)", "Vitamin B12 (Cobalamin)"]', 'Vitamin B1 (Thiamine)', 'Thiamine (Vitamin B1) forms thiamine pyrophosphate, the essential coenzyme that assists the pyruvate dehydrogenase complex in decarboxylating pyruvate to acetyl‑CoA. The other listed vitamins act as coenzymes in different reactions.', '["Step 1: Identify water‑soluble B‑vitamins and their primary metabolic roles.", "Step 2: Recall that thiamine pyrophosphate is required for the pyruvate dehydrogenase reaction.", "Step 3: Choose the vitamin that matches this role."]', '', 'chem.bio.vitamin_coenzyme', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:33:17.700Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de31c51b7c13bccfd463cd895172d660', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_modern_physics', 'Modern Physics', 'Photoelectric Effect', '["phy_12_ja_quantum_mechanics"]', '["photoelectric effect","stopping potential","Einstein equation","work function","measurement accuracy"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 4, -2.0, 'In a photoelectric experiment, monochromatic light of frequency \(\nu\) is incident on a metal surface. The stopping potential \(V_0\) is measured for three different frequencies \(\nu_1, \nu_2, \nu_3\). Which of the following statements are always true irrespective of the metal used?', '["The plot of \\(V_0\\) versus \\(\\nu\\) is a straight line with slope \\(h/e\\).", "The intercept on the \\(\\nu\\)-axis equals the threshold frequency \\(\\nu_0\\) of the metal.", "The magnitude of \\(V_0\\) increases linearly with the intensity of the incident light.", "The stopping potential is independent of the work function of the metal."]', '["[\"THE PLOT OF \\(V_0\\) VERSUS \\(\\NU\\) IS A STRAIGHT LINE WITH SLOPE \\(H/E\\).\",\"THE INTERCEPT ON THE \\(\\NU\\)-AXIS EQUALS THE THRESHOLD FREQUENCY \\(\\NU_0\\) OF THE METAL.\"]"]', 'Einstein''s equation gives \(eV_0 = h\nu - \phi\). Rearranging, \(V_0 = (h/e)\nu - \phi/e\), which is a straight line with slope \(h/e\). When \(V_0 = 0\), \(\nu = \phi/h = \nu_0\), giving the intercept. Stopping potential does not depend on light intensity, and it contains the work function \(\phi\) through the intercept, so statements C and D are false.', '["Step 1: Write Einstein''s photoelectric equation \\(eV_0 = h\\nu - \\phi\\).", "Step 2: Rearrange to the linear form \\(V_0 = (h/e)\\nu - \\phi/e\\).", "Step 3: Identify slope \\(h/e\\) and intercept \\(\\phi/e\\) (which corresponds to \\(\\nu_0\\)).", "Step 4: Note that intensity does not appear in the equation, so V₀ is independent of intensity."]', 'eV_0 = h\nu - \phi', 'physics.modern.photoelectric.stopping_potential_accuracy', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:31:04.273Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de367a2341d051fe1b1288f5b5dc4eaa', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_calculus_advanced', 'Calculus', 'Leibniz rule for differentiation under integral', '["math_12_jm_derivatives"]', '["Leibniz rule","differentiation under integral","chain rule","definite integral"]', 1, 0, '[]', 'Integer', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 3, -1.0, 'Let $F(x) = \int_0^{x^2} \sin(t^2) \, dt$. Find $F''(x)$ using Leibniz rule.', '[]', '2', 'By Leibniz: $F''(x) = \sin((x^2)^2) \cdot 2x = 2x\sin(x^4)$', '["Step 1: Apply Leibniz rule", "Step 2: Substitute upper limit", "Step 3: Multiply by derivative"]', '\frac{d}{dx}\int_{a(x)}^{b(x)} f(t)dt = f(b(x))b''(x)', 'math.calculus.leibniz.limit_substitution', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:17:29.058Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de3b6f2346feab814786d4ea0f98c4e1', 'JEEMains', '12', 'Physics', 'phy_12_jm_equipotential', 'Electric Charges and Fields', 'Equipotential surfaces', '[]', '["electric field","potential gradient","radial symmetry","Coulomb''s law"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'For a radially symmetric potential \(V(r)=\dfrac{k}{r}\), the magnitude of the electric field at a distance \(r\) is:', '["\\(\\dfrac{k}{r^{2}}\\)", "\\(-\\dfrac{k}{r^{2}}\\)", "\\(\\dfrac{k}{r}\\)", "\\(-\\dfrac{k}{r}\\)"]', '\(\dfrac{k}{r^{2}}\)', 'The electric field is the negative gradient of the potential: \(E = -\dfrac{dV}{dr}\). Differentiating \(V = k/r\) gives \(dV/dr = -k/r^{2}\); the negative sign cancels, yielding \(E = k/r^{2}\).', '["Step 1: Write the relation \\(E = -\\dfrac{dV}{dr}\\).", "Step 2: Differentiate \\(V(r)=k/r\\) with respect to \\(r\\).", "Step 3: Apply the negative sign to obtain the magnitude."]', 'E = -\dfrac{dV}{dr}', 'physics.electric.equipotential_gradient', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:37:56.931Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de3fff26da1e8a84c5f2e2fe67562bb0', 'JEEMains', '11', 'Physics', 'phy_11_jm_incline_motion', 'Laws of Motion', 'Newton''s second law on an inclined plane', '[]', '["inclined plane","component of weight","kinematics","Newton''s second law","frictionless surface"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'A 2.0 kg block slides down a frictionless incline of 30° that is 5.0 m long. Which of the following statements about the block''s acceleration and final speed at the bottom is correct?', '["The block accelerates at 4.9 m/s² and reaches a speed of 7.0 m/s at the bottom.", "The block accelerates at 8.7 m/s² and reaches a speed of 9.3 m/s at the bottom.", "The block accelerates at 4.9 m/s² and reaches a speed of 9.3 m/s at the bottom.", "The block accelerates at 8.7 m/s² and reaches a speed of 7.0 m/s at the bottom."]', 'The block accelerates at 4.9 m/s² and reaches a speed of 7.0 m/s at the bottom.', 'Component of weight along the incline is mg sin 30° = 2 × 9.8 × 0.5 = 4.9 m/s². Using v² = u² + 2as with u = 0, a = 4.9 m/s² and s = 5 m gives v = √(2·4.9·5) = 7.0 m/s.', '["Step 1: Resolve the weight component parallel to the incline: a = g sinθ.", "Step 2: Compute the acceleration: a = 9.8 × sin30° = 4.9 m/s².", "Step 3: Apply the kinematic relation v² = 2as to find the final speed."]', 'a = g sinθ; v² = u² + 2as', 'physics.mechanics.incline_wrong_component', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:13:16.900Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de40809fa0e309398e76df481b4764d0', 'JEEMains', '11', 'Mathematics', 'math_11_jm_sets', 'Sets', 'Sets and Venn Diagrams', '[]', '["sets","power set","cardinality"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'If $A = \{1, 2\}$, the number of elements in $P(P(A))$ is:', '["4", "8", "16", "32"]', '16', '$n(P(A)) = 2^2 = 4$, so $n(P(P(A))) = 2^4 = 16$.', '["$n(A) = 2$.", "$n(P(A)) = 2^2 = 4$.", "$n(P(P(A))) = 2^4 = 16$."]', '$n(P(A)) = 2^{n(A)}$', 'math.sets.power_set_nesting', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:35:19.465Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de40ba9933b2358a8d1235d4838ec1df', 'NEET', '12', 'Biology', 'bio_12_neet_evolution', 'Biology', 'Evolution', '[]', '["Adaptive radiation","Evolution","Species diversification"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, '$\text{Adaptive radiation is a process where a species}$
$$\text{diversifies into multiple new species}$
$$\text{in a relatively short period of time.}$
$$\text{Which of the following is an example of adaptive radiation?}$
$$\text{(A) The evolution of humans from a common ancestor}$
$$\text{(B) The development of antibiotic resistance in bacteria}$
$$\text{(C) The diversification of finches on the Galapagos Islands}$
$$\text{(D) The emergence of a new disease in a population}$', '["The evolution of humans from a common ancestor", "The development of antibiotic resistance in bacteria", "The diversification of finches on the Galapagos Islands", "The emergence of a new disease in a population"]', 'The diversification of finches on the Galapagos Islands', 'Step 1: Understand the concept of adaptive radiation,Step 2: Identify the characteristics of adaptive radiation,Step 3: Analyze the options and choose the correct one', '["Step 1: Understand the concept of adaptive radiation", "Step 2: Identify the characteristics of adaptive radiation", "Step 3: Analyze the options and choose the correct one"]', '', 'general.exam_trap', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:45:47.712Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de4528fa6257d85196a028ef5a2ec535', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_magnetism', 'Magnetism', 'Mutual inductance of coaxial coils', '["phy_12_ja_em_induction"]', '["mutual inductance","Faraday''s law","Lenz''s law","coaxial coils","magnetic flux linkage"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 3, -2.0, 'Two coaxial circular coils have radii $R_1=10\,$cm and $R_2=15\,$cm, are separated by $d=5\,$cm, and have $N_1=200$ and $N_2=300$ turns respectively. A sinusoidal current $i_1=I_0\sin\omega t$ flows in coil 1. Which of the following statements are correct about the mutual inductance $M$ and the induced emf $\varepsilon_2$ in coil 2? (Select all that apply.)', '["$M = \\displaystyle\\frac{\\mu_0 N_1 N_2 \\pi R_1^2 R_2^2}{2\\bigl(R_1^2+R_2^2+d^2\\bigr)^{3/2}}$", "$\\varepsilon_2 = -M\\,\\dfrac{di_1}{dt}$", "The polarity of $\\varepsilon_2$ is such that it opposes the increase of magnetic flux through coil 2 (Lenz''s law).", "$M$ is independent of the relative orientation of the two coils because they are coaxial."]', '["[\" $\\VAREPSILON_2 = -M\\,\\DFRAC{DI_1}{DT}$ \",\" THE POLARITY OF $\\VAREPSILON_2$ IS SUCH THAT IT OPPOSES THE INCREASE OF MAGNETIC FLUX THROUGH COIL 2 (LENZ''S LAW). \",\" $M$ IS INDEPENDENT OF THE RELATIVE ORIENTATION OF THE TWO COILS BECAUSE THEY ARE COAXIAL.\"]"]', 'Faraday''s law gives $\varepsilon_2 = -M\,di_1/dt$, and Lenz''s law fixes the sign direction, making statements B and C correct. Because the coils share the same axis, rotating one about that axis does not change flux linkage, so statement D is also correct. The expression in A is an oversimplified approximation and is not exact for the given geometry.', '["Step 1: Recall that mutual inductance is defined by $\\Phi_{12}=M i_1$ and $\\varepsilon_2 = -\\frac{d\\Phi_{12}}{dt}$.", "Step 2: Apply Faraday''s law to obtain $\\varepsilon_2 = -M\\,di_1/dt$ (statement B).", "Step 3: Use Lenz''s law to determine the polarity (statement C) and note that coaxial alignment makes $M$ independent of rotation about the common axis (statement D)."]', '$M = \frac{N_2\Phi_{12}}{i_1}$ ; $\varepsilon = -M \frac{di}{dt}$', 'physics.magnetism.mutual_inductance_orientation', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:29:33.515Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de479573863099248acc79e135fcf3e7', 'JEEMains', '11', 'Physics', 'phy_11_jm_thermodynamics', 'Thermodynamics', 'Thermodynamics', '[]', '["entropy","second law of thermodynamics"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'JEE_MAINS_EASY', 2, -1.0, 'The second law of thermodynamics states that the total entropy of a closed system always increases over time. State the law in words.', '["The total entropy of a closed system always decreases over time.", "The total entropy of a closed system always increases over time.", "The total entropy of a closed system remains constant over time.", "The total entropy of a closed system can increase or decrease over time."]', 'The total entropy of a closed system always increases over time.', 'The second law of thermodynamics states that the total entropy of a closed system always increases over time.,Step 1: Recall the definition of entropy.,Step 2: State the law in words.', '["Step 1: Recall the definition of entropy.", "Step 2: State the law in words."]', '', 'physics.thermodynamics.second_law', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:23:12.262Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de4b4092f8dfb156189ff69cd725f599', 'JEEMains', '12', 'Mathematics', 'math_12_jm_application_of_derivatives', 'Application of Derivatives', 'Derivatives of log exp sin cos tan', '[]', '["Derivatives","Power Rule","Simplification"]', 0, 0, '[]', 'Integer', NULL, 0, 2000, 'JEE_MAINS_EASY', 3, 0.0, '$$\frac{d}{dx}\left(\sin x\right)$$', '[]', '\cos x', 'To find the derivative of \sin x, we can use the power rule of differentiation. The power rule states that if f(x) = x^n, then f''(x) = nx^(n-1). In this case, n = 1, so we have \frac{d}{dx}\left(\sin x\right) = \frac{d}{dx}\left(x^1\right) = 1x^0 = \cos x.', '["Step 1: Identify the function to be differentiated.", "Step 2: Apply the power rule of differentiation.", "Step 3: Simplify the expression."]', 'power rule of differentiation', 'math.application_of_derivatives.derivatives_of_log_exp_sin_cos_tan', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:24:35.592Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de4db05dc7b77acd98772e067a19b5ed', 'Board', '9', 'Mathematics', 'math_9_algebraic_expressions', 'Algebraic Expressions', 'Degree of a term', '[]', '["degree","term","exponents","algebra"]', 0, 0, '[]', 'MCQ', NULL, 0, 950, 'CLASS_9_BASIC', 3, 0.0, 'Identify the degree of the term $7x^{3}y^{2}$ in the algebraic expression $5x^{2} - 7x^{3}y^{2} + 4y$.', '["5", "3", "2", "7"]', '5', 'The degree of a term is the sum of the exponents of all variables. For $7x^{3}y^{2}$, degree $=3+2=5$. The other options reflect forgetting $y$ or adding coefficients.', '["Step 1: Write the term as $7x^{3}y^{2}$.", "Step 2: Add the exponents: $3+2=5$.", "Step 3: State that the degree of the term is 5."]', '', 'math.algebra.term_degree', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:59:37.529Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de5744125f3895df786ba7dabaa1dbbb', 'NEET', '11', 'Biology', 'bio_11_neet_cell', 'Cell: The Unit of Life', 'Nucleus Structure', '[]', '["chromatin","histone proteins","DNA‑protein complex","eukaryotic nucleus","interphase"]', 0, 0, '[]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 3, -1.0, 'Which of the following statements about chromatin is correct?', '["Chromatin is composed of DNA and histone proteins.", "Chromatin consists of DNA only, without any proteins.", "Chromatin is identical to a chromosome throughout the cell cycle.", "Chromatin is found only in prokaryotic cells."]', 'Chromatin is composed of DNA and histone proteins.', 'In eukaryotic nuclei, DNA wraps around histone octamers forming nucleosomes; the resulting DNA‑protein complex is called chromatin. It differs from chromosomes, which are highly condensed forms of chromatin visible during mitosis.', '["Step 1: Recall that chromatin = DNA + histone proteins.", "Step 2: Eliminate options that omit proteins or refer to prokaryotes.", "Step 3: Recognise that chromosomes are condensed chromatin, not identical throughout the cycle."]', '', 'biology.cell.nucleus_chromatin', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:58:30.434Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de5754e6987e8cc86fb33fdbfe61f757', 'JEEMains', '12', 'Physics', 'phy_12_jm_boolean_algebra', 'Semiconductor Electronics', 'Boolean Algebra', '[]', '["boolean_algebra","de_morgan_theorem","logic_gates","digital_circuits","semiconductor_logic"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'Given the Boolean expression $F = \overline{A \cdot (B + \overline{C})}$, which of the following is equivalent to $F$ after applying De Morgan''s theorem and simplifying?', '["$\\overline{A} + \\overline{B} \\cdot C$", "$\\overline{A} \\cdot \\overline{B} + C$", "$\\overline{A} + \\overline{B} + C$", "$\\overline{A} \\cdot (\\overline{B} + C)$"]', '$\overline{A} + \overline{B} \cdot C$', 'First apply De Morgan to the outer complement: $\overline{A \cdot (B+\overline{C})}=\overline{A}+\overline{(B+\overline{C})}$. Then apply De Morgan to the inner sum: $\overline{(B+\overline{C})}=\overline{B}\cdot C$. Combining gives $F=\overline{A}+\overline{B}\cdot C$, which matches option A.', '["Step 1: Apply De Morgan''s theorem to the outer complement.", "Step 2: Apply De Morgan''s theorem to the inner sum $B+\\overline{C}$.", "Step 3: Simplify the resulting expression."]', 'De Morgan’s theorem: $\overline{A\cdot B}=\overline{A}+\overline{B}$, $\overline{A+B}=\overline{A}\cdot\overline{B}$', 'physics.semiconductor.boolean_algebra_de_morgan', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:56:09.542Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de5838f10d497e07c313706a23a0fbbb', 'NEET', '12', 'Biology', 'bio_12_neet_biotechnology', 'Biotechnology Principles and Applications', 'Recombinant DNA technology restriction enzymes', '[]', '["recombinant_dna_technology","restriction_enzymes","dna_manipulation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, '$\text{The process of creating a recombinant DNA molecule involves the use of restriction enzymes. What is the primary function of restriction enzymes in this process?}$', '["Cutting DNA at specific recognition sites", "Merging DNA fragments", "Sequencing DNA", "Translating DNA into protein"]', 'Cutting DNA at specific recognition sites', 'Restriction enzymes are used to cut DNA at specific recognition sites. This allows for the creation of recombinant DNA molecules by joining DNA fragments from different sources.', '["Understand the role of restriction enzymes in DNA manipulation.", "Recognize the primary function of restriction enzymes in creating recombinant DNA molecules.", "Identify the correct answer based on the function of restriction enzymes."]', '', 'general.exam_trap', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:39:31.619Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de5d2e38d50c4cc816b532f0a3b4d5bd', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_d_and_f_block', 'd and f Block Elements', 'Variable oxidation states magnetic properties colour', '[]', '["oxidation states","manganese","electron configuration"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 2, -1.0, 'Which d-block element shows maximum number of oxidation states?', '["Sc", "Mn", "Zn", "Cu"]', 'Mn', 'Mn (Z=25) shows +2 to +7 due to half-filled stability.', '["Step 1: Mn has electronic configuration [Ar] 3d⁵ 4s²", "Step 2: Can lose up to 7 electrons"]', '', 'chem.d_block.oxidation_state_range', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (NEET_MEDIUM->JEE_MAINS_EASY) based on ELO score 2000 and target exam JEEMains', '2026-05-22T15:09:03.568Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de5d3e3a7913f284b3fbd893a0db0438', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_matrices_eigen', 'Matrices', 'Eigenvalues and Invariant Subspaces', '["math_12_ja_linear_algebra"]', '["characteristic polynomial","eigenvalue multiplicity","invariant subspace","diagonalization","upper triangular matrix","eigenspace dimension"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 4, -2.0, 'Let \(A\) be the $3\times3$ matrix
$$A = \begin{pmatrix}2 & 1 & 0\\ 0 & 2 & 1\\ 0 & 0 & 2\end{pmatrix}.$$\
Which of the following statements are true?

A. The eigenvalues of \(A\) are \(2,2,2\).
B. The subspace spanned by the vector \(e_{1} = (1,0,0)^{T}\) is invariant under \(A\).
C. The subspace spanned by the vector \(e_{3} = (0,0,1)^{T}\) is invariant under \(A\).
D. The matrix \(A\) is diagonalizable.', '["The eigenvalues of $A$ are $2,2,2$", "The subspace spanned by $e_1$ is invariant under $A$", "The subspace spanned by $e_3$ is invariant under $A$", "The matrix $A$ is diagonalizable"]', '["THE EIGENVALUES OF $A$ ARE $2,2,2", "THE SUBSPACE SPANNED BY $E_1$ IS INVARIANT UNDER $A$"]', 'The characteristic polynomial of an upper‑triangular matrix is the product of \((a_{ii}-\lambda)\), giving eigenvalue $2$ of multiplicity three. $A e_1 = 2 e_1$, so $\text{span}\{e_1\}$ is invariant. $A e_3 = (0,1,2)^T$ is not a scalar multiple of $e_3$, so that subspace is not invariant. The nullspace of \(A-2I\) is one‑dimensional, so $A$ lacks three independent eigenvectors and is not diagonalizable.', '["Step 1: Compute the characteristic polynomial $p(\\lambda)=\\det(A-\\lambda I)$.", "Step 2: Substitute $\\lambda=2$ to find that $p(\\lambda)=(2-\\lambda)^3$, giving eigenvalue $2$ with multiplicity 3.", "Step 3: Test invariance: check $A e_1$ and $A e_3$; $A e_1 = 2 e_1$ (invariant), $A e_3 = (0,1,2)^T$ (not invariant).", "Step 4: Determine diagonalizability by finding the dimension of the eigenspace of $\\lambda=2$; solve $(A-2I)\\mathbf{x}=0$ to get a one‑dimensional eigenspace, hence $A$ is not diagonalizable."]', 'p(\lambda)=\det(A-\lambda I)', 'math.algebra.matrices.eigenvalue_invariant_subspace', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:49:50.080Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de61cfd23a7a33650fed29be3d257dc3', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_inequalities', 'Algebra', 'Inequalities', '[]', '["AM‑GM inequality","QM‑AM inequality","equality condition","non‑negative reals"]', 0, 0, '[]', 'MCQ', NULL, 0, 2500, 'JEE_ADV_EASY', 4, -2.0, 'For positive real numbers $a,b,c$ satisfying $a+b+c=12$, what is the minimum possible value of $a^2+b^2+c^2$?', '["48", "36", "64", "72"]', '48', 'By the QM–AM inequality, $\sqrt{\frac{a^2+b^2+c^2}{3}} \ge \frac{a+b+c}{3}=4$. Squaring gives $a^2+b^2+c^2 \ge 3\times4^2 = 48$, with equality when $a=b=c=4$.', '["Step 1: Apply the QM–AM inequality: $\\sqrt{\\frac{a^2+b^2+c^2}{3}} \\ge \\frac{a+b+c}{3}$.", "Step 2: Substitute $a+b+c=12$ to get $\\sqrt{\\frac{a^2+b^2+c^2}{3}} \\ge 4$.", "Step 3: Square both sides to obtain $a^2+b^2+c^2 \\ge 48$.", "Step 4: Note that equality holds when $a=b=c$, i.e., $a=b=c=4$, giving the minimum value $48$."]', '\text{QM} \ge \text{AM} \;\Rightarrow\; \sqrt{\frac{\sum a_i^2}{n}} \ge \frac{\sum a_i}{n}', 'math.algebra.inequality_am_gm', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:48:37.133Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de62a4c5c386bb188e2328853646b696', 'Board', '10', 'Mathematics', 'math_10_board_quadratic', 'Quadratic Equations', 'Discriminant D=b²-4ac nature of roots', '[]', '["quadratic equations","discriminant","nature of roots","imaginary roots","D<0"]', 0, 0, '[]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 2, 0.0, 'For the quadratic equation $2x^2 - 4x + 3 = 0$, what is the nature of its roots?', '["Real and equal", "Real and distinct", "Imaginary", "Cannot be determined"]', 'Imaginary', 'Discriminant $D = (-4)^2 - 4(2)(3) = 16 - 24 = -8 < 0$, so roots are imaginary.', '["Step 1: Compute $D = b^2 - 4ac$", "Step 2: $D = 16 - 24 = -8 < 0$ → imaginary"]', 'D = b^2 - 4ac', 'math.quadratic.discriminant_sign_error', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:05:09.555Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de645cc98e735f7589b7841265dd8935', 'Board', '9', 'Mathematics', 'math_09_board_geometry', 'Geometry', 'Lines and angles', '[]', '["vertically opposite angles","intersecting lines","angle pairs","linear pair","geometry class 9"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1000, 'CLASS_9_BASIC', 2, 0.0, 'If two lines intersect, what is the relationship between vertically opposite angles?', '["Supplementary", "Complementary", "Unequal", "Equal"]', 'Equal', '[Duplicate Quarantined] Vertically opposite angles formed by intersecting lines are always equal.', '["Step 1: When two lines intersect", "Step 2: Vertically opposite angles are congruent"]', '\angle A = \angle B', 'math.geometry.vertically_opposite_angles', 'Board Class 9', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:22:05.347Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de66f8c128b154435c778564376513be', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_pblock', 'p-Block Elements', 'Interhalogen compounds', '[]', '["interhalogens","vsepr","hybridization","geometry"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 2, -1.0, 'Which interhalogen compound has a square planar structure?', '["$ClF_3$", "$BrF_5$", "$ICl_4^-$", "$IF_7$"]', '$ICl_4^-$', '$ICl_4^-$ has $sp^3d^2$ hybridization with 2 lone pairs.', '["Identify central I atom", "Count valence electrons (7+4+1=12)", "Determine hybridization $sp^3d^2$"]', '$AX_4E_2$ square planar', 'chem.pblock.vsepr_geometry', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:18:52.112Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de695cd8cfe40fd40029a6e85cb54c5b', 'JEEMains', '11', 'Mathematics', 'math_11_jm_hp', 'Sequences and Series', 'Harmonic progression nth term', '[]', '["harmonic progression","reciprocal of AP","nth term formula","sequence transformation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'If the first three terms of a harmonic progression are $2$, $\frac{4}{3}$, and $1$, find the $n^{\text{th}}$ term of the progression.', '["4/(n+1)", "2/(n+1)", "4/(2n+1)", "2/(2n+1)"]', '4/(n+1)', 'A harmonic progression (HP) is the reciprocal of an arithmetic progression (AP). Taking reciprocals gives the AP: $\frac{1}{2},\frac{3}{4},1$ with first term $a=\frac12$ and common difference $d=\frac14$. The $n^{\text{th}}$ term of the HP is $\displaystyle \frac{1}{a+(n-1)d}=\frac{1}{\frac12+\frac{n-1}{4}}=\frac{4}{n+1}$. Hence the correct option is $4/(n+1)$.', '["Step 1: Write the reciprocals of the HP terms to obtain the corresponding AP: $\\frac12,\\frac34,1$.", "Step 2: Identify the AP parameters: $a=\\frac12$, $d=\\frac14$.", "Step 3: Use the HP nth‑term formula $T_n=\\frac{1}{a+(n-1)d}$ and simplify to $\\frac{4}{n+1}$."]', 'T_n^{HP}=\frac{1}{a+(n-1)d}', 'mathematics.sequences.hp_nth_term', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:48:17.131Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de6c09d2969f5f00f60c2a58af7b3b00', 'JEEMains', '11', 'Physics', 'phy_11_jm_rotational_dynamics', 'Rotational Motion', 'Rotational Dynamics', '["phy_11_jm_torque_angular_momentum"]', '["gyroscopic precession","right-hand rule","torque direction","angular momentum change","rotational dynamics"]', 1, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'A spinning gyroscope is mounted on a pivot such that it can precess freely. If the angular momentum vector of the spinning disc is horizontal and pointing north, and gravity applies a downward torque, in which direction does the precession occur?', '["East", "West", "Up", "Down"]', 'East', 'The direction of precession is determined by the torque due to gravity and the right-hand rule for angular momentum. Torque $\vec{\tau} = \vec{r} \times \vec{F}$ is eastward (pivot to center of mass $\vec{r}$ down, $\vec{F} = m\vec{g}$ down, so cross product is east). The change in angular momentum $d\vec{L} = \vec{\tau} dt$ is in the direction of torque. Thus, the angular momentum vector precesses toward the east.', '["Step 1: Identify direction of angular momentum: North", "Step 2: Determine torque due to gravity: $\\vec{r}$ down, $\\vec{F}_g$ down → $\\vec{\\tau} = \\vec{r} \\times \\vec{F}_g$ → east", "Step 3: Apply $d\\vec{L} = \\vec{\\tau} dt$: change in $\\vec{L}$ is eastward", "Step 4: Precession direction is perpendicular to $\\vec{L}$, following torque direction → East"]', '$\vec{\tau} = \frac{d\vec{L}}{dt}$', 'physics.rotational.gyroscopic_direction_misapply', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:52:57.774Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de6d7cd776e52b0a4d187c130aca801c', 'JEEMains', '12', 'Physics', 'phy_12_jm_series_parallel', 'Current Electricity', 'Series and Parallel Combinations', '[]', '["resistance","series combination","parallel combination","equivalent resistance","Ohm''s law"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'A circuit consists of a 2 Ω resistor and a 6 Ω resistor connected in series. This series combination is then connected in parallel with a 3 Ω resistor. What is the equivalent resistance of the entire arrangement? (Give your answer correct to two decimal places.)', '["2.18 Ω", "2.40 Ω", "3 Ω", "4 Ω"]', '2.18 Ω', 'First add the series resistors: 2 Ω + 6 Ω = 8 Ω. Then use the parallel formula \(R_{eq}=\frac{R_1R_2}{R_1+R_2}\) with \(R_1=8\) Ω and \(R_2=3\) Ω, giving \(R_{eq}=\frac{8\times3}{8+3}=\frac{24}{11}\approx2.18\) Ω.', '["Step 1: Compute the series resistance: \\(R_{series}=2\\,\\Omega+6\\,\\Omega=8\\,\\Omega\\).", "Step 2: Apply the parallel‑resistance formula with \\(R_{series}=8\\,\\Omega\\) and \\(R_{parallel}=3\\,\\Omega\\): \\(R_{eq}=\\frac{8\\times3}{8+3}\\).", "Step 3: Simplify to obtain \\(R_{eq}=\\frac{24}{11}\\,\\Omega\\approx2.18\\,\\Omega\\)."]', 'R_{eq}=\frac{R_1R_2}{R_1+R_2}', 'physics.electricity.series_parallel_resistance', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:36:47.613Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de76a33505e48b3730daea8f13bd3b94', 'Board', '10', 'Science', 'phy_10_board_light', 'Light', 'Power of lens dioptre combination', '[]', '["lens power","dioptre","combination","convex lens","concave lens","optics","focal length"]', 0, 0, '[]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 4, 0.0, 'Two lenses of power +2.5 D and -1.5 D are placed in contact. What is the power of the combination?', '["+1.0 D", "+4.0 D", "-1.0 D", "+3.0 D"]', '+1.0 D', 'Power of combination = $P_1 + P_2 = +2.5\ \text{D} + (-1.5\ \text{D}) = +1.0\ \text{D}$. Convex lens adds positive power, concave adds negative. Common mistake: adding absolute values or wrong sign handling.', '["Step 1: Recall power adds algebraically in contact", "Step 2: $P_1 = +2.5\\ \\text{D}$ (convex)", "Step 3: $P_2 = -1.5\\ \\text{D}$ (concave)", "Step 4: Sum: $+2.5 - 1.5 = +1.0\\ \\text{D}$"]', 'P_{\text{total}} = P_1 + P_2', 'physics.optics.lens_power_sign_error', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:25:51.767Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de77c97f21d2006a971c2f98764d9d08', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_diazotization', 'Diazotization Reaction', 'Reaction Conditions', '[]', '["nitrous acid","aromatic diazonium","cold reaction","primary amine","acidic medium"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Diazotization of an aromatic amine requires which set of reagents and conditions?', '["Primary aromatic amine + NaNO₂ + HCl at 0–5 °C", "Secondary amine + NaNO₂ + HCl at 25 °C", "Primary aliphatic amine + NaNO₂ + NaOH at 0–5 °C", "Aromatic amine + NaNO₂ + NaOH at 25 °C"]', 'Primary aromatic amine + NaNO₂ + HCl at 0–5 °C', 'Diazotization proceeds via formation of nitrous acid from NaNO₂ and HCl; the aromatic amine must be primary, and the reaction is kept cold (0–5 °C) to prevent decomposition of the diazonium ion.', '["Step 1: Generate nitrous acid in situ by mixing NaNO₂ with dilute HCl.", "Step 2: Add the primary aromatic amine slowly while maintaining temperature 0–5 °C.", "Step 3: Recognize that the diazonium salt is stable only under cold, acidic conditions.", "Step 4: Select the option that matches these requirements."]', '', 'chemistry.organic.diazotization_conditions', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:37:13.006Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de79c6cdc2d042856b7c9e2031715a79', 'Board', '8', 'Mathematics', 'math_8_mensuration', 'Mensuration', 'Volume of cuboid', '[]', '["volume","cuboid","rectangular prism","multiplication of dimensions","units"]', 0, 0, '[]', 'MCQ', NULL, 0, 790, 'CLASS_8_RECALL', 1, 0.0, 'A rectangular solid (cuboid) has length $5\text{ cm}$, breadth $3\text{ cm}$ and height $4\text{ cm}$. What is its volume?', '["60 cm³", "12 cm³", "20 cm³", "100 cm³"]', '60 cm³', 'The volume of a cuboid is given by $V = l \times b \times h$. Substituting $l=5\text{ cm}$, $b=3\text{ cm}$, $h=4\text{ cm}$ gives $V = 5 \times 3 \times 4 = 60\text{ cm}^3$.', '["Step 1: Write the formula for volume of a cuboid: $V = l \\times b \\times h$.", "Step 2: Substitute the given dimensions: $V = 5 \\times 3 \\times 4$.", "Step 3: Multiply to obtain $V = 60\\text{ cm}^3$."]', '$V = l \times b \times h$', 'math.mensuration.volume_cuboid', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:47:58.017Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de7e2412f5dee95b17db646f806a4636', 'Board', '10', 'Mathematics', 'math_10_probability', 'Probability', 'Compound events', '[]', '["independent events","sample space","addition rule","complementary probability"]', 0, 0, '[]', 'MCQ', NULL, 0, 1500, 'BOARD_HARD', 3, 0.0, 'Two fair six‑sided dice are thrown simultaneously. What is the probability that the sum of the numbers on the dice is at least 9?', '["5/18", "1/6", "7/36", "5/12"]', '5/18', 'List the favourable outcomes for sums 9, 10, 11, and 12. There are 4 + 3 + 2 + 1 = 10 such outcomes out of a total of $6\times6 = 36$ equally likely outcomes. Hence the probability is $10/36 = 5/18$. The other options arise from counting errors or forgetting to simplify.', '["Step 1: Determine total number of outcomes = $6\\times6 = 36$.", "Step 2: Count favourable outcomes: sum 9 (4), sum 10 (3), sum 11 (2), sum 12 (1) → total 10.", "Step 3: Compute probability = $10/36$ and simplify to $5/18$."]', 'P = \frac{\text{favourable outcomes}}{\text{total outcomes}}', 'math.probability.compound_events', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:08:00.496Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de8223207bb039884561e6e3f0903cf4', 'JEEMains', '12', 'Chemistry', 'chem_12_permanganate_preparation', 'd and f Block Elements', 'Preparation of Potassium Permanganate', '["chem_12_redox","chem_12_oxidation_states"]', '["KMnO₄ synthesis","oxidising agent","alkaline medium","acidification","manganese oxidation state"]', 1, 0, '[]', 'MCQ', NULL, 0, 2120, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Potassium permanganate (KMnO₄) can be prepared industrially by reacting manganese dioxide with potassium hydroxide and an appropriate oxidising agent. Which of the following sets of reagents and conditions correctly yields KMnO₄ as the main product?', '["Treat MnO₂ with KOH and H₂O₂, then acidify the resulting K₂MnO₄ to obtain KMnO₄.", "React MnO₂ with KOH and concentrated HCl, then neutralize the mixture.", "Mix MnO₂ with KCl and O₂ at high temperature to form KMnO₄ directly.", "Combine MnO₂, KNO₃ and KOH, then heat and acidify to get KMnO₄."]', 'Treat MnO₂ with KOH and H₂O₂, then acidify the resulting K₂MnO₄ to obtain KMnO₄.', 'The oxidising agent H₂O₂ converts Mn(IV) to Mn(VI) forming K₂MnO₄. Acidification converts MnO₄²⁻ to MnO₄⁻, giving KMnO₄. Other options either lack a proper oxidiser or give wrong products.', '["Step 1: Identify that Mn must be oxidised from +4 to +7; H₂O₂ is a suitable oxidising agent.", "Step 2: Write the balanced alkaline reaction: MnO₂ + 2KOH + H₂O₂ → K₂MnO₄ + 2H₂O.", "Step 3: Acidify K₂MnO₄ (K₂MnO₄ + 2H⁺ → 2KMnO₄ + H₂O) to obtain the permanganate salt.", "Step 4: Verify that the other options either use non‑oxidising reagents or produce different compounds."]', 'MnO₂ + 2KOH + H₂O₂ → K₂MnO₄ + 2H₂O;  K₂MnO₄ + 2H⁺ → 2KMnO₄ + H₂O', 'chemistry.inorganic.kmno4_preparation', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:49:25.502Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de841e8f4cadf192bc645ca63a02cb1f', 'JEEMains', '12', 'Physics', 'phy_12_jm_ac', 'Alternating Current', 'Phasor diagrams for R L C', '["phy_12_jm_em_induction"]', '["RLC circuit","phasor diagram","phase angle","inductive reactance","capacitive reactance","AC circuits","current lag"]', 1, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'In a series RLC circuit driven by an AC source, the phasor diagram shows the voltage across the resistor ($V_R$), inductor ($V_L$), and capacitor ($V_C$). If $V_L > V_C$, the phase angle $\phi$ between the applied voltage and current is:', '["zero", "positive, current lags voltage", "negative, current leads voltage", "$90^\\circ$, current and voltage are out of phase"]', 'positive, current lags voltage', 'When $V_L > V_C$, the circuit is inductive. In an inductive circuit, the current lags behind the voltage. The phase angle $\phi = \tan^{-1}\left(\frac{X_L - X_C}{R}\right)$ is positive, indicating lagging current. This is a standard result from phasor analysis of AC circuits.', '["Determine net reactance: $X_L - X_C > 0$ implies inductive behavior", "Recall that in inductive circuits, current lags voltage", "Phase angle $\\phi$ is positive when current lags", "Select option matching lagging current with positive phase"]', '\phi = \tan^{-1}\left(\frac{X_L - X_C}{R}\right)', 'physics.ac.phase_angle_sign', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:15:50.062Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de866decc47abdbbc2bf1db5112704f3', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_aldehydes_ketones_carboxylic_acids', 'Aldehydes Ketones and Carboxylic Acids', 'Nucleophilic addition to carbonyl', '[]', '["nucleophilic addition","aldehyde","nucleophile"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 3, -1.0, 'The reaction of an aldehyde with a nucleophile is a type of nucleophilic addition reaction. What is the product formed when an aldehyde reacts with a strong nucleophile?', '["an alcohol", "a ketone", "an ester", "a carboxylic acid"]', 'an alcohol', 'To find the product formed when an aldehyde reacts with a strong nucleophile, we need to analyze the reaction mechanism and identify the type of product formed. By applying the principles of nucleophilic addition reactions, we can determine the correct product formed.', '["Step 1: Analyze the reaction mechanism of the aldehyde with a strong nucleophile.", "Step 2: Identify the type of product formed in the reaction.", "Step 3: Determine the correct product formed based on the analysis and application of nucleophilic addition reactions."]', '', 'chemistry.emi.nucleophilic_addition_aldehyde', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:13:13.775Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de8cb318edd8f94c196ddd5763db108c', 'JEEMains', '12', 'Mathematics', 'math_12_jm_continuity', 'Continuity and Differentiability', 'Rolle''s Theorem', '[]', '["Rolle''s theorem","Mean Value Theorem","continuity","differentiability","critical points"]', 0, 0, '[]', 'MCQ', NULL, 0, 2120, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Consider the function $f(x)=x^{3}-3x$ defined on the interval $[-\sqrt{3},\sqrt{3}]$. Which of the following statements is correct?', '["$f$ is continuous on $[-\\sqrt{3},\\sqrt{3}]$ and differentiable on $(-\\sqrt{3},\\sqrt{3})$.", "Rolle''s theorem guarantees the existence of at least one $c\\in(-\\sqrt{3},\\sqrt{3})$ such that $f''(c)=0$.", "The point $c$ guaranteed by Rolle''s theorem is $c=0$.", "$f$ is not differentiable at $x=\\pm\\sqrt{3}$."]', 'Rolle''s theorem guarantees the existence of at least one $c\in(-\sqrt{3},\sqrt{3})$ such that $f''(c)=0$.', '[Contradiction Quarantined] The function $f(x)=x^{3}-3x$ is a polynomial, hence continuous everywhere and differentiable everywhere. At the endpoints $f(-\sqrt{3})=f(\sqrt{3})=0$, so the hypotheses of Rolle''s theorem are satisfied. Therefore there exists $c$ in $(-\sqrt{3},\sqrt{3})$ with $f''(c)=0$. Solving $f''(x)=3x^{2}-3=0$ gives $x=\pm1$, both lying inside the interval, confirming the theorem.', '["Step 1: Verify continuity and differentiability of $f(x)$ on the given interval (polynomial ⇒ both true).", "Step 2: Compute the endpoint values: $f(-\\sqrt{3})=f(\\sqrt{3})=0$; they are equal.", "Step 3: Apply Rolle''s theorem to conclude a $c$ exists with $f''(c)=0$.", "Step 4: Find $f''(x)=3x^{2}-3$ and solve $3x^{2}-3=0 \\Rightarrow x=\\pm1$, which lie in $(-\\sqrt{3},\\sqrt{3})$."]', 'If $f$ is continuous on $[a,b]$ and differentiable on $(a,b)$ with $f(a)=f(b)$, then $\exists\,c\in(a,b)$ such that $f''(c)=0$.', 'math.calculus.rolle_theorem_conditions', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:12:40.401Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de8dff4458d43d6a528e44ad7c5be552', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_alcohols', 'Alcohols, Phenols and Ethers', 'Preparation of alcohols – hydration', '[]', '["hydration","acid_catalysis","alkene_to_alcohol","reaction_mechanism"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'Hydration of ethene in the presence of dilute $\mathrm{H_2SO_4}$ as a catalyst yields which of the following alcohols?', '["Ethanol", "Ethylene glycol", "Acetaldehyde", "Acetone"]', 'Ethanol', 'The acid‑catalysed hydration of an alkene adds water across the double bond: $\mathrm{C_2H_4 + H_2O \xrightarrow{H_2SO_4} C_2H_5OH}$.  The product is ethanol, not a diol or carbonyl compound.', '["Step 1: Write the balanced reaction: $\\mathrm{C_2H_4 + H_2O \\rightarrow C_2H_5OH}$.", "Step 2: Note that dilute $\\mathrm{H_2SO_4}$ acts only as a proton donor, not as an oxidising agent.", "Step 3: Identify the product as the corresponding alcohol, ethanol."]', '', 'chemistry.organic.hydration_product', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:56:53.420Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de8f9535e98c5243cbc6781b536cade0', 'JEEMains', '11', 'Physics', 'phy_12_jm_thermodynamics', 'Thermodynamics', 'Carnot engine efficiency and theorem', '[]', '["Thermodynamics","Carnot engine","Efficiency","Coefficient of performance"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 3, -1.0, '$$\text{A Carnot engine operates between two temperatures } T_1 \text{ and } T_2.\text{ The efficiency of the engine is given by } \eta = 1 - \frac{T_2}{T_1}.\text{ If the engine is run in reverse as a refrigerator, what is the coefficient of performance (COP) of the refrigerator?}\text{ Express your answer in terms of } T_1 \text{ and } T_2.$$$,', '["$$\\frac{T_1}{T_2}$$", "$$\\frac{T_2}{T_1}$$", "$$\\frac{T_1 - T_2}{T_1}$$", "$$\\frac{T_1}{T_1 - T_2}$$"]', '$$\frac{T_1}{T_1 - T_2}$$', 'Step 1: Recall the efficiency of a Carnot engine, which is given by $$\eta = 1 - \frac{T_2}{T_1}.$$,Step 2: The coefficient of performance (COP) of a refrigerator is given by $$\text{COP} = \frac{T_2}{T_1 - T_2}.$$,Step 3: Since the engine is run in reverse, we can use the same formula for the COP, but with the temperatures reversed.', '["Step 1: Recall the efficiency of a Carnot engine", "Step 2: Use the same formula for the COP, but with the temperatures reversed", "Step 3: Simplify the expression to get the final answer"]', '$$\eta = 1 - \frac{T_2}{T_1}$$', 'physics.thermo.carnot_engine_efficiency', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:07:48.023Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de9158295416e544a96bbc08025881b3', 'NEET', '11', 'Biology', 'bio_11_biomolecules_mm', 'Biomolecules', 'Michaelis‑Menten kinetics', '[]', '["enzyme kinetics","Km","Vmax","substrate concentration","Lineweaver‑Burk plot"]', 0, 0, '[]', 'MCQ', NULL, 0, 1760, 'NEET_EASY', 3, -1.0, 'In Michaelis‑Menten kinetics, which statement correctly describes the Michaelis constant (Km)?', '["Km is the substrate concentration at which the reaction rate equals Vmax.", "Km is the substrate concentration at which the reaction rate is half of Vmax.", "Km is the maximum possible reaction rate for the enzyme.", "Km is the substrate concentration at which the reaction rate is zero."]', 'Km is the substrate concentration at which the reaction rate is half of Vmax.', 'Km is defined as the substrate concentration at which the velocity v reaches half of its maximum value Vmax. At [S]=Km, v = Vmax/2. This definition is independent of enzyme concentration.', '["Step 1: Recall the Michaelis‑Menten equation v = (Vmax [S])/(Km + [S]).", "Step 2: Set v = Vmax/2 and solve for [S].", "Step 3: The resulting [S] equals Km, confirming the definition."]', 'v = \frac{V_{\max}[S]}{K_m + [S]}', 'biology.enzymes.mm_km_vmax', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:43:09.627Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de91861000bb9808f0237837935b1101', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_acid_base', 'Acids and Bases', 'Acid‑Base Classification', '[]', '["Lewis acid","Brønsted‑Lowry acid","electron pair acceptance","proton donation","acid classification","AlCl₃"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Which of the following species can act as a Lewis acid but cannot act as a Brønsted‑Lowry acid?', '["AlCl₃", "NH₃", "H₂O", "CH₃COOH"]', 'AlCl₃', 'A Lewis acid accepts an electron pair, while a Brønsted‑Lowry acid donates a proton. AlCl₃ accepts electron pairs from bases (e.g., Cl⁻) but has no hydrogen to donate, so it is a Lewis acid only.', '["Step 1: Recall definitions – Lewis acid = electron‑pair acceptor; Brønsted‑Lowry acid = proton donor.", "Step 2: Examine each option for the presence of a proton that can be donated.", "Step 3: Identify AlCl₃ as lacking any hydrogen atoms, thus cannot donate a proton.", "Step 4: Recognize that AlCl₃ can accept electron pairs from a Lewis base, satisfying the Lewis‑acid criterion."]', '', 'chemistry.acid_base.classification_error', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:42:30.157Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de92ce69383000460540b364b4d776a5', 'Board', '10', 'Science', 'phy_10_board_magnetism', 'Magnetic Effects of Current', 'Magnetic Field of a Straight Wire', '[]', '["Biot–Savart law","magnetic field","straight current‑carrying wire","μ0","SI units"]', 0, 0, '[]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 3, 0.0, 'A long straight wire carries a current of 5 A. What is the magnitude of the magnetic field at a point 0.20 m from the wire? (Use \(\mu_0 = 4\pi\times10^{-7}\) T·m/A.)', '["5 \\mu T", "10 \\mu T", "2.5 \\mu T", "1 \\mu T"]', '5 \mu T', 'The magnetic field around a straight current‑carrying conductor is given by \(B = \frac{\mu_0 I}{2\pi r}\). Substituting \(I=5\) A and \(r=0.20\) m yields \(B = 5\times10^{-6}\) T = 5 µT.', '["Step 1: Write the Biot–Savart expression for a straight wire: \\(B = \\frac{\\mu_0 I}{2\\pi r}\\).", "Step 2: Substitute \\(\\mu_0 = 4\\pi\\times10^{-7}\\) T·m/A, \\(I = 5\\) A, and \\(r = 0.20\\) m.", "Step 3: Simplify: \\(B = \\frac{4\\pi\\times10^{-7}\\times5}{2\\pi\\times0.20} = 5\\times10^{-6}\\) T = 5 µT."]', 'B = \frac{\mu_0 I}{2\pi r}', 'physics.magnetism.biot_savart_direction', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:19:18', 'v2.1', 'Taxonomy alignment: updated class (10->10), exam (Board->Board), subject (Physics->Science) to match canonical taxonomy item sci_10_board_magnetism', '2026-05-20T12:57:12.004Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de9d3e160a01e9909efb8aaccc0625ba', 'JEEMains', '11', 'Physics', 'phy_11_jm_kinematics_2d', 'Circular Motion', 'Centripetal Acceleration', '[]', '["centripetal_force","uniform_circular_motion","acceleration","v_squared_over_r"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'A particle moves in a horizontal circular path of radius $0.50\ \text{m}$ with a constant speed of $4.0\ \text{m s}^{-1}$. What is the magnitude of its centripetal acceleration?', '["$8.0\\ \\text{m s}^{-2}$", "$16\\ \\text{m s}^{-2}$", "$32\\ \\text{m s}^{-2}$", "$64\\ \\text{m s}^{-2}$"]', '$32\ \text{m s}^{-2}$', 'Centripetal acceleration is given by $a_c = v^2/r$. Substituting $v = 4.0\ \text{m s}^{-1}$ and $r = 0.50\ \text{m}$ yields $a_c = 16/0.5 = 32\ \text{m s}^{-2}$.', '["Step 1: Write the formula $a_c = \\frac{v^2}{r}$.", "Step 2: Square the speed: $v^2 = (4.0)^2 = 16$.", "Step 3: Divide by the radius: $16 / 0.50 = 32$.", "Step 4: State the result with appropriate units."]', 'a_c = \frac{v^2}{r}', 'physics.mechanics.centripetal_acceleration', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:41:38.710Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('de9ef1387adfb9cf5a92345c75f6a128', 'JEEMains', '11', 'Mathematics', 'math_11_jm_sets', 'Sets', 'Set notation roster builder form', '[]', '["set builder","roster form","integer set","element counting"]', 0, 0, '["Board"]', 'Integer', NULL, 0, 1850, 'JEE_MAINS_EASY', 2, 0.0, 'Set $A = \{x \in \mathbb{Z} \mid -3 < x \leq 4\}$. How many elements in A?', '[]', '7', 'Elements are -2,-1,0,1,2,3,4 → total 7 integers.', '["Step 1: List integers in range", "Step 2: Count from -2 to 4 inclusive"]', '', 'math.sets.boundaries_exclusive_inclusive', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:08:18.808Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dea013507bc7524370db555551ed0614', 'JEEMains', '12', 'Mathematics', 'math_12_jm_relations_functions', 'Relations and Functions', 'Types of relations â€” reflexive symmetric transitive', '[]', '["reflexive_relation","symmetric_relation","transitive_relation","binary_relations","set_theory","relation_properties","discrete_mathematics"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 5, -1.0, 'Let $ R $ be a relation on the set $ A = \{1, 2, 3, 4\} $ defined as:
$$
R = \{(1,1), (2,2), (3,3), (4,4), (1,2), (2,1), (3,4)\}
$$
Which of the following is true about $ R $?

$$
\text{A) } \text{Reflexive and symmetric but not transitive} \quad \text{B) } \text{Symmetric and transitive but not reflexive} \\
\text{C) } \text{Reflexive and transitive but not symmetric} \quad \text{D) } \text{Equivalence relation}
$$', '["Reflexive and symmetric but not transitive", "Symmetric and transitive but not reflexive", "Reflexive and transitive but not symmetric", "Equivalence relation"]', 'Reflexive and symmetric but not transitive', 'The relation contains all (a,a), so reflexive. (1,2) and (2,1) are both present, but (3,4) is present while (4,3) is not → not symmetric. For transitivity: (1,2) and (2,1) imply (1,1) and (2,2), which exist. No other pairs form a chain, so transitivity holds. Thus, R is reflexive and transitive but not symmetric.', '["Step 1: Check reflexivity — all diagonal elements present → reflexive.", "Step 2: Check symmetry — (3,4) ∈ R but (4,3) ∉ R → not symmetric.", "Step 3: Check transitivity — only possible chain is (1,2), (2,1) → requires (1,1), (2,2) which exist.", "Step 4: No other chains, so transitive.", "Step 5: Conclude: reflexive and transitive, not symmetric."]', '', 'math.relations.symmetry_check_incomplete', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:20:45.562Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dea07f1a2999d93e959317f47b512ad1', 'JEEMains', '12', 'Chemistry', 'che_12_jm_group16_allotropes', 'p‑Block Elements', 'Group 16 – Sulfur compounds', '[]', '["SO₃ hydrolysis","sulfuric acid formation","physical state of SO₃","oxidizing ability"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'Which of the following statements about sulfur trioxide (SO₃) is correct?', '["It exists as a dimer (S₂O₆) at room temperature", "It is a strong oxidizing agent", "It is a gas at 25 °C", "It reacts with water to form sulfuric acid"]', 'It reacts with water to form sulfuric acid', 'SO₃ readily hydrolyses with water: \(\text{SO}_{3}+\text{H}_{2}\text{O}\rightarrow\text{H}_{2}\text{SO}_{4}\). The other statements are false: SO₃ is a liquid at 25 °C, not a dimer, and its oxidizing strength is moderate compared with Cl₂O₇.', '["Step 1: Recall physical state – SO₃ is a liquid (melting point 16.9 °C).", "Step 2: Evaluate reactivity – SO₃ reacts vigorously with water to give H₂SO₄.", "Step 3: Eliminate incorrect options based on known properties.", "Step 4: Choose the statement that matches the hydrolysis reaction."]', '', 'chem.pblock.group16.hydrolysis_misinterpret', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:16:05.816Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dea387d92ea9bb037ce3bda34de607a0', 'JEEMains', '12', 'Physics', 'phy_12_jm_current_electricity', 'Current Electricity', 'Kirchhoff''s Voltage Law', '[]', '["Kirchhoff''s Voltage Law","Series circuits","Ohm''s law","Resistance calculation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'In the circuit shown, a 12 V battery is connected in series with a resistor R₁ = 4 Ω, a resistor R₂ = 6 Ω, and an unknown resistor Rₓ. The current flowing through the circuit is 1 A. Using Kirchhoff''s Voltage Law, find the value of Rₓ.', '["2 Ω", "4 Ω", "6 Ω", "8 Ω"]', '2 Ω', 'Apply KVL: the sum of the IR drops equals the emf. 12 V = 1 A × (R₁+R₂+Rₓ). Substituting R₁ and R₂ gives 12 = 1 × (4+6+Rₓ) ⇒ Rₓ = 2 Ω.', '["Step 1: Write KVL equation V = I(R₁+R₂+Rₓ).", "Step 2: Substitute V = 12 V, I = 1 A, R₁ = 4 Ω, R₂ = 6 Ω.", "Step 3: Solve for Rₓ to obtain Rₓ = 2 Ω."]', 'V = I R', 'physics.electricity.kirchhoff_voltage', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:57:22.898Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dea8af1f65e811b82c040732b1da24d7', 'NEET', '11', 'Biology', 'bio_11_neet_photosynthesis', 'Photosynthesis', 'CAM plants and their adaptation', '[]', '["photosynthesis","CAM plants","Kranz anatomy"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, '$$\text{Which of the following plants exhibit Crassulacean acid metabolism (CAM) photosynthesis?}$$_{\text{[NEET 2022]}}', '["C3 plants", "C4 plants", "CAM plants", "Kranz anatomy"]', 'CAM plants', 'Crassulacean acid metabolism (CAM) photosynthesis is a type of photosynthesis that is found in certain plants, such as cacti and succulents. In CAM photosynthesis, the stomata are open at night and closed during the day, allowing for CO2 to enter the leaf and be fixed into organic compounds. This type of photosynthesis is adapted to hot and dry environments, where water is scarce.', '["Step 1: Identify the type of photosynthesis exhibited by CAM plants.", "Step 2: Recall the characteristics of CAM photosynthesis.", "Step 3: Match the characteristics with the correct type of photosynthesis."]', '', 'general.exam_trap', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:24:25.745Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('deaa94e66d02df16c5beb6289fbca503', 'NEET', '12', 'Biology', 'bio_12_neet_genetics', 'Principles of Inheritance', 'ABO Blood Groups', '[]', '["multiple alleles","genotype","phenotype","probability"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 2, -1.0, 'Father (IAi) and Mother (IBi). Probability of O blood group child?', '["0%", "25%", "50%", "75%"]', '25%', 'Cross IAi x IBi gives ii genotype with 1/4 probability.', '["Set up cross: IAi x IBi", "Calculate ii probability"]', 'Punnett Square', 'biology.genetics.probability_error', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:51:38.338Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('deadf0f68fc421d5a58888bfe76a4534', 'JEEAdvanced', '12', 'Mathematics', 'math_12_jadv_number_theory', 'Number Theory', 'Legendre’s formula for prime exponents in factorials', '[]', '["Legendre formula","prime exponent","factorial","valuation","p‑adic"]', 0, 0, '[]', 'Integer', NULL, 0, 2500, 'JEE_ADV_EASY', 4, -1.0, 'What is the exponent of the prime $7$ in the factorisation of $100!$ ?', '[]', '16', 'Legendre''s formula gives the exponent of a prime $p$ in $n!$ as $\displaystyle e_p(n!) = \sum_{k=1}^{\infty} \left\lfloor \frac{n}{p^k} \right\rfloor$. For $p=7$ and $n=100$: $\lfloor 100/7 \rfloor = 14$, $\lfloor 100/49 \rfloor = 2$, $\lfloor 100/343 \rfloor = 0$. Summing gives $14+2 = 16$.', '["Step 1: Apply Legendre''s formula $e_p(n!) = \\sum_{k\\ge1} \\lfloor n/p^k \\rfloor$.", "Step 2: Compute $\\lfloor 100/7 \\rfloor = 14$.", "Step 3: Compute $\\lfloor 100/49 \\rfloor = 2$ and note higher powers give zero.", "Step 4: Add the contributions: $14 + 2 = 16$."]', '$e_p(n!) = \sum_{k=1}^{\infty} \left\lfloor \frac{n}{p^k}\right\rfloor$', 'mathematics.number_theory.legendre_exponent', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:55:26.868Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('deb8d78db6ed9b92792c64c56c90644c', 'JEEMains', '11', 'Mathematics', 'math_11_jm_perm_rank', 'Permutations and Combinations', 'Rank of word in dictionary', '[]', '["dictionary rank","factorial","lexicographic order","permutations"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 5, -1.0, 'Find the rank of the word "MATH" when all its letters are arranged in alphabetical order and listed as permutations.', '["12", "14", "16", "20"]', '14', 'Alphabetical order of letters: A, H, M, T. For first letter M, two letters (A, H) precede it, each giving $3!$ permutations. Count = $2\times6=12$. Remaining letters A, H, T: next letter A contributes 0. For T, one smaller letter H gives $1!$ permutation. Total count = $12+0+1=13$, rank = $13+1=14$.', '["Step 1: List letters in alphabetical order: A, H, M, T.", "Step 2: For the first letter M, count permutations starting with letters smaller than M: $2\\times3! = 12$.", "Step 3: For the second letter A, no smaller letters remain, so add 0.", "Step 4: For the third letter T, one smaller letter (H) gives $1! = 1$.", "Step 5: Add 1 to the total count to obtain the rank: $12+0+1+1 = 14$."]', 'Rank = 1 + \sum_{i} (\text{smaller letters before } i)\times (n-i)!', 'mathematics.combinatorics.dictionary_rank', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:32:51.184Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('debd81fea98b802d32a62d733dbc6f76', 'JEEMains', '11', 'Physics', 'phy_11_jee_work_energy', 'Work Energy and Power', 'Work Energy Theorem', '[]', '["Work Energy","Theorem"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'JEE_MAINS_EASY', 2, -1.0, '$$\text{The work-energy theorem states that the work done on an object is equal to the change in its kinetic energy. The equation for this theorem is:}', '["$W = \\Delta K$", "$W = K - U$", "$W = U - K$", "$W = K + U$"]', '$W = \Delta K$', 'Step 1: Identify the work-energy theorem and its equation.,Step 2: Determine the correct equation using the given information.', '["Step 1: Identify the work-energy theorem and its equation.", "Step 2: Determine the correct equation using the given information."]', '', 'physics.work_energy.theorem', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:17:36.086Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('debee8f0ddd63215a98800ff4536aab1', 'JEEMains', '12', 'Mathematics', 'math_12_jm_orthogonal_trajectories', 'Differential Equations', 'Orthogonal trajectories', '[]', '["orthogonal trajectories","first order ODE","separation of variables","family of curves","parabola"]', 0, 0, '[]', 'MCQ', NULL, 0, 2120, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Find the family of orthogonal trajectories of the family of curves $y = c x^{2}$, where $c$ is an arbitrary constant.', '["$y^{2} + \\frac{x^{2}}{2} = C$", "$y^{2} - \\frac{x^{2}}{2} = C$", "$y = \\frac{C}{x^{2}}$", "$x y = C$"]', '$y^{2} + \frac{x^{2}}{2} = C$', 'Differentiate $y = c x^{2}$ to get $\frac{dy}{dx}=2c x = \frac{2y}{x}$. For orthogonal trajectories replace the slope by its negative reciprocal: $\frac{dy}{dx}= -\frac{x}{2y}$. Separate variables and integrate: $2y\,dy = -x\,dx \Rightarrow y^{2}+\frac{x^{2}}{2}=C$. This is the required family.', '["Step 1: Differentiate the given family to obtain $\\frac{dy}{dx}=\\frac{2y}{x}$.", "Step 2: For orthogonal trajectories replace the slope with its negative reciprocal: $\\frac{dy}{dx}= -\\frac{x}{2y}$.", "Step 3: Separate variables: $2y\\,dy = -x\\,dx$.", "Step 4: Integrate both sides to obtain $y^{2}+\\frac{x^{2}}{2}=C$."]', '$\frac{dy}{dx}= -\frac{1}{(dy/dx)_{\text{given}}}$', 'math.diff_eq.orthogonal_trajectory', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:38:15.892Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('debfe99a7e3f3fc03372ff165b9e4d4e', 'Board', '9', 'Mathematics', 'math_9_board_algebra', 'Algebraic Expressions', 'Word problems linear equations', '["math_9_board_linear_equations"]', '["linear equations","word problem","system of equations","algebraic expressions","substitution method","elimination method","number problems"]', 1, 0, '[]', 'Integer', NULL, 0, 1250, 'CLASS_9_BASIC', 4, 0.0, 'The sum of two numbers is 25 and their difference is 7. What is the smaller number?', '[]', '9', 'Let the numbers be $x$ and $y$, $x > y$. Then $x + y = 25$, $x - y = 7$. Adding: $2x = 32 \Rightarrow x = 16$. So $y = 25 - 16 = 9$. The smaller number is 9.', '["Set up equations: x + y = 25, x - y = 7", "Add equations: 2x = 32 → x = 16", "Substitute: y = 25 - 16 = 9", "Identify smaller number as 9"]', '', 'math.algebra.linear_equation_setup_error', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1250 and target exam Board', '2026-05-20T11:53:20.962Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dec0a57824db7758ce47152422a843e4', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_biomolecules', 'Biomolecules', 'Essential and non-essential amino acids', '[]', '["amino acids","essential amino acids","non-essential amino acids","human nutrition","protein synthesis","biochemistry","dietary requirements"]', 0, 0, '["NEET","Board"]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 4, -1.0, 'Which of the following amino acids is classified as essential for humans and must be obtained through diet?

$$\text{(A) Alanine} \quad \text{(B) Aspartic acid} \quad \text{(C) Glutamic acid} \quad \text{(D) Lysine}$$', '["Alanine", "Aspartic acid", "Glutamic acid", "Lysine"]', 'Lysine', 'Essential amino acids cannot be synthesized by the human body and must be obtained from the diet. There are 9 essential amino acids, including Lysine. Non-essential amino acids like Alanine, Aspartic acid, and Glutamic acid can be synthesized in the body. Therefore, Lysine is the correct answer.', '["Step 1: Recall definition of essential amino acids — cannot be synthesized by the body.", "Step 2: List common essential amino acids: Histidine, Isoleucine, Leucine, Lysine, Methionine, Phenylalanine, Threonine, Tryptophan, Valine.", "Step 3: Identify that Lysine is in this list; others listed (Alanine, Aspartic acid, Glutamic acid) are non-essential.", "Step 4: Select correct option based on this distinction."]', '', 'chemistry.biomolecules.amino_acid_classification_misconception', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:05:51.523Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dec5934d376627fbf8d5447eadc7da71', 'Board', '9', 'Mathematics', 'math_9_board_mean_deviation', 'Statistics', 'Mean deviation', '[]', '["mean deviation","average","absolute deviation","data set"]', 0, 0, '[]', 'MCQ', NULL, 0, 980, 'CLASS_9_BASIC', 4, 0.0, 'Find the mean deviation about the mean for the data set {4, 6, 8, 10, 12}.', '["2.4", "2", "3", "2.8"]', '2.4', 'Mean = (4+6+8+10+12)/5 = 8. Absolute deviations: 4,2,0,2,4 → sum = 12. Mean deviation = 12/5 = 2.4.', '["Step 1: Compute the mean: (4+6+8+10+12)/5 = 8.", "Step 2: Find absolute deviations from the mean: |4‑8|, |6‑8|, |8‑8|, |10‑8|, |12‑8|.", "Step 3: Sum the deviations (4+2+0+2+4 = 12).", "Step 4: Divide by the number of observations: 12/5 = 2.4."]', '\text{Mean deviation} = \frac{\sum |x_i-\bar{x}|}{n}', 'math.statistics.mean_deviation', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:55:01.462Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dec9f285968d22046e87568c69831a51', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_thermo_cpcv', 'Thermodynamics', 'Heat capacity Cv Cp relation', '[]', '["heat capacity ratio","degrees of freedom","ideal gas","Cp and Cv","gamma for diatomic"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 4, -1.0, 'For a diatomic ideal gas, what is the ratio $\frac{C_p}{C_v}$?', '["1.40", "1.67", "1.33", "2.00"]', '1.40', 'For a diatomic gas, degrees of freedom $f = 5$ (3 translational + 2 rotational). $C_v = \frac{f}{2}R = \frac{5}{2}R$, $C_p = C_v + R = \frac{7}{2}R$. So $\frac{C_p}{C_v} = \frac{7/2}{5/2} = \frac{7}{5} = 1.40$.', '["Step 1: Identify degrees of freedom for diatomic gas: 5", "Step 2: Use $C_v = \\frac{f}{2}R = \\frac{5}{2}R$", "Step 3: $C_p = C_v + R = \\frac{7}{2}R$", "Step 4: Compute ratio $\\gamma = C_p/C_v = 7/5 = 1.40$"]', '$\gamma = \frac{C_p}{C_v} = 1 + \frac{2}{f}$', 'chemistry.thermo.diatomic_dof_miss_rotational', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:21:50', 'v2.1', 'Healed LaTeX math delimiter balancing, boxed LaTeX math structures, currency formatting, and robotic AI phrasing in Phase 5 verification pass.', '2026-05-20T11:52:57.776Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('decf1330785339a6895a6448396a4314', 'NEET', '11', 'Biology', 'bio_11_synapse_neurotransmitters', 'Neural Control and Coordination', 'Synapse types and neurotransmitters', '[]', '["acetylcholine","neuromuscular junction","excitatory neurotransmitter","nicotinic receptor","motor neuron"]', 0, 0, '[]', 'MCQ', NULL, 0, 1950, 'NEET_MEDIUM', 3, -1.0, 'Which neurotransmitter mediates excitatory transmission at the vertebrate neuromuscular junction?', '["Acetylcholine", "γ‑Aminobutyric acid (GABA)", "Glycine", "Dopamine"]', 'Acetylcholine', 'At the neuromuscular junction, acetylcholine released from motor neurons binds to nicotinic receptors, causing depolarization and muscle contraction.', '["Step 1: Recall the primary neurotransmitter at the neuromuscular junction.", "Step 2: Identify its effect – excitatory depolarization.", "Step 3: Match the neurotransmitter to the described function."]', '', 'biology.neurotransmitter.nmj_excitation', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:52:48.630Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('ded86e95c2948ff092e60328e8dabaf3', 'JEEMains', '12', 'Mathematics', 'mat_12_jm_inverse_trig', 'Mathematics', 'Inverse Trigonometric Functions', '[]', '["domain","range","inverse sine","inverse cosine","function composition"]', 0, 0, '[]', 'MCQ', NULL, 0, 2120, 'JEE_MAINS_MEDIUM', 4, -1.0, 'What is the domain of the function $f(x)=\sin^{-1}(2x-1)$ and the range of the function $g(x)=\cos^{-1}(x^{2})$?', '["Domain: $[-1,1]$, Range: $[0,\\pi]$", "Domain: $[0,1]$, Range: $[0,\\pi/2]$", "Domain: $[0,1]$, Range: $[0,\\pi]$", "Domain: $[0,0.5]$, Range: $[0,\\pi]$"]', 'Domain: $[0,1]$, Range: $[0,\pi]$', 'For $\sin^{-1}(2x-1)$ the argument must satisfy $-1\le 2x-1\le 1$, giving $0\le x\le1$, so the domain is $[0,1]$. The range of $\cos^{-1}$ is always $[0,\pi]$, irrespective of the argument $x^2$, which lies in $[0,1]$. Hence the correct pair is domain $[0,1]$ and range $[0,\pi]$.', '["Step 1: Impose the condition $-1 \\le 2x-1 \\le 1$ for the arcsine argument.", "Step 2: Solve the inequality to obtain $0 \\le x \\le 1$.", "Step 3: Recall that the principal value range of $\\cos^{-1}$ is $[0,\\pi]$.", "Step 4: Combine the results to state the domain and range."]', '-1 \le \text{argument} \le 1 \; (\text{arcsin}), \; \text{range of arccos} = [0,\pi]', 'mathematics.inverse_trig.domain_range', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:03:25.921Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('deda37ad0e2c789c1eefbfc47ede6bb1', 'JEEAdvanced', '12', 'Physics', 'phy_12_jadv_doppler', 'Advanced Wave Physics', 'Doppler effect for accelerating source – instantaneous frequency', '[]', '["Doppler effect","accelerating source","instantaneous frequency","kinematics","wave propagation"]', 0, 0, '[]', 'MCQ', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 4, -2.0, 'A source moves towards a stationary observer with constant acceleration $a$, starting from rest at distance $d$. At the instant when the source is at distance $x$ from the observer, its instantaneous speed is $v=\sqrt{2a(d-x)}$. The observed frequency is $f = f_0\,\frac{c}{c-v}$. Which expression correctly gives $f$ in terms of $x$?', '["$f = f_0\\,\\frac{c}{c-\\sqrt{2a(d-x)}}$", "$f = f_0\\,\\frac{c+\\sqrt{2a(d-x)}}{c}$", "$f = f_0\\,\\frac{c-\\sqrt{2a(d-x)}}{c}$", "$f = f_0\\,\\frac{c}{c+\\sqrt{2a(d-x)}}$"]', '$f = f_0\,\frac{c}{c-\sqrt{2a(d-x)}}$', 'Insert $v=\sqrt{2a(d-x)}$ into the Doppler formula $f = f_0\,c/(c-v)$; the minus sign in the denominator remains because the source approaches the observer.', '["Step 1: Write the Doppler formula for a source moving towards the observer: $f = f_0\\,\\frac{c}{c-v}$.", "Step 2: Substitute $v = \\sqrt{2a(d-x)}$.", "Step 3: Simplify to obtain $f = f_0\\,\\frac{c}{c-\\sqrt{2a(d-x)}}$."]', '$f = f_0\,\frac{c}{c-v}$', 'physics.waves.doppler_accelerating_source', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:43:09.781Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dede781893f2addbeed9b4890dabd78d', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_d_and_f_block', 'd and f Block Elements', 'General properties of transition elements', '[]', '["oxidation states","transition metals","manganese","d-electron configuration"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'Which of the following transition elements exhibits the highest number of oxidation states?', '["Sc", "Mn", "Zn", "Cu"]', 'Mn', 'Mn (Z=25) shows oxidation states from +2 to +7 due to maximum unpaired d-electrons.', '["Step 1: Recall oxidation state trend in d-block", "Step 2: Mn has 5 unpaired d-electrons", "Step 3: Exhibits +2 to +7 states"]', '', 'chem.dblock.oxidation_state_underestimation', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:02:08.942Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('dee549a458829df0bc037df2f827fb9e', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_lechatelier', 'Equilibrium', 'Le Chatelier principle - pressure change', '[]', '["Le Chatelier","pressure effect","equilibrium shift","gas moles"]', 0, 0, '[]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 2, -1.0, 'For the reaction $N_2(g) + 3H_2(g) \rightleftharpoons 2NH_3(g)$, what happens when pressure is increased at constant temperature?', '["$K_c$ increases", "$K_c$ decreases", "Equilibrium shifts left", "Equilibrium shifts right"]', 'Equilibrium shifts right', 'Increased pressure favors side with fewer moles (right: 2 vs 4).', '["Step 1: Count moles: 4 → 2", "Step 2: High pressure favors forward reaction"]', '$\Delta n_g < 0$ favors high pressure', 'chemistry.equilibrium.kc_vs_shift', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:17:15.140Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('def4c7996551f780aa210de5aa9be8a9', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_organic_mechanisms', 'Advanced Organic Chemistry', 'Neighbouring group participation', '["chem_12_ja_stereochemistry"]', '["neighbouring group participation","anchimeric assistance","retention of configuration","nucleophilic substitution","stereochemistry"]', 1, 0, '[]', 'MCQ', NULL, 0, 2450, 'JEE_ADV_EASY', 2, -2.0, 'Neighbouring group participation (NGP) leads to:', '["Retention of configuration", "Racemization", "Inversion of configuration", "No reaction"]', 'Retention of configuration', 'NGP involves intramolecular nucleophilic attack, leading to retention.', '["Step 1: Recall NGP involves neighboring group acting as nucleophile.", "Step 2: Intermediate formation retains stereochemistry."]', '', 'chemistry.organic.stereochemistry_misconception', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:11:48.261Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('df018e6f7d448b1d0831b482a56cf93f', 'NEET', '12', 'Biology', 'bio_12_neet_plasmid_vectors', 'Plasmids as vectors', 'Ti plasmid characteristics', '[]', '["Ti plasmid","binary vector","gene cloning","restriction sites","antibiotic resistance"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 1850, 'NEET_EASY', 4, -1.0, 'In the construction of recombinant plasmid vectors, the Ti plasmid of *Agrobacterium tumefaciens* is preferred because:', '["It contains a high‑copy‑number origin of replication suitable for *E. coli* expression", "It possesses a T‑DNA region that can be easily excised and transferred into plant genomes", "It carries an antibiotic resistance gene that is lethal to most plant cells", "It lacks any restriction sites, preventing unwanted cleavage during cloning"]', 'It possesses a T‑DNA region that can be easily excised and transferred into plant genomes', 'The Ti plasmid''s T‑DNA region integrates into the plant genome, making it ideal for plant genetic engineering. It is not a high‑copy‑number plasmid in *E. coli*, and its antibiotic resistance markers are used for selection, not lethality. The plasmid contains multiple restriction sites to facilitate cloning.', '["Step 1: Recall the unique features of Ti plasmids used in plant transformation.", "Step 2: Identify which option describes the T‑DNA region''s role in gene transfer.", "Step 3: Discard options that misrepresent copy number, lethality, or lack of restriction sites.", "Step 4: Choose the statement that correctly highlights the Ti plasmid''s advantage."]', '', 'biology.biotech.plasmid_vector_feature', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:58:58.300Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('df06cfceab9e66e67864816922d7bda1', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_number_theory', 'Number Theory', 'Euclid GCD algorithm', '[]', '["gcd","euclidean algorithm","number theory","divisibility"]', 0, 0, '[]', 'Integer', NULL, 0, 1850, 'JEE_ADV_EASY', 3, -1.0, 'What is the greatest common divisor (GCD) of $48$ and $18$ using the Euclidean algorithm?', '[]', '6', 'Apply Euclidean algorithm: $48 = 2\cdot18 + 12$, $18 = 1\cdot12 + 6$, $12 = 2\cdot6 + 0$. GCD is last non-zero remainder.', '["Step 1: $48 \\mod 18 = 12$", "Step 2: $18 \\mod 12 = 6$", "Step 3: $12 \\mod 6 = 0$"]', '$\gcd(a,b) = \gcd(b, a \mod b)$', 'math.number_theory.gcd.modulo_order', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (JEE_MAINS_EASY->JEE_ADV_EASY) based on ELO score 1850 and target exam JEEAdvanced', '2026-05-22T15:08:27.498Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('df08859b77721e5bc4dfb8040613c3ab', 'JEEMains', '11', 'Mathematics', 'math_11_jm_limits_derivatives', 'Limits and Derivatives', 'Definition of limit ε‑δ informally', '[]', '["limit evaluation","factorisation","indeterminate form","cancellation","continuity"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Find $\displaystyle\lim_{x\to2}\frac{x^2-4}{x-2}$. Choose the correct limit value.', '["4", "2", "0", "Does not exist"]', '4', 'Factor numerator: $x^2-4=(x-2)(x+2)$. Cancel $(x-2)$ (for $x\neq2$) to get $x+2$. Taking $x\to2$ gives $2+2=4$. The other options stem from direct substitution (giving $0/0$) or forgetting to cancel.', '["Step 1: Recognize the indeterminate form $0/0$ and factor the numerator.", "Step 2: Write $x^2-4=(x-2)(x+2)$.", "Step 3: Cancel the common factor $(x-2)$ to obtain $x+2$.", "Step 4: Substitute $x=2$ into $x+2$ to get $4$."]', '$\lim_{x\to a}\frac{f(x)}{g(x)} = \frac{f''(a)}{g''(a)}$ (or factorisation)', 'mathematics.limits.direct_substitution_error', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:45:17.729Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('df0926b7548805974b5198a0ec834931', 'NEET', '12', 'Biology', 'bio_12_neet_reproduction_flowering_plants', 'Sexual Reproduction in Flowering Plants', 'Megasporogenesis and female gametophyte (embryo sac)', '[]', '["megasporogenesis","meiosis","female gametophyte","embryo sac","angiosperm reproduction","megaspore mother cell","gametogenesis"]', 0, 0, '["Board"]', 'Integer', NULL, 0, 2000, 'NEET_MEDIUM', 2, -1.0, 'In a typical angiosperm, how many meiotic divisions are required to form 100 embryo sacs?', '[]', '100', 'Each megasporocyte undergoes meiosis to produce one functional megaspore per embryo sac.', '["Step 1: One meiotic division → one functional megaspore", "Step 2: Each develops into one embryo sac."]', '', 'bio.reproduction.megasporogenesis_division_count_confusion', 'NEET Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:16:55.779Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('df0af4fe40aa0e9999ae73f4a738f92f', 'NEET', '11', 'Biology', 'bio_11_neet_water_potential', 'Plant Physiology Advanced', 'Water potential Î¨=Î¨s+Î¨p â€” osmosis quantitative', '[]', '["water potential","solute potential","pressure potential","osmosis","turgor pressure","plant cell physiology","Î¨ = Î¨s + Î¨p"]', 0, 0, '["Board"]', 'Integer', NULL, 0, 1780, 'NEET_EASY', 4, -1.0, 'A plant cell has a solute potential ($ \Psi_s $) of -0.7 MPa and a pressure potential ($ \Psi_p $) of +0.3 MPa. What is the water potential ($ \Psi $) of the cell?', '[]', '-0.4', 'Water potential is given by $ \Psi = \Psi_s + \Psi_p $. Substituting values: $ -0.7 + 0.3 = -0.4 $ MPa. Water moves from higher to lower water potential.', '["Step 1: Recall formula: $ \\Psi = \\Psi_s + \\Psi_p $", "Step 2: $ \\Psi_s = -0.7 $ MPa (always negative)", "Step 3: $ \\Psi_p = +0.3 $ MPa (positive due to turgor)", "Step 4: $ \\Psi = -0.7 + 0.3 = -0.4 $ MPa"]', '\Psi = \Psi_s + \Psi_p', 'biology.plantphys.sign_error_in_water_potential', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:03:43.386Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('df14f839011a1a9f88ba3ec2d4b78843', 'NEET', '11', 'Biology', 'bio_11_neet_cell_structure', 'Cell: The Unit of Life', 'Prokaryotic vs eukaryotic cell structure', '[]', '["nucleus","prokaryote","eukaryote","nuclear envelope","membrane-bound organelles","cell biology","plasma membrane"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 1, -1.0, 'Which feature is present in eukaryotes but absent in prokaryotes?', '["Plasma membrane", "Ribosomes", "Nuclear membrane", "Cell wall"]', 'Nuclear membrane', 'Eukaryotes have membrane-bound nucleus; prokaryotes do not.', '["Step 1: Recall nucleus is membrane-bound in eukaryotes", "Step 2: Nuclear membrane is absent in prokaryotes"]', '', 'bio.cell.organelle_presence', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:02:25.272Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('df17440499b26c9facb5669ad4296b2f', 'JEEMains', '12', 'Physics', 'phy_12_jm_em_induction', 'Electromagnetic Induction', 'Flux linkage and rate of change', '[]', '["Faraday''s law","flux linkage","induced emf","rate of change of magnetic field","N turns"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'A coil of $20$ turns and area $0.02\ \text{m}^2$ is placed in a uniform magnetic field that changes from $0.10\ \text{T}$ to $0.30\ \text{T}$ in $0.5\ \text{s}$. What is the magnitude of the induced emf (in volts)?', '["0.08 V", "0.16 V", "0.32 V", "0.64 V"]', '0.16 V', 'Using Faraday''s law $\varepsilon = -N\frac{\Delta \Phi}{\Delta t}$ with $\Delta \Phi = A\Delta B$, we get $\Delta B = (0.30-0.10)/0.5 = 0.40\ \text{T/s}$, $\Delta \Phi = 0.02\times0.20 = 0.004\ \text{Wb}$, and $\varepsilon = 20\times0.004/0.5 = 0.16\ \text{V}$.', '["Step 1: Compute the rate of change of magnetic field: $\\Delta B/\\Delta t = (0.30-0.10)/0.5 = 0.40\\ \\text{T/s}$.", "Step 2: Find the change in flux per turn: $\\Delta \\Phi = A\\Delta B = 0.02\\times0.20 = 0.004\\ \\text{Wb}$.", "Step 3: Apply Faraday''s law: $\\varepsilon = N\\,\\Delta \\Phi/\\Delta t = 20\\times0.004/0.5 = 0.16\\ \\text{V}$.", "Step 4: Choose the matching option."]', '\varepsilon = -N\frac{\Delta \Phi}{\Delta t}', 'physics.emi.flux_rate_misinterpretation', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:49:58.271Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('df1c0d2e5e987ecb994613a0964d9a74', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_dipole', 'Chemical Bonding', 'Dipole moment of polar covalent bonds', '[]', '["dipole moment","polar covalent bond","electronegativity","bond length","Debye"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'Which of the following statements correctly describes the relationship between bond polarity and dipole moment in a polar covalent bond?', '["A bond with a larger difference in electronegativity always has a larger dipole moment, irrespective of bond length.", "The dipole moment is the product of the magnitude of charge separation and the distance between the nuclei.", "Dipole moment depends only on the molecular geometry, not on individual bond polarity.", "All polar covalent bonds have the same dipole moment value of 1.0 D."]', 'The dipole moment is the product of the magnitude of charge separation and the distance between the nuclei.', 'Dipole moment $\mu$ is defined as $\mu = q\,d$, where $q$ is the effective charge separation (related to electronegativity difference) and $d$ is the internuclear distance. Both factors influence $\mu$, so option B is the correct statement.', '["Step 1: Recall the definition $\\mu = q\\times d$ for a polar bond.", "Step 2: Recognize that $q$ depends on electronegativity difference, while $d$ is the bond length.", "Step 3: Evaluate each option against the definition; only option B matches.", "Step 4: Choose option B as the correct answer."]', '$\mu = q \times d$', 'chemistry.bonding.dipole_relation', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:11:12.345Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('df1c758596025effd9315927660b90bc', 'Board', '8', 'Mathematics', 'math_8_board_algebra_identities', 'Algebraic Expressions and Identities', 'Difference of squares', '[]', '["difference of squares","factorisation","algebraic identities","a^2 - b^2"]', 0, 0, '[]', 'MCQ', NULL, 0, 820, 'CLASS_8_RECALL', 2, 0.0, 'Factorise the algebraic expression \(a^{2}-b^{2}\).', '["(a-b)(a+b)", "(a+b)^{2}", "(a-b)^{2}", "a^{2}+b^{2}"]', '(a-b)(a+b)', 'The expression matches the difference of squares identity \(x^{2}-y^{2}=(x-y)(x+y)\). Substituting \(x=a\) and \(y=b\) gives the required factorisation.', '["Step 1: Recognise the pattern \\(a^{2}-b^{2}\\) as a difference of squares.", "Step 2: Apply the identity \\(x^{2}-y^{2}=(x-y)(x+y)\\).", "Step 3: Write the factorised form \\((a-b)(a+b)\\)."]', '$a^{2}-b^{2}=(a-b)(a+b)$', 'math.algebra.difference_of_squares', 'Board Class 8', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:49:10.862Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('df248a43ce4f132366426cf001d03895', 'NEET', '12', 'Biology', 'bio_12_neet_translation', 'Molecular Basis of Inheritance', 'Translation', '[]', '["ribosome","codon","anticodon","start codon","initiation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 2, -1.0, 'In eukaryotic translation, the anticodon of the tRNA that pairs with the start codon \(AUG\) is:', '["UAC", "UAU", "CAU", "GUA"]', 'UAC', 'The start codon \(AUG\) (5''→3'') pairs with the anticodon \(UAC\) (5''→3'') on the initiator tRNA\(^{Met}\). This complementary base pairing is essential for the initiation of protein synthesis.', '["Step 1: Write the start codon \\(AUG\\) in the 5''→3'' direction.", "Step 2: Determine the complementary bases (A↔U, G↔C) to form the anticodon.", "Step 3: Verify the orientation (5''→3'') of the anticodon."]', '', 'biology.molecular.translation_start_codon', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:37:56.927Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('df27fd8b1a2449139865917b91116e0e', 'NEET', '11', 'Biology', 'bio_11_neet_plant_physiology', 'Plant Physiology Advanced', 'Vernalisation â€” mechanism and crop applications', '["bio_11_neet_plant_hormones"]', '["vernalisation","gibberellin","flowering induction","cold treatment","biennial plants","epigenetic regulation","plant development"]', 1, 0, '["Board"]', 'MCQ', NULL, 0, 1850, 'NEET_EASY', 3, -1.0, 'Vernalisation promotes flowering in certain plants by:

(A) Stimulating ethylene production in apical meristems

(B) Inducing gibberellin synthesis after prolonged cold exposure

(C) Breaking seed dormancy through desiccation tolerance

(D) Promoting abscisic acid accumulation in leaves', '["Stimulating ethylene production in apical meristems", "Inducing gibberellin synthesis after prolonged cold exposure", "Breaking seed dormancy through desiccation tolerance", "Promoting abscisic acid accumulation in leaves"]', 'Inducing gibberellin synthesis after prolonged cold exposure', 'Vernalisation is the process where prolonged exposure to cold temperatures accelerates flowering in biennial plants. This cold stimulus triggers epigenetic changes that lead to increased gibberellin synthesis, which in turn promotes flowering. It does not primarily involve ethylene, ABA, or direct seed dormancy breaking.', '["Step 1: Define vernalisation as cold-induced flowering promotion.", "Step 2: Recall that gibberellins are key hormones mediating this response.", "Step 3: Eliminate options related to ethylene (fruit ripening), ABA (dormancy), and desiccation (not involved in vernalisation)."]', '', 'biology.plant_physiology.hormone_function_confusion', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:06:21.858Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('df29c80719667c90010e64a85f968e90', 'JEEAdvanced', '12', 'Mathematics', 'math_12_jee_adv_numbertheory', 'Number Theory and Modular Arithmetic', 'Chinese remainder theorem', '[]', '["Chinese remainder theorem","number theory","modular arithmetic"]', 0, 0, '[]', 'MCQ', NULL, 0, 2400, 'JEE_ADV_EASY', 2, -2.0, 'What is the Chinese remainder theorem and its application in number theory?', '["A theorem that states that a system of congruences has a unique solution", "A theorem that states that a system of congruences has no solution", "A theorem that states that a system of congruences has infinitely many solutions", "A theorem that states that a system of congruences has a finite number of solutions"]', 'A theorem that states that a system of congruences has a unique solution', 'The Chinese remainder theorem is a theorem that states that a system of congruences has a unique solution, which is significant in number theory.', '["Step 1: Define the Chinese remainder theorem", "Step 2: Explain its application in number theory"]', '', 'general.exam_trap', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:55:19.059Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('df2c81ba2906f54568d89c540020dc95', 'JEEMains', '12', 'Chemistry', 'che_12_jadv_electrochem', 'Physical Chemistry', 'Electrochemistry', '["che_12_jadv_thermodynamics"]', '["decomposition potential","electrode overvoltage","electrolysis","standard electrode potential","KCl solution"]', 1, 0, '[]', 'MCQ', NULL, 0, 2650, 'JEE_MAINS_HARD', 5, -2.0, 'Electrolysis of an aqueous KCl solution is carried out using Pt electrodes. The standard decomposition potential of water is $1.23\,\text{V}$. The overvoltage for hydrogen evolution on Pt is $0.30\,\text{V}$ and for chlorine evolution on Pt is $0.40\,\text{V}$. The standard electrode potential for the half‑reaction $\ce{Cl- -> Cl2 + 2e-}$ is $1.36\,\text{V}$. Assuming no other side reactions, what is the minimum applied voltage required to obtain hydrogen at the cathode and chlorine at the anode?', '["1.53 V", "2.06 V", "2.30 V", "2.73 V"]', '2.06 V', 'At the cathode, hydrogen evolution requires an effective potential of $-0.30\,\text{V}$ (standard 0 V plus overvoltage). At the anode, chlorine evolution needs $1.36\,\text{V} + 0.40\,\text{V}=1.76\,\text{V}$. The cell voltage is the difference: $1.76 - (-0.30)=2.06\,\text{V}$, which is the minimum applied voltage.', '["Step 1: Identify the half‑reactions and their standard potentials.", "Step 2: Add the given overvoltages to the standard potentials to obtain effective cathode and anode potentials.", "Step 3: Compute the effective cathode potential (hydrogen evolution) = $0\\,\\text{V} + 0.30\\,\\text{V}= -0.30\\,\\text{V}$.", "Step 4: Compute the effective anode potential (chlorine evolution) = $1.36\\,\\text{V} + 0.40\\,\\text{V}=1.76\\,\\text{V}$.", "Step 5: Minimum cell voltage = $E_{\\text{anode}} - E_{\\text{cathode}} = 1.76 - (-0.30)=2.06\\,\\text{V}$."]', 'E_{cell}=E_{anode}-E_{cathode}', 'chem.electrochem.overvoltage_calculation', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (JEE_ADV_MEDIUM->JEE_MAINS_HARD) based on ELO score 2650 and target exam JEEMains', '2026-05-22T13:12:23.328Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('df30865a6de265017c0546e58c43e9b7', 'JEEMains', '11', 'Physics', 'phy_11_jm_circular_motion', 'Motion in a Plane', 'Uniform circular motion – centripetal acceleration', '[]', '["centripetal acceleration","uniform circular motion","radius","speed","v^2/r"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, -1.0, 'A particle moves in a horizontal circle of radius \(0.5\) m with a constant speed of \(4\) m/s. What is the magnitude of its centripetal acceleration?', '["8 m/s²", "16 m/s²", "32 m/s²", "4 m/s²"]', '32 m/s²', 'Centripetal acceleration is given by \(a_c = \frac{v^2}{r}\). Substituting \(v = 4\) m/s and \(r = 0.5\) m gives \(a_c = \frac{4^2}{0.5} = \frac{16}{0.5} = 32\) m/s².', '["Step 1: Identify the formula for centripetal acceleration: \\(a_c = v^2 / r\\).", "Step 2: Insert the given values \\(v = 4\\) m/s and \\(r = 0.5\\) m.", "Step 3: Perform the calculation: \\(4^2 = 16\\); \\(16 / 0.5 = 32\\) m/s².", "Step 4: Select the option that matches the computed value."]', 'a_c = v^2 / r', 'physics.mechanics.centripetal_acceleration_magnitude', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:07:26.580Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('df3b1d1e576afb2eb2deaa8af151a83b', 'JEEMains', '12', 'Physics', 'phy_12_jm_em_induction', 'Physics', 'Electromagnetic Induction', '["phy_12_jm_ac_generator"]', '["Faraday''s law","Lenz''s law","induced emf","rotating coil","AC generator","magnetic flux"]', 1, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, -1.0, 'A rectangular coil having 50 turns, each side 10 cm long, rotates at 3000 rpm about an axis that is perpendicular to a uniform magnetic field of 0.2 T. What is the maximum (peak) emf induced in the coil? (Use $\pi \approx 3.14$)', '["31.4 V", "3.14 V", "62.8 V", "15.7 V"]', '31.4 V', 'First compute the coil area $A = (0.10\,\text{m})^2 = 0.01\,\text{m}^2$. The rotation speed gives $f = 3000/60 = 50\,\text{Hz}$, so $\omega = 2\pi f = 100\pi\,\text{rad/s} \approx 314\,\text{rad/s}$. Using Faraday''s law, $E_{\text{max}} = N B A \omega = 50 \times 0.2 \times 0.01 \times 314 \approx 31.4\,\text{V}$.', '["Step 1: Calculate the coil area $A = l^2 = (0.10\\,\\text{m})^2 = 0.01\\,\\text{m}^2$.", "Step 2: Convert the rotation speed to angular frequency $\\omega = 2\\pi \\times (3000/60) = 100\\pi\\,\\text{rad/s}$.", "Step 3: Apply the peak emf formula $E_{\\text{max}} = N B A \\omega$ and substitute the values.", "Step 4: Perform the multiplication to obtain $E_{\\text{max}} \\approx 31.4\\,\\text{V}$."]', 'E_{max}=N B A \omega', 'physics.emi.ac_generator_emf', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:12:27.860Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('df4265cf8f2e9e5723b4e2778376c9f4', 'JEEMains', '12', 'Mathematics', 'math_12_jm_coplanar_vectors', 'Vector Algebra', 'Coplanar vectors condition', '[]', '["scalar triple product","cross product","coplanarity","determinant method"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'Three vectors $\mathbf{a}=\langle1,2,3\rangle$, $\mathbf{b}=\langle4,-1,2\rangle$, and $\mathbf{c}=\langle k,5, -1\rangle$ are given. For which value of $k$ are the three vectors coplanar?', '["$k = -7$", "$k = 3$", "$k = 1$", "$k = -1$"]', '$k = -7$', 'Vectors are coplanar if their scalar triple product is zero: $\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c})=0$. Computing $\mathbf{b}\times\mathbf{c}$ and then the dot product with $\mathbf{a}$ gives $-7 - k = 0$, so $k = -7$.', '["Step 1: Compute $\\mathbf{b}\\times\\mathbf{c}$ using the determinant method.", "Step 2: Take the dot product of $\\mathbf{a}$ with the result from Step 1.", "Step 3: Set the scalar triple product equal to zero and solve for $k$."]', '$\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c})=0$', 'math.vector.coplanarity', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:53:52.147Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('df456db9a9a61ef5f383de7c3c37a8b2', 'JEEMains', '12', 'Physics', 'phy_12_jm_electrostatics', 'Electric Charges and Fields', 'Gauss law — sphere cylinder infinite plane', '[]', '["Gauss law","electric field","charged sphere","Coulomb''s law"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 2, -1.0, 'A uniformly charged solid sphere has radius $R$ and total charge $Q$. The electric field at $r = 2R$ is', '["$\\frac{kQ}{R^2}$", "$\\frac{kQ}{4R^2}$", "$\\frac{kQ}{2R^2}$", "$\\frac{2kQ}{R^2}$"]', '$\frac{kQ}{4R^2}$', 'For $r > R$, $E = \frac{kQ}{r^2} = \frac{kQ}{(2R)^2} = \frac{kQ}{4R^2}$', '["Step 1: Use $E = \\frac{kQ}{r^2}$ for $r > R$", "Step 2: Substitute $r = 2R$"]', 'E = \frac{kQ}{r^2}', 'physics.electrostatics.gauss_field_inside_vs_outside', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:23:03.422Z', -1);
